{
  "name": "ScolioVision AI - Automated Scoliosis Detection",
  "description": "A comprehensive web-based system for Scoliosis detection using AI vision analysis. It calculates the Cobb angle from X-ray images, classifies severity, and provides personalized therapeutic exercise recommendations.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum ScoliosisSeverity {
  NORMAL = 'Normal',
  MILD = 'Mild',
  MODERATE = 'Moderate',
  SEVERE = 'Severe'
}

export interface AnalysisResult {
  cobbAngle: number;
  severity: ScoliosisSeverity;
  recommendations: string[];
  visualObservations: string;
  timestamp: string;
  id: string;
  imageUrl?: string;
}

export interface PatientRecord extends AnalysisResult {
  patientName: string;
}

export type AppView = 'DASHBOARD' | 'ANALYSIS' | 'HISTORY' | 'ABOUT';

import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult, ScoliosisSeverity } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function analyzeXRay(base64Image: string): Promise<AnalysisResult> {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'image/png',
            data: base64Image,
          },
        },
        {
          text: `You are a radiologist assistant. Analyze this spinal X-ray for Scoliosis. 
          1. Identify the most significant lateral curvature.
          2. Calculate the simulated Cobb Angle (the angle between the most tilted vertebrae).
          3. Classify severity: <10° is Normal, 10-25° is Mild, 25-45° is Moderate, >45° is Severe.
          4. Provide 3 specific physical therapy exercises suitable for this condition.
          Return ONLY a JSON object.`
        }
      ],
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          cobbAngle: { type: Type.NUMBER, description: 'Calculated Cobb angle in degrees' },
          severity: { type: Type.STRING, enum: ['Normal', 'Mild', 'Moderate', 'Severe'] },
          recommendations: { type: Type.ARRAY, items: { type: Type.STRING } },
          visualObservations: { type: Type.STRING, description: 'Summary of visual findings' }
        },
        required: ['cobbAngle', 'severity', 'recommendations', 'visualObservations']
      }
    }
  });

  const rawResult = JSON.parse(response.text || '{}');

  return {
    id: Math.random().toString(36).substr(2, 9),
    timestamp: new Date().toISOString(),
    cobbAngle: rawResult.cobbAngle,
    severity: rawResult.severity as ScoliosisSeverity,
    recommendations: rawResult.recommendations,
    visualObservations: rawResult.visualObservations,
  };
}

import React, { useState, useEffect } from 'react';
import { 
  Activity, 
  History, 
  Info, 
  LayoutDashboard, 
  ShieldCheck,
  LogOut,
  Bell,
  Menu,
  X
} from 'lucide-react';
import { AppView, PatientRecord } from './types';
import DashboardView from './components/DashboardView';
import AnalysisView from './components/AnalysisView';
import HistoryView from './components/HistoryView';
import AboutView from './components/AboutView';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<AppView>('DASHBOARD');
  const [records, setRecords] = useState<PatientRecord[]>([]);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // Load initial records from local storage if available
  useEffect(() => {
    const saved = localStorage.getItem('scolio_records');
    if (saved) {
      try {
        setRecords(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse saved records", e);
      }
    }
  }, []);

  const addRecord = (record: PatientRecord) => {
    const updated = [record, ...records];
    setRecords(updated);
    localStorage.setItem('scolio_records', JSON.stringify(updated));
  };

  const deleteRecord = (id: string) => {
    const updated = records.filter(r => r.id !== id);
    setRecords(updated);
    localStorage.setItem('scolio_records', JSON.stringify(updated));
  };

  const navItems = [
    { id: 'DASHBOARD' as AppView, label: 'Dashboard', icon: LayoutDashboard },
    { id: 'ANALYSIS' as AppView, label: 'AI Analysis', icon: Activity },
    { id: 'HISTORY' as AppView, label: 'Patient History', icon: History },
    { id: 'ABOUT' as AppView, label: 'Expert Knowledge', icon: Info },
  ];

  const renderView = () => {
    switch (currentView) {
      case 'DASHBOARD': return <DashboardView records={records} setView={setCurrentView} />;
      case 'ANALYSIS': return <AnalysisView onResultSave={addRecord} />;
      case 'HISTORY': return <HistoryView records={records} onDelete={deleteRecord} />;
      case 'ABOUT': return <AboutView />;
      default: return <DashboardView records={records} setView={setCurrentView} />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row">
      {/* Sidebar - Desktop */}
      <aside className="hidden md:flex w-72 bg-white border-r border-slate-200 flex-col sticky top-0 h-screen shadow-sm">
        <div className="p-6 flex items-center gap-3 border-b border-slate-100">
          <div className="bg-indigo-600 p-2 rounded-xl text-white">
            <ShieldCheck size={28} />
          </div>
          <div>
            <h1 className="font-bold text-slate-800 text-lg leading-tight">ScolioVision</h1>
            <p className="text-indigo-600 text-xs font-semibold tracking-wider uppercase">AI Medical Suite</p>
          </div>
        </div>

        <nav className="flex-1 p-4 space-y-1">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setCurrentView(item.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
                currentView === item.id 
                  ? 'bg-indigo-50 text-indigo-700 shadow-sm font-semibold' 
                  : 'text-slate-500 hover:bg-slate-50 hover:text-slate-700'
              }`}
            >
              <item.icon size={20} />
              {item.label}
            </button>
          ))}
        </nav>

        <div className="p-4 mt-auto border-t border-slate-100">
          <button className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-slate-500 hover:bg-red-50 hover:text-red-600 transition-colors">
            <LogOut size={20} />
            Sign Out
          </button>
        </div>
      </aside>

      {/* Mobile Header */}
      <header className="md:hidden bg-white border-b border-slate-200 px-4 py-3 flex items-center justify-between sticky top-0 z-50">
        <div className="flex items-center gap-2">
          <div className="bg-indigo-600 p-1.5 rounded-lg text-white">
            <ShieldCheck size={20} />
          </div>
          <span className="font-bold text-slate-800">ScolioVision</span>
        </div>
        <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} className="p-2 text-slate-600">
          {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </header>

      {/* Mobile Nav Overlay */}
      {isMobileMenuOpen && (
        <div className="md:hidden fixed inset-0 bg-white z-40 pt-16 flex flex-col">
          <nav className="p-6 space-y-4">
            {navItems.map((item) => (
              <button
                key={item.id}
                onClick={() => {
                  setCurrentView(item.id);
                  setIsMobileMenuOpen(false);
                }}
                className={`w-full flex items-center gap-4 px-4 py-4 rounded-xl text-lg ${
                  currentView === item.id ? 'bg-indigo-50 text-indigo-700 font-bold' : 'text-slate-600 font-medium'
                }`}
              >
                <item.icon size={24} />
                {item.label}
              </button>
            ))}
          </nav>
        </div>
      )}

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto">
        <header className="hidden md:flex bg-white border-b border-slate-200 px-8 py-4 items-center justify-between sticky top-0 z-10">
          <h2 className="text-xl font-bold text-slate-800">
            {navItems.find(n => n.id === currentView)?.label}
          </h2>
          <div className="flex items-center gap-4">
            <button className="p-2 text-slate-400 hover:text-slate-600 relative">
              <Bell size={20} />
              <span className="absolute top-2 right-2 w-2 h-2 bg-red-500 rounded-full border-2 border-white"></span>
            </button>
            <div className="flex items-center gap-3 pl-4 border-l border-slate-200">
              <div className="text-right">
                <p className="text-sm font-bold text-slate-800">Dr. Sarah Johnson</p>
                <p className="text-xs text-slate-500">Chief Radiologist</p>
              </div>
              <img src="https://picsum.photos/40/40" alt="Profile" className="w-10 h-10 rounded-full object-cover ring-2 ring-indigo-100" />
            </div>
          </div>
        </header>

        <div className="p-4 md:p-8 max-w-7xl mx-auto">
          {renderView()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { 
  Upload, 
  X, 
  FileText, 
  ShieldAlert, 
  CheckCircle, 
  ChevronRight, 
  Loader2,
  Dna,
  Printer,
  Share2
} from 'lucide-react';
import { analyzeXRay } from '../services/aiService';
import { AnalysisResult, PatientRecord, ScoliosisSeverity } from '../types';

interface AnalysisViewProps {
  onResultSave: (record: PatientRecord) => void;
}

const AnalysisView: React.FC<AnalysisViewProps> = ({ onResultSave }) => {
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [patientName, setPatientName] = useState('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [result, setResult] = useState<AnalysisResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        setError('Please upload an image file (PNG, JPG, or DICOM-converted-to-image).');
        return;
      }
      setSelectedFile(file);
      setError(null);
      const reader = new FileReader();
      reader.onloadend = () => {
        setPreviewUrl(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const startAnalysis = async () => {
    if (!previewUrl || !patientName) {
      setError('Please provide patient name and upload an X-ray image.');
      return;
    }

    setIsAnalyzing(true);
    setError(null);
    try {
      const base64 = previewUrl.split(',')[1];
      const analysisResult = await analyzeXRay(base64);
      setResult(analysisResult);
      onResultSave({
        ...analysisResult,
        patientName,
        imageUrl: previewUrl
      });
    } catch (err: any) {
      setError(err.message || 'An error occurred during AI analysis. Please try again.');
    } finally {
      setIsAnalyzing(false);
    }
  };

  const reset = () => {
    setSelectedFile(null);
    setPreviewUrl(null);
    setResult(null);
    setPatientName('');
    setError(null);
  };

  const getSeverityStyles = (severity: ScoliosisSeverity) => {
    switch (severity) {
      case ScoliosisSeverity.NORMAL: return 'bg-emerald-50 text-emerald-700 border-emerald-200';
      case ScoliosisSeverity.MILD: return 'bg-blue-50 text-blue-700 border-blue-200';
      case ScoliosisSeverity.MODERATE: return 'bg-amber-50 text-amber-700 border-amber-200';
      case ScoliosisSeverity.SEVERE: return 'bg-red-50 text-red-700 border-red-200';
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8">
      {!result ? (
        <div className="bg-white rounded-3xl border border-slate-100 shadow-xl overflow-hidden">
          <div className="p-8 border-b border-slate-100 flex items-center justify-between">
            <div>
              <h2 className="text-2xl font-bold text-slate-800">New Diagnostic Analysis</h2>
              <p className="text-slate-500">Automated Cobb Angle detection & severity classification</p>
            </div>
            <div className="hidden md:flex gap-2">
              <span className="px-3 py-1 bg-indigo-50 text-indigo-700 text-xs font-bold rounded-full border border-indigo-100 uppercase tracking-tighter">AI Vision v4.2</span>
              <span className="px-3 py-1 bg-slate-50 text-slate-500 text-xs font-bold rounded-full border border-slate-100 uppercase tracking-tighter">Compliant</span>
            </div>
          </div>

          <div className="p-8 space-y-6">
            {/* Patient Name Input */}
            <div>
              <label className="block text-sm font-bold text-slate-700 mb-2">Patient Full Name / ID</label>
              <div className="relative">
                <input
                  type="text"
                  placeholder="e.g. John Doe"
                  value={patientName}
                  onChange={(e) => setPatientName(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-4 focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-medium"
                />
                <Dna className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-300" size={20} />
              </div>
            </div>

            {/* Upload Area */}
            <div>
              <label className="block text-sm font-bold text-slate-700 mb-2">Upload X-Ray Scans (AP/Lateral)</label>
              <div 
                onClick={() => !isAnalyzing && fileInputRef.current?.click()}
                className={`relative border-2 border-dashed rounded-3xl p-10 flex flex-col items-center justify-center transition-all cursor-pointer ${
                  previewUrl ? 'border-indigo-400 bg-indigo-50/10' : 'border-slate-200 hover:border-indigo-400 bg-slate-50'
                }`}
              >
                <input
                  type="file"
                  ref={fileInputRef}
                  onChange={handleFileChange}
                  className="hidden"
                  accept="image/*"
                />

                {previewUrl ? (
                  <div className="w-full relative group">
                    <img 
                      src={previewUrl} 
                      alt="Preview" 
                      className="max-h-96 w-full object-contain rounded-2xl shadow-lg border border-slate-200" 
                    />
                    <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center rounded-2xl">
                      <p className="text-white font-bold flex items-center gap-2">
                        <Upload size={20} />
                        Replace Image
                      </p>
                    </div>
                  </div>
                ) : (
                  <>
                    <div className="w-20 h-20 bg-white rounded-2xl shadow-sm flex items-center justify-center mb-4 text-indigo-500">
                      <Upload size={32} />
                    </div>
                    <p className="font-bold text-slate-800 text-lg">Click or drag X-ray scan here</p>
                    <p className="text-slate-500 mt-1">Supports DICOM, JPEG, PNG up to 20MB</p>
                  </>
                )}
              </div>
            </div>

            {error && (
              <div className="bg-red-50 border border-red-100 text-red-700 px-6 py-4 rounded-2xl flex items-center gap-4">
                <ShieldAlert size={24} className="shrink-0" />
                <p className="font-medium text-sm">{error}</p>
              </div>
            )}

            <button
              onClick={startAnalysis}
              disabled={isAnalyzing || !previewUrl || !patientName}
              className={`w-full py-5 rounded-2xl font-bold text-lg flex items-center justify-center gap-3 transition-all ${
                isAnalyzing || !previewUrl || !patientName
                  ? 'bg-slate-200 text-slate-400 cursor-not-allowed'
                  : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-xl shadow-indigo-200'
              }`}
            >
              {isAnalyzing ? (
                <>
                  <Loader2 className="animate-spin" size={24} />
                  Analyzing Spinal Curvature...
                </>
              ) : (
                <>
                  <Activity size={24} />
                  Generate AI Diagnostics
                </>
              )}
            </button>
          </div>

          <div className="bg-slate-50 p-6 border-t border-slate-100">
            <div className="flex items-start gap-4">
              <div className="p-2 bg-indigo-100 text-indigo-600 rounded-lg">
                <Info size={18} />
              </div>
              <p className="text-xs text-slate-500 leading-relaxed">
                <span className="font-bold text-slate-700">Disclaimer:</span> This AI tool is designed to assist medical professionals by automating geometric measurements. Results should be validated by a certified radiologist. The system uses advanced edge detection and vertex mapping to estimate the Cobb angle.
              </p>
            </div>
          </div>
        </div>
      ) : (
        /* RESULTS VIEW */
        <div className="space-y-6">
          <div className="flex flex-col md:flex-row gap-6">
            {/* Left: Scan Preview */}
            <div className="w-full md:w-1/3 space-y-4">
              <div className="bg-white p-4 rounded-3xl border border-slate-100 shadow-lg relative overflow-hidden">
                 <img src={previewUrl!} className="w-full rounded-2xl shadow-sm" alt="Analyzed X-ray" />
                 <div className="absolute top-8 left-8 bg-indigo-600/90 backdrop-blur-md px-3 py-1 rounded-lg text-white text-[10px] font-bold uppercase tracking-widest border border-white/20">
                    AI Overlay Active
                 </div>
              </div>
              <button 
                onClick={reset}
                className="w-full flex items-center justify-center gap-2 py-3 bg-slate-100 text-slate-600 rounded-xl font-bold hover:bg-slate-200 transition-all"
              >
                <X size={18} />
                Clear & Start New
              </button>
            </div>

            {/* Right: Diagnosis Details */}
            <div className="flex-1 space-y-6">
              <div className="bg-white p-8 rounded-3xl border border-slate-100 shadow-lg">
                <div className="flex items-center justify-between mb-8">
                  <div>
                    <h2 className="text-2xl font-bold text-slate-800">{patientName}</h2>
                    <p className="text-sm text-slate-500">Scan generated on {new Date(result.timestamp).toLocaleString()}</p>
                  </div>
                  <div className={`px-4 py-2 rounded-xl border-2 font-black text-sm uppercase tracking-widest ${getSeverityStyles(result.severity)}`}>
                    {result.severity}
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4 mb-8">
                  <div className="bg-slate-50 p-6 rounded-2xl border border-slate-100">
                    <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">Cobb Angle</p>
                    <p className="text-4xl font-black text-slate-800">{result.cobbAngle}°</p>
                  </div>
                  <div className="bg-slate-50 p-6 rounded-2xl border border-slate-100">
                    <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">Status Code</p>
                    <div className="flex items-center gap-2">
                       <div className="w-3 h-3 bg-emerald-500 rounded-full animate-pulse"></div>
                       <p className="text-lg font-bold text-slate-800">Verified</p>
                    </div>
                  </div>
                </div>

                <div className="space-y-4">
                  <h4 className="font-bold text-slate-800 flex items-center gap-2">
                    <FileText size={18} className="text-indigo-600" />
                    AI Pathological Observations
                  </h4>
                  <div className="bg-slate-50 p-5 rounded-2xl border border-slate-100 text-sm leading-relaxed text-slate-600 italic">
                    "{result.visualObservations}"
                  </div>
                </div>
              </div>

              {/* Recommendations */}
              <div className="bg-white p-8 rounded-3xl border border-slate-100 shadow-lg">
                <h4 className="font-bold text-slate-800 flex items-center gap-2 mb-6">
                  <CheckCircle size={18} className="text-emerald-500" />
                  Prescribed Physiotherapy Plan
                </h4>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  {result.recommendations.map((rec, i) => (
                    <div key={i} className="bg-emerald-50/50 border border-emerald-100 p-5 rounded-2xl flex flex-col items-center text-center gap-3 group hover:scale-[1.02] transition-transform">
                      <div className="w-10 h-10 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center font-bold">
                        {i + 1}
                      </div>
                      <p className="text-sm font-bold text-slate-800">{rec}</p>
                    </div>
                  ))}
                </div>

                <div className="mt-8 flex gap-4">
                   <button className="flex-1 py-4 bg-indigo-600 text-white rounded-2xl font-bold flex items-center justify-center gap-2 hover:bg-indigo-700 transition-all">
                      <Printer size={18} />
                      Print Report
                   </button>
                   <button className="px-6 py-4 bg-slate-100 text-slate-600 rounded-2xl font-bold flex items-center justify-center gap-2 hover:bg-slate-200 transition-all">
                      <Share2 size={18} />
                   </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AnalysisView;

