    if (!ctx) return;

    const { width, height } = canvasRef.current;
    ctx.clearRect(0, 0, width, height);

    if (analysis.landmarks) {
      // Connect points to form a skeleton
      const points = analysis.landmarks;
      const getPt = (label: string) => points.find(p => p.label.toLowerCase().includes(label.toLowerCase()));

      const head = getPt('Head');
      const ls = getPt('LeftShoulder');
      const rs = getPt('RightShoulder');
      const spine = getPt('Spine');
      const lh = getPt('LeftHip');
      const rh = getPt('RightHip');

      ctx.lineWidth = 3;
      ctx.strokeStyle = analysis.isDeviating ? '#ef4444' : '#10b981';
      ctx.shadowBlur = 10;
      ctx.shadowColor = ctx.strokeStyle;

      const drawLine = (p1?: Landmark, p2?: Landmark) => {
        if (p1 && p2) {
          ctx.beginPath();
          ctx.moveTo(p1.x * width / 100, p1.y * height / 100);
          ctx.lineTo(p2.x * width / 100, p2.y * height / 100);
          ctx.stroke();
        }
      };

      // Draw Skeleton Lines
      drawLine(head, spine);
      drawLine(ls, rs);
      drawLine(ls, lh);
      drawLine(rs, rh);
      drawLine(lh, rh);
      drawLine(spine, lh);
      drawLine(spine, rh);

      // Draw Landmark Nodes
      points.forEach(pt => {
        const x = pt.x * width / 100;
        const y = pt.y * height / 100;
        ctx.beginPath();
        ctx.arc(x, y, 5, 0, Math.PI * 2);
        ctx.fillStyle = ctx.strokeStyle;
        ctx.fill();

        // Add Pulse Effect
        ctx.beginPath();
        ctx.arc(x, y, 10 + Math.sin(Date.now() / 200) * 5, 0, Math.PI * 2);
        ctx.stroke();
      });
    }
