        }
      });
      const result = JSON.parse(response.text || '{}');
      if (result.landmarks) {
        setBaselineLandmarks(result.landmarks);
        setCalibrationStep('complete');
        // Automatically dismiss the "Complete" state after 2 seconds
        setTimeout(() => setCalibrationStep('idle'), 2000);
      }
    } catch (err) {
      console.error("Calibration capture failed:", err);
      setError("Calibration failed. Please try again.");
      setCalibrationStep('idle');
    }
  };

  // Perform AI Analysis on a Frame
  const analyzeFrame = async () => {
    if (!isActive || !videoRef.current || isAnalyzing || calibrationStep !== 'idle') return;

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    setIsAnalyzing(true);
    try {
      const promptText = baselineLandmarks 
        ? `Analyze posture in this frame relative to these baseline landmarks: ${JSON.stringify(baselineLandmarks)}.
           1. Detect current normalized (0-100) coordinates for key points.
           2. Calculate alignment score (0-100) comparing deviation from baseline.
           3. Provide a brief feedback string.
           Return ONLY a JSON object.`
        : `Analyze posture in this frame. 
           1. Detect normalized (0-100) coordinates for: Head, LeftShoulder, RightShoulder, SpineCenter, LeftHip, RightHip.
           2. Calculate an alignment score (0-100).
           3. Provide a brief postural feedback string.
           Return ONLY a JSON object.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
