export type AppView = 'DASHBOARD' | 'ANALYSIS' | 'HISTORY' | 'POSTURE_LIVE' | 'ABOUT';

import React, { useState, useEffect } from 'react';
import { 
  Activity, 
  History, 
  LayoutDashboard, 
  ShieldCheck,
  LogOut,
  Bell,
  Menu,
  X,
  Video
} from 'lucide-react';
import { AppView, PatientRecord, User } from './types';
import DashboardView from './components/DashboardView';
import AnalysisView from './components/AnalysisView';
import HistoryView from './components/HistoryView';
import LoginView from './components/LoginView';
import PostureLiveView from './components/PostureLiveView';
import AboutView from './components/AboutView';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<AppView>('DASHBOARD');
  const [records, setRecords] = useState<PatientRecord[]>([]);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // Load user and records from local storage
  useEffect(() => {
    const savedRecords = localStorage.getItem('scolio_records');
    if (savedRecords) {
      try { setRecords(JSON.parse(savedRecords)); } catch (e) { console.error(e); }
    }

    const savedUser = localStorage.getItem('scolio_user');
    if (savedUser) {
      try { setUser(JSON.parse(savedUser)); } catch (e) { console.error(e); }
    }
  }, []);

  const handleLogin = (userData: User) => {
    setUser(userData);
    localStorage.setItem('scolio_user', JSON.stringify(userData));
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('scolio_user');
  };

  const addRecord = (record: PatientRecord) => {
    const updated = [record, ...records];
    setRecords(updated);
    localStorage.setItem('scolio_records', JSON.stringify(updated));
  };

  const deleteRecord = (id: string) => {
    const updated = records.filter(r => r.id !== id);
    setRecords(updated);
    localStorage.setItem('scolio_records', JSON.stringify(updated));
  };

  const navItems = [
    { id: 'DASHBOARD' as AppView, label: 'Dashboard', icon: LayoutDashboard },
    { id: 'ANALYSIS' as AppView, label: 'AI Analysis', icon: Activity },
    { id: 'POSTURE_LIVE' as AppView, label: 'Live Monitoring', icon: Video },
    { id: 'HISTORY' as AppView, label: 'Patient History', icon: History },
  ];

  if (!user) {
    return <LoginView onLogin={handleLogin} />;
  }

  const renderView = () => {
    switch (currentView) {
      case 'DASHBOARD': return <DashboardView records={records} setView={setCurrentView} user={user} />;
      case 'ANALYSIS': return <AnalysisView onResultSave={addRecord} />;
      case 'POSTURE_LIVE': return <PostureLiveView />;
      case 'HISTORY': return <HistoryView records={records} onDelete={deleteRecord} />;
      case 'ABOUT': return <AboutView />;
      default: return <DashboardView records={records} setView={setCurrentView} user={user} />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row">
      {/* Sidebar - Desktop */}
      <aside className="hidden md:flex w-72 bg-white border-r border-slate-200 flex-col sticky top-0 h-screen shadow-sm">
        <div className="p-6 flex items-center gap-3 border-b border-slate-100">
          <div className="bg-indigo-600 p-2 rounded-xl text-white">
            <ShieldCheck size={28} />
          </div>
          <div>
            <h1 className="font-bold text-slate-800 text-lg leading-tight">ScolioVision</h1>
            <p className="text-indigo-600 text-xs font-semibold tracking-wider uppercase">AI Medical Suite</p>
          </div>
        </div>

        <nav className="flex-1 p-4 space-y-1">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setCurrentView(item.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
                currentView === item.id 
                  ? 'bg-indigo-50 text-indigo-700 shadow-sm font-semibold' 
                  : 'text-slate-500 hover:bg-slate-50 hover:text-slate-700'
              }`}
            >
              <item.icon size={20} />
              {item.label}
            </button>
          ))}
        </nav>

        <div className="p-4 mt-auto border-t border-slate-100">
          <button 
            onClick={handleLogout}
            className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-slate-500 hover:bg-red-50 hover:text-red-600 transition-colors"
          >
            <LogOut size={20} />
            Sign Out
          </button>
        </div>
      </aside>

      {/* Mobile Header */}
      <header className="md:hidden bg-white border-b border-slate-200 px-4 py-3 flex items-center justify-between sticky top-0 z-50">
        <div className="flex items-center gap-2">
          <div className="bg-indigo-600 p-1.5 rounded-lg text-white">
            <ShieldCheck size={20} />
          </div>
          <span className="font-bold text-slate-800">ScolioVision</span>
        </div>
        <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} className="p-2 text-slate-600">
          {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </header>

      {/* Mobile Nav Overlay */}
      {isMobileMenuOpen && (
        <div className="md:hidden fixed inset-0 bg-white z-40 pt-16 flex flex-col">
          <nav className="p-6 space-y-4">
            {navItems.map((item) => (
              <button
                key={item.id}
                onClick={() => {
                  setCurrentView(item.id);
                  setIsMobileMenuOpen(false);
                }}
                className={`w-full flex items-center gap-4 px-4 py-4 rounded-xl text-lg ${
                  currentView === item.id ? 'bg-indigo-50 text-indigo-700 font-bold' : 'text-slate-600 font-medium'
                }`}
              >
                <item.icon size={24} />
                {item.label}
              </button>
            ))}
            <button 
              onClick={handleLogout}
              className="w-full flex items-center gap-4 px-4 py-4 rounded-xl text-lg text-red-600 font-medium"
            >
              <LogOut size={24} />
              Sign Out
            </button>
          </nav>
        </div>
      )}

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto">
        <header className="hidden md:flex bg-white border-b border-slate-200 px-8 py-4 items-center justify-between sticky top-0 z-10">
          <h2 className="text-xl font-bold text-slate-800">
            {navItems.find(n => n.id === currentView)?.label}
          </h2>
          <div className="flex items-center gap-4">
            <button className="p-2 text-slate-400 hover:text-slate-600 relative">
              <Bell size={20} />
              <span className="absolute top-2 right-2 w-2 h-2 bg-red-500 rounded-full border-2 border-white"></span>
            </button>
            <div className="flex items-center gap-3 pl-4 border-l border-slate-200">
              <div className="text-right">
                <p className="text-sm font-bold text-slate-800">{user.name}</p>
                <p className="text-xs text-slate-500">{user.designation}</p>
              </div>
              <div className="w-10 h-10 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-700 font-bold ring-2 ring-white">
                {user.name.charAt(0)}
              </div>
            </div>
          </div>
        </header>

        <div className="p-4 md:p-8 max-w-7xl mx-auto">
          {renderView()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState, useMemo } from 'react';
import { 
  Camera, 
  CameraOff, 
  Play, 
  Square, 
  RefreshCw, 
  Zap, 
  AlertCircle, 
  Activity,
  CheckCircle2,
  ScanEye,
  Target,
  ChevronRight,
  ShieldCheck,
  Dumbbell,
  Stethoscope,
  TrendingUp,
  AlertTriangle,
  ArrowUpRight,
  ArrowDownRight
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";
import { PostureAnalysis, Landmark, ScoliosisSeverity } from '../types';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

type CalibrationStep = 'idle' | 'preparing' | 'capturing' | 'complete';

interface SessionDataPoint {
  time: string;
  score: number;
  angle: number;
}

const PostureLiveView: React.FC = () => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const [isActive, setIsActive] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<PostureAnalysis | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [sessionHistory, setSessionHistory] = useState<SessionDataPoint[]>([]);

  // Calibration State
  const [calibrationStep, setCalibrationStep] = useState<CalibrationStep>('idle');
  const [baselineLandmarks, setBaselineLandmarks] = useState<Landmark[] | null>(null);
  const [countdown, setCountdown] = useState(0);

  // Significant Change Logic
  const significantChange = useMemo(() => {
    if (sessionHistory.length < 2) return null;
    const current = sessionHistory[sessionHistory.length - 1];
    const previous = sessionHistory[sessionHistory.length - 2];
    const diff = current.score - previous.score;

    if (Math.abs(diff) > 12) { // Slightly lower threshold for more reactive feedback
      // Using explicit casting to ensure string literals are correctly typed
      return {
        type: (diff > 0 ? 'improvement' : 'deterioration') as 'improvement' | 'deterioration',
        value: Math.abs(diff)
      };
    }
    return null;
  }, [sessionHistory]);

  // Visual Alert State
  const [activeAlert, setActiveAlert] = useState<'improvement' | 'deterioration' | null>(null);

  useEffect(() => {
    if (significantChange) {
      // significantChange.type is now correctly typed as 'improvement' | 'deterioration'
      setActiveAlert(significantChange.type);
      const timer = setTimeout(() => setActiveAlert(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [significantChange]);

  // Toggle Camera
  const toggleCamera = async () => {
    if (isActive) {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
      setIsActive(false);
      setAnalysis(null);
      setCalibrationStep('idle');
      setSessionHistory([]);
      setActiveAlert(null);
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsActive(true);
          setError(null);
        }
      } catch (err) {
        setError("Could not access camera. Please check permissions.");
      }
    }
  };

  // Start Calibration Wizard
  const startCalibration = () => {
    if (!isActive) return;
    setCalibrationStep('preparing');
    setCountdown(5);
  };

  // Countdown timer for calibration
  useEffect(() => {
    if (calibrationStep === 'preparing' && countdown > 0) {
      const timer = setTimeout(() => setCountdown(countdown - 1), 1000);
      return () => clearTimeout(timer);
    } else if (calibrationStep === 'preparing' && countdown === 0) {
      captureCalibration();
    }
  }, [calibrationStep, countdown]);

  const captureCalibration = async () => {
    if (!videoRef.current) return;
    setCalibrationStep('capturing');

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `This is a baseline calibration frame for posture analysis. 
              Detect normalized (0-100) coordinates for: Head, LeftShoulder, RightShoulder, SpineCenter, LeftHip, RightHip.
              Return ONLY the JSON list of landmarks.` }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER },
                    y: { type: Type.NUMBER },
                    label: { type: Type.STRING }
                  },
                  required: ['x', 'y', 'label']
                }
              }
            },
            required: ['landmarks']
          }
        }
      });
      const result = JSON.parse(response.text || '{}');
      if (result.landmarks) {
        setBaselineLandmarks(result.landmarks);
        setCalibrationStep('complete');
        setTimeout(() => setCalibrationStep('idle'), 2000);
      }
    } catch (err) {
      console.error("Calibration capture failed:", err);
      setError("Calibration failed. Please try again.");
      setCalibrationStep('idle');
    }
  };

  // Perform AI Analysis on a Frame
  const analyzeFrame = async () => {
    if (!isActive || !videoRef.current || isAnalyzing || calibrationStep !== 'idle') return;

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    setIsAnalyzing(true);
    try {
      const promptText = `Analyze posture in this frame ${baselineLandmarks ? `relative to these baseline landmarks: ${JSON.stringify(baselineLandmarks)}` : ''}.
           1. Detect current normalized (0-100) coordinates for: Head, LeftShoulder, RightShoulder, SpineCenter, LeftHip, RightHip.
           2. Estimate a simulated 'Postural Cobb Angle' (0-90 degrees) based on shoulder/hip tilt and spinal curvature visible.
           3. Classify severity: <10 is Normal, 10-25 is Mild, 25-45 is Moderate, >45 is Severe.
           4. Provide 3 personalized exercise recommendations.
           5. Calculate an alignment score (0-100).
           6. Provide a brief postural feedback string.
           Return ONLY a JSON object.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: promptText }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER },
                    y: { type: Type.NUMBER },
                    label: { type: Type.STRING }
                  },
                  required: ['x', 'y', 'label']
                }
              },
              alignmentScore: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              isDeviating: { type: Type.BOOLEAN },
              estimatedCobbAngle: { type: Type.NUMBER },
              severity: { type: Type.STRING, enum: ['Normal', 'Mild', 'Moderate', 'Severe'] },
              recommendations: { type: Type.ARRAY, items: { type: Type.STRING } }
            },
            required: ['landmarks', 'alignmentScore', 'feedback', 'isDeviating', 'estimatedCobbAngle', 'severity', 'recommendations']
          }
        }
      });

      const result = JSON.parse(response.text || '{}');
      setAnalysis(result);

      const newPoint: SessionDataPoint = {
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
        score: result.alignmentScore,
        angle: result.estimatedCobbAngle || 0
      };
      setSessionHistory(prev => [...prev.slice(-19), newPoint]);
    } catch (err) {
      console.error("Frame analysis failed:", err);
    } finally {
      setIsAnalyzing(false);
    }
  };

  // Interval for analysis
  useEffect(() => {
    let interval: number;
    if (isActive && calibrationStep === 'idle') {
      interval = window.setInterval(analyzeFrame, 4000); 
    }
    return () => clearInterval(interval);
  }, [isActive, isAnalyzing, calibrationStep, baselineLandmarks]);

  // Draw Overlay
  useEffect(() => {
    if (!canvasRef.current || (!analysis && !baselineLandmarks)) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const { width, height } = canvasRef.current;
    ctx.clearRect(0, 0, width, height);

    const drawSkeleton = (points: Landmark[], color: string, isSolid: boolean = true) => {
      const getPt = (label: string) => points.find(p => p.label.toLowerCase().includes(label.toLowerCase()));

      const head = getPt('Head');
      const ls = getPt('LeftShoulder');
      const rs = getPt('RightShoulder');
      const spine = getPt('Spine');
      const lh = getPt('LeftHip');
      const rh = getPt('RightHip');

      ctx.lineWidth = isSolid ? 4 : 2;
      ctx.strokeStyle = color;
      ctx.setLineDash(isSolid ? [] : [5, 5]);
      ctx.shadowBlur = isSolid ? 15 : 0;
      ctx.shadowColor = color;

      const drawLine = (p1?: Landmark, p2?: Landmark) => {
        if (p1 && p2) {
          ctx.beginPath();
          ctx.moveTo(p1.x * width / 100, p1.y * height / 100);
          ctx.lineTo(p2.x * width / 100, p2.y * height / 100);
          ctx.stroke();
        }
      };

      drawLine(head, spine);
      drawLine(ls, rs);
      drawLine(ls, lh);
      drawLine(rs, rh);
      drawLine(lh, rh);
      drawLine(spine, lh);
      drawLine(spine, rh);

      points.forEach(pt => {
        const x = pt.x * width / 100;
        const y = pt.y * height / 100;
        ctx.beginPath();
        ctx.arc(x, y, isSolid ? 6 : 4, 0, Math.PI * 2);
        ctx.fillStyle = color;
        ctx.fill();
      });
    };

    if (baselineLandmarks && isActive) {
      drawSkeleton(baselineLandmarks, 'rgba(129, 140, 248, 0.4)', false);
    }

    if (analysis?.landmarks && isActive) {
      drawSkeleton(analysis.landmarks, analysis.isDeviating ? '#ef4444' : '#10b981', true);
    }
  }, [analysis, baselineLandmarks, isActive]);

  const getSeverityStyles = (severity?: ScoliosisSeverity) => {
    switch (severity) {
      case ScoliosisSeverity.NORMAL: return 'text-emerald-500 bg-emerald-50 border-emerald-100';
      case ScoliosisSeverity.MILD: return 'text-blue-500 bg-blue-50 border-blue-100';
      case ScoliosisSeverity.MODERATE: return 'text-amber-500 bg-amber-50 border-amber-100';
      case ScoliosisSeverity.SEVERE: return 'text-red-500 bg-red-50 border-red-100';
      default: return 'text-slate-400 bg-slate-50 border-slate-100';
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <style>{`
        @keyframes pulse-emerald {
          0%, 100% { border-color: rgba(16, 185, 129, 1); box-shadow: 0 0 0 0 rgba(16, 185, 129, 0.7); }
          50% { border-color: rgba(16, 185, 129, 0.5); box-shadow: 0 0 30px 10px rgba(16, 185, 129, 0.3); }
        }
        @keyframes pulse-amber {
          0%, 100% { border-color: rgba(245, 158, 11, 1); box-shadow: 0 0 0 0 rgba(245, 158, 11, 0.7); }
          50% { border-color: rgba(245, 158, 11, 0.5); box-shadow: 0 0 30px 10px rgba(245, 158, 11, 0.3); }
        }
        .animate-pulse-emerald { animation: pulse-emerald 1s infinite ease-in-out; }
        .animate-pulse-amber { animation: pulse-amber 1s infinite ease-in-out; }
      `}</style>

      {/* Significant Change Alert Banner */}
      {significantChange && (
        <div className={`flex items-center justify-between p-4 rounded-2xl border animate-in slide-in-from-top-4 ${
          significantChange.type === 'improvement' 
            ? 'bg-emerald-50 border-emerald-200 text-emerald-800' 
            : 'bg-amber-50 border-amber-200 text-amber-800'
        }`}>
          <div className="flex items-center gap-3">
            {significantChange.type === 'improvement' ? <TrendingUp size={24} /> : <AlertTriangle size={24} />}
            <div>
              <p className="font-bold uppercase text-xs tracking-widest">Significant Posture Shift Detected</p>
              <p className="text-sm">Alignment {significantChange.type === 'improvement' ? 'improved' : 'deteriorated'} by {significantChange.value.toFixed(1)}% since last measurement.</p>
            </div>
          </div>
          <button onClick={() => setSessionHistory([])} className="p-2 hover:bg-black/5 rounded-full transition-colors">
            <ChevronRight size={20} />
          </button>
        </div>
      )}

      <div className="flex flex-col xl:flex-row gap-8">
        {/* Monitoring Window */}
        <div className="flex-1 flex flex-col gap-6">
          <div className={`bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl relative aspect-video group border-4 transition-all duration-300 ${
            activeAlert === 'improvement' ? 'border-emerald-500 animate-pulse-emerald' : 
            activeAlert === 'deterioration' ? 'border-amber-500 animate-pulse-amber' : 
            'border-slate-800'
          }`}>
            <video 
              ref={videoRef} 
              autoPlay 
              playsInline 
              muted 
              className={`w-full h-full object-cover transition-opacity duration-700 ${isActive ? 'opacity-100' : 'opacity-20'}`}
            />
            <canvas 
              ref={canvasRef} 
              className="absolute inset-0 w-full h-full pointer-events-none"
              width={640}
              height={480}
            />

            {/* HUD Elements */}
            <div className="absolute top-8 left-8 flex items-center gap-3">
              <div className={`w-3 h-3 rounded-full ${isActive ? 'bg-red-500 animate-pulse' : 'bg-slate-600'}`}></div>
              <span className="text-white text-xs font-black tracking-widest uppercase opacity-80">
                {isActive ? 'Live Bio-Feedback' : 'Camera Standby'}
              </span>
            </div>

            {/* On-Screen HUD Alert Badge */}
            {activeAlert && (
              <div className={`absolute top-8 right-8 flex items-center gap-3 px-4 py-2 rounded-xl border-2 backdrop-blur-md animate-in slide-in-from-right-4 duration-300 ${
                activeAlert === 'improvement' 
                  ? 'bg-emerald-500/20 border-emerald-500 text-emerald-400' 
                  : 'bg-amber-500/20 border-amber-500 text-amber-400'
              }`}>
                {activeAlert === 'improvement' ? <ArrowUpRight size={20} className="animate-bounce" /> : <ArrowDownRight size={20} className="animate-bounce" />}
                <span className="font-black text-xs uppercase tracking-widest">
                  {activeAlert === 'improvement' ? 'Improving' : 'Deteriorating'}
                </span>
              </div>
            )}

            {/* Calibration Overlay */}
            {calibrationStep !== 'idle' && (
              <div className="absolute inset-0 bg-indigo-900/60 backdrop-blur-sm flex flex-col items-center justify-center text-white z-10 animate-in fade-in zoom-in duration-300">
                {calibrationStep === 'preparing' && (
                  <>
                    <div className="w-24 h-24 rounded-full border-4 border-white/20 flex items-center justify-center mb-6 relative">
                       <div className="absolute inset-0 border-4 border-white rounded-full animate-ping opacity-20"></div>
                       <span className="text-5xl font-black">{countdown}</span>
                    </div>
                    <h2 className="text-2xl font-black mb-2">Posture Calibration</h2>
                    <p className="text-indigo-100 font-medium">Please stand in your natural neutral pose</p>
                  </>
                )}
                {calibrationStep === 'capturing' && (
                  <div className="flex flex-col items-center gap-4">
                    <RefreshCw size={48} className="animate-spin text-white opacity-80" />
                    <p className="font-black text-xl">Recording Baseline...</p>
                  </div>
                )}
                {calibrationStep === 'complete' && (
                  <div className="flex flex-col items-center gap-4">
                    <div className="w-20 h-20 bg-emerald-500 rounded-full flex items-center justify-center shadow-lg shadow-emerald-500/20">
                      <CheckCircle2 size={40} />
                    </div>
                    <p className="font-black text-xl">Calibration Successful</p>
                  </div>
                )}
              </div>
            )}

            {!isActive && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-white space-y-4">
                <div className="w-20 h-20 bg-white/10 backdrop-blur-md rounded-3xl flex items-center justify-center border border-white/20">
                  <CameraOff size={40} className="text-slate-400" />
                </div>
                <div className="text-center">
                  <p className="font-bold text-lg">Sensor Feed Inactive</p>
                  <p className="text-slate-400 text-sm">Initiate camera to start live posture tracking</p>
                </div>
              </div>
            )}

            {isAnalyzing && (
              <div className="absolute bottom-8 right-8 flex items-center gap-2 bg-indigo-600 px-4 py-2 rounded-xl text-white text-xs font-bold shadow-lg animate-pulse">
                <RefreshCw size={14} className="animate-spin" />
                Analyzing...
              </div>
            )}

            <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-4 transition-transform group-hover:scale-105 duration-300">
              <button 
                onClick={toggleCamera}
                className={`flex items-center gap-3 px-8 py-4 rounded-2xl font-black text-sm uppercase tracking-widest transition-all ${
                  isActive 
                    ? 'bg-white/10 backdrop-blur-md text-white border border-white/20 hover:bg-white/20' 
                    : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-xl shadow-indigo-500/20'
                }`}
              >
                {isActive ? <><Square size={18} /> Stop</> : <><Play size={18} /> Start Monitoring</>}
              </button>

              {isActive && (
                <button 
                  onClick={startCalibration}
                  disabled={calibrationStep !== 'idle'}
                  className="flex items-center gap-3 px-8 py-4 bg-indigo-600 text-white rounded-2xl font-black text-sm uppercase tracking-widest hover:bg-indigo-700 shadow-xl shadow-indigo-500/30 transition-all disabled:opacity-50"
                >
                  <Target size={18} />
                  Calibrate
                </button>
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col justify-between">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Estimated Cobb Angle</p>
              <div className="flex items-baseline gap-2">
                <p className="text-4xl font-black text-slate-800">{analysis?.estimatedCobbAngle ? `${analysis.estimatedCobbAngle}°` : '--°'}</p>
                <span className="text-[10px] font-bold text-slate-400 italic">Postural Estimation</span>
              </div>
            </div>
            <div className={`p-6 rounded-3xl border shadow-sm flex flex-col justify-between transition-colors ${getSeverityStyles(analysis?.severity as ScoliosisSeverity)}`}>
              <p className="text-[10px] font-black uppercase tracking-widest mb-1 opacity-70">Calculated Severity</p>
              <p className="text-3xl font-black">{analysis?.severity || '--'}</p>
            </div>
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col justify-between">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Alignment Score</p>
              <p className="text-4xl font-black text-indigo-600">{analysis ? `${analysis.alignmentScore}%` : '--%'}</p>
            </div>
          </div>
        </div>

        {/* Analytics & Feedback Sidebar */}
        <div className="w-full xl:w-96 space-y-6">
          {/* Posture Trend Analytics */}
          <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-lg">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2">
                <TrendingUp size={24} className="text-emerald-500" />
                Posture Trends
              </h3>
              {sessionHistory.length > 0 && (
                <div className="px-2 py-1 bg-emerald-50 text-emerald-600 text-[10px] font-black rounded-lg border border-emerald-100">LIVE</div>
              )}
            </div>

            <div className="h-48 w-full -ml-4">
              {sessionHistory.length > 1 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={sessionHistory}>
                    <defs>
                      <linearGradient id="colorScore" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#4f46e5" stopOpacity={0.1}/>
                        <stop offset="95%" stopColor="#4f46e5" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                    <XAxis dataKey="time" hide />
                    <YAxis domain={[0, 100]} hide />
                    <Tooltip 
                      contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                      labelStyle={{ fontSize: '10px', fontWeight: 'bold' }}
                    />
                    <Area type="monotone" dataKey="score" stroke="#4f46e5" strokeWidth={3} fillOpacity={1} fill="url(#colorScore)" />
                  </AreaChart>
                </ResponsiveContainer>
              ) : (
                <div className="h-full flex flex-col items-center justify-center text-slate-300 text-center px-6">
                  <Activity size={32} className="opacity-20 mb-2" />
                  <p className="text-xs font-bold uppercase tracking-widest leading-relaxed">Insufficient Data<br/><span className="text-[10px] font-medium normal-case">Collect more frames for trend analysis</span></p>
                </div>
              )}
            </div>

            <div className="mt-4 flex justify-between text-[10px] font-black uppercase text-slate-400">
              <span>Session Start</span>
              <span>Latest</span>
            </div>
          </div>

          {/* Recommendation Engine */}
          <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-lg">
            <h3 className="text-xl font-black text-slate-800 mb-6 flex items-center gap-2">
              <Dumbbell size={24} className="text-indigo-600" />
              Dynamic Exercises
            </h3>

            {analysis?.recommendations ? (
              <div className="space-y-4">
                {analysis.recommendations.map((rec, i) => (
                  <div key={i} className="flex gap-4 group p-4 bg-slate-50 rounded-2xl border border-slate-100 hover:border-indigo-200 hover:bg-indigo-50 transition-all">
                    <div className="w-8 h-8 rounded-full bg-indigo-600 text-white flex items-center justify-center text-xs font-black shrink-0">
                      {i + 1}
                    </div>
                    <p className="text-sm font-bold text-slate-700 leading-snug">{rec}</p>
                  </div>
                ))}
              </div>
            ) : (
              <div className="flex flex-col items-center justify-center py-6 text-slate-400 text-center">
                <Activity size={48} className="opacity-10 mb-4" />
                <p className="text-sm font-medium">Monitoring active. Recommendations will update based on detected deviations.</p>
              </div>
            )}
          </div>

          {/* Clinical Insights */}
          <div className="bg-slate-900 p-8 rounded-[2rem] text-white shadow-2xl relative overflow-hidden">
            <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-600/20 rounded-full blur-3xl"></div>
            <h4 className="font-black text-lg flex items-center gap-2 mb-4 relative z-10 uppercase tracking-widest">
              <Stethoscope size={20} className="text-indigo-400" />
              AI Diagnosis
            </h4>
            <p className="text-sm text-slate-300 leading-relaxed relative z-10 italic">
              {analysis?.feedback || "System calibrated. Awaiting bio-metric input stream..."}
            </p>
          </div>
        </div>
      </div>

      {error && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-red-50 text-red-700 px-6 py-4 rounded-2xl border border-red-100 shadow-2xl flex items-center gap-4 z-50">
          <AlertCircle size={24} />
          <p className="font-bold">{error}</p>
        </div>
      )}
    </div>
  );
};

export default PostureLiveView;

import React, { useEffect, useRef, useState, useMemo } from 'react';
import { 
  Camera, 
  CameraOff, 
  Play, 
  Square, 
  RefreshCw, 
  Zap, 
  AlertCircle, 
  Activity,
  CheckCircle2,
  ScanEye,
  Target,
  ChevronRight,
  ShieldCheck,
  Dumbbell,
  Stethoscope,
  TrendingUp,
  AlertTriangle,
  ArrowUpRight,
  ArrowDownRight,
  Info,
  UserCheck,
  Undo2
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";
import { PostureAnalysis, Landmark, ScoliosisSeverity } from '../types';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

type CalibrationStep = 'idle' | 'instruction' | 'preparing' | 'capturing' | 'complete';

interface SessionDataPoint {
  time: string;
  score: number;
  angle: number;
}

const PostureLiveView: React.FC = () => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const [isActive, setIsActive] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<PostureAnalysis | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [sessionHistory, setSessionHistory] = useState<SessionDataPoint[]>([]);

  // Calibration State
  const [calibrationStep, setCalibrationStep] = useState<CalibrationStep>('idle');
  const [baselineLandmarks, setBaselineLandmarks] = useState<Landmark[] | null>(null);
  const [countdown, setCountdown] = useState(0);

  // Significant Change Logic
  const significantChange = useMemo(() => {
    if (sessionHistory.length < 2) return null;
    const current = sessionHistory[sessionHistory.length - 1];
    const previous = sessionHistory[sessionHistory.length - 2];
    const diff = current.score - previous.score;

    if (Math.abs(diff) > 12) {
      return {
        type: (diff > 0 ? 'improvement' : 'deterioration') as 'improvement' | 'deterioration',
        value: Math.abs(diff)
      };
    }
    return null;
  }, [sessionHistory]);

  // Visual Alert State
  const [activeAlert, setActiveAlert] = useState<'improvement' | 'deterioration' | null>(null);

  useEffect(() => {
    if (significantChange) {
      setActiveAlert(significantChange.type);
      const timer = setTimeout(() => setActiveAlert(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [significantChange]);

  // Toggle Camera
  const toggleCamera = async () => {
    if (isActive) {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
      setIsActive(false);
      setAnalysis(null);
      setCalibrationStep('idle');
      setSessionHistory([]);
      setActiveAlert(null);
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsActive(true);
          setError(null);
        }
      } catch (err) {
        setError("Could not access camera. Please check permissions.");
      }
    }
  };

  // Start Calibration Wizard
  const startCalibrationWizard = () => {
    if (!isActive) return;
    setCalibrationStep('instruction');
  };

  const proceedToCountdown = () => {
    setCalibrationStep('preparing');
    setCountdown(5);
  };

  const clearCalibration = () => {
    setBaselineLandmarks(null);
  };

  // Countdown timer for calibration
  useEffect(() => {
    if (calibrationStep === 'preparing' && countdown > 0) {
      const timer = setTimeout(() => setCountdown(countdown - 1), 1000);
      return () => clearTimeout(timer);
    } else if (calibrationStep === 'preparing' && countdown === 0) {
      captureCalibration();
    }
  }, [calibrationStep, countdown]);

  const captureCalibration = async () => {
    if (!videoRef.current) return;
    setCalibrationStep('capturing');

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `This is a baseline calibration frame for posture analysis. 
              Detect normalized (0-100) coordinates for: Head, LeftShoulder, RightShoulder, SpineCenter, LeftHip, RightHip.
              Return ONLY the JSON list of landmarks.` }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER },
                    y: { type: Type.NUMBER },
                    label: { type: Type.STRING }
                  },
                  required: ['x', 'y', 'label']
                }
              }
            },
            required: ['landmarks']
          }
        }
      });
      const result = JSON.parse(response.text || '{}');
      if (result.landmarks) {
        setBaselineLandmarks(result.landmarks);
        setCalibrationStep('complete');
        setTimeout(() => setCalibrationStep('idle'), 2000);
      }
    } catch (err) {
      console.error("Calibration capture failed:", err);
      setError("Calibration failed. Please try again.");
      setCalibrationStep('idle');
    }
  };

  // Perform AI Analysis on a Frame
  const analyzeFrame = async () => {
    if (!isActive || !videoRef.current || isAnalyzing || calibrationStep !== 'idle') return;

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    setIsAnalyzing(true);
    try {
      const promptText = `Analyze posture in this frame ${baselineLandmarks ? `relative to these baseline NEUTRAL landmarks: ${JSON.stringify(baselineLandmarks)}. These represent the user's "perfect" neutral pose.` : ''}.
           1. Detect current normalized (0-100) coordinates for: Head, LeftShoulder, RightShoulder, SpineCenter, LeftHip, RightHip.
           2. Estimate a simulated 'Postural Cobb Angle' (0-90 degrees) based on shoulder/hip tilt and spinal curvature visible.
           3. Classify severity: <10 is Normal, 10-25 is Mild, 25-45 is Moderate, >45 is Severe.
           4. Provide 3 personalized exercise recommendations.
           5. Calculate an alignment score (0-100) based on deviation from the baseline if provided.
           6. Provide a brief postural feedback string.
           Return ONLY a JSON object.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: promptText }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER },
                    y: { type: Type.NUMBER },
                    label: { type: Type.STRING }
                  },
                  required: ['x', 'y', 'label']
                }
              },
              alignmentScore: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              isDeviating: { type: Type.BOOLEAN },
              estimatedCobbAngle: { type: Type.NUMBER },
              severity: { type: Type.STRING, enum: ['Normal', 'Mild', 'Moderate', 'Severe'] },
              recommendations: { type: Type.ARRAY, items: { type: Type.STRING } }
            },
            required: ['landmarks', 'alignmentScore', 'feedback', 'isDeviating', 'estimatedCobbAngle', 'severity', 'recommendations']
          }
        }
      });

      const result = JSON.parse(response.text || '{}');
      setAnalysis(result);

      const newPoint: SessionDataPoint = {
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
        score: result.alignmentScore,
        angle: result.estimatedCobbAngle || 0
      };
      setSessionHistory(prev => [...prev.slice(-19), newPoint]);
    } catch (err) {
      console.error("Frame analysis failed:", err);
    } finally {
      setIsAnalyzing(false);
    }
  };

  // Interval for analysis
  useEffect(() => {
    let interval: number;
    if (isActive && calibrationStep === 'idle') {
      interval = window.setInterval(analyzeFrame, 4000); 
    }
    return () => clearInterval(interval);
  }, [isActive, isAnalyzing, calibrationStep, baselineLandmarks]);

  // Draw Overlay
  useEffect(() => {
    if (!canvasRef.current || (!analysis && !baselineLandmarks)) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const { width, height } = canvasRef.current;
    ctx.clearRect(0, 0, width, height);

    const drawSkeleton = (points: Landmark[], color: string, isSolid: boolean = true) => {
      const getPt = (label: string) => points.find(p => p.label.toLowerCase().includes(label.toLowerCase()));

      const head = getPt('Head');
      const ls = getPt('LeftShoulder');
      const rs = getPt('RightShoulder');
      const spine = getPt('Spine');
      const lh = getPt('LeftHip');
      const rh = getPt('RightHip');

      ctx.lineWidth = isSolid ? 4 : 2;
      ctx.strokeStyle = color;
      ctx.setLineDash(isSolid ? [] : [5, 5]);
      ctx.shadowBlur = isSolid ? 15 : 0;
      ctx.shadowColor = isSolid ? color : 'transparent';

      const drawLine = (p1?: Landmark, p2?: Landmark) => {
        if (p1 && p2) {
          ctx.beginPath();
          ctx.moveTo(p1.x * width / 100, p1.y * height / 100);
          ctx.lineTo(p2.x * width / 100, p2.y * height / 100);
          ctx.stroke();
        }
      };

      drawLine(head, spine);
      drawLine(ls, rs);
      drawLine(ls, lh);
      drawLine(rs, rh);
      drawLine(lh, rh);
      drawLine(spine, lh);
      drawLine(spine, rh);

      points.forEach(pt => {
        const x = pt.x * width / 100;
        const y = pt.y * height / 100;
        ctx.beginPath();
        ctx.arc(x, y, isSolid ? 6 : 4, 0, Math.PI * 2);
        ctx.fillStyle = color;
        ctx.fill();
      });
    };

    // Draw Ghost Skeleton (Baseline)
    if (baselineLandmarks && isActive) {
      drawSkeleton(baselineLandmarks, 'rgba(99, 102, 241, 0.5)', false);
    }

    // Draw Current Skeleton
    if (analysis?.landmarks && isActive) {
      drawSkeleton(analysis.landmarks, analysis.isDeviating ? '#ef4444' : '#10b981', true);
    }
  }, [analysis, baselineLandmarks, isActive]);

  const getSeverityStyles = (severity?: ScoliosisSeverity) => {
    switch (severity) {
      case ScoliosisSeverity.NORMAL: return 'text-emerald-500 bg-emerald-50 border-emerald-100';
      case ScoliosisSeverity.MILD: return 'text-blue-500 bg-blue-50 border-blue-100';
      case ScoliosisSeverity.MODERATE: return 'text-amber-500 bg-amber-50 border-amber-100';
      case ScoliosisSeverity.SEVERE: return 'text-red-500 bg-red-50 border-red-100';
      default: return 'text-slate-400 bg-slate-50 border-slate-100';
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <style>{`
        @keyframes pulse-emerald {
          0%, 100% { border-color: rgba(16, 185, 129, 1); box-shadow: 0 0 0 0 rgba(16, 185, 129, 0.7); }
          50% { border-color: rgba(16, 185, 129, 0.5); box-shadow: 0 0 30px 10px rgba(16, 185, 129, 0.3); }
        }
        @keyframes pulse-amber {
          0%, 100% { border-color: rgba(245, 158, 11, 1); box-shadow: 0 0 0 0 rgba(245, 158, 11, 0.7); }
          50% { border-color: rgba(245, 158, 11, 0.5); box-shadow: 0 0 30px 10px rgba(245, 158, 11, 0.3); }
        }
        .animate-pulse-emerald { animation: pulse-emerald 1s infinite ease-in-out; }
        .animate-pulse-amber { animation: pulse-amber 1s infinite ease-in-out; }
      `}</style>

      {/* Significant Change Alert Banner */}
      {significantChange && (
        <div className={`flex items-center justify-between p-4 rounded-2xl border animate-in slide-in-from-top-4 ${
          significantChange.type === 'improvement' 
            ? 'bg-emerald-50 border-emerald-200 text-emerald-800' 
            : 'bg-amber-50 border-amber-200 text-amber-800'
        }`}>
          <div className="flex items-center gap-3">
            {significantChange.type === 'improvement' ? <TrendingUp size={24} /> : <AlertTriangle size={24} />}
            <div>
              <p className="font-bold uppercase text-xs tracking-widest">Significant Posture Shift Detected</p>
              <p className="text-sm">Alignment {significantChange.type === 'improvement' ? 'improved' : 'deteriorated'} by {significantChange.value.toFixed(1)}% since last measurement.</p>
            </div>
          </div>
          <button onClick={() => setSessionHistory([])} className="p-2 hover:bg-black/5 rounded-full transition-colors">
            <ChevronRight size={20} />
          </button>
        </div>
      )}

      <div className="flex flex-col xl:flex-row gap-8">
        {/* Monitoring Window */}
        <div className="flex-1 flex flex-col gap-6">
          <div className={`bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl relative aspect-video group border-4 transition-all duration-300 ${
            activeAlert === 'improvement' ? 'border-emerald-500 animate-pulse-emerald' : 
            activeAlert === 'deterioration' ? 'border-amber-500 animate-pulse-amber' : 
