            {/* Calibration Wizard Overlays */}
            {calibrationStep !== 'idle' && (
              <div className="absolute inset-0 bg-indigo-900/80 backdrop-blur-md flex flex-col items-center justify-center text-white z-20 animate-in fade-in duration-300 p-12 text-center">

                {calibrationStep === 'instruction' && (
                  <div className="max-w-md space-y-6 animate-in zoom-in duration-300">
                    <div className="w-20 h-20 bg-white/10 rounded-3xl flex items-center justify-center mx-auto border border-white/20">
                      <ScanEye size={40} className="text-indigo-400" />
                    </div>
                    <h2 className="text-3xl font-black">Geometric Calibration</h2>
                    <p className="text-indigo-100 leading-relaxed font-medium">
                      Position yourself in your ideal <strong>Neutral Pose</strong>. 
                      Ensure your shoulders and hips are clearly visible to the sensor.
                    </p>
                    <div className="flex gap-3">
                      <button 
                        onClick={() => setCalibrationStep('idle')}
                        className="flex-1 py-4 bg-white/10 hover:bg-white/20 rounded-2xl font-bold transition-all border border-white/10"
                      >
                        Cancel
