                      <button 
                        onClick={proceedToCountdown}
                        className="flex-1 py-4 bg-indigo-500 hover:bg-indigo-600 rounded-2xl font-bold shadow-xl shadow-indigo-500/20 transition-all"
                      >
                        Start Calibration
                      </button>
                    </div>
                  </div>
                )}

                {calibrationStep === 'preparing' && (
                  <>
                    <div className="w-32 h-32 rounded-full border-8 border-white/10 flex items-center justify-center mb-8 relative">
                       <div className="absolute inset-0 border-4 border-white rounded-full animate-ping opacity-20"></div>
                       <span className="text-6xl font-black">{countdown}</span>
                    </div>
                    <h2 className="text-3xl font-black mb-2">Recording Baseline</h2>
                    <p className="text-indigo-200 font-medium text-lg uppercase tracking-widest">Stay perfectly still</p>
                  </>
                )}

                {calibrationStep === 'capturing' && (
                  <div className="flex flex-col items-center gap-6">
                    <div className="relative">
                      <RefreshCw size={64} className="animate-spin text-indigo-400" />
                    </div>
                    <div>
                      <p className="font-black text-2xl uppercase tracking-widest mb-2">Analyzing Geometry</p>
                      <p className="text-indigo-300 font-medium">Mapping vertebrae endplates for normalization...</p>
                    </div>
                  </div>
                )}

                {calibrationStep === 'complete' && (
                  <div className="flex flex-col items-center gap-4 animate-in zoom-in duration-300">
                    <div className="w-24 h-24 bg-emerald-500 rounded-full flex items-center justify-center shadow-2xl shadow-emerald-500/40">
                      <CheckCircle2 size={48} />
                    </div>
                    <div>
                      <p className="font-black text-3xl mb-1">Success</p>
                      <p className="text-emerald-100 font-medium">Postural baseline locked.</p>
                    </div>
                  </div>
                )}
              </div>
            )}

            {!isActive && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-white space-y-4">
                <div className="w-20 h-20 bg-white/10 backdrop-blur-md rounded-3xl flex items-center justify-center border border-white/20">
                  <CameraOff size={40} className="text-slate-400" />
                </div>
                <div className="text-center px-8">
                  <p className="font-black text-xl mb-1">Optical Feed Offline</p>
                  <p className="text-slate-400 text-sm font-medium">Open the feed to start monitoring postural shifts and Cobb angle estimation.</p>
                </div>
              </div>
            )}

            {isAnalyzing && (
              <div className="absolute bottom-8 right-8 flex items-center gap-2 bg-indigo-600 px-4 py-2 rounded-xl text-white text-xs font-bold shadow-lg animate-pulse z-10">
                <RefreshCw size={14} className="animate-spin" />
                AI Analysis Active
              </div>
            )}

            <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-4 transition-transform group-hover:scale-105 duration-300 z-10">
              <button 
                onClick={toggleCamera}
                className={`flex items-center gap-3 px-8 py-4 rounded-2xl font-black text-sm uppercase tracking-widest transition-all ${
                  isActive 
                    ? 'bg-white/10 backdrop-blur-md text-white border border-white/20 hover:bg-white/20' 
                    : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-xl shadow-indigo-500/20'
                }`}
              >
                {isActive ? <><Square size={18} /> Stop Session</> : <><Play size={18} /> Start Session</>}
              </button>

              {isActive && (
                <div className="flex gap-2">
                  <button 
                    onClick={startCalibrationWizard}
                    disabled={calibrationStep !== 'idle'}
                    className="flex items-center gap-3 px-8 py-4 bg-indigo-600 text-white rounded-2xl font-black text-sm uppercase tracking-widest hover:bg-indigo-700 shadow-xl shadow-indigo-500/30 transition-all disabled:opacity-50"
                  >
                    <Target size={18} />
                    {baselineLandmarks ? 'Reset Base' : 'Calibrate'}
                  </button>
                  {baselineLandmarks && (
                    <button 
                      onClick={clearCalibration}
                      className="p-4 bg-white/10 backdrop-blur-md text-white border border-white/20 rounded-2xl hover:bg-red-500/20 hover:text-red-400 transition-all"
                      title="Clear Baseline"
                    >
                      <Undo2 size={18} />
                    </button>
                  )}
                </div>
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col justify-between group hover:border-indigo-100 transition-all">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Est. Cobb Angle</p>
              <div className="flex items-baseline gap-2">
                <p className="text-4xl font-black text-slate-800">{analysis?.estimatedCobbAngle ? `${analysis.estimatedCobbAngle}°` : '--°'}</p>
                <span className="text-[10px] font-bold text-slate-400 italic">Optical Est.</span>
              </div>
            </div>
            <div className={`p-6 rounded-3xl border shadow-sm flex flex-col justify-between transition-colors ${getSeverityStyles(analysis?.severity as ScoliosisSeverity)}`}>
              <p className="text-[10px] font-black uppercase tracking-widest mb-1 opacity-70">Scoliosis Indicator</p>
              <p className="text-3xl font-black">{analysis?.severity || '--'}</p>
            </div>
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col justify-between group hover:border-indigo-100 transition-all">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Alignment Score</p>
              <p className="text-4xl font-black text-indigo-600">{analysis ? `${analysis.alignmentScore}%` : '--%'}</p>
            </div>
          </div>
        </div>

        {/* Analytics & Feedback Sidebar */}
        <div className="w-full xl:w-96 space-y-6">
          {/* Posture Trend Analytics */}
          <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-lg relative overflow-hidden">
            <div className="absolute top-0 left-0 w-2 h-full bg-indigo-500 opacity-20"></div>
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2">
                <TrendingUp size={24} className="text-indigo-600" />
                Live Trends
              </h3>
              {sessionHistory.length > 0 && (
                <div className="flex items-center gap-1.5 px-2 py-1 bg-indigo-50 text-indigo-600 text-[10px] font-black rounded-lg border border-indigo-100">
                  <div className="w-1.5 h-1.5 bg-indigo-600 rounded-full animate-pulse"></div>
                  RECORDING
                </div>
              )}
            </div>

            <div className="h-48 w-full -ml-4">
              {sessionHistory.length > 1 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={sessionHistory}>
                    <defs>
                      <linearGradient id="colorScore" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#4f46e5" stopOpacity={0.1}/>
                        <stop offset="95%" stopColor="#4f46e5" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                    <XAxis dataKey="time" hide />
                    <YAxis domain={[0, 100]} hide />
                    <Tooltip 
                      contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                      labelStyle={{ fontSize: '10px', fontWeight: 'bold' }}
                    />
                    <Area type="monotone" dataKey="score" stroke="#4f46e5" strokeWidth={3} fillOpacity={1} fill="url(#colorScore)" />
                    {sessionHistory.filter(p => p.isEvent).map((p, i) => (
                      <ReferenceDot 
                        key={i} 
                        x={p.time} 
                        y={p.score} 
                        r={4} 
                        fill={p.score > (sessionHistory[sessionHistory.indexOf(p)-1]?.score || 0) ? '#10b981' : '#f59e0b'} 
                        stroke="white" 
                        strokeWidth={2}
                      />
                    ))}
                  </AreaChart>
                </ResponsiveContainer>
              ) : (
                <div className="h-full flex flex-col items-center justify-center text-slate-300 text-center px-6">
                  <Activity size={32} className="opacity-20 mb-2" />
                  <p className="text-xs font-bold uppercase tracking-widest leading-relaxed">Insufficient Samples<br/><span className="text-[10px] font-medium normal-case text-slate-400">Trend data will populate as you move</span></p>
                </div>
              )}
            </div>

            <div className="mt-4 flex justify-between text-[10px] font-black uppercase text-slate-400">
              <span>Start</span>
              <span>Realtime</span>
            </div>
          </div>

          {/* Session Highlights / Event Log */}
          <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-lg">
            <h3 className="text-xl font-black text-slate-800 mb-6 flex items-center gap-2">
              <History size={24} className="text-indigo-600" />
              Session Log
            </h3>

            <div className="space-y-4">
              {sessionEvents.length > 0 ? sessionEvents.map((event) => (
                <div key={event.id} className="flex gap-4 group p-4 bg-slate-50 rounded-2xl border border-slate-100 hover:border-indigo-200 hover:bg-indigo-50 transition-all animate-in slide-in-from-left-2">
                  <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 shadow-sm ${
                    event.type === 'improvement' ? 'bg-emerald-100 text-emerald-600' : 'bg-amber-100 text-amber-600'
                  }`}>
                    {event.type === 'improvement' ? <ArrowUpRight size={20} /> : <ArrowDownRight size={20} />}
                  </div>
                  <div className="flex-1">
                    <div className="flex justify-between items-center mb-1">
                      <p className="text-xs font-black uppercase tracking-widest text-slate-400">{event.time}</p>
                      <span className={`text-[10px] font-black px-2 py-0.5 rounded-md ${
                        event.type === 'improvement' ? 'bg-emerald-500 text-white' : 'bg-amber-500 text-white'
                      }`}>
                        {event.type === 'improvement' ? 'CORRECTION' : 'SHIFT'}
                      </span>
                    </div>
                    <p className="text-sm font-bold text-slate-800 mb-1">{event.type === 'improvement' ? 'Improved Alignment' : 'Alignment Slump'}</p>
                    <p className="text-[10px] text-slate-500 font-medium italic">"{event.feedback.split('.')[0]}..."</p>
                  </div>
