import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult, ScoliosisSeverity } from "../types";

export async function analyzeXRay(base64Image: string): Promise<AnalysisResult> {
  // Initialize AI client right before making the call as per SDK guidelines.
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'image/png',
            data: base64Image,
          },
        },
        {
          text: `You are a radiologist assistant. Analyze this spinal X-ray for Scoliosis. 
          1. Identify the most significant lateral curvature.
          2. Calculate the simulated Cobb Angle (the angle between the most tilted vertebrae).
          3. Classify severity: <10° is Normal, 10-25° is Mild, 25-45° is Moderate, >45° is Severe.
          4. Provide 3 specific physical therapy exercises suitable for this condition.
          5. Identify the top endplate and bottom endplate of the curve. Provide their coordinates (x1, y1, x2, y2) on a scale of 0-100 where 0,0 is top-left and 100,100 is bottom-right.
          Return ONLY a JSON object.`
        }
      ],
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          cobbAngle: { type: Type.NUMBER, description: 'Calculated Cobb angle in degrees' },
          severity: { type: Type.STRING, enum: ['Normal', 'Mild', 'Moderate', 'Severe'] },
          recommendations: { type: Type.ARRAY, items: { type: Type.STRING } },
          visualObservations: { type: Type.STRING, description: 'Summary of visual findings' },
          markers: {
            type: Type.OBJECT,
            properties: {
              topLine: {
                type: Type.OBJECT,
                properties: {
                  x1: { type: Type.NUMBER }, y1: { type: Type.NUMBER },
                  x2: { type: Type.NUMBER }, y2: { type: Type.NUMBER }
                },
                required: ['x1', 'y1', 'x2', 'y2']
              },
              bottomLine: {
                type: Type.OBJECT,
                properties: {
                  x1: { type: Type.NUMBER }, y1: { type: Type.NUMBER },
                  x2: { type: Type.NUMBER }, y2: { type: Type.NUMBER }
                },
                required: ['x1', 'y1', 'x2', 'y2']
              }
            },
            required: ['topLine', 'bottomLine']
          }
        },
        required: ['cobbAngle', 'severity', 'recommendations', 'visualObservations', 'markers']
      }
    }
  });

  // Property access is correct: response.text (not a method).
  const rawResult = JSON.parse(response.text || '{}');

  return {
    id: Math.random().toString(36).substr(2, 9),
    timestamp: new Date().toISOString(),
    cobbAngle: rawResult.cobbAngle,
    severity: rawResult.severity as ScoliosisSeverity,
    recommendations: rawResult.recommendations,
    visualObservations: rawResult.visualObservations,
    markers: rawResult.markers
  };
}

import React, { useEffect, useRef, useState, useMemo } from 'react';
import { 
  Camera, 
  CameraOff, 
  Play, 
  Square, 
  RefreshCw, 
  Zap, 
  AlertCircle, 
  Activity,
  CheckCircle2,
  ScanEye,
  Target,
  ChevronRight,
  ShieldCheck,
  Dumbbell,
  Stethoscope,
  TrendingUp,
  AlertTriangle,
  ArrowUpRight,
  ArrowDownRight,
  Info,
  UserCheck,
  Undo2,
  Clock,
  History,
  Timer,
  Waves,
  Lightbulb,
  ArrowRight
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";
import { PostureAnalysis, Landmark, ScoliosisSeverity } from '../types';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceLine } from 'recharts';

type CalibrationStep = 'idle' | 'instruction' | 'preparing' | 'capturing' | 'complete';

interface SessionEvent {
  id: string;
  time: string;
  type: 'improvement' | 'deterioration';
  score: number;
  delta: number;
  feedback: string;
}

interface SessionDataPoint {
  time: string;
  timestamp: number;
  score: number;
  angle: number;
  landmarks?: Landmark[];
  isEvent?: boolean;
}

const PostureLiveView: React.FC = () => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const [isActive, setIsActive] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<PostureAnalysis | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [sessionHistory, setSessionHistory] = useState<SessionDataPoint[]>([]);
  const [sessionEvents, setSessionEvents] = useState<SessionEvent[]>([]);
  const [startTime, setStartTime] = useState<number | null>(null);

  // Calibration State
  const [calibrationStep, setCalibrationStep] = useState<CalibrationStep>('idle');
  const [baselineLandmarks, setBaselineLandmarks] = useState<Landmark[] | null>(null);
  const [countdown, setCountdown] = useState(0);

  // Significant Change Logic
  const significantChange = useMemo(() => {
    if (sessionHistory.length < 2) return null;
    const current = sessionHistory[sessionHistory.length - 1];
    const previous = sessionHistory[sessionHistory.length - 2];
    const diff = current.score - previous.score;

    if (Math.abs(diff) > 12) {
      return {
        type: (diff > 0 ? 'improvement' : 'deterioration') as 'improvement' | 'deterioration',
        value: Math.abs(diff)
      };
    }
    return null;
  }, [sessionHistory]);

  // Stability Index (Standard deviation of last 5 scores)
  const stabilityIndex = useMemo(() => {
    if (sessionHistory.length < 3) return 100;
    const lastScores = sessionHistory.slice(-5).map(p => p.score);
    const mean = lastScores.reduce((a, b) => a + b, 0) / lastScores.length;
    const variance = lastScores.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / lastScores.length;
    return Math.max(0, 100 - Math.sqrt(variance) * 5);
  }, [sessionHistory]);

  // Dynamic Aura Color based on current score
  const auraStyles = useMemo(() => {
    if (!analysis) return { glow: 'transparent', border: 'border-slate-800' };
    const score = analysis.alignmentScore;
    if (score > 85) return { glow: 'rgba(16, 185, 129, 0.2)', border: 'border-emerald-500/50 shadow-emerald-500/20' };
    if (score > 70) return { glow: 'rgba(79, 70, 229, 0.15)', border: 'border-indigo-500/50 shadow-indigo-500/20' };
    if (score > 50) return { glow: 'rgba(245, 158, 11, 0.2)', border: 'border-amber-500/50 shadow-amber-500/20' };
    return { glow: 'rgba(239, 68, 68, 0.25)', border: 'border-red-500/50 shadow-red-500/20' };
  }, [analysis]);

  // Visual Alert State
  const [activeAlert, setActiveAlert] = useState<'improvement' | 'deterioration' | null>(null);

  useEffect(() => {
    if (significantChange) {
      setActiveAlert(significantChange.type);
      const timer = setTimeout(() => setActiveAlert(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [significantChange]);

  // Session Statistics
  const sessionStats = useMemo(() => {
    if (sessionHistory.length === 0) return null;
    const scores = sessionHistory.map(d => d.score);
    const angles = sessionHistory.map(d => d.angle);
    return {
      avgScore: Math.round(scores.reduce((a, b) => a + b, 0) / scores.length),
      maxAngle: Math.max(...angles),
      minScore: Math.min(...scores),
      duration: startTime ? Math.round((Date.now() - startTime) / 1000 / 60) : 0
    };
  }, [sessionHistory, startTime]);

  // Toggle Camera
  const toggleCamera = async () => {
    if (isActive) {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
      setIsActive(false);
      setAnalysis(null);
      setCalibrationStep('idle');
      setActiveAlert(null);
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsActive(true);
          setStartTime(Date.now());
          setSessionHistory([]);
          setSessionEvents([]);
          setError(null);
        }
      } catch (err) {
        setError("Could not access camera. Please check permissions.");
      }
    }
  };

  const startCalibrationWizard = () => {
    if (!isActive) return;
    setCalibrationStep('instruction');
  };

  const proceedToCountdown = () => {
    setCalibrationStep('preparing');
    setCountdown(5);
  };

  const clearCalibration = () => {
    setBaselineLandmarks(null);
  };

  useEffect(() => {
    if (calibrationStep === 'preparing' && countdown > 0) {
      const timer = setTimeout(() => setCountdown(countdown - 1), 1000);
      return () => clearTimeout(timer);
    } else if (calibrationStep === 'preparing' && countdown === 0) {
      captureCalibration();
    }
  }, [calibrationStep, countdown]);

  const captureCalibration = async () => {
    if (!videoRef.current) return;
    setCalibrationStep('capturing');

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `Detect normalized (0-100) coordinates for posture landmarks: Head, LeftShoulder, RightShoulder, SpineCenter, LeftHip, RightHip. Return ONLY JSON.` }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER },
                    y: { type: Type.NUMBER },
                    label: { type: Type.STRING }
                  },
                  required: ['x', 'y', 'label']
                }
              }
            },
            required: ['landmarks']
          }
        }
      });
      const result = JSON.parse(response.text || '{}');
      if (result.landmarks) {
        setBaselineLandmarks(result.landmarks);
        setCalibrationStep('complete');
        setTimeout(() => setCalibrationStep('idle'), 2000);
      }
    } catch (err) {
      setError("Calibration failed. Please try again.");
      setCalibrationStep('idle');
    }
  };

  const analyzeFrame = async () => {
    if (!isActive || !videoRef.current || isAnalyzing || calibrationStep !== 'idle') return;

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const promptText = `Analyze posture ${baselineLandmarks ? `relative to baseline: ${JSON.stringify(baselineLandmarks)}` : ''}.
           1. Detect normalized landmarks (0-100): Head, LeftShoulder, RightShoulder, SpineCenter, LeftHip, RightHip.
           2. Estimate simulated Cobb Angle (0-90°).
           3. Classify severity.
           4. alignmentScore (0-100).
           5. feedback: concise clinical tip.
           6. recommendations: 3 short exercise names.
           Return JSON.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: promptText }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER },
                    y: { type: Type.NUMBER },
                    label: { type: Type.STRING }
                  },
                  required: ['x', 'y', 'label']
                }
              },
              alignmentScore: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              isDeviating: { type: Type.BOOLEAN },
              estimatedCobbAngle: { type: Type.NUMBER },
              severity: { type: Type.STRING, enum: ['Normal', 'Mild', 'Moderate', 'Severe'] },
              recommendations: { type: Type.ARRAY, items: { type: Type.STRING } }
            },
            required: ['landmarks', 'alignmentScore', 'feedback', 'isDeviating', 'estimatedCobbAngle', 'severity', 'recommendations']
          }
        }
      });

      const result = JSON.parse(response.text || '{}');
      setAnalysis(result);

      const currentTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

      if (sessionHistory.length > 0) {
        const lastPoint = sessionHistory[sessionHistory.length - 1];
        const delta = result.alignmentScore - lastPoint.score;
        if (Math.abs(delta) > 15) {
          setSessionEvents(prev => [{
            id: Math.random().toString(36).substr(2, 9),
            time: currentTime,
            type: delta > 0 ? 'improvement' : 'deterioration',
            score: result.alignmentScore,
            delta: Math.abs(delta),
            feedback: result.feedback
          }, ...prev.slice(0, 4)]);
        }
      }

      const newPoint: SessionDataPoint = {
        time: currentTime,
        timestamp: Date.now(),
        score: result.alignmentScore,
        angle: result.estimatedCobbAngle || 0,
        landmarks: result.landmarks,
        isEvent: Math.abs((sessionHistory[sessionHistory.length-1]?.score || result.alignmentScore) - result.alignmentScore) > 15
      };
      setSessionHistory(prev => [...prev.slice(-44), newPoint]); 
    } catch (err) {
      console.error(err);
    } finally {
      setIsAnalyzing(false);
    }
  };

  useEffect(() => {
    let interval: number;
    if (isActive && calibrationStep === 'idle') {
      interval = window.setInterval(analyzeFrame, 4000); 
    }
    return () => clearInterval(interval);
  }, [isActive, isAnalyzing, calibrationStep, baselineLandmarks]);

  useEffect(() => {
    if (!canvasRef.current || (!analysis && !baselineLandmarks)) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const { width, height } = canvasRef.current;
    ctx.clearRect(0, 0, width, height);

    const drawSkeleton = (points: Landmark[], color: string, alpha: number = 1, isSolid: boolean = true) => {
      const getPt = (label: string) => points.find(p => p.label.toLowerCase().includes(label.toLowerCase()));

      const head = getPt('Head');
      const ls = getPt('LeftShoulder');
      const rs = getPt('RightShoulder');
      const spine = getPt('Spine');
      const lh = getPt('LeftHip');
      const rh = getPt('RightHip');

      ctx.globalAlpha = alpha;
      ctx.lineWidth = isSolid ? 4 : 2;
      ctx.strokeStyle = color;
      ctx.setLineDash(isSolid ? [] : [5, 5]);

      const drawLine = (p1?: Landmark, p2?: Landmark) => {
        if (p1 && p2) {
          ctx.beginPath();
          ctx.moveTo(p1.x * width / 100, p1.y * height / 100);
          ctx.lineTo(p2.x * width / 100, p2.y * height / 100);
          ctx.stroke();
        }
      };

      drawLine(head, spine);
      drawLine(ls, rs);
      drawLine(ls, lh);
      drawLine(rs, rh);
      drawLine(lh, rh);
      drawLine(spine, lh);
      drawLine(spine, rh);

      points.forEach(pt => {
        const x = pt.x * width / 100;
        const y = pt.y * height / 100;
        ctx.beginPath();
        ctx.arc(x, y, isSolid ? 6 : 4, 0, Math.PI * 2);
        ctx.fillStyle = color;
        ctx.fill();
      });
      ctx.globalAlpha = 1;
    };

    if (baselineLandmarks && isActive) {
      drawSkeleton(baselineLandmarks, 'rgba(99, 102, 241, 0.4)', 1, false);
    }

    if (analysis?.landmarks && isActive) {
      drawSkeleton(analysis.landmarks, analysis.isDeviating ? '#ef4444' : '#10b981', 1, true);
    }
  }, [analysis, baselineLandmarks, isActive]);

  const getSeverityStyles = (severity?: ScoliosisSeverity) => {
    switch (severity) {
      case ScoliosisSeverity.NORMAL: return 'text-emerald-500 bg-emerald-50 border-emerald-100';
      case ScoliosisSeverity.MILD: return 'text-blue-500 bg-blue-50 border-blue-100';
      case ScoliosisSeverity.MODERATE: return 'text-amber-500 bg-amber-50 border-amber-100';
      case ScoliosisSeverity.SEVERE: return 'text-red-500 bg-red-50 border-red-100';
      default: return 'text-slate-400 bg-slate-50 border-slate-100';
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      {significantChange && (
        <div className={`flex items-center justify-between p-4 rounded-2xl border animate-in slide-in-from-top-4 ${
          significantChange.type === 'improvement' ? 'bg-emerald-50 border-emerald-200 text-emerald-800' : 'bg-amber-50 border-amber-200 text-amber-800'
        }`}>
          <div className="flex items-center gap-3">
            {significantChange.type === 'improvement' ? <TrendingUp size={24} /> : <AlertTriangle size={24} />}
            <div>
              <p className="font-bold uppercase text-xs tracking-widest">Postural Change</p>
              <p className="text-sm">Alignment {significantChange.type === 'improvement' ? 'improved' : 'deviated'} by {significantChange.value.toFixed(1)}%.</p>
            </div>
          </div>
          <button onClick={() => setSessionHistory([])} className="p-2 hover:bg-black/5 rounded-full"><ChevronRight size={20} /></button>
        </div>
      )}

      <div className="flex flex-col xl:flex-row gap-8">
        <div className="flex-1 flex flex-col gap-6">
          <div className={`bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl relative aspect-video group border-4 transition-all duration-700 ${auraStyles.border}`}>
            <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity duration-700 ${isActive ? 'opacity-100' : 'opacity-20'}`} />

            {/* Real-time Graph Overlay */}
            {isActive && sessionHistory.length > 1 && (
              <div className="absolute inset-x-0 bottom-0 h-1/4 pointer-events-none opacity-40 z-0">
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={sessionHistory} margin={{ top: 0, right: 0, left: 0, bottom: 0 }}>
                    <defs>
                      <linearGradient id="scoreOverlay" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#818cf8" stopOpacity={0.6}/>
                        <stop offset="95%" stopColor="#818cf8" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <Area 
                      type="monotone" 
                      dataKey="score" 
                      stroke="#ffffff" 
                      strokeWidth={1} 
                      fillOpacity={1} 
                      fill="url(#scoreOverlay)" 
                      isAnimationActive={true}
                      animationDuration={1500}
                    />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
            )}

            <div className="absolute inset-0 aura-overlay" style={{ background: `radial-gradient(circle, transparent 40%, ${auraStyles.glow} 100%)` }} />

            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none" width={640} height={480} />

            <div className="absolute top-8 left-8 flex items-center gap-3">
              <div className={`w-3 h-3 rounded-full ${isActive ? 'bg-red-500 animate-pulse' : 'bg-slate-600'}`}></div>
              <span className="text-white text-xs font-black tracking-widest uppercase opacity-80">
                {isActive ? 'Live Bio-Feedback' : 'Camera Off'}
              </span>
            </div>

            {isActive && (
              <div className="absolute top-8 right-8 flex flex-col items-end gap-2">
                <div className="bg-black/40 backdrop-blur-md px-4 py-2 rounded-xl border border-white/10 flex items-center gap-3">
                  <Waves size={16} className={`text-indigo-400 ${stabilityIndex < 60 ? 'animate-bounce' : ''}`} />
                  <div>
                    <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest leading-none mb-1">Stability</p>
                    <p className="text-sm font-black text-white">{Math.round(stabilityIndex)}%</p>
                  </div>
                </div>
                {baselineLandmarks && (
                   <div className="bg-indigo-600/90 px-3 py-1.5 rounded-lg text-white text-[10px] font-black uppercase tracking-widest shadow-lg flex items-center gap-2">
                      <ShieldCheck size={14} /> Profile Locked
                   </div>
                )}
              </div>
            )}

            {calibrationStep !== 'idle' && (
              <div className="absolute inset-0 bg-indigo-900/80 backdrop-blur-md flex flex-col items-center justify-center text-white z-20 animate-in fade-in p-12 text-center">
                {calibrationStep === 'instruction' && (
                  <div className="max-w-md space-y-6">
                    <div className="w-20 h-20 bg-white/10 rounded-3xl flex items-center justify-center mx-auto border border-white/20"><ScanEye size={40} className="text-indigo-400" /></div>
                    <h2 className="text-3xl font-black">Clinical Baseline</h2>
                    <p className="text-indigo-100 font-medium">Please stand centered and face the camera directly to calibrate your neutral posture.</p>
                    <div className="flex gap-3">
                      <button onClick={() => setCalibrationStep('idle')} className="flex-1 py-4 bg-white/10 rounded-2xl font-bold">Cancel</button>
                      <button onClick={proceedToCountdown} className="flex-1 py-4 bg-indigo-500 rounded-2xl font-bold">Start</button>
                    </div>
                  </div>
                )}
                {calibrationStep === 'preparing' && (
                  <><div className="w-32 h-32 rounded-full border-8 border-white/10 flex items-center justify-center mb-8 relative"><span className="text-6xl font-black">{countdown}</span></div><h2 className="text-3xl font-black mb-2">Analyzing Pose</h2></>
                )}
                {calibrationStep === 'complete' && (
                  <div className="flex flex-col items-center gap-4"><div className="w-24 h-24 bg-emerald-500 rounded-full flex items-center justify-center"><CheckCircle2 size={48} /></div><p className="font-black text-3xl">Calibration Complete</p></div>
                )}
              </div>
            )}

            {!isActive && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-white space-y-4">
                <div className="w-20 h-20 bg-white/10 backdrop-blur-md rounded-3xl flex items-center justify-center text-slate-400"><CameraOff size={40} /></div>
                <div className="text-center px-8">
                  <p className="font-black text-xl mb-1">System Ready</p>
                  <p className="text-slate-400 text-sm font-medium">Initialize monitoring for real-time skeletal feedback.</p>
                </div>
              </div>
            )}

            {isAnalyzing && (
              <div className="absolute bottom-8 right-8 flex items-center gap-2 bg-indigo-600 px-4 py-2 rounded-xl text-white text-xs font-bold shadow-lg animate-pulse z-10">
                <RefreshCw size={14} className="animate-spin" /> Analyzing Vectors...
              </div>
            )}

            <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-4 group-hover:scale-105 transition-transform z-10">
              <button onClick={toggleCamera} className={`flex items-center gap-3 px-8 py-4 rounded-2xl font-black text-sm uppercase tracking-widest transition-all ${isActive ? 'bg-white/10 backdrop-blur-md text-white border border-white/20 hover:bg-white/20' : 'bg-indigo-600 text-white shadow-xl shadow-indigo-500/20'}`}>
                {isActive ? <><Square size={18} /> Stop Feed</> : <><Play size={18} /> Start Feed</>}
              </button>
              {isActive && (
                <div className="flex gap-2">
                  <button onClick={startCalibrationWizard} disabled={calibrationStep !== 'idle'} className="flex items-center gap-3 px-8 py-4 bg-indigo-600 text-white rounded-2xl font-black text-sm uppercase tracking-widest shadow-lg shadow-indigo-500/30 disabled:opacity-50">
                    <Target size={18} /> {baselineLandmarks ? 'Re-Calibrate' : 'Calibrate'}
                  </button>
                  {baselineLandmarks && <button onClick={clearCalibration} className="p-4 bg-white/10 backdrop-blur-md text-white border border-white/20 rounded-2xl hover:bg-red-500/20 transition-all"><Undo2 size={18} /></button>}
                </div>
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col justify-between hover:border-indigo-100 transition-all">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Geometric Cobb Angle</p>
              <p className="text-4xl font-black text-slate-800">{analysis?.estimatedCobbAngle ? `${analysis.estimatedCobbAngle}°` : '--°'}</p>
            </div>
            <div className={`p-6 rounded-3xl border shadow-sm flex flex-col justify-between transition-colors ${getSeverityStyles(analysis?.severity as ScoliosisSeverity)}`}>
              <p className="text-[10px] font-black uppercase tracking-widest mb-1 opacity-70">Curvature Risk</p>
              <p className="text-3xl font-black">{analysis?.severity || '--'}</p>
            </div>
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col justify-between hover:border-indigo-100 transition-all">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Alignment Accuracy</p>
              <p className="text-4xl font-black text-indigo-600">{analysis ? `${analysis.alignmentScore}%` : '--%'}</p>
            </div>
          </div>
        </div>

        <div className="w-full xl:w-96 space-y-6">
          <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-lg">
            <h3 className="text-xl font-black text-slate-800 flex items-center gap-2 mb-6"><TrendingUp size={24} className="text-indigo-600" /> Dynamics</h3>
            <div className="h-48 w-full -ml-4">
              {sessionHistory.length > 1 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={sessionHistory}>
                    <defs><linearGradient id="colorScoreMain" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#4f46e5" stopOpacity={0.1}/><stop offset="95%" stopColor="#4f46e5" stopOpacity={0}/></linearGradient></defs>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                    <XAxis dataKey="time" hide />
                    <YAxis domain={[0, 100]} hide />
                    <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }} />
                    <Area type="monotone" dataKey="score" stroke="#4f46e5" strokeWidth={3} fillOpacity={1} fill="url(#colorScoreMain)" />
                  </AreaChart>
                </ResponsiveContainer>
              ) : (
                <div className="h-full flex flex-col items-center justify-center text-slate-300"><Activity size={32} className="opacity-20 mb-2" /><p className="text-[10px] font-black uppercase tracking-widest">Awaiting Samples</p></div>
              )}
            </div>
          </div>

          <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-lg">
            <h3 className="text-xl font-black text-slate-800 mb-6 flex items-center gap-2"><History size={24} className="text-indigo-600" /> Session Trace</h3>
            <div className="space-y-4">
              {sessionEvents.length > 0 ? sessionEvents.map((event) => (
                <div key={event.id} className="flex gap-4 p-4 bg-slate-50 rounded-2xl border border-slate-100 animate-in slide-in-from-left-2">
                  <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${event.type === 'improvement' ? 'bg-emerald-100 text-emerald-600' : 'bg-amber-100 text-amber-600'}`}>{event.type === 'improvement' ? <ArrowUpRight size={20} /> : <ArrowDownRight size={20} />}</div>
                  <div className="flex-1">
                    <p className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-1">{event.time} • {event.type === 'improvement' ? 'Correction' : 'Shift'}</p>
                    <p className="text-sm font-bold text-slate-800">Score: {event.score}% ({event.type === 'improvement' ? '+' : '-'}{event.delta}%)</p>
                  </div>
                </div>
              )) : (
                <div className="flex flex-col items-center justify-center py-6 text-slate-400 opacity-60"><Clock size={32} className="mb-2" /><p className="text-xs font-medium">Tracking baseline stability...</p></div>
              )}
            </div>
          </div>

          <div className="bg-indigo-50 p-6 rounded-[2rem] border border-indigo-100">
             <div className="flex items-center gap-3 mb-4">
                <Lightbulb size={20} className="text-indigo-600" />
                <h4 className="font-black text-xs uppercase tracking-widest text-indigo-800">Clinical Tip</h4>
             </div>
             <p className="text-sm text-indigo-700 leading-relaxed italic">
                {analysis?.feedback || "Sensors monitoring symmetry. Maintain a neutral posture for initial diagnostic scan."}
             </p>
             {analysis?.recommendations && (
               <div className="mt-4 pt-4 border-t border-indigo-200">
                 <div className="flex flex-wrap gap-2">
                   {analysis.recommendations.map((r, i) => (
                     <span key={i} className="px-2 py-1 bg-white rounded-lg text-[10px] font-bold text-indigo-600 border border-indigo-200">{r}</span>
                   ))}
                 </div>
               </div>
             )}
          </div>
        </div>
      </div>

      {error && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-red-50 text-red-700 px-6 py-4 rounded-2xl border border-red-100 shadow-2xl flex items-center gap-4 z-50 animate-in slide-in-from-bottom-4">
          <AlertCircle size={24} /> <p className="font-bold">{error}</p> <button onClick={() => setError(null)} className="ml-4"><ChevronRight size={18} /></button>
        </div>
      )}
    </div>
  );
};

export default PostureLiveView;

import React, { useEffect, useRef, useState, useMemo } from 'react';
import { 
  Camera, 
  CameraOff, 
  Play, 
  Square, 
  RefreshCw, 
  Zap, 
  AlertCircle, 
  Activity,
  CheckCircle2,
  ScanEye,
  Target,
  ChevronRight,
  ShieldCheck,
  Dumbbell,
  Stethoscope,
  TrendingUp,
  AlertTriangle,
  ArrowUpRight,
  ArrowDownRight,
  Info,
  UserCheck,
  Undo2,
  Clock,
  History,
  Timer,
  Waves,
  Lightbulb,
  ArrowRight,
  MoveUp,
  MoveDown
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";
import { PostureAnalysis, Landmark, ScoliosisSeverity } from '../types';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceLine } from 'recharts';

type CalibrationStep = 'idle' | 'instruction' | 'preparing' | 'capturing' | 'complete';

interface SessionEvent {
  id: string;
  time: string;
  type: 'improvement' | 'deterioration';
  score: number;
  delta: number;
  feedback: string;
}

interface SessionDataPoint {
  time: string;
  timestamp: number;
  score: number;
  angle: number;
  landmarks?: Landmark[];
  isEvent?: boolean;
}

const PostureLiveView: React.FC = () => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const [isActive, setIsActive] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<PostureAnalysis | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [sessionHistory, setSessionHistory] = useState<SessionDataPoint[]>([]);
  const [sessionEvents, setSessionEvents] = useState<SessionEvent[]>([]);
  const [startTime, setStartTime] = useState<number | null>(null);

  // Real-time Visual indicators
  const [lastGhostLandmarks, setLastGhostLandmarks] = useState<Landmark[] | null>(null);
  const [deltaIndicator, setDeltaIndicator] = useState<{ value: number, type: 'plus' | 'minus' } | null>(null);

  // Calibration State
  const [calibrationStep, setCalibrationStep] = useState<CalibrationStep>('idle');
  const [baselineLandmarks, setBaselineLandmarks] = useState<Landmark[] | null>(null);
  const [countdown, setCountdown] = useState(0);

  // Significant Change Logic
  const significantChange = useMemo(() => {
    if (sessionHistory.length < 2) return null;
    const current = sessionHistory[sessionHistory.length - 1];
    const previous = sessionHistory[sessionHistory.length - 2];
    const diff = current.score - previous.score;

    if (Math.abs(diff) > 10) {
      return {
        type: (diff > 0 ? 'improvement' : 'deterioration') as 'improvement' | 'deterioration',
        value: Math.abs(diff)
      };
    }
    return null;
  }, [sessionHistory]);

  // Stability Index
  const stabilityIndex = useMemo(() => {
    if (sessionHistory.length < 3) return 100;
    const lastScores = sessionHistory.slice(-5).map(p => p.score);
    const mean = lastScores.reduce((a, b) => a + b, 0) / lastScores.length;
    const variance = lastScores.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / lastScores.length;
    return Math.max(0, 100 - Math.sqrt(variance) * 5);
  }, [sessionHistory]);

  // Dynamic Aura Color
  const auraStyles = useMemo(() => {
    if (!analysis) return { glow: 'transparent', border: 'border-slate-800' };
    const score = analysis.alignmentScore;
    if (score > 85) return { glow: 'rgba(16, 185, 129, 0.1)', border: 'border-emerald-500/40 shadow-emerald-500/10' };
    if (score > 70) return { glow: 'rgba(79, 70, 229, 0.1)', border: 'border-indigo-500/40 shadow-indigo-500/10' };
    if (score > 50) return { glow: 'rgba(245, 158, 11, 0.15)', border: 'border-amber-500/40 shadow-amber-500/10' };
    return { glow: 'rgba(239, 68, 68, 0.2)', border: 'border-red-500/60 shadow-red-500/20' };
  }, [analysis]);

  const [activeAlert, setActiveAlert] = useState<'improvement' | 'deterioration' | null>(null);

  useEffect(() => {
    if (significantChange) {
      setActiveAlert(significantChange.type);
      setDeltaIndicator({
        value: Math.round(significantChange.value),
        type: significantChange.type === 'improvement' ? 'plus' : 'minus'
      });

      const timer = setTimeout(() => {
        setActiveAlert(null);
        setDeltaIndicator(null);
      }, 3000);
      return () => clearTimeout(timer);
    }
  }, [significantChange]);

  const toggleCamera = async () => {
    if (isActive) {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
      setIsActive(false);
      setAnalysis(null);
      setCalibrationStep('idle');
      setActiveAlert(null);
      setLastGhostLandmarks(null);
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsActive(true);
          setStartTime(Date.now());
          setSessionHistory([]);
          setSessionEvents([]);
          setError(null);
        }
      } catch (err) {
        setError("Could not access camera. Please check permissions.");
      }
    }
  };

  const startCalibrationWizard = () => {
    if (!isActive) return;
    setCalibrationStep('instruction');
  };

  const proceedToCountdown = () => {
    setCalibrationStep('preparing');
    setCountdown(5);
  };

  const clearCalibration = () => {
    setBaselineLandmarks(null);
  };

  useEffect(() => {
    if (calibrationStep === 'preparing' && countdown > 0) {
      const timer = setTimeout(() => setCountdown(countdown - 1), 1000);
      return () => clearTimeout(timer);
    } else if (calibrationStep === 'preparing' && countdown === 0) {
      captureCalibration();
    }
  }, [calibrationStep, countdown]);

  const captureCalibration = async () => {
    if (!videoRef.current) return;
    setCalibrationStep('capturing');

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `Detect normalized (0-100) coordinates for posture landmarks: Head, LeftShoulder, RightShoulder, SpineCenter, LeftHip, RightHip. Return ONLY JSON.` }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER },
                    y: { type: Type.NUMBER },
                    label: { type: Type.STRING }
                  },
                  required: ['x', 'y', 'label']
                }
              }
            },
            required: ['landmarks']
          }
        }
      });
      const result = JSON.parse(response.text || '{}');
      if (result.landmarks) {
        setBaselineLandmarks(result.landmarks);
        setCalibrationStep('complete');
        setTimeout(() => setCalibrationStep('idle'), 2000);
      }
    } catch (err) {
      setError("Calibration failed. Please try again.");
      setCalibrationStep('idle');
    }
  };

  const analyzeFrame = async () => {
    if (!isActive || !videoRef.current || isAnalyzing || calibrationStep !== 'idle') return;

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const promptText = `Analyze posture ${baselineLandmarks ? `relative to baseline: ${JSON.stringify(baselineLandmarks)}` : ''}.
           1. Detect normalized landmarks (0-100): Head, LeftShoulder, RightShoulder, SpineCenter, LeftHip, RightHip.
           2. Estimate simulated Cobb Angle (0-90°).
           3. Classify severity.
           4. alignmentScore (0-100).
           5. feedback: concise clinical tip.
           6. recommendations: 3 short exercise names.
           Return JSON.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: promptText }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER },
                    y: { type: Type.NUMBER },
                    label: { type: Type.STRING }
                  },
                  required: ['x', 'y', 'label']
                }
              },
              alignmentScore: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              isDeviating: { type: Type.BOOLEAN },
              estimatedCobbAngle: { type: Type.NUMBER },
              severity: { type: Type.STRING, enum: ['Normal', 'Mild', 'Moderate', 'Severe'] },
              recommendations: { type: Type.ARRAY, items: { type: Type.STRING } }
            },
            required: ['landmarks', 'alignmentScore', 'feedback', 'isDeviating', 'estimatedCobbAngle', 'severity', 'recommendations']
          }
        }
      });

      const result = JSON.parse(response.text || '{}');

      // Update Ghosting Landmarks if a significant change is detected
      if (sessionHistory.length > 0) {
        const lastScore = sessionHistory[sessionHistory.length - 1].score;
        if (Math.abs(result.alignmentScore - lastScore) > 12) {
          setLastGhostLandmarks(sessionHistory[sessionHistory.length - 1].landmarks || null);
        }
      }

      setAnalysis(result);

      const currentTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

      if (sessionHistory.length > 0) {
        const lastPoint = sessionHistory[sessionHistory.length - 1];
        const delta = result.alignmentScore - lastPoint.score;
        if (Math.abs(delta) > 15) {
          setSessionEvents(prev => [{
            id: Math.random().toString(36).substr(2, 9),
            time: currentTime,
            type: delta > 0 ? 'improvement' : 'deterioration',
            score: result.alignmentScore,
            delta: Math.abs(delta),
            feedback: result.feedback
          }, ...prev.slice(0, 4)]);
        }
      }

      const newPoint: SessionDataPoint = {
        time: currentTime,
        timestamp: Date.now(),
        score: result.alignmentScore,
        angle: result.estimatedCobbAngle || 0,
        landmarks: result.landmarks,
        isEvent: Math.abs((sessionHistory[sessionHistory.length-1]?.score || result.alignmentScore) - result.alignmentScore) > 15
      };
      setSessionHistory(prev => [...prev.slice(-44), newPoint]); 
    } catch (err) {
      console.error(err);
    } finally {
      setIsAnalyzing(false);
    }
  };

  useEffect(() => {
    let interval: number;
    if (isActive && calibrationStep === 'idle') {
      interval = window.setInterval(analyzeFrame, 4000); 
    }
    return () => clearInterval(interval);
  }, [isActive, isAnalyzing, calibrationStep, baselineLandmarks]);

  useEffect(() => {
    if (!canvasRef.current || (!analysis && !baselineLandmarks)) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const { width, height } = canvasRef.current;
    ctx.clearRect(0, 0, width, height);

    const drawSkeleton = (points: Landmark[], color: string, alpha: number = 1, isSolid: boolean = true, isGhost: boolean = false) => {
      const getPt = (label: string) => points.find(p => p.label.toLowerCase().includes(label.toLowerCase()));

      const head = getPt('Head');
      const ls = getPt('LeftShoulder');
      const rs = getPt('RightShoulder');
      const spine = getPt('Spine');
      const lh = getPt('LeftHip');
      const rh = getPt('RightHip');

      ctx.globalAlpha = alpha;
      ctx.lineWidth = isSolid ? 4 : 2;
      ctx.strokeStyle = color;
      ctx.setLineDash(isGhost ? [5, 5] : []);

      if (isSolid && !isGhost) {
        ctx.shadowBlur = 15;
        ctx.shadowColor = color;
      } else {
        ctx.shadowBlur = 0;
      }

      const drawLine = (p1?: Landmark, p2?: Landmark) => {
        if (p1 && p2) {
          ctx.beginPath();
          ctx.moveTo(p1.x * width / 100, p1.y * height / 100);
          ctx.lineTo(p2.x * width / 100, p2.y * height / 100);
          ctx.stroke();
        }
      };

      drawLine(head, spine);
      drawLine(ls, rs);
      drawLine(ls, lh);
      drawLine(rs, rh);
      drawLine(lh, rh);
      drawLine(spine, lh);
      drawLine(spine, rh);

      points.forEach(pt => {
        const x = pt.x * width / 100;
        const y = pt.y * height / 100;

        // Highlight joint deviations
        let jointColor = color;
        let radius = isSolid ? 6 : 4;

        ctx.beginPath();
        ctx.arc(x, y, radius, 0, Math.PI * 2);
        ctx.fillStyle = jointColor;
        ctx.fill();

        if (isSolid && !isGhost && analysis?.isDeviating) {
           ctx.beginPath();
           ctx.arc(x, y, radius + 4, 0, Math.PI * 2);
           ctx.strokeStyle = '#ef4444';
           ctx.setLineDash([]);
           ctx.lineWidth = 1;
           ctx.stroke();
        }
      });
      ctx.globalAlpha = 1;
      ctx.shadowBlur = 0;
    };

    // Draw Session History Ghosts (Faded trail)
    if (isActive && sessionHistory.length > 2 && !isAnalyzing) {
       const recent = sessionHistory.slice(-5, -1);
       recent.forEach((pt, i) => {
          if (pt.landmarks) {
            drawSkeleton(pt.landmarks, '#94a3b8', 0.05 * (i + 1), true, true);
          }
       });
    }

    // Draw Significant Shift Ghost
    if (lastGhostLandmarks && isActive) {
      drawSkeleton(lastGhostLandmarks, '#fbbf24', 0.4, false, true);
    }

    // Draw Clinical Baseline
    if (baselineLandmarks && isActive) {
      drawSkeleton(baselineLandmarks, 'rgba(99, 102, 241, 0.4)', 1, false);
    }

    // Draw Current Analysis
    if (analysis?.landmarks && isActive) {
      drawSkeleton(analysis.landmarks, analysis.isDeviating ? '#ef4444' : '#10b981', 1, true);
    }
  }, [analysis, baselineLandmarks, isActive, lastGhostLandmarks, sessionHistory, isAnalyzing]);

  const getSeverityStyles = (severity?: ScoliosisSeverity) => {
    switch (severity) {
      case ScoliosisSeverity.NORMAL: return 'text-emerald-500 bg-emerald-50 border-emerald-100';
      case ScoliosisSeverity.MILD: return 'text-blue-500 bg-blue-50 border-blue-100';
      case ScoliosisSeverity.MODERATE: return 'text-amber-500 bg-amber-50 border-amber-100';
      case ScoliosisSeverity.SEVERE: return 'text-red-500 bg-red-50 border-red-100';
      default: return 'text-slate-400 bg-slate-50 border-slate-100';
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <style>{`
        @keyframes slide-up-fade {
          0% { opacity: 0; transform: translateY(0); }
          50% { opacity: 1; }
          100% { opacity: 0; transform: translateY(-40px); }
        }
        .animate-delta-indicator {
          animation: slide-up-fade 3s ease-out forwards;
        }
      `}</style>

      {significantChange && (
        <div className={`flex items-center justify-between p-4 rounded-2xl border animate-in slide-in-from-top-4 ${
          significantChange.type === 'improvement' ? 'bg-emerald-50 border-emerald-200 text-emerald-800' : 'bg-amber-50 border-amber-200 text-amber-800'
        }`}>
          <div className="flex items-center gap-3">
            {significantChange.type === 'improvement' ? <TrendingUp size={24} /> : <AlertTriangle size={24} />}
            <div>
              <p className="font-bold uppercase text-xs tracking-widest">Significant Postural Shift</p>
              <p className="text-sm">Alignment {significantChange.type === 'improvement' ? 'improved' : 'deviated'} by {significantChange.value.toFixed(1)} units.</p>
            </div>
          </div>
          <button onClick={() => setSessionHistory([])} className="p-2 hover:bg-black/5 rounded-full"><ChevronRight size={20} /></button>
        </div>
      )}

      <div className="flex flex-col xl:flex-row gap-8">
        <div className="flex-1 flex flex-col gap-6">
          <div className={`bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl relative aspect-video group border-4 transition-all duration-700 ${auraStyles.border}`}>
            <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity duration-700 ${isActive ? 'opacity-100' : 'opacity-20'}`} />

            {/* Alignment Delta Indicator (Overlay) */}
            {deltaIndicator && (
               <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 pointer-events-none z-30">
                  <div className={`flex items-center gap-2 px-6 py-3 rounded-full text-2xl font-black shadow-2xl backdrop-blur-md border-2 animate-delta-indicator ${
                    deltaIndicator.type === 'plus' ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500' : 'bg-red-500/20 text-red-400 border-red-500'
                  }`}>
                    {deltaIndicator.type === 'plus' ? <MoveUp size={28} /> : <MoveDown size={28} />}
                    {deltaIndicator.type === 'plus' ? '+' : '-'}{deltaIndicator.value} ALIGNMENT
                  </div>
               </div>
            )}

            {/* Real-time Graph Overlay */}
            {isActive && sessionHistory.length > 1 && (
              <div className="absolute inset-x-0 bottom-0 h-1/4 pointer-events-none opacity-40 z-0">
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={sessionHistory} margin={{ top: 0, right: 0, left: 0, bottom: 0 }}>
                    <defs>
                      <linearGradient id="scoreOverlay" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#818cf8" stopOpacity={0.6}/>
                        <stop offset="95%" stopColor="#818cf8" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <Area 
                      type="monotone" 
                      dataKey="score" 
                      stroke="#ffffff" 
                      strokeWidth={1} 
                      fillOpacity={1} 
                      fill="url(#scoreOverlay)" 
                      isAnimationActive={true}
                      animationDuration={1500}
                    />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
            )}

            <div className="absolute inset-0 aura-overlay" style={{ background: `radial-gradient(circle, transparent 40%, ${auraStyles.glow} 100%)` }} />

            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none" width={640} height={480} />

            <div className="absolute top-8 left-8 flex items-center gap-3">
              <div className={`w-3 h-3 rounded-full ${isActive ? 'bg-red-500 animate-pulse' : 'bg-slate-600'}`}></div>
              <span className="text-white text-xs font-black tracking-widest uppercase opacity-80">
                {isActive ? 'Clinical Bio-Feedback' : 'Optical Engine Inactive'}
              </span>
            </div>

            {isActive && (
              <div className="absolute top-8 right-8 flex flex-col items-end gap-2">
                <div className="bg-black/40 backdrop-blur-md px-4 py-2 rounded-xl border border-white/10 flex items-center gap-3">
                  <Waves size={16} className={`text-indigo-400 ${stabilityIndex < 60 ? 'animate-bounce' : ''}`} />
                  <div>
                    <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest leading-none mb-1">Session Stability</p>
                    <p className="text-sm font-black text-white">{Math.round(stabilityIndex)}%</p>
                  </div>
                </div>
                {baselineLandmarks && (
                   <div className="bg-indigo-600/90 px-3 py-1.5 rounded-lg text-white text-[10px] font-black uppercase tracking-widest shadow-lg flex items-center gap-2">
                      <ShieldCheck size={14} /> Clinical Baseline Locked
                   </div>
                )}
                {lastGhostLandmarks && (
                   <div className="bg-amber-600/90 px-3 py-1.5 rounded-lg text-white text-[10px] font-black uppercase tracking-widest shadow-lg flex items-center gap-2 animate-pulse">
                      <History size={14} /> Deviation Ghost Active
                   </div>
                )}
              </div>
            )}

            {calibrationStep !== 'idle' && (
              <div className="absolute inset-0 bg-indigo-900/80 backdrop-blur-md flex flex-col items-center justify-center text-white z-20 animate-in fade-in p-12 text-center">
                {calibrationStep === 'instruction' && (
                  <div className="max-w-md space-y-6">
                    <div className="w-20 h-20 bg-white/10 rounded-3xl flex items-center justify-center mx-auto border border-white/20"><ScanEye size={40} className="text-indigo-400" /></div>
                    <h2 className="text-3xl font-black">Posture Normalization</h2>
                    <p className="text-indigo-100 font-medium">Stand straight with shoulders level to calibrate your neutral spinal alignment.</p>
                    <div className="flex gap-3">
                      <button onClick={() => setCalibrationStep('idle')} className="flex-1 py-4 bg-white/10 rounded-2xl font-bold">Cancel</button>
                      <button onClick={proceedToCountdown} className="flex-1 py-4 bg-indigo-500 rounded-2xl font-bold">Start</button>
                    </div>
                  </div>
                )}
                {calibrationStep === 'preparing' && (
                  <><div className="w-32 h-32 rounded-full border-8 border-white/10 flex items-center justify-center mb-8 relative"><span className="text-6xl font-black">{countdown}</span></div><h2 className="text-3xl font-black mb-2">Analyzing Pose</h2></>
                )}
                {calibrationStep === 'complete' && (
                  <div className="flex flex-col items-center gap-4"><div className="w-24 h-24 bg-emerald-500 rounded-full flex items-center justify-center"><CheckCircle2 size={48} /></div><p className="font-black text-3xl">Normalization Applied</p></div>
                )}
              </div>
            )}

            {!isActive && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-white space-y-4">
                <div className="w-20 h-20 bg-white/10 backdrop-blur-md rounded-3xl flex items-center justify-center text-slate-400"><CameraOff size={40} /></div>
                <div className="text-center px-8">
                  <p className="font-black text-xl mb-1">Optical Standby</p>
                  <p className="text-slate-400 text-sm font-medium">Connect the camera feed to begin real-time postural mapping.</p>
                </div>
              </div>
            )}

            {isAnalyzing && (
              <div className="absolute bottom-8 right-8 flex items-center gap-2 bg-indigo-600 px-4 py-2 rounded-xl text-white text-xs font-bold shadow-lg animate-pulse z-10">
                <RefreshCw size={14} className="animate-spin" /> Geometric Extraction...
              </div>
            )}

            <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-4 group-hover:scale-105 transition-transform z-10">
              <button onClick={toggleCamera} className={`flex items-center gap-3 px-8 py-4 rounded-2xl font-black text-sm uppercase tracking-widest transition-all ${isActive ? 'bg-white/10 backdrop-blur-md text-white border border-white/20 hover:bg-white/20' : 'bg-indigo-600 text-white shadow-xl shadow-indigo-500/20'}`}>
                {isActive ? <><Square size={18} /> Stop Feed</> : <><Play size={18} /> Start Feed</>}
              </button>
              {isActive && (
                <div className="flex gap-2">
                  <button onClick={startCalibrationWizard} disabled={calibrationStep !== 'idle'} className="flex items-center gap-3 px-8 py-4 bg-indigo-600 text-white rounded-2xl font-black text-sm uppercase tracking-widest shadow-lg shadow-indigo-500/30 disabled:opacity-50">
                    <Target size={18} /> {baselineLandmarks ? 'Adjust Base' : 'Calibrate'}
                  </button>
                  {baselineLandmarks && <button onClick={clearCalibration} className="p-4 bg-white/10 backdrop-blur-md text-white border border-white/20 rounded-2xl hover:bg-red-500/20 transition-all" title="Clear Baseline"><Undo2 size={18} /></button>}
                </div>
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col justify-between hover:border-indigo-100 transition-all">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Observed Cobb Angle</p>
              <p className="text-4xl font-black text-slate-800">{analysis?.estimatedCobbAngle ? `${analysis.estimatedCobbAngle.toFixed(1)}°` : '--°'}</p>
            </div>
            <div className={`p-6 rounded-3xl border shadow-sm flex flex-col justify-between transition-colors ${getSeverityStyles(analysis?.severity as ScoliosisSeverity)}`}>
              <p className="text-[10px] font-black uppercase tracking-widest mb-1 opacity-70">Curvature Risk</p>
              <p className="text-3xl font-black">{analysis?.severity || '--'}</p>
            </div>
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col justify-between hover:border-indigo-100 transition-all">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Alignment Score</p>
              <div className="flex items-baseline gap-1">
                <p className="text-4xl font-black text-indigo-600">{analysis ? `${Math.round(analysis.alignmentScore)}` : '--'}</p>
                <span className="text-xs font-bold text-slate-400">/ 100</span>
              </div>
            </div>
          </div>
        </div>

        <div className="w-full xl:w-96 space-y-6">
          <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-lg">
            <h3 className="text-xl font-black text-slate-800 flex items-center gap-2 mb-6"><TrendingUp size={24} className="text-indigo-600" /> Session Progression</h3>
            <div className="h-48 w-full -ml-4">
              {sessionHistory.length > 1 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={sessionHistory}>
                    <defs><linearGradient id="colorScoreMain" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#4f46e5" stopOpacity={0.1}/><stop offset="95%" stopColor="#4f46e5" stopOpacity={0}/></linearGradient></defs>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                    <XAxis dataKey="time" hide />
                    <YAxis domain={[0, 100]} hide />
                    <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }} />
                    <Area type="monotone" dataKey="score" stroke="#4f46e5" strokeWidth={3} fillOpacity={1} fill="url(#colorScoreMain)" />
                  </AreaChart>
                </ResponsiveContainer>
              ) : (
                <div className="h-full flex flex-col items-center justify-center text-slate-300"><Activity size={32} className="opacity-20 mb-2" /><p className="text-[10px] font-black uppercase tracking-widest">Awaiting Samples</p></div>
              )}
            </div>
          </div>

          <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-lg">
            <h3 className="text-xl font-black text-slate-800 mb-6 flex items-center gap-2"><History size={24} className="text-indigo-600" /> Monitoring Log</h3>
            <div className="space-y-4">
              {sessionEvents.length > 0 ? sessionEvents.map((event) => (
                <div key={event.id} className="flex gap-4 p-4 bg-slate-50 rounded-2xl border border-slate-100 animate-in slide-in-from-left-2">
                  <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${event.type === 'improvement' ? 'bg-emerald-100 text-emerald-600' : 'bg-amber-100 text-amber-600'}`}>{event.type === 'improvement' ? <ArrowUpRight size={20} /> : <ArrowDownRight size={20} />}</div>
                  <div className="flex-1">
                    <p className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-1">{event.time} • {event.type === 'improvement' ? 'Clinical Improvement' : 'Postural Deviation'}</p>
                    <p className="text-sm font-bold text-slate-800">Alignment: {Math.round(event.score)}% ({event.type === 'improvement' ? '+' : '-'}{Math.round(event.delta)}%)</p>
                  </div>
                </div>
              )) : (
                <div className="flex flex-col items-center justify-center py-6 text-slate-400 opacity-60"><Clock size={32} className="mb-2" /><p className="text-xs font-medium">Establishing baseline...</p></div>
              )}
            </div>
          </div>

          <div className="bg-indigo-50 p-6 rounded-[2rem] border border-indigo-100 relative overflow-hidden group">
             <div className="absolute -right-4 -top-4 w-20 h-20 bg-indigo-600/5 rounded-full group-hover:scale-150 transition-transform"></div>
             <div className="flex items-center gap-3 mb-4">
                <Lightbulb size={20} className="text-indigo-600" />
                <h4 className="font-black text-xs uppercase tracking-widest text-indigo-800">Dynamic Guidance</h4>
             </div>
             <p className="text-sm text-indigo-700 leading-relaxed italic relative z-10">
                {analysis?.feedback || "System is calculating symmetry vectors. Maintain vertical alignment for clinical accuracy."}
             </p>
             {analysis?.recommendations && (
               <div className="mt-4 pt-4 border-t border-indigo-200">
                 <p className="text-[10px] font-black text-indigo-400 uppercase mb-2">Prescribed Correctives</p>
                 <div className="flex flex-wrap gap-2">
                   {analysis.recommendations.map((r, i) => (
                     <span key={i} className="px-2 py-1 bg-white rounded-lg text-[10px] font-bold text-indigo-600 border border-indigo-200 shadow-sm">{r}</span>
                   ))}
                 </div>
               </div>
             )}
          </div>
        </div>
      </div>

      {error && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-red-50 text-red-700 px-6 py-4 rounded-2xl border border-red-100 shadow-2xl flex items-center gap-4 z-50 animate-in slide-in-from-bottom-4">
          <AlertCircle size={24} /> <p className="font-bold">{error}</p> <button onClick={() => setError(null)} className="ml-4 p-1 hover:bg-red-100 rounded-full transition-colors"><ChevronRight size={18} /></button>
        </div>
      )}
    </div>
  );
};

export default PostureLiveView;

import React, { useEffect, useRef, useState, useMemo } from 'react';
import { 
  Camera, 
  CameraOff, 
  Play, 
  Square, 
  RefreshCw, 
  Zap, 
  AlertCircle, 
  Activity,
  CheckCircle2,
  ScanEye,
  Target,
  ChevronRight,
  ShieldCheck,
  Dumbbell,
  Stethoscope,
  TrendingUp,
  AlertTriangle,
  ArrowUpRight,
  ArrowDownRight,
  Info,
  UserCheck,
  Undo2,
  Clock,
  History,
  Timer,
  Waves,
  Lightbulb,
  ArrowRight,
  MoveUp,
  MoveDown,
  Trash2,
  Settings
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";
import { PostureAnalysis, Landmark, ScoliosisSeverity } from '../types';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceLine } from 'recharts';

type CalibrationStep = 'idle' | 'instruction' | 'preparing' | 'capturing' | 'complete';

interface SessionEvent {
  id: string;
  time: string;
  type: 'improvement' | 'deterioration' | 'system';
  score?: number;
  delta?: number;
  label: string;
  feedback?: string;
}

interface SessionDataPoint {
  time: string;
  timestamp: number;
  score: number;
  angle: number;
  landmarks?: Landmark[];
  isEvent?: boolean;
}

const PostureLiveView: React.FC = () => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const logEndRef = useRef<HTMLDivElement>(null);

  const [isActive, setIsActive] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<PostureAnalysis | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [sessionHistory, setSessionHistory] = useState<SessionDataPoint[]>([]);
  const [sessionEvents, setSessionEvents] = useState<SessionEvent[]>([]);
  const [startTime, setStartTime] = useState<number | null>(null);

  // Real-time Visual indicators
  const [lastGhostLandmarks, setLastGhostLandmarks] = useState<Landmark[] | null>(null);
  const [deltaIndicator, setDeltaIndicator] = useState<{ value: number, type: 'plus' | 'minus' } | null>(null);

  // Calibration State
  const [calibrationStep, setCalibrationStep] = useState<CalibrationStep>('idle');
  const [baselineLandmarks, setBaselineLandmarks] = useState<Landmark[] | null>(null);
  const [countdown, setCountdown] = useState(0);

  // Significant Change Logic
  const significantChange = useMemo(() => {
    if (sessionHistory.length < 2) return null;
    const current = sessionHistory[sessionHistory.length - 1];
    const previous = sessionHistory[sessionHistory.length - 2];
    const diff = current.score - previous.score;

    // Lowered threshold to 8 for more sensitive logging in the history
    if (Math.abs(diff) > 8) {
      return {
        type: (diff > 0 ? 'improvement' : 'deterioration') as 'improvement' | 'deterioration',
        value: Math.abs(diff)
      };
    }
    return null;
  }, [sessionHistory]);

  // Stability Index
  const stabilityIndex = useMemo(() => {
    if (sessionHistory.length < 3) return 100;
    const lastScores = sessionHistory.slice(-5).map(p => p.score);
    const mean = lastScores.reduce((a, b) => a + b, 0) / lastScores.length;
    const variance = lastScores.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / lastScores.length;
    return Math.max(0, 100 - Math.sqrt(variance) * 5);
  }, [sessionHistory]);

  // Dynamic Aura Color
  const auraStyles = useMemo(() => {
    if (!analysis) return { glow: 'transparent', border: 'border-slate-800' };
    const score = analysis.alignmentScore;
    if (score > 85) return { glow: 'rgba(16, 185, 129, 0.1)', border: 'border-emerald-500/40 shadow-emerald-500/10' };
    if (score > 70) return { glow: 'rgba(79, 70, 229, 0.1)', border: 'border-indigo-500/40 shadow-indigo-500/10' };
    if (score > 50) return { glow: 'rgba(245, 158, 11, 0.15)', border: 'border-amber-500/40 shadow-amber-500/10' };
    return { glow: 'rgba(239, 68, 68, 0.2)', border: 'border-red-500/60 shadow-red-500/20' };
  }, [analysis]);

  const [activeAlert, setActiveAlert] = useState<'improvement' | 'deterioration' | null>(null);

  useEffect(() => {
    if (significantChange) {
      setActiveAlert(significantChange.type);
      setDeltaIndicator({
        value: Math.round(significantChange.value),
        type: significantChange.type === 'improvement' ? 'plus' : 'minus'
      });

      const timer = setTimeout(() => {
        setActiveAlert(null);
        setDeltaIndicator(null);
      }, 3000);
      return () => clearTimeout(timer);
    }
  }, [significantChange]);

  // Auto-scroll log to bottom
  useEffect(() => {
    if (logEndRef.current) {
      logEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [sessionEvents]);

  const addEvent = (event: Omit<SessionEvent, 'id' | 'time'>) => {
    const newEvent: SessionEvent = {
      ...event,
      id: Math.random().toString(36).substr(2, 9),
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })
    };
    setSessionEvents(prev => [...prev.slice(-49), newEvent]);
  };

  const toggleCamera = async () => {
    if (isActive) {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
      setIsActive(false);
      setAnalysis(null);
      setCalibrationStep('idle');
      setActiveAlert(null);
      setLastGhostLandmarks(null);
      addEvent({ type: 'system', label: 'Monitoring Session Terminated' });
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsActive(true);
          setStartTime(Date.now());
          setSessionHistory([]);
          setSessionEvents([]);
          setError(null);
          addEvent({ type: 'system', label: 'New Monitoring Session Initiated' });
        }
      } catch (err) {
        setError("Could not access camera. Please check permissions.");
      }
    }
  };

  const startCalibrationWizard = () => {
    if (!isActive) return;
    setCalibrationStep('instruction');
  };

  const proceedToCountdown = () => {
    setCalibrationStep('preparing');
    setCountdown(5);
  };

  const clearCalibration = () => {
    setBaselineLandmarks(null);
    addEvent({ type: 'system', label: 'Clinical Baseline Cleared' });
  };

  useEffect(() => {
    if (calibrationStep === 'preparing' && countdown > 0) {
      const timer = setTimeout(() => setCountdown(countdown - 1), 1000);
      return () => clearTimeout(timer);
    } else if (calibrationStep === 'preparing' && countdown === 0) {
      captureCalibration();
    }
  }, [calibrationStep, countdown]);

  const captureCalibration = async () => {
    if (!videoRef.current) return;
    setCalibrationStep('capturing');

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `Detect normalized (0-100) coordinates for posture landmarks: Head, LeftShoulder, RightShoulder, SpineCenter, LeftHip, RightHip. Return ONLY JSON.` }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER },
                    y: { type: Type.NUMBER },
                    label: { type: Type.STRING }
                  },
                  required: ['x', 'y', 'label']
                }
              }
            },
            required: ['landmarks']
          }
        }
      });
      const result = JSON.parse(response.text || '{}');
      if (result.landmarks) {
        setBaselineLandmarks(result.landmarks);
        setCalibrationStep('complete');
        addEvent({ type: 'system', label: 'New Baseline Calibration Applied' });
        setTimeout(() => setCalibrationStep('idle'), 2000);
      }
    } catch (err) {
      setError("Calibration failed. Please try again.");
      setCalibrationStep('idle');
    }
  };

  const analyzeFrame = async () => {
    if (!isActive || !videoRef.current || isAnalyzing || calibrationStep !== 'idle') return;

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const promptText = `Analyze posture ${baselineLandmarks ? `relative to baseline: ${JSON.stringify(baselineLandmarks)}` : ''}.
           1. Detect normalized landmarks (0-100): Head, LeftShoulder, RightShoulder, SpineCenter, LeftHip, RightHip.
           2. Estimate simulated Cobb Angle (0-90°).
           3. Classify severity.
           4. alignmentScore (0-100).
           5. feedback: concise clinical tip.
           6. recommendations: 3 short exercise names.
           Return JSON.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: promptText }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER },
                    y: { type: Type.NUMBER },
                    label: { type: Type.STRING }
                  },
                  required: ['x', 'y', 'label']
                }
              },
              alignmentScore: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              isDeviating: { type: Type.BOOLEAN },
              estimatedCobbAngle: { type: Type.NUMBER },
              severity: { type: Type.STRING, enum: ['Normal', 'Mild', 'Moderate', 'Severe'] },
              recommendations: { type: Type.ARRAY, items: { type: Type.STRING } }
            },
            required: ['landmarks', 'alignmentScore', 'feedback', 'isDeviating', 'estimatedCobbAngle', 'severity', 'recommendations']
          }
        }
      });

      const result = JSON.parse(response.text || '{}');

      // Update Ghosting Landmarks if a significant change is detected
      if (sessionHistory.length > 0) {
        const lastScore = sessionHistory[sessionHistory.length - 1].score;
        const delta = result.alignmentScore - lastScore;

        if (Math.abs(delta) > 12) {
          setLastGhostLandmarks(sessionHistory[sessionHistory.length - 1].landmarks || null);
          addEvent({
            type: delta > 0 ? 'improvement' : 'deterioration',
            label: delta > 0 ? 'Posture Improvement' : 'Postural Deviation',
            score: Math.round(result.alignmentScore),
            delta: Math.round(Math.abs(delta)),
            feedback: result.feedback
          });
        }
      }

      setAnalysis(result);

      const currentTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

      const newPoint: SessionDataPoint = {
        time: currentTime,
        timestamp: Date.now(),
        score: result.alignmentScore,
        angle: result.estimatedCobbAngle || 0,
        landmarks: result.landmarks,
        isEvent: Math.abs((sessionHistory[sessionHistory.length-1]?.score || result.alignmentScore) - result.alignmentScore) > 15
      };
      setSessionHistory(prev => [...prev.slice(-44), newPoint]); 
    } catch (err) {
      console.error(err);
    } finally {
      setIsAnalyzing(false);
    }
  };

  useEffect(() => {
    let interval: number;
    if (isActive && calibrationStep === 'idle') {
      interval = window.setInterval(analyzeFrame, 4000); 
    }
    return () => clearInterval(interval);
  }, [isActive, isAnalyzing, calibrationStep, baselineLandmarks]);

  useEffect(() => {
    if (!canvasRef.current || (!analysis && !baselineLandmarks)) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const { width, height } = canvasRef.current;
    ctx.clearRect(0, 0, width, height);

    const drawSkeleton = (points: Landmark[], color: string, alpha: number = 1, isSolid: boolean = true, isGhost: boolean = false) => {
      const getPt = (label: string) => points.find(p => p.label.toLowerCase().includes(label.toLowerCase()));

      const head = getPt('Head');
      const ls = getPt('LeftShoulder');
      const rs = getPt('RightShoulder');
      const spine = getPt('Spine');
      const lh = getPt('LeftHip');
      const rh = getPt('RightHip');

      ctx.globalAlpha = alpha;
      ctx.lineWidth = isSolid ? 4 : 2;
      ctx.strokeStyle = color;
      ctx.setLineDash(isGhost ? [5, 5] : []);

      if (isSolid && !isGhost) {
        ctx.shadowBlur = 15;
        ctx.shadowColor = color;
      } else {
        ctx.shadowBlur = 0;
      }

      const drawLine = (p1?: Landmark, p2?: Landmark) => {
        if (p1 && p2) {
          ctx.beginPath();
          ctx.moveTo(p1.x * width / 100, p1.y * height / 100);
          ctx.lineTo(p2.x * width / 100, p2.y * height / 100);
          ctx.stroke();
        }
      };

      drawLine(head, spine);
      drawLine(ls, rs);
      drawLine(ls, lh);
      drawLine(rs, rh);
      drawLine(lh, rh);
      drawLine(spine, lh);
      drawLine(spine, rh);

      points.forEach(pt => {
        const x = pt.x * width / 100;
        const y = pt.y * height / 100;

        // Highlight joint deviations
        let radius = isSolid ? 6 : 4;

        ctx.beginPath();
        ctx.arc(x, y, radius, 0, Math.PI * 2);
        ctx.fillStyle = color;
        ctx.fill();

        if (isSolid && !isGhost && analysis?.isDeviating) {
           ctx.beginPath();
           ctx.arc(x, y, radius + 4, 0, Math.PI * 2);
           ctx.strokeStyle = '#ef4444';
           ctx.setLineDash([]);
           ctx.lineWidth = 1;
           ctx.stroke();
        }
      });
      ctx.globalAlpha = 1;
      ctx.shadowBlur = 0;
    };

    // Draw Session History Ghosts (Faded trail)
    if (isActive && sessionHistory.length > 2 && !isAnalyzing) {
       const recent = sessionHistory.slice(-5, -1);
       recent.forEach((pt, i) => {
          if (pt.landmarks) {
            drawSkeleton(pt.landmarks, '#94a3b8', 0.05 * (i + 1), true, true);
          }
       });
    }

    // Draw Significant Shift Ghost
    if (lastGhostLandmarks && isActive) {
      drawSkeleton(lastGhostLandmarks, '#fbbf24', 0.4, false, true);
    }

    // Draw Clinical Baseline
    if (baselineLandmarks && isActive) {
      drawSkeleton(baselineLandmarks, 'rgba(99, 102, 241, 0.4)', 1, false);
    }

    // Draw Current Analysis
    if (analysis?.landmarks && isActive) {
      drawSkeleton(analysis.landmarks, analysis.isDeviating ? '#ef4444' : '#10b981', 1, true);
    }
  }, [analysis, baselineLandmarks, isActive, lastGhostLandmarks, sessionHistory, isAnalyzing]);

  const getSeverityStyles = (severity?: ScoliosisSeverity) => {
    switch (severity) {
      case ScoliosisSeverity.NORMAL: return 'text-emerald-500 bg-emerald-50 border-emerald-100';
      case ScoliosisSeverity.MILD: return 'text-blue-500 bg-blue-50 border-blue-100';
      case ScoliosisSeverity.MODERATE: return 'text-amber-500 bg-amber-50 border-amber-100';
      case ScoliosisSeverity.SEVERE: return 'text-red-500 bg-red-50 border-red-100';
      default: return 'text-slate-400 bg-slate-50 border-slate-100';
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <style>{`
        @keyframes slide-up-fade {
          0% { opacity: 0; transform: translateY(0); }
          50% { opacity: 1; }
          100% { opacity: 0; transform: translateY(-40px); }
        }
        .animate-delta-indicator {
          animation: slide-up-fade 3s ease-out forwards;
        }
        .custom-scrollbar::-webkit-scrollbar {
          width: 4px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: transparent;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #e2e8f0;
          border-radius: 10px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background: #cbd5e1;
        }
      `}</style>

      {significantChange && (
        <div className={`flex items-center justify-between p-4 rounded-2xl border animate-in slide-in-from-top-4 ${
          significantChange.type === 'improvement' ? 'bg-emerald-50 border-emerald-200 text-emerald-800' : 'bg-amber-50 border-amber-200 text-amber-800'
        }`}>
          <div className="flex items-center gap-3">
            {significantChange.type === 'improvement' ? <TrendingUp size={24} /> : <AlertTriangle size={24} />}
            <div>
              <p className="font-bold uppercase text-xs tracking-widest">Significant Postural Shift</p>
              <p className="text-sm">Alignment {significantChange.type === 'improvement' ? 'improved' : 'deviated'} by {significantChange.value.toFixed(1)} units.</p>
            </div>
          </div>
          <button onClick={() => setSessionHistory([])} className="p-2 hover:bg-black/5 rounded-full"><ChevronRight size={20} /></button>
        </div>
      )}

      <div className="flex flex-col xl:flex-row gap-8">
        <div className="flex-1 flex flex-col gap-6">
          <div className={`bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl relative aspect-video group border-4 transition-all duration-700 ${auraStyles.border}`}>
            <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity duration-700 ${isActive ? 'opacity-100' : 'opacity-20'}`} />

            {/* Alignment Delta Indicator (Overlay) */}
            {deltaIndicator && (
               <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 pointer-events-none z-30">
                  <div className={`flex items-center gap-2 px-6 py-3 rounded-full text-2xl font-black shadow-2xl backdrop-blur-md border-2 animate-delta-indicator ${
                    deltaIndicator.type === 'plus' ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500' : 'bg-red-500/20 text-red-400 border-red-500'
                  }`}>
                    {deltaIndicator.type === 'plus' ? <MoveUp size={28} /> : <MoveDown size={28} />}
                    {deltaIndicator.type === 'plus' ? '+' : '-'}{deltaIndicator.value} ALIGNMENT
                  </div>
               </div>
            )}

            {/* Real-time Graph Overlay */}
            {isActive && sessionHistory.length > 1 && (
              <div className="absolute inset-x-0 bottom-0 h-1/4 pointer-events-none opacity-40 z-0">
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={sessionHistory} margin={{ top: 0, right: 0, left: 0, bottom: 0 }}>
                    <defs>
                      <linearGradient id="scoreOverlay" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#818cf8" stopOpacity={0.6}/>
                        <stop offset="95%" stopColor="#818cf8" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <Area 
                      type="monotone" 
                      dataKey="score" 
                      stroke="#ffffff" 
                      strokeWidth={1} 
                      fillOpacity={1} 
                      fill="url(#scoreOverlay)" 
                      isAnimationActive={true}
                      animationDuration={1500}
                    />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
            )}

            <div className="absolute inset-0 aura-overlay" style={{ background: `radial-gradient(circle, transparent 40%, ${auraStyles.glow} 100%)` }} />

            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none" width={640} height={480} />

            <div className="absolute top-8 left-8 flex items-center gap-3">
              <div className={`w-3 h-3 rounded-full ${isActive ? 'bg-red-500 animate-pulse' : 'bg-slate-600'}`}></div>
              <span className="text-white text-xs font-black tracking-widest uppercase opacity-80">
