              </button>
              {isActive && (
                <div className="flex gap-2">
                  <button onClick={startCalibrationWizard} disabled={calibrationStep !== 'idle'} className="flex items-center gap-3 px-8 py-4 bg-indigo-600 text-white rounded-2xl font-black text-sm uppercase tracking-widest shadow-lg shadow-indigo-500/30 disabled:opacity-50">
                    <Target size={18} /> {baselineLandmarks ? 'Adjust Base' : 'Calibrate'}
                  </button>
                  {baselineLandmarks && <button onClick={clearCalibration} className="p-4 bg-white/10 backdrop-blur-md text-white border border-white/20 rounded-2xl hover:bg-red-500/20 transition-all" title="Clear Baseline"><Undo2 size={18} /></button>}
                </div>
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col justify-between hover:border-indigo-100 transition-all">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Observed Cobb Angle</p>
              <p className="text-4xl font-black text-slate-800">{analysis?.estimatedCobbAngle ? `${analysis.estimatedCobbAngle.toFixed(1)}°` : '--°'}</p>
            </div>
            <div className={`p-6 rounded-3xl border shadow-sm flex flex-col justify-between transition-colors ${getSeverityStyles(analysis?.severity as ScoliosisSeverity)}`}>
              <p className="text-[10px] font-black uppercase tracking-widest mb-1 opacity-70">Curvature Risk</p>
              <p className="text-3xl font-black">{analysis?.severity || '--'}</p>
            </div>
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col justify-between hover:border-indigo-100 transition-all">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Alignment Score</p>
              <div className="flex items-baseline gap-1">
                <p className="text-4xl font-black text-indigo-600">{analysis ? `${Math.round(analysis.alignmentScore)}` : '--'}</p>
                <span className="text-xs font-bold text-slate-400">/ 100</span>
              </div>
            </div>
          </div>
        </div>

        <div className="w-full xl:w-96 space-y-6 flex flex-col">
          <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-lg">
            <h3 className="text-xl font-black text-slate-800 flex items-center gap-2 mb-6"><TrendingUp size={24} className="text-indigo-600" /> Session Progression</h3>
            <div className="h-48 w-full -ml-4">
              {sessionHistory.length > 1 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={sessionHistory}>
                    <defs><linearGradient id="colorScoreMain" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#4f46e5" stopOpacity={0.1}/><stop offset="95%" stopColor="#4f46e5" stopOpacity={0}/></linearGradient></defs>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                    <XAxis dataKey="time" hide />
                    <YAxis domain={[0, 100]} hide />
                    <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }} />
                    <Area type="monotone" dataKey="score" stroke="#4f46e5" strokeWidth={3} fillOpacity={1} fill="url(#colorScoreMain)" />
                  </AreaChart>
                </ResponsiveContainer>
              ) : (
                <div className="h-full flex flex-col items-center justify-center text-slate-300"><Activity size={32} className="opacity-20 mb-2" /><p className="text-[10px] font-black uppercase tracking-widest">Awaiting Samples</p></div>
              )}
            </div>
          </div>

          <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-lg flex flex-col flex-1 h-[400px]">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><History size={24} className="text-indigo-600" /> Monitoring Log</h3>
              {sessionEvents.length > 0 && (
                <button 
                  onClick={() => setSessionEvents([])}
                  className="p-2 hover:bg-red-50 text-slate-400 hover:text-red-500 rounded-lg transition-colors"
                  title="Clear Log"
                >
                  <Trash2 size={16} />
                </button>
              )}
            </div>

            <div className="space-y-4 overflow-y-auto flex-1 pr-2 custom-scrollbar">
              {sessionEvents.length > 0 ? (
                sessionEvents.map((event) => (
                  <div key={event.id} className="flex gap-4 p-4 bg-slate-50 rounded-2xl border border-slate-100 animate-in slide-in-from-left-2">
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${
                      event.type === 'improvement' ? 'bg-emerald-100 text-emerald-600' : 
                      event.type === 'deterioration' ? 'bg-amber-100 text-amber-600' :
                      'bg-indigo-100 text-indigo-600'
                    }`}>
                      {event.type === 'improvement' ? <ArrowUpRight size={20} /> : 
                       event.type === 'deterioration' ? <ArrowDownRight size={20} /> :
                       <Settings size={20} />}
                    </div>
                    <div className="flex-1">
                      <div className="flex justify-between items-start mb-1">
                        <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">{event.time}</p>
                        {event.delta !== undefined && (
                          <span className={`text-[10px] font-black px-1.5 py-0.5 rounded ${
                            event.type === 'improvement' ? 'bg-emerald-500 text-white' : 'bg-amber-500 text-white'
                          }`}>
                            {event.type === 'improvement' ? '+' : '-'}{event.delta}%
                          </span>
                        )}
                      </div>
                      <p className="text-sm font-bold text-slate-800 leading-tight">{event.label}</p>
                      {event.score !== undefined && <p className="text-[11px] font-medium text-slate-500 mt-0.5">Alignment Score: {event.score}%</p>}
                      {event.feedback && <p className="text-[11px] font-medium text-slate-400 italic mt-1 leading-snug">"{event.feedback}"</p>}
                    </div>
                  </div>
                ))
              ) : (
                <div className="flex flex-col items-center justify-center py-20 text-slate-400 opacity-60">
                  <Clock size={32} className="mb-2" />
                  <p className="text-xs font-medium">Establishing baseline...</p>
                </div>
              )}
              <div ref={logEndRef} />
            </div>
          </div>

          <div className="bg-indigo-50 p-6 rounded-[2rem] border border-indigo-100 relative overflow-hidden group">
             <div className="absolute -right-4 -top-4 w-20 h-20 bg-indigo-600/5 rounded-full group-hover:scale-150 transition-transform"></div>
             <div className="flex items-center gap-3 mb-4">
                <Lightbulb size={20} className="text-indigo-600" />
                <h4 className="font-black text-xs uppercase tracking-widest text-indigo-800">Dynamic Guidance</h4>
             </div>
             <p className="text-sm text-indigo-700 leading-relaxed italic relative z-10">
                {analysis?.feedback || "System is calculating symmetry vectors. Maintain vertical alignment for clinical accuracy."}
             </p>
             {analysis?.recommendations && (
               <div className="mt-4 pt-4 border-t border-indigo-200">
                 <p className="text-[10px] font-black text-indigo-400 uppercase mb-2">Prescribed Correctives</p>
                 <div className="flex flex-wrap gap-2">
                   {analysis.recommendations.map((r, i) => (
                     <span key={i} className="px-2 py-1 bg-white rounded-lg text-[10px] font-bold text-indigo-600 border border-indigo-200 shadow-sm">{r}</span>
                   ))}
                 </div>
               </div>
             )}
          </div>
        </div>
      </div>

      {error && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-red-50 text-red-700 px-6 py-4 rounded-2xl border border-red-100 shadow-2xl flex items-center gap-4 z-50 animate-in slide-in-from-bottom-4">
          <AlertCircle size={24} /> <p className="font-bold">{error}</p> <button onClick={() => setError(null)} className="ml-4 p-1 hover:bg-red-100 rounded-full transition-colors"><ChevronRight size={18} /></button>
        </div>
      )}
    </div>
  );
};

export default PostureLiveView;

import React, { useEffect, useRef, useState, useMemo } from 'react';
import { 
  Camera, 
  CameraOff, 
  Play, 
  Square, 
  RefreshCw, 
  Zap, 
  AlertCircle, 
  Activity,
  CheckCircle2,
  ScanEye,
  Target,
  ChevronRight,
  ShieldCheck,
  Dumbbell,
  Stethoscope,
  TrendingUp,
  AlertTriangle,
  ArrowUpRight,
  ArrowDownRight,
  Info,
  UserCheck,
  Undo2,
  Clock,
  History,
  Timer,
  Waves,
  Lightbulb,
  ArrowRight,
  MoveUp,
  MoveDown,
  Trash2,
  Settings,
  Activity as ActivityIcon
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";
import { PostureAnalysis, Landmark, ScoliosisSeverity } from '../types';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceLine } from 'recharts';

type CalibrationStep = 'idle' | 'instruction' | 'preparing' | 'capturing' | 'complete';

interface SessionEvent {
  id: string;
  time: string;
  type: 'improvement' | 'deterioration' | 'system';
  score?: number;
  delta?: number;
  label: string;
  feedback?: string;
}

interface SessionDataPoint {
  time: string;
  timestamp: number;
  score: number;
  angle: number;
  landmarks?: Landmark[];
  isEvent?: boolean;
}

const PostureLiveView: React.FC = () => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const logEndRef = useRef<HTMLDivElement>(null);

  const [isActive, setIsActive] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<PostureAnalysis | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [sessionHistory, setSessionHistory] = useState<SessionDataPoint[]>([]);
  const [sessionEvents, setSessionEvents] = useState<SessionEvent[]>([]);
  const [startTime, setStartTime] = useState<number | null>(null);

  // Real-time Visual indicators
  const [lastGhostLandmarks, setLastGhostLandmarks] = useState<Landmark[] | null>(null);
  const [deltaIndicator, setDeltaIndicator] = useState<{ value: number, type: 'plus' | 'minus' } | null>(null);
  const [triggerRipple, setTriggerRipple] = useState(false);

  // Calibration State
  const [calibrationStep, setCalibrationStep] = useState<CalibrationStep>('idle');
  const [baselineLandmarks, setBaselineLandmarks] = useState<Landmark[] | null>(null);
  const [countdown, setCountdown] = useState(0);

  // Significant Change Logic
  const significantChange = useMemo(() => {
    if (sessionHistory.length < 2) return null;
    const current = sessionHistory[sessionHistory.length - 1];
    const previous = sessionHistory[sessionHistory.length - 2];
    const diff = current.score - previous.score;

    if (Math.abs(diff) > 8) {
      return {
        type: (diff > 0 ? 'improvement' : 'deterioration') as 'improvement' | 'deterioration',
        value: Math.abs(diff)
      };
    }
    return null;
  }, [sessionHistory]);

  // Stability Index
  const stabilityIndex = useMemo(() => {
    if (sessionHistory.length < 3) return 100;
    const lastScores = sessionHistory.slice(-5).map(p => p.score);
    const mean = lastScores.reduce((a, b) => a + b, 0) / lastScores.length;
    const variance = lastScores.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / lastScores.length;
    return Math.max(0, 100 - Math.sqrt(variance) * 5);
  }, [sessionHistory]);

  // Dynamic Aura Color
  const auraStyles = useMemo(() => {
    if (!analysis) return { glow: 'transparent', border: 'border-slate-800', pulse: '' };
    const score = analysis.alignmentScore;
    if (score > 85) return { glow: 'rgba(16, 185, 129, 0.1)', border: 'border-emerald-500/40 shadow-emerald-500/10', pulse: '' };
    if (score > 70) return { glow: 'rgba(79, 70, 229, 0.1)', border: 'border-indigo-500/40 shadow-indigo-500/10', pulse: '' };
    if (score > 50) return { glow: 'rgba(245, 158, 11, 0.15)', border: 'border-amber-500/40 shadow-amber-500/10', pulse: 'animate-pulse' };
    return { glow: 'rgba(239, 68, 68, 0.2)', border: 'border-red-500/60 shadow-red-500/20', pulse: 'animate-pulse' };
  }, [analysis]);

  const [activeAlert, setActiveAlert] = useState<'improvement' | 'deterioration' | null>(null);

  useEffect(() => {
    if (significantChange) {
      setActiveAlert(significantChange.type);
      setDeltaIndicator({
        value: Math.round(significantChange.value),
        type: significantChange.type === 'improvement' ? 'plus' : 'minus'
      });
      setTriggerRipple(true);

      const timer = setTimeout(() => {
        setActiveAlert(null);
        setDeltaIndicator(null);
        setTriggerRipple(false);
      }, 3000);
      return () => clearTimeout(timer);
    }
  }, [significantChange]);

  // Auto-scroll log to bottom
  useEffect(() => {
    if (logEndRef.current) {
      logEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [sessionEvents]);

  const addEvent = (event: Omit<SessionEvent, 'id' | 'time'>) => {
    const newEvent: SessionEvent = {
      ...event,
      id: Math.random().toString(36).substr(2, 9),
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })
    };
    setSessionEvents(prev => [...prev.slice(-49), newEvent]);
  };

  const toggleCamera = async () => {
    if (isActive) {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
      setIsActive(false);
      setAnalysis(null);
      setCalibrationStep('idle');
      setActiveAlert(null);
      setLastGhostLandmarks(null);
      addEvent({ type: 'system', label: 'Monitoring Session Terminated' });
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsActive(true);
          setStartTime(Date.now());
          setSessionHistory([]);
          setSessionEvents([]);
          setError(null);
          addEvent({ type: 'system', label: 'New Monitoring Session Initiated' });
        }
      } catch (err) {
        setError("Could not access camera. Please check permissions.");
      }
    }
  };

  const startCalibrationWizard = () => {
    if (!isActive) return;
    setCalibrationStep('instruction');
  };

  const proceedToCountdown = () => {
    setCalibrationStep('preparing');
    setCountdown(5);
  };

  const clearCalibration = () => {
    setBaselineLandmarks(null);
    addEvent({ type: 'system', label: 'Clinical Baseline Cleared' });
  };

  useEffect(() => {
    if (calibrationStep === 'preparing' && countdown > 0) {
      const timer = setTimeout(() => setCountdown(countdown - 1), 1000);
      return () => clearTimeout(timer);
    } else if (calibrationStep === 'preparing' && countdown === 0) {
      captureCalibration();
    }
  }, [calibrationStep, countdown]);

  const captureCalibration = async () => {
    if (!videoRef.current) return;
    setCalibrationStep('capturing');

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `Detect normalized (0-100) coordinates for posture landmarks: Head, LeftShoulder, RightShoulder, SpineCenter, LeftHip, RightHip. Return ONLY JSON.` }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER },
                    y: { type: Type.NUMBER },
                    label: { type: Type.STRING }
                  },
                  required: ['x', 'y', 'label']
                }
              }
            },
            required: ['landmarks']
          }
        }
      });
      const result = JSON.parse(response.text || '{}');
      if (result.landmarks) {
        setBaselineLandmarks(result.landmarks);
        setCalibrationStep('complete');
        addEvent({ type: 'system', label: 'New Baseline Calibration Applied' });
        setTimeout(() => setCalibrationStep('idle'), 2000);
      }
    } catch (err) {
      setError("Calibration failed. Please try again.");
      setCalibrationStep('idle');
    }
  };

  const analyzeFrame = async () => {
    if (!isActive || !videoRef.current || isAnalyzing || calibrationStep !== 'idle') return;

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const promptText = `Analyze posture ${baselineLandmarks ? `relative to baseline: ${JSON.stringify(baselineLandmarks)}` : ''}.
           1. Detect normalized landmarks (0-100): Head, LeftShoulder, RightShoulder, SpineCenter, LeftHip, RightHip.
           2. Estimate simulated Cobb Angle (0-90°).
           3. Classify severity.
           4. alignmentScore (0-100).
           5. feedback: concise clinical tip.
           6. recommendations: 3 short exercise names.
           Return JSON.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: promptText }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER },
                    y: { type: Type.NUMBER },
                    label: { type: Type.STRING }
                  },
                  required: ['x', 'y', 'label']
                }
              },
              alignmentScore: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              isDeviating: { type: Type.BOOLEAN },
              estimatedCobbAngle: { type: Type.NUMBER },
              severity: { type: Type.STRING, enum: ['Normal', 'Mild', 'Moderate', 'Severe'] },
              recommendations: { type: Type.ARRAY, items: { type: Type.STRING } }
            },
            required: ['landmarks', 'alignmentScore', 'feedback', 'isDeviating', 'estimatedCobbAngle', 'severity', 'recommendations']
          }
        }
      });

      const result = JSON.parse(response.text || '{}');

      // Update Ghosting Landmarks if a significant change is detected
      if (sessionHistory.length > 0) {
        const lastScore = sessionHistory[sessionHistory.length - 1].score;
        const delta = result.alignmentScore - lastScore;

        if (Math.abs(delta) > 12) {
          setLastGhostLandmarks(sessionHistory[sessionHistory.length - 1].landmarks || null);
          addEvent({
            type: delta > 0 ? 'improvement' : 'deterioration',
            label: delta > 0 ? 'Posture Improvement' : 'Postural Deviation',
            score: Math.round(result.alignmentScore),
            delta: Math.round(Math.abs(delta)),
            feedback: result.feedback
          });
        }
      }

      setAnalysis(result);

      const currentTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

      const newPoint: SessionDataPoint = {
        time: currentTime,
        timestamp: Date.now(),
        score: result.alignmentScore,
        angle: result.estimatedCobbAngle || 0,
        landmarks: result.landmarks,
        isEvent: Math.abs((sessionHistory[sessionHistory.length-1]?.score || result.alignmentScore) - result.alignmentScore) > 15
      };
      setSessionHistory(prev => [...prev.slice(-44), newPoint]); 
    } catch (err) {
      console.error(err);
    } finally {
      setIsAnalyzing(false);
    }
  };

  useEffect(() => {
    let interval: number;
    if (isActive && calibrationStep === 'idle') {
      interval = window.setInterval(analyzeFrame, 4000); 
    }
    return () => clearInterval(interval);
  }, [isActive, isAnalyzing, calibrationStep, baselineLandmarks]);

  useEffect(() => {
    if (!canvasRef.current || (!analysis && !baselineLandmarks)) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const { width, height } = canvasRef.current;
    ctx.clearRect(0, 0, width, height);

    const drawSkeleton = (points: Landmark[], color: string, alpha: number = 1, isSolid: boolean = true, isGhost: boolean = false) => {
      const getPt = (label: string) => points.find(p => p.label.toLowerCase().includes(label.toLowerCase()));

      const head = getPt('Head');
      const ls = getPt('LeftShoulder');
      const rs = getPt('RightShoulder');
      const spine = getPt('Spine');
      const lh = getPt('LeftHip');
      const rh = getPt('RightHip');

      ctx.globalAlpha = alpha;
      ctx.lineWidth = isSolid ? 4 : 2;
      ctx.strokeStyle = color;
      ctx.setLineDash(isGhost ? [5, 5] : []);

      if (isSolid && !isGhost) {
        ctx.shadowBlur = 15;
        ctx.shadowColor = color;
      } else {
        ctx.shadowBlur = 0;
      }

      const drawLine = (p1?: Landmark, p2?: Landmark) => {
        if (p1 && p2) {
          ctx.beginPath();
          ctx.moveTo(p1.x * width / 100, p1.y * height / 100);
          ctx.lineTo(p2.x * width / 100, p2.y * height / 100);
          ctx.stroke();
        }
      };

      drawLine(head, spine);
      drawLine(ls, rs);
      drawLine(ls, lh);
      drawLine(rs, rh);
      drawLine(lh, rh);
      drawLine(spine, lh);
      drawLine(spine, rh);

      points.forEach(pt => {
        const x = pt.x * width / 100;
        const y = pt.y * height / 100;

        // Highlight joint deviations if baseline exists
        let radius = isSolid ? 6 : 4;
        let jointColor = color;

        if (baselineLandmarks && isSolid && !isGhost) {
          const basePt = baselineLandmarks.find(b => b.label === pt.label);
          if (basePt) {
            const dx = Math.abs(pt.x - basePt.x);
            const dy = Math.abs(pt.y - basePt.y);
            if (dx > 8 || dy > 8) {
              jointColor = '#ef4444'; // Red if high deviation
              // Draw deviation halo
              ctx.beginPath();
              ctx.arc(x, y, radius + 10, 0, Math.PI * 2);
              ctx.strokeStyle = 'rgba(239, 68, 68, 0.4)';
              ctx.setLineDash([]);
              ctx.lineWidth = 2;
              ctx.stroke();
            } else if (dx > 4 || dy > 4) {
              jointColor = '#fbbf24'; // Yellow if moderate deviation
            }
          }
        }

        ctx.beginPath();
        ctx.arc(x, y, radius, 0, Math.PI * 2);
        ctx.fillStyle = jointColor;
        ctx.fill();

        if (isSolid && !isGhost && analysis?.isDeviating) {
           ctx.beginPath();
           ctx.arc(x, y, radius + 4, 0, Math.PI * 2);
           ctx.strokeStyle = '#ef4444';
           ctx.setLineDash([]);
           ctx.lineWidth = 1;
           ctx.stroke();
        }
      });
      ctx.globalAlpha = 1;
      ctx.shadowBlur = 0;
    };

    // Draw Session History Ghosts (Faded trail)
    if (isActive && sessionHistory.length > 2 && !isAnalyzing) {
       const recent = sessionHistory.slice(-5, -1);
       recent.forEach((pt, i) => {
          if (pt.landmarks) {
            drawSkeleton(pt.landmarks, '#94a3b8', 0.05 * (i + 1), true, true);
          }
       });
    }

    // Draw Significant Shift Ghost
    if (lastGhostLandmarks && isActive) {
      drawSkeleton(lastGhostLandmarks, '#fbbf24', 0.4, false, true);
    }

    // Draw Clinical Baseline
    if (baselineLandmarks && isActive) {
      drawSkeleton(baselineLandmarks, 'rgba(99, 102, 241, 0.4)', 1, false);
    }

    // Draw Current Analysis
    if (analysis?.landmarks && isActive) {
      drawSkeleton(analysis.landmarks, analysis.isDeviating ? '#ef4444' : '#10b981', 1, true);
    }
  }, [analysis, baselineLandmarks, isActive, lastGhostLandmarks, sessionHistory, isAnalyzing]);

  const getSeverityStyles = (severity?: ScoliosisSeverity) => {
    switch (severity) {
      case ScoliosisSeverity.NORMAL: return 'text-emerald-500 bg-emerald-50 border-emerald-100';
      case ScoliosisSeverity.MILD: return 'text-blue-500 bg-blue-50 border-blue-100';
      case ScoliosisSeverity.MODERATE: return 'text-amber-500 bg-amber-50 border-amber-100';
      case ScoliosisSeverity.SEVERE: return 'text-red-500 bg-red-50 border-red-100';
      default: return 'text-slate-400 bg-slate-50 border-slate-100';
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <style>{`
        @keyframes slide-up-fade {
          0% { opacity: 0; transform: translateY(0); }
          50% { opacity: 1; }
          100% { opacity: 0; transform: translateY(-40px); }
        }
        @keyframes stability-ripple {
          0% { transform: translate(-50%, -50%) scale(0); opacity: 0.8; }
          100% { transform: translate(-50%, -50%) scale(2); opacity: 0; }
        }
        .animate-delta-indicator {
          animation: slide-up-fade 3s ease-out forwards;
        }
        .animate-stability-ripple {
          animation: stability-ripple 1.5s ease-out forwards;
        }
        .custom-scrollbar::-webkit-scrollbar {
          width: 4px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: transparent;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #e2e8f0;
          border-radius: 10px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background: #cbd5e1;
        }
      `}</style>

      {significantChange && (
        <div className={`flex items-center justify-between p-4 rounded-2xl border animate-in slide-in-from-top-4 ${
          significantChange.type === 'improvement' ? 'bg-emerald-50 border-emerald-200 text-emerald-800' : 'bg-amber-50 border-amber-200 text-amber-800'
        }`}>
          <div className="flex items-center gap-3">
            {significantChange.type === 'improvement' ? <TrendingUp size={24} /> : <AlertTriangle size={24} />}
            <div>
              <p className="font-bold uppercase text-xs tracking-widest">Significant Postural Shift</p>
              <p className="text-sm">Alignment {significantChange.type === 'improvement' ? 'improved' : 'deviated'} by {significantChange.value.toFixed(1)} units.</p>
            </div>
          </div>
          <button onClick={() => setSessionHistory([])} className="p-2 hover:bg-black/5 rounded-full"><ChevronRight size={20} /></button>
        </div>
      )}

      <div className="flex flex-col xl:flex-row gap-8">
        <div className="flex-1 flex flex-col gap-6">
          <div className={`bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl relative aspect-video group border-4 transition-all duration-700 ${auraStyles.border} ${auraStyles.pulse}`}>
            <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity duration-700 ${isActive ? 'opacity-100' : 'opacity-20'}`} />

            {/* Stability Ripple Effect */}
            {triggerRipple && (
              <div className="absolute top-1/2 left-1/2 w-96 h-96 rounded-full border-4 border-indigo-500/50 pointer-events-none animate-stability-ripple" />
            )}

            {/* Alignment Delta Indicator (Overlay) */}
            {deltaIndicator && (
               <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 pointer-events-none z-30">
                  <div className={`flex items-center gap-2 px-6 py-3 rounded-full text-2xl font-black shadow-2xl backdrop-blur-md border-2 animate-delta-indicator ${
                    deltaIndicator.type === 'plus' ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500' : 'bg-red-500/20 text-red-400 border-red-500'
                  }`}>
                    {deltaIndicator.type === 'plus' ? <MoveUp size={28} /> : <MoveDown size={28} />}
                    {deltaIndicator.type === 'plus' ? '+' : '-'}{deltaIndicator.value} ALIGNMENT
                  </div>
               </div>
            )}

            {/* Live Alignment Meter (Vertical Bar on the Right) */}
            {isActive && (
              <div className="absolute right-6 top-1/2 -translate-y-1/2 w-4 h-48 bg-black/40 backdrop-blur-md rounded-full border border-white/10 p-0.5 overflow-hidden group-hover:w-6 transition-all duration-300">
                <div 
                  className="w-full rounded-full transition-all duration-1000 bg-gradient-to-t from-red-500 via-amber-400 to-emerald-500" 
                  style={{ height: `${analysis?.alignmentScore || 0}%`, marginTop: `${100 - (analysis?.alignmentScore || 0)}%` }}
                />
                <div className="absolute inset-0 flex flex-col justify-between items-center py-2 pointer-events-none">
                  <div className="w-1.5 h-px bg-white/20" />
                  <div className="w-1.5 h-px bg-white/20" />
                  <div className="w-1.5 h-px bg-white/20" />
                </div>
              </div>
            )}

            {/* Real-time Graph Overlay */}
            {isActive && sessionHistory.length > 1 && (
              <div className="absolute inset-x-0 bottom-0 h-1/4 pointer-events-none opacity-40 z-0">
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={sessionHistory} margin={{ top: 0, right: 0, left: 0, bottom: 0 }}>
                    <defs>
                      <linearGradient id="scoreOverlay" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#818cf8" stopOpacity={0.6}/>
                        <stop offset="95%" stopColor="#818cf8" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <Area 
                      type="monotone" 
                      dataKey="score" 
                      stroke="#ffffff" 
                      strokeWidth={1} 
                      fillOpacity={1} 
                      fill="url(#scoreOverlay)" 
                      isAnimationActive={true}
                      animationDuration={1500}
                    />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
            )}

            <div className="absolute inset-0 aura-overlay" style={{ background: `radial-gradient(circle, transparent 40%, ${auraStyles.glow} 100%)` }} />

            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none" width={640} height={480} />

            <div className="absolute top-8 left-8 flex items-center gap-3">
              <div className={`w-3 h-3 rounded-full ${isActive ? 'bg-red-500 animate-pulse' : 'bg-slate-600'}`}></div>
              <span className="text-white text-xs font-black tracking-widest uppercase opacity-80">
                {isActive ? 'Clinical Bio-Feedback' : 'Optical Engine Inactive'}
              </span>
            </div>

            {isActive && (
              <div className="absolute top-8 right-16 flex flex-col items-end gap-2">
                <div className="bg-black/40 backdrop-blur-md px-4 py-2 rounded-xl border border-white/10 flex items-center gap-3">
                  <Waves size={16} className={`text-indigo-400 ${stabilityIndex < 60 ? 'animate-bounce' : ''}`} />
                  <div>
                    <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest leading-none mb-1">Session Stability</p>
                    <p className="text-sm font-black text-white">{Math.round(stabilityIndex)}%</p>
                  </div>
                </div>
                {baselineLandmarks && (
                   <div className="bg-indigo-600/90 px-3 py-1.5 rounded-lg text-white text-[10px] font-black uppercase tracking-widest shadow-lg flex items-center gap-2">
                      <ShieldCheck size={14} /> Clinical Baseline Locked
                   </div>
                )}
                {lastGhostLandmarks && (
                   <div className="bg-amber-600/90 px-3 py-1.5 rounded-lg text-white text-[10px] font-black uppercase tracking-widest shadow-lg flex items-center gap-2 animate-pulse">
                      <History size={14} /> Deviation Ghost Active
                   </div>
                )}
              </div>
            )}

            {calibrationStep !== 'idle' && (
              <div className="absolute inset-0 bg-indigo-900/80 backdrop-blur-md flex flex-col items-center justify-center text-white z-20 animate-in fade-in p-12 text-center">
                {calibrationStep === 'instruction' && (
                  <div className="max-w-md space-y-6">
                    <div className="w-20 h-20 bg-white/10 rounded-3xl flex items-center justify-center mx-auto border border-white/20"><ScanEye size={40} className="text-indigo-400" /></div>
                    <h2 className="text-3xl font-black">Posture Normalization</h2>
                    <p className="text-indigo-100 font-medium">Stand straight with shoulders level to calibrate your neutral spinal alignment.</p>
                    <div className="flex gap-3">
                      <button onClick={() => setCalibrationStep('idle')} className="flex-1 py-4 bg-white/10 rounded-2xl font-bold">Cancel</button>
                      <button onClick={proceedToCountdown} className="flex-1 py-4 bg-indigo-500 rounded-2xl font-bold">Start</button>
                    </div>
                  </div>
                )}
                {calibrationStep === 'preparing' && (
                  <><div className="w-32 h-32 rounded-full border-8 border-white/10 flex items-center justify-center mb-8 relative"><span className="text-6xl font-black">{countdown}</span></div><h2 className="text-3xl font-black mb-2">Analyzing Pose</h2></>
                )}
                {calibrationStep === 'complete' && (
                  <div className="flex flex-col items-center gap-4"><div className="w-24 h-24 bg-emerald-500 rounded-full flex items-center justify-center"><CheckCircle2 size={48} /></div><p className="font-black text-3xl">Normalization Applied</p></div>
                )}
              </div>
            )}

            {!isActive && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-white space-y-4">
                <div className="w-20 h-20 bg-white/10 backdrop-blur-md rounded-3xl flex items-center justify-center text-slate-400"><CameraOff size={40} /></div>
                <div className="text-center px-8">
                  <p className="font-black text-xl mb-1">Optical Standby</p>
                  <p className="text-slate-400 text-sm font-medium">Connect the camera feed to begin real-time postural mapping.</p>
                </div>
              </div>
            )}

            {isAnalyzing && (
              <div className="absolute bottom-8 right-8 flex items-center gap-2 bg-indigo-600 px-4 py-2 rounded-xl text-white text-xs font-bold shadow-lg animate-pulse z-10">
                <RefreshCw size={14} className="animate-spin" /> Geometric Extraction...
              </div>
            )}

            <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-4 group-hover:scale-105 transition-transform z-10">
              <button onClick={toggleCamera} className={`flex items-center gap-3 px-8 py-4 rounded-2xl font-black text-sm uppercase tracking-widest transition-all ${isActive ? 'bg-white/10 backdrop-blur-md text-white border border-white/20 hover:bg-white/20' : 'bg-indigo-600 text-white shadow-xl shadow-indigo-500/20'}`}>
                {isActive ? <><Square size={18} /> Stop Feed</> : <><Play size={18} /> Start Feed</>}
              </button>
              {isActive && (
                <div className="flex gap-2">
                  <button onClick={startCalibrationWizard} disabled={calibrationStep !== 'idle'} className="flex items-center gap-3 px-8 py-4 bg-indigo-600 text-white rounded-2xl font-black text-sm uppercase tracking-widest shadow-lg shadow-indigo-500/30 disabled:opacity-50">
                    <Target size={18} /> {baselineLandmarks ? 'Adjust Base' : 'Calibrate'}
                  </button>
                  {baselineLandmarks && <button onClick={clearCalibration} className="p-4 bg-white/10 backdrop-blur-md text-white border border-white/20 rounded-2xl hover:bg-red-500/20 transition-all" title="Clear Baseline"><Undo2 size={18} /></button>}
                </div>
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col justify-between hover:border-indigo-100 transition-all">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Observed Cobb Angle</p>
              <p className="text-4xl font-black text-slate-800">{analysis?.estimatedCobbAngle ? `${analysis.estimatedCobbAngle.toFixed(1)}°` : '--°'}</p>
            </div>
            <div className={`p-6 rounded-3xl border shadow-sm flex flex-col justify-between transition-colors ${getSeverityStyles(analysis?.severity as ScoliosisSeverity)}`}>
              <p className="text-[10px] font-black uppercase tracking-widest mb-1 opacity-70">Curvature Risk</p>
              <p className="text-3xl font-black">{analysis?.severity || '--'}</p>
            </div>
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col justify-between hover:border-indigo-100 transition-all">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Alignment Score</p>
              <div className="flex items-baseline gap-1">
                <p className="text-4xl font-black text-indigo-600">{analysis ? `${Math.round(analysis.alignmentScore)}` : '--'}</p>
                <span className="text-xs font-bold text-slate-400">/ 100</span>
              </div>
            </div>
          </div>
        </div>

        <div className="w-full xl:w-96 space-y-6 flex flex-col">
          <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-lg">
            <h3 className="text-xl font-black text-slate-800 flex items-center gap-2 mb-6"><TrendingUp size={24} className="text-indigo-600" /> Session Progression</h3>
            <div className="h-48 w-full -ml-4">
              {sessionHistory.length > 1 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={sessionHistory}>
                    <defs><linearGradient id="colorScoreMain" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#4f46e5" stopOpacity={0.1}/><stop offset="95%" stopColor="#4f46e5" stopOpacity={0}/></linearGradient></defs>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                    <XAxis dataKey="time" hide />
                    <YAxis domain={[0, 100]} hide />
                    <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }} />
                    <Area type="monotone" dataKey="score" stroke="#4f46e5" strokeWidth={3} fillOpacity={1} fill="url(#colorScoreMain)" />
                  </AreaChart>
                </ResponsiveContainer>
              ) : (
                <div className="h-full flex flex-col items-center justify-center text-slate-300"><ActivityIcon size={32} className="opacity-20 mb-2" /><p className="text-[10px] font-black uppercase tracking-widest">Awaiting Samples</p></div>
              )}
            </div>
          </div>

          <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-lg flex flex-col flex-1 h-[400px]">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><History size={24} className="text-indigo-600" /> Monitoring Log</h3>
              {sessionEvents.length > 0 && (
                <button 
                  onClick={() => setSessionEvents([])}
                  className="p-2 hover:bg-red-50 text-slate-400 hover:text-red-500 rounded-lg transition-colors"
                  title="Clear Log"
                >
                  <Trash2 size={16} />
                </button>
              )}
            </div>

            <div className="space-y-4 overflow-y-auto flex-1 pr-2 custom-scrollbar">
              {sessionEvents.length > 0 ? (
                sessionEvents.map((event) => (
                  <div key={event.id} className="flex gap-4 p-4 bg-slate-50 rounded-2xl border border-slate-100 animate-in slide-in-from-left-2">
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${
                      event.type === 'improvement' ? 'bg-emerald-100 text-emerald-600' : 
                      event.type === 'deterioration' ? 'bg-amber-100 text-amber-600' :
                      'bg-indigo-100 text-indigo-600'
                    }`}>
                      {event.type === 'improvement' ? <ArrowUpRight size={20} /> : 
                       event.type === 'deterioration' ? <ArrowDownRight size={20} /> :
                       <Settings size={20} />}
                    </div>
                    <div className="flex-1">
                      <div className="flex justify-between items-start mb-1">
                        <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">{event.time}</p>
                        {event.delta !== undefined && (
                          <span className={`text-[10px] font-black px-1.5 py-0.5 rounded ${
                            event.type === 'improvement' ? 'bg-emerald-500 text-white' : 'bg-amber-500 text-white'
                          }`}>
                            {event.type === 'improvement' ? '+' : '-'}{event.delta}%
                          </span>
                        )}
                      </div>
                      <p className="text-sm font-bold text-slate-800 leading-tight">{event.label}</p>
                      {event.score !== undefined && <p className="text-[11px] font-medium text-slate-500 mt-0.5">Alignment Score: {event.score}%</p>}
                      {event.feedback && <p className="text-[11px] font-medium text-slate-400 italic mt-1 leading-snug">"{event.feedback}"</p>}
                    </div>
                  </div>
                ))
              ) : (
                <div className="flex flex-col items-center justify-center py-20 text-slate-400 opacity-60">
                  <Clock size={32} className="mb-2" />
                  <p className="text-xs font-medium">Establishing baseline...</p>
                </div>
              )}
              <div ref={logEndRef} />
            </div>
          </div>

          <div className="bg-indigo-50 p-6 rounded-[2rem] border border-indigo-100 relative overflow-hidden group">
             <div className="absolute -right-4 -top-4 w-20 h-20 bg-indigo-600/5 rounded-full group-hover:scale-150 transition-transform"></div>
             <div className="flex items-center gap-3 mb-4">
                <Lightbulb size={20} className="text-indigo-600" />
                <h4 className="font-black text-xs uppercase tracking-widest text-indigo-800">Dynamic Guidance</h4>
             </div>
             <p className="text-sm text-indigo-700 leading-relaxed italic relative z-10">
                {analysis?.feedback || "System is calculating symmetry vectors. Maintain vertical alignment for clinical accuracy."}
             </p>
             {analysis?.recommendations && (
               <div className="mt-4 pt-4 border-t border-indigo-200">
                 <p className="text-[10px] font-black text-indigo-400 uppercase mb-2">Prescribed Correctives</p>
                 <div className="flex flex-wrap gap-2">
                   {analysis.recommendations.map((r, i) => (
                     <span key={i} className="px-2 py-1 bg-white rounded-lg text-[10px] font-bold text-indigo-600 border border-indigo-200 shadow-sm">{r}</span>
                   ))}
                 </div>
               </div>
             )}
          </div>
        </div>
      </div>

      {error && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-red-50 text-red-700 px-6 py-4 rounded-2xl border border-red-100 shadow-2xl flex items-center gap-4 z-50 animate-in slide-in-from-bottom-4">
          <AlertCircle size={24} /> <p className="font-bold">{error}</p> <button onClick={() => setError(null)} className="ml-4 p-1 hover:bg-red-100 rounded-full transition-colors"><ChevronRight size={18} /></button>
        </div>
      )}
    </div>
  );
};

export default PostureLiveView;

import React, { useEffect, useRef, useState, useMemo } from 'react';
import { 
  Camera, 
  CameraOff, 
  Play, 
  Square, 
  RefreshCw, 
  Zap, 
  AlertCircle, 
  Activity,
  CheckCircle2,
  ScanEye,
  Target,
  ChevronRight,
  ShieldCheck,
  Dumbbell,
  Stethoscope,
  TrendingUp,
  AlertTriangle,
  ArrowUpRight,
  ArrowDownRight,
  Info,
  UserCheck,
  Undo2,
  Clock,
  History,
  Timer,
  Waves,
  Lightbulb,
  ArrowRight,
  MoveUp,
  MoveDown,
  Trash2,
  Settings,
  Activity as ActivityIcon,
  Pulse
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";
import { PostureAnalysis, Landmark, ScoliosisSeverity } from '../types';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceLine } from 'recharts';

type CalibrationStep = 'idle' | 'instruction' | 'preparing' | 'capturing' | 'complete';

interface SessionEvent {
  id: string;
  time: string;
  type: 'improvement' | 'deterioration' | 'deviation' | 'system';
  score: number;
  delta: number;
  label: string;
  feedback: string;
}

interface SessionDataPoint {
  time: string;
  timestamp: number;
  score: number;
  angle: number;
  landmarks?: Landmark[];
  isEvent?: boolean;
}

const PostureLiveView: React.FC = () => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const logEndRef = useRef<HTMLDivElement>(null);

  const [isActive, setIsActive] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<PostureAnalysis | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [sessionHistory, setSessionHistory] = useState<SessionDataPoint[]>([]);
  const [sessionEvents, setSessionEvents] = useState<SessionEvent[]>([]);
  const [startTime, setStartTime] = useState<number | null>(null);

  // Real-time Visual indicators
  const [lastGhostLandmarks, setLastGhostLandmarks] = useState<Landmark[] | null>(null);
  const [deltaIndicator, setDeltaIndicator] = useState<{ value: number, type: 'plus' | 'minus' | 'alert' } | null>(null);
  const [triggerRipple, setTriggerRipple] = useState(false);

  // Calibration State
  const [calibrationStep, setCalibrationStep] = useState<CalibrationStep>('idle');
  const [baselineLandmarks, setBaselineLandmarks] = useState<Landmark[] | null>(null);
  const [baselineScore, setBaselineScore] = useState<number | null>(null);
  const [countdown, setCountdown] = useState(0);

  // Auto-scroll log to bottom
  useEffect(() => {
    if (logEndRef.current) {
      logEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [sessionEvents]);

  // Session Stats
  const sessionSummary = useMemo(() => {
    if (sessionHistory.length < 2) return { trend: 0, status: 'Neutral' };
    const first = sessionHistory[0].score;
    const current = sessionHistory[sessionHistory.length - 1].score;
    const diff = current - first;
    return {
      trend: Math.round(diff),
      status: diff > 5 ? 'Improving' : diff < -5 ? 'Regressing' : 'Stable'
    };
  }, [sessionHistory]);

  // Dynamic Aura Color
  const auraStyles = useMemo(() => {
    if (!analysis) return { glow: 'transparent', border: 'border-slate-800', pulse: '' };
    const score = analysis.alignmentScore;
    if (score > 85) return { glow: 'rgba(16, 185, 129, 0.1)', border: 'border-emerald-500/40 shadow-emerald-500/10', pulse: '' };
    if (score > 70) return { glow: 'rgba(79, 70, 229, 0.1)', border: 'border-indigo-500/40 shadow-indigo-500/10', pulse: '' };
    if (score > 50) return { glow: 'rgba(245, 158, 11, 0.15)', border: 'border-amber-500/40 shadow-amber-500/10', pulse: 'animate-pulse' };
    return { glow: 'rgba(239, 68, 68, 0.2)', border: 'border-red-500/60 shadow-red-500/20', pulse: 'animate-pulse' };
  }, [analysis]);

  const addEvent = (event: Omit<SessionEvent, 'id' | 'time'>) => {
    const newEvent: SessionEvent = {
      ...event,
      id: Math.random().toString(36).substr(2, 9),
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })
    };
    setSessionEvents(prev => [...prev.slice(-49), newEvent]);
  };

  const toggleCamera = async () => {
    if (isActive) {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
      setIsActive(false);
      setAnalysis(null);
      setCalibrationStep('idle');
      setLastGhostLandmarks(null);
      addEvent({ type: 'system', label: 'Session Stopped', score: 0, delta: 0, feedback: 'Monitoring terminated by user.' });
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsActive(true);
          setStartTime(Date.now());
          setSessionHistory([]);
          setSessionEvents([]);
          setError(null);
          addEvent({ type: 'system', label: 'Session Started', score: 0, delta: 0, feedback: 'Optical engine initialized.' });
        }
      } catch (err) {
        setError("Could not access camera. Please check permissions.");
      }
    }
  };

  const captureCalibration = async () => {
    if (!videoRef.current) return;
    setCalibrationStep('capturing');

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `Detect normalized (0-100) coordinates for posture landmarks: Head, LeftShoulder, RightShoulder, SpineCenter, LeftHip, RightHip. Calculate an initial alignmentScore (0-100). Return ONLY JSON.` }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER },
                    y: { type: Type.NUMBER },
                    label: { type: Type.STRING }
                  },
                  required: ['x', 'y', 'label']
                }
              },
              alignmentScore: { type: Type.NUMBER }
            },
            required: ['landmarks', 'alignmentScore']
          }
        }
      });
      const result = JSON.parse(response.text || '{}');
      if (result.landmarks) {
        setBaselineLandmarks(result.landmarks);
        setBaselineScore(result.alignmentScore);
        setCalibrationStep('complete');
        addEvent({ 
          type: 'system', 
          label: 'Baseline Fixed', 
          score: result.alignmentScore, 
          delta: 0, 
          feedback: `Clinical baseline locked at ${result.alignmentScore}% alignment.` 
        });
        setTimeout(() => setCalibrationStep('idle'), 2000);
      }
    } catch (err) {
      setError("Calibration failed. Please try again.");
      setCalibrationStep('idle');
    }
  };

  const analyzeFrame = async () => {
    if (!isActive || !videoRef.current || isAnalyzing || calibrationStep !== 'idle') return;

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const promptText = `Analyze posture ${baselineLandmarks ? `relative to baseline: ${JSON.stringify(baselineLandmarks)}` : ''}.
           1. Detect normalized landmarks (0-100): Head, LeftShoulder, RightShoulder, SpineCenter, LeftHip, RightHip.
           2. Estimate simulated Cobb Angle (0-90°).
           3. Classify severity.
           4. alignmentScore (0-100).
           5. feedback: concise clinical tip.
           Return JSON.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: promptText }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  },
                  required: ['x', 'y', 'label']
                }
              },
              alignmentScore: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              isDeviating: { type: Type.BOOLEAN },
              estimatedCobbAngle: { type: Type.NUMBER },
              severity: { type: Type.STRING, enum: ['Normal', 'Mild', 'Moderate', 'Severe'] },
              recommendations: { type: Type.ARRAY, items: { type: Type.STRING } }
            },
            required: ['landmarks', 'alignmentScore', 'feedback', 'isDeviating', 'estimatedCobbAngle', 'severity']
          }
        }
      });

      const result = JSON.parse(response.text || '{}');

      // LOGIC: Detect significant changes
      if (sessionHistory.length > 0) {
        const lastScore = sessionHistory[sessionHistory.length - 1].score;
        const deltaPrev = result.alignmentScore - lastScore;

        // 1. Check change from PREVIOUS frame
        if (Math.abs(deltaPrev) > 10) {
          setDeltaIndicator({
            value: Math.round(Math.abs(deltaPrev)),
            type: deltaPrev > 0 ? 'plus' : 'minus'
          });
          setTriggerRipple(true);

          addEvent({
            type: deltaPrev > 0 ? 'improvement' : 'deterioration',
            label: deltaPrev > 0 ? 'Clinical Correction' : 'Postural Drift',
            score: Math.round(result.alignmentScore),
            delta: Math.round(deltaPrev),
            feedback: result.feedback
          });
        }

        // 2. Check deviation from BASELINE
        if (baselineScore !== null) {
          const deltaBase = result.alignmentScore - baselineScore;
          if (deltaBase < -15) {
             addEvent({
                type: 'deviation',
                label: 'Significant Baseline Deviation',
                score: Math.round(result.alignmentScore),
                delta: Math.round(deltaBase),
                feedback: 'Posture has regressed significantly from original baseline.'
             });
             setDeltaIndicator({ value: Math.round(Math.abs(deltaBase)), type: 'alert' });
          }
        }

        setTimeout(() => {
          setDeltaIndicator(null);
          setTriggerRipple(false);
        }, 3000);
      }

      setAnalysis(result);

      const currentTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
      const newPoint: SessionDataPoint = {
        time: currentTime,
        timestamp: Date.now(),
        score: result.alignmentScore,
        angle: result.estimatedCobbAngle || 0,
        landmarks: result.landmarks
      };
      setSessionHistory(prev => [...prev.slice(-44), newPoint]); 
    } catch (err) {
      console.error(err);
    } finally {
      setIsAnalyzing(false);
    }
  };

  useEffect(() => {
    let interval: number;
    if (isActive && calibrationStep === 'idle') {
      interval = window.setInterval(analyzeFrame, 4000); 
    }
    return () => clearInterval(interval);
  }, [isActive, isAnalyzing, calibrationStep, baselineLandmarks]);

  useEffect(() => {
    if (!canvasRef.current || (!analysis && !baselineLandmarks)) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const { width, height } = canvasRef.current;
    ctx.clearRect(0, 0, width, height);

    const drawSkeleton = (points: Landmark[], color: string, alpha: number = 1, isSolid: boolean = true, isGhost: boolean = false) => {
      const getPt = (label: string) => points.find(p => p.label.toLowerCase().includes(label.toLowerCase()));
      const head = getPt('Head');
      const ls = getPt('LeftShoulder');
      const rs = getPt('RightShoulder');
      const spine = getPt('Spine');
      const lh = getPt('LeftHip');
      const rh = getPt('RightHip');

      ctx.globalAlpha = alpha;
      ctx.lineWidth = isSolid ? 4 : 2;
      ctx.strokeStyle = color;
      ctx.setLineDash(isGhost ? [5, 5] : []);

      const drawLine = (p1?: Landmark, p2?: Landmark) => {
        if (p1 && p2) {
          ctx.beginPath();
          ctx.moveTo(p1.x * width / 100, p1.y * height / 100);
          ctx.lineTo(p2.x * width / 100, p2.y * height / 100);
          ctx.stroke();
        }
      };

      drawLine(head, spine);
      drawLine(ls, rs);
      drawLine(ls, lh);
      drawLine(rs, rh);
      drawLine(lh, rh);
      drawLine(spine, lh);
      drawLine(spine, rh);

      points.forEach(pt => {
        const x = pt.x * width / 100;
        const y = pt.y * height / 100;
        ctx.beginPath();
        ctx.arc(x, y, isSolid ? 6 : 4, 0, Math.PI * 2);
        ctx.fillStyle = color;
        ctx.fill();
      });
      ctx.globalAlpha = 1;
    };

    if (baselineLandmarks && isActive) {
      drawSkeleton(baselineLandmarks, 'rgba(99, 102, 241, 0.4)', 1, false);
    }

    if (analysis?.landmarks && isActive) {
      drawSkeleton(analysis.landmarks, analysis.isDeviating ? '#ef4444' : '#10b981', 1, true);
    }
  }, [analysis, baselineLandmarks, isActive]);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <style>{`
        @keyframes slide-up-fade {
          0% { opacity: 0; transform: translateY(0); }
          50% { opacity: 1; }
          100% { opacity: 0; transform: translateY(-40px); }
        }
        @keyframes ripple {
          0% { transform: translate(-50%, -50%) scale(0); opacity: 0.8; }
          100% { transform: translate(-50%, -50%) scale(2.5); opacity: 0; }
        }
        .animate-delta-indicator { animation: slide-up-fade 3s ease-out forwards; }
        .animate-ripple { animation: ripple 1.5s ease-out forwards; }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }
      `}</style>

      <div className="flex flex-col xl:flex-row gap-8">
        {/* VIDEO MONITORING AREA */}
        <div className="flex-1 flex flex-col gap-6">
          <div className={`bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl relative aspect-video group border-4 transition-all duration-700 ${auraStyles.border} ${auraStyles.pulse}`}>
            <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity duration-700 ${isActive ? 'opacity-100' : 'opacity-20'}`} />

            {triggerRipple && <div className="absolute top-1/2 left-1/2 w-96 h-96 rounded-full border-4 border-white/50 pointer-events-none animate-ripple" />}

            {deltaIndicator && (
               <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 pointer-events-none z-30">
                  <div className={`flex items-center gap-2 px-6 py-3 rounded-full text-2xl font-black shadow-2xl backdrop-blur-md border-2 animate-delta-indicator ${
                    deltaIndicator.type === 'plus' ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500' : 
                    deltaIndicator.type === 'minus' ? 'bg-amber-500/20 text-amber-400 border-amber-500' :
                    'bg-red-500/20 text-red-400 border-red-500'
                  }`}>
                    {deltaIndicator.type === 'plus' ? <MoveUp size={28} /> : <MoveDown size={28} />}
                    {deltaIndicator.type === 'plus' ? '+' : '-'}{deltaIndicator.value}%
                  </div>
               </div>
            )}

            <div className="absolute inset-0 aura-overlay" style={{ background: `radial-gradient(circle, transparent 40%, ${auraStyles.glow} 100%)` }} />
            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none" width={640} height={480} />

            <div className="absolute top-8 left-8 flex items-center gap-3">
              <div className={`w-3 h-3 rounded-full ${isActive ? 'bg-red-500 animate-pulse' : 'bg-slate-600'}`}></div>
              <span className="text-white text-xs font-black tracking-widest uppercase opacity-80">
                {isActive ? 'Clinical Bio-Feedback Engine' : 'System Standby'}
              </span>
            </div>

            {isActive && (
              <div className="absolute top-8 right-8 flex flex-col items-end gap-2">
                <div className="bg-black/40 backdrop-blur-md px-4 py-2 rounded-xl border border-white/10 flex items-center gap-3">
                  <Waves size={16} className="text-indigo-400" />
                  <div>
                    <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest leading-none mb-1">Session Summary</p>
                    <p className={`text-sm font-black ${sessionSummary.trend >= 0 ? 'text-emerald-400' : 'text-amber-400'}`}>
                       {sessionSummary.trend > 0 ? '+' : ''}{sessionSummary.trend}% {sessionSummary.status}
                    </p>
                  </div>
                </div>
                {baselineLandmarks && (
                   <div className="bg-indigo-600/90 px-3 py-1.5 rounded-lg text-white text-[10px] font-black uppercase tracking-widest shadow-lg flex items-center gap-2">
                      <ShieldCheck size={14} /> Clinical Baseline Locked
                   </div>
                )}
              </div>
            )}

            {calibrationStep !== 'idle' && (
              <div className="absolute inset-0 bg-indigo-900/80 backdrop-blur-md flex flex-col items-center justify-center text-white z-20 animate-in fade-in p-12 text-center">
                {calibrationStep === 'instruction' && (
                  <div className="max-w-md space-y-6">
                    <div className="w-20 h-20 bg-white/10 rounded-3xl flex items-center justify-center mx-auto border border-white/20"><ScanEye size={40} className="text-indigo-400" /></div>
                    <h2 className="text-3xl font-black">Clinical Calibration</h2>
                    <p className="text-indigo-100 font-medium">Stand centered and align your spine vertically to lock your neutral posture baseline.</p>
                    <div className="flex gap-3">
                      <button onClick={() => setCalibrationStep('idle')} className="flex-1 py-4 bg-white/10 rounded-2xl font-bold">Cancel</button>
                      <button onClick={() => { setCalibrationStep('preparing'); setCountdown(5); }} className="flex-1 py-4 bg-indigo-500 rounded-2xl font-bold">Start Capture</button>
                    </div>
                  </div>
                )}
                {calibrationStep === 'preparing' && (
                   <><div className="w-32 h-32 rounded-full border-8 border-white/10 flex items-center justify-center mb-8"><span className="text-6xl font-black">{countdown}</span></div><h2 className="text-3xl font-black mb-2">Analyzing Vector Base...</h2></>
                )}
                {calibrationStep === 'complete' && (
                  <div className="flex flex-col items-center gap-4"><div className="w-24 h-24 bg-emerald-500 rounded-full flex items-center justify-center"><CheckCircle2 size={48} /></div><p className="font-black text-3xl">Normalization Applied</p></div>
                )}
              </div>
            )}

            {!isActive && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-white space-y-4">
                <div className="w-20 h-20 bg-white/10 backdrop-blur-md rounded-3xl flex items-center justify-center text-slate-400"><CameraOff size={40} /></div>
                <div className="text-center px-8">
                  <p className="font-black text-xl mb-1">Optical Standby</p>
                  <p className="text-slate-400 text-sm font-medium">Initialize feed for real-time skeletal mapping.</p>
                </div>
              </div>
            )}

            <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-4 group-hover:scale-105 transition-transform z-10">
              <button onClick={toggleCamera} className={`flex items-center gap-3 px-8 py-4 rounded-2xl font-black text-sm uppercase tracking-widest transition-all ${isActive ? 'bg-white/10 backdrop-blur-md text-white border border-white/20 hover:bg-white/20' : 'bg-indigo-600 text-white shadow-xl shadow-indigo-500/20'}`}>
                {isActive ? <><Square size={18} /> Stop Feed</> : <><Play size={18} /> Start Feed</>}
              </button>
              {isActive && (
                <button onClick={() => setCalibrationStep('instruction')} disabled={calibrationStep !== 'idle'} className="flex items-center gap-3 px-8 py-4 bg-indigo-600 text-white rounded-2xl font-black text-sm uppercase tracking-widest shadow-lg shadow-indigo-500/30 disabled:opacity-50">
                   <Target size={18} /> {baselineLandmarks ? 'Reset Base' : 'Set Baseline'}
                </button>
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Cobb Angle (Live)</p>
              <p className="text-4xl font-black text-slate-800">{analysis?.estimatedCobbAngle ? `${analysis.estimatedCobbAngle.toFixed(1)}°` : '--°'}</p>
            </div>
            <div className={`p-6 rounded-3xl border shadow-sm ${getSeverityStyles(analysis?.severity as ScoliosisSeverity)}`}>
              <p className="text-[10px] font-black uppercase tracking-widest mb-1 opacity-70">Curvature Risk</p>
              <p className="text-3xl font-black">{analysis?.severity || '--'}</p>
            </div>
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Alignment Score</p>
              <p className="text-4xl font-black text-indigo-600">{analysis ? `${Math.round(analysis.alignmentScore)}%` : '--%'}</p>
            </div>
          </div>
        </div>

        {/* SIDEBAR LOGGING AREA */}
        <div className="w-full xl:w-96 space-y-6 flex flex-col max-h-[calc(100vh-200px)]">
          <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-lg flex flex-col flex-1 overflow-hidden">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><History size={24} className="text-indigo-600" /> Monitoring Log</h3>
              <button 
                onClick={() => setSessionEvents([])} 
                className="p-2 hover:bg-slate-100 text-slate-400 hover:text-red-500 rounded-lg transition-colors"
                title="Clear Session History"
              >
                <Trash2 size={16} />
              </button>
            </div>

            <div className="space-y-4 overflow-y-auto flex-1 pr-2 custom-scrollbar">
              {sessionEvents.length > 0 ? (
                sessionEvents.map((event) => (
                  <div key={event.id} className={`flex gap-4 p-4 rounded-2xl border animate-in slide-in-from-left-2 ${
                    event.type === 'improvement' ? 'bg-emerald-50 border-emerald-100' :
                    event.type === 'deterioration' ? 'bg-amber-50 border-amber-100' :
                    event.type === 'deviation' ? 'bg-red-50 border-red-100' :
                    'bg-slate-50 border-slate-100'
                  }`}>
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${
                      event.type === 'improvement' ? 'bg-emerald-100 text-emerald-600' : 
                      event.type === 'deterioration' ? 'bg-amber-100 text-amber-600' :
                      event.type === 'deviation' ? 'bg-red-100 text-red-600' :
                      'bg-indigo-100 text-indigo-600'
                    }`}>
                      {event.type === 'improvement' ? <ArrowUpRight size={20} /> : 
                       event.type === 'deterioration' ? <ArrowDownRight size={20} /> :
                       event.type === 'deviation' ? <AlertTriangle size={20} /> :
                       <ActivityIcon size={20} />}
                    </div>
                    <div className="flex-1">
                      <div className="flex justify-between items-start mb-1">
                        <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">{event.time}</p>
                        <span className={`text-[10px] font-black px-1.5 py-0.5 rounded shadow-sm ${
                           event.type === 'improvement' ? 'bg-emerald-600 text-white' : 
                           event.type === 'deterioration' ? 'bg-amber-600 text-white' : 
                           'bg-red-600 text-white'
                        }`}>
                           {event.delta > 0 ? '+' : ''}{event.delta}%
                        </span>
                      </div>
                      <p className="text-sm font-bold text-slate-800 leading-tight">{event.label}</p>
                      <p className="text-[11px] font-medium text-slate-500 mt-1 leading-relaxed italic">"{event.feedback}"</p>
                    </div>
                  </div>
                ))
              ) : (
                <div className="flex flex-col items-center justify-center py-20 text-slate-300 opacity-60">
                  <Clock size={32} className="mb-2" />
                  <p className="text-xs font-bold uppercase tracking-widest">Awaiting Events</p>
                </div>
              )}
              <div ref={logEndRef} />
            </div>
          </div>

          <div className="bg-indigo-50 p-6 rounded-[2rem] border border-indigo-100">
             <div className="flex items-center gap-3 mb-4">
                <Lightbulb size={20} className="text-indigo-600" />
                <h4 className="font-black text-xs uppercase tracking-widest text-indigo-800">Dynamic Guidance</h4>
             </div>
             <p className="text-sm text-indigo-700 leading-relaxed italic">
                {analysis?.feedback || "System standing by. Please align with camera for baseline vector mapping."}
             </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PostureLiveView;

import React, { useEffect, useRef, useState, useMemo } from 'react';
import { 
  Camera, 
  CameraOff, 
  Play, 
  Square, 
  RefreshCw, 
  Zap, 
  AlertCircle, 
  Activity,
  CheckCircle2,
  ScanEye,
  Target,
  ChevronRight,
  ShieldCheck,
  Dumbbell,
  Stethoscope,
  TrendingUp,
  AlertTriangle,
  ArrowUpRight,
  ArrowDownRight,
  Info,
  UserCheck,
  Undo2,
  Clock,
  History,
  Timer,
  Waves,
  Lightbulb,
  ArrowRight,
  MoveUp,
  MoveDown,
  Trash2,
  Settings,
  Activity as ActivityIcon
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";
import { PostureAnalysis, Landmark, ScoliosisSeverity } from '../types';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceLine } from 'recharts';

type CalibrationStep = 'idle' | 'instruction' | 'preparing' | 'capturing' | 'complete';

interface SessionEvent {
  id: string;
  time: string;
  type: 'improvement' | 'deterioration' | 'deviation' | 'system';
  score: number;
  delta: number;
  label: string;
  feedback: string;
}

interface SessionDataPoint {
  time: string;
  timestamp: number;
  score: number;
  angle: number;
  landmarks?: Landmark[];
  isEvent?: boolean;
}

const PostureLiveView: React.FC = () => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const logEndRef = useRef<HTMLDivElement>(null);

  const [isActive, setIsActive] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<PostureAnalysis | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [sessionHistory, setSessionHistory] = useState<SessionDataPoint[]>([]);
  const [sessionEvents, setSessionEvents] = useState<SessionEvent[]>([]);
  const [startTime, setStartTime] = useState<number | null>(null);

  // Real-time Visual indicators
  const [lastGhostLandmarks, setLastGhostLandmarks] = useState<Landmark[] | null>(null);
  const [deltaIndicator, setDeltaIndicator] = useState<{ value: number, type: 'plus' | 'minus' | 'alert' } | null>(null);
  const [triggerRipple, setTriggerRipple] = useState(false);

  // Calibration State
  const [calibrationStep, setCalibrationStep] = useState<CalibrationStep>('idle');
  const [baselineLandmarks, setBaselineLandmarks] = useState<Landmark[] | null>(null);
  const [baselineScore, setBaselineScore] = useState<number | null>(null);
  const [countdown, setCountdown] = useState(0);

  // Helper to determine severity styles for the UI
  const getSeverityStyles = (severity: ScoliosisSeverity) => {
    switch (severity) {
      case ScoliosisSeverity.NORMAL: return 'bg-emerald-50 text-emerald-700 border-emerald-200';
      case ScoliosisSeverity.MILD: return 'bg-blue-50 text-blue-700 border-blue-200';
      case ScoliosisSeverity.MODERATE: return 'bg-amber-50 text-amber-700 border-amber-200';
      case ScoliosisSeverity.SEVERE: return 'bg-red-50 text-red-700 border-red-200';
      default: return 'bg-slate-50 text-slate-700 border-slate-200';
    }
  };

  // Auto-scroll log to bottom
  useEffect(() => {
    if (logEndRef.current) {
      logEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [sessionEvents]);

  // Session Stats
  const sessionSummary = useMemo(() => {
    if (sessionHistory.length < 2) return { trend: 0, status: 'Neutral' };
    const first = sessionHistory[0].score;
    const current = sessionHistory[sessionHistory.length - 1].score;
    const diff = current - first;
    return {
      trend: Math.round(diff),
      status: diff > 5 ? 'Improving' : diff < -5 ? 'Regressing' : 'Stable'
    };
  }, [sessionHistory]);

  // Dynamic Aura Color
  const auraStyles = useMemo(() => {
    if (!analysis) return { glow: 'transparent', border: 'border-slate-800', pulse: '' };
    const score = analysis.alignmentScore;
    if (score > 85) return { glow: 'rgba(16, 185, 129, 0.1)', border: 'border-emerald-500/40 shadow-emerald-500/10', pulse: '' };
    if (score > 70) return { glow: 'rgba(79, 70, 229, 0.1)', border: 'border-indigo-500/40 shadow-indigo-500/10', pulse: '' };
    if (score > 50) return { glow: 'rgba(245, 158, 11, 0.15)', border: 'border-amber-500/40 shadow-amber-500/10', pulse: 'animate-pulse' };
    return { glow: 'rgba(239, 68, 68, 0.2)', border: 'border-red-500/60 shadow-red-500/20', pulse: 'animate-pulse' };
  }, [analysis]);

  const addEvent = (event: Omit<SessionEvent, 'id' | 'time'>) => {
    const newEvent: SessionEvent = {
      ...event,
      id: Math.random().toString(36).substr(2, 9),
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })
    };
    setSessionEvents(prev => [...prev.slice(-49), newEvent]);
  };

  const toggleCamera = async () => {
    if (isActive) {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
      setIsActive(false);
      setAnalysis(null);
      setCalibrationStep('idle');
      setLastGhostLandmarks(null);
      addEvent({ type: 'system', label: 'Session Stopped', score: 0, delta: 0, feedback: 'Monitoring terminated by user.' });
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsActive(true);
          setStartTime(Date.now());
          setSessionHistory([]);
          setSessionEvents([]);
          setError(null);
          addEvent({ type: 'system', label: 'Session Started', score: 0, delta: 0, feedback: 'Optical engine initialized.' });
        }
      } catch (err) {
        setError("Could not access camera. Please check permissions.");
      }
    }
  };

  const captureCalibration = async () => {
    if (!videoRef.current) return;
    setCalibrationStep('capturing');

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `Detect normalized (0-100) coordinates for posture landmarks: Head, LeftShoulder, RightShoulder, SpineCenter, LeftHip, RightHip. Calculate an initial alignmentScore (0-100). Return ONLY JSON.` }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER },
                    y: { type: Type.NUMBER },
                    label: { type: Type.STRING }
                  },
                  required: ['x', 'y', 'label']
                }
              },
              alignmentScore: { type: Type.NUMBER }
            },
            required: ['landmarks', 'alignmentScore']
          }
        }
      });
      const result = JSON.parse(response.text || '{}');
      if (result.landmarks) {
        setBaselineLandmarks(result.landmarks);
        setBaselineScore(result.alignmentScore);
        setCalibrationStep('complete');
        addEvent({ 
          type: 'system', 
          label: 'Baseline Fixed', 
          score: result.alignmentScore, 
          delta: 0, 
          feedback: `Clinical baseline locked at ${result.alignmentScore}% alignment.` 
        });
        setTimeout(() => setCalibrationStep('idle'), 2000);
      }
    } catch (err) {
      setError("Calibration failed. Please try again.");
      setCalibrationStep('idle');
    }
  };

  const analyzeFrame = async () => {
    if (!isActive || !videoRef.current || isAnalyzing || calibrationStep !== 'idle') return;

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const promptText = `Analyze posture ${baselineLandmarks ? `relative to baseline: ${JSON.stringify(baselineLandmarks)}` : ''}.
           1. Detect normalized landmarks (0-100): Head, LeftShoulder, RightShoulder, SpineCenter, LeftHip, RightHip.
           2. Estimate simulated Cobb Angle (0-90°).
           3. Classify severity.
           4. alignmentScore (0-100).
           5. feedback: concise clinical tip.
           Return JSON.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: promptText }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  },
                  required: ['x', 'y', 'label']
                }
              },
              alignmentScore: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              isDeviating: { type: Type.BOOLEAN },
              estimatedCobbAngle: { type: Type.NUMBER },
              severity: { type: Type.STRING, enum: ['Normal', 'Mild', 'Moderate', 'Severe'] },
              recommendations: { type: Type.ARRAY, items: { type: Type.STRING } }
            },
            required: ['landmarks', 'alignmentScore', 'feedback', 'isDeviating', 'estimatedCobbAngle', 'severity']
          }
        }
      });

      const result = JSON.parse(response.text || '{}');

      // LOGIC: Detect significant changes
      if (sessionHistory.length > 0) {
        const lastScore = sessionHistory[sessionHistory.length - 1].score;
        const deltaPrev = result.alignmentScore - lastScore;

        // 1. Check change from PREVIOUS frame
        if (Math.abs(deltaPrev) > 10) {
          setDeltaIndicator({
            value: Math.round(Math.abs(deltaPrev)),
            type: deltaPrev > 0 ? 'plus' : 'minus'
          });
          setTriggerRipple(true);

          addEvent({
            type: deltaPrev > 0 ? 'improvement' : 'deterioration',
            label: deltaPrev > 0 ? 'Clinical Correction' : 'Postural Drift',
            score: Math.round(result.alignmentScore),
            delta: Math.round(deltaPrev),
            feedback: result.feedback
          });
        }

        // 2. Check deviation from BASELINE
        if (baselineScore !== null) {
          const deltaBase = result.alignmentScore - baselineScore;
          if (deltaBase < -15) {
             addEvent({
                type: 'deviation',
                label: 'Significant Baseline Deviation',
                score: Math.round(result.alignmentScore),
                delta: Math.round(deltaBase),
                feedback: 'Posture has regressed significantly from original baseline.'
             });
             setDeltaIndicator({ value: Math.round(Math.abs(deltaBase)), type: 'alert' });
          }
        }

        setTimeout(() => {
          setDeltaIndicator(null);
          setTriggerRipple(false);
        }, 3000);
      }

      setAnalysis(result);

      const currentTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
      const newPoint: SessionDataPoint = {
        time: currentTime,
        timestamp: Date.now(),
        score: result.alignmentScore,
        angle: result.estimatedCobbAngle || 0,
        landmarks: result.landmarks
      };
      setSessionHistory(prev => [...prev.slice(-44), newPoint]); 
    } catch (err) {
      console.error(err);
    } finally {
      setIsAnalyzing(false);
    }
  };

  useEffect(() => {
    let interval: number;
    if (isActive && calibrationStep === 'idle') {
      interval = window.setInterval(analyzeFrame, 4000); 
    }
    return () => clearInterval(interval);
  }, [isActive, isAnalyzing, calibrationStep, baselineLandmarks]);

  useEffect(() => {
    if (!canvasRef.current || (!analysis && !baselineLandmarks)) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const { width, height } = canvasRef.current;
    ctx.clearRect(0, 0, width, height);

    const drawSkeleton = (points: Landmark[], color: string, alpha: number = 1, isSolid: boolean = true, isGhost: boolean = false) => {
      const getPt = (label: string) => points.find(p => p.label.toLowerCase().includes(label.toLowerCase()));
      const head = getPt('Head');
      const ls = getPt('LeftShoulder');
      const rs = getPt('RightShoulder');
      const spine = getPt('Spine');
      const lh = getPt('LeftHip');
      const rh = getPt('RightHip');

      ctx.globalAlpha = alpha;
      ctx.lineWidth = isSolid ? 4 : 2;
      ctx.strokeStyle = color;
      ctx.setLineDash(isGhost ? [5, 5] : []);

      const drawLine = (p1?: Landmark, p2?: Landmark) => {
        if (p1 && p2) {
          ctx.beginPath();
          ctx.moveTo(p1.x * width / 100, p1.y * height / 100);
          ctx.lineTo(p2.x * width / 100, p2.y * height / 100);
          ctx.stroke();
        }
      };

      drawLine(head, spine);
      drawLine(ls, rs);
      drawLine(ls, lh);
      drawLine(rs, rh);
      drawLine(lh, rh);
      drawLine(spine, lh);
      drawLine(spine, rh);

      points.forEach(pt => {
        const x = pt.x * width / 100;
        const y = pt.y * height / 100;
        ctx.beginPath();
        ctx.arc(x, y, isSolid ? 6 : 4, 0, Math.PI * 2);
        ctx.fillStyle = color;
        ctx.fill();
      });
      ctx.globalAlpha = 1;
    };

    if (baselineLandmarks && isActive) {
      drawSkeleton(baselineLandmarks, 'rgba(99, 102, 241, 0.4)', 1, false);
    }

    if (analysis?.landmarks && isActive) {
      drawSkeleton(analysis.landmarks, analysis.isDeviating ? '#ef4444' : '#10b981', 1, true);
    }
  }, [analysis, baselineLandmarks, isActive]);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <style>{`
        @keyframes slide-up-fade {
          0% { opacity: 0; transform: translateY(0); }
          50% { opacity: 1; }
          100% { opacity: 0; transform: translateY(-40px); }
        }
        @keyframes ripple {
          0% { transform: translate(-50%, -50%) scale(0); opacity: 0.8; }
          100% { transform: translate(-50%, -50%) scale(2.5); opacity: 0; }
        }
        .animate-delta-indicator { animation: slide-up-fade 3s ease-out forwards; }
        .animate-ripple { animation: ripple 1.5s ease-out forwards; }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }
      `}</style>

      <div className="flex flex-col xl:flex-row gap-8">
        {/* VIDEO MONITORING AREA */}
        <div className="flex-1 flex flex-col gap-6">
          <div className={`bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl relative aspect-video group border-4 transition-all duration-700 ${auraStyles.border} ${auraStyles.pulse}`}>
            <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity duration-700 ${isActive ? 'opacity-100' : 'opacity-20'}`} />

            {triggerRipple && <div className="absolute top-1/2 left-1/2 w-96 h-96 rounded-full border-4 border-white/50 pointer-events-none animate-ripple" />}

            {deltaIndicator && (
               <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 pointer-events-none z-30">
                  <div className={`flex items-center gap-2 px-6 py-3 rounded-full text-2xl font-black shadow-2xl backdrop-blur-md border-2 animate-delta-indicator ${
                    deltaIndicator.type === 'plus' ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500' : 
                    deltaIndicator.type === 'minus' ? 'bg-amber-500/20 text-amber-400 border-amber-500' :
                    'bg-red-500/20 text-red-400 border-red-500'
                  }`}>
                    {deltaIndicator.type === 'plus' ? <MoveUp size={28} /> : <MoveDown size={28} />}
                    {deltaIndicator.type === 'plus' ? '+' : '-'}{deltaIndicator.value}%
                  </div>
               </div>
            )}

            <div className="absolute inset-0 aura-overlay" style={{ background: `radial-gradient(circle, transparent 40%, ${auraStyles.glow} 100%)` }} />
            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none" width={640} height={480} />

            <div className="absolute top-8 left-8 flex items-center gap-3">
              <div className={`w-3 h-3 rounded-full ${isActive ? 'bg-red-500 animate-pulse' : 'bg-slate-600'}`}></div>
              <span className="text-white text-xs font-black tracking-widest uppercase opacity-80">
                {isActive ? 'Clinical Bio-Feedback Engine' : 'System Standby'}
              </span>
            </div>

            {isActive && (
              <div className="absolute top-8 right-8 flex flex-col items-end gap-2">
                <div className="bg-black/40 backdrop-blur-md px-4 py-2 rounded-xl border border-white/10 flex items-center gap-3">
                  <Waves size={16} className="text-indigo-400" />
                  <div>
                    <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest leading-none mb-1">Session Summary</p>
                    <p className={`text-sm font-black ${sessionSummary.trend >= 0 ? 'text-emerald-400' : 'text-amber-400'}`}>
                       {sessionSummary.trend > 0 ? '+' : ''}{sessionSummary.trend}% {sessionSummary.status}
                    </p>
                  </div>
                </div>
                {baselineLandmarks && (
                   <div className="bg-indigo-600/90 px-3 py-1.5 rounded-lg text-white text-[10px] font-black uppercase tracking-widest shadow-lg flex items-center gap-2">
                      <ShieldCheck size={14} /> Clinical Baseline Locked
                   </div>
                )}
              </div>
            )}

            {calibrationStep !== 'idle' && (
              <div className="absolute inset-0 bg-indigo-900/80 backdrop-blur-md flex flex-col items-center justify-center text-white z-20 animate-in fade-in p-12 text-center">
                {calibrationStep === 'instruction' && (
                  <div className="max-w-md space-y-6">
                    <div className="w-20 h-20 bg-white/10 rounded-3xl flex items-center justify-center mx-auto border border-white/20"><ScanEye size={40} className="text-indigo-400" /></div>
                    <h2 className="text-3xl font-black">Clinical Calibration</h2>
                    <p className="text-indigo-100 font-medium">Stand centered and align your spine vertically to lock your neutral posture baseline.</p>
                    <div className="flex gap-3">
                      <button onClick={() => setCalibrationStep('idle')} className="flex-1 py-4 bg-white/10 rounded-2xl font-bold">Cancel</button>
                      <button onClick={() => { setCalibrationStep('preparing'); setCountdown(5); }} className="flex-1 py-4 bg-indigo-500 rounded-2xl font-bold">Start Capture</button>
                    </div>
                  </div>
                )}
                {calibrationStep === 'preparing' && (
                   <><div className="w-32 h-32 rounded-full border-8 border-white/10 flex items-center justify-center mb-8"><span className="text-6xl font-black">{countdown}</span></div><h2 className="text-3xl font-black mb-2">Analyzing Vector Base...</h2></>
                )}
                {calibrationStep === 'complete' && (
                  <div className="flex flex-col items-center gap-4"><div className="w-24 h-24 bg-emerald-500 rounded-full flex items-center justify-center"><CheckCircle2 size={48} /></div><p className="font-black text-3xl">Normalization Applied</p></div>
                )}
              </div>
            )}

            {!isActive && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-white space-y-4">
                <div className="w-20 h-20 bg-white/10 backdrop-blur-md rounded-3xl flex items-center justify-center text-slate-400"><CameraOff size={40} /></div>
                <div className="text-center px-8">
                  <p className="font-black text-xl mb-1">Optical Standby</p>
                  <p className="text-slate-400 text-sm font-medium">Initialize feed for real-time skeletal mapping.</p>
                </div>
              </div>
            )}

            <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-4 group-hover:scale-105 transition-transform z-10">
              <button onClick={toggleCamera} className={`flex items-center gap-3 px-8 py-4 rounded-2xl font-black text-sm uppercase tracking-widest transition-all ${isActive ? 'bg-white/10 backdrop-blur-md text-white border border-white/20 hover:bg-white/20' : 'bg-indigo-600 text-white shadow-xl shadow-indigo-500/20'}`}>
                {isActive ? <><Square size={18} /> Stop Feed</> : <><Play size={18} /> Start Feed</>}
              </button>
              {isActive && (
                <button onClick={() => setCalibrationStep('instruction')} disabled={calibrationStep !== 'idle'} className="flex items-center gap-3 px-8 py-4 bg-indigo-600 text-white rounded-2xl font-black text-sm uppercase tracking-widest shadow-lg shadow-indigo-500/30 disabled:opacity-50">
                   <Target size={18} /> {baselineLandmarks ? 'Reset Base' : 'Set Baseline'}
                </button>
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Cobb Angle (Live)</p>
              <p className="text-4xl font-black text-slate-800">{analysis?.estimatedCobbAngle ? `${analysis.estimatedCobbAngle.toFixed(1)}°` : '--°'}</p>
            </div>
            <div className={`p-6 rounded-3xl border shadow-sm ${getSeverityStyles(analysis?.severity as ScoliosisSeverity)}`}>
              <p className="text-[10px] font-black uppercase tracking-widest mb-1 opacity-70">Curvature Risk</p>
              <p className="text-3xl font-black">{analysis?.severity || '--'}</p>
            </div>
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Alignment Score</p>
              <p className="text-4xl font-black text-indigo-600">{analysis ? `${Math.round(analysis.alignmentScore)}%` : '--%'}</p>
            </div>
          </div>
        </div>

        {/* SIDEBAR LOGGING AREA */}
        <div className="w-full xl:w-96 space-y-6 flex flex-col max-h-[calc(100vh-200px)]">
          <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-lg flex flex-col flex-1 overflow-hidden">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><History size={24} className="text-indigo-600" /> Monitoring Log</h3>
              <button 
                onClick={() => setSessionEvents([])} 
                className="p-2 hover:bg-slate-100 text-slate-400 hover:text-red-500 rounded-lg transition-colors"
                title="Clear Session History"
              >
                <Trash2 size={16} />
              </button>
            </div>

            <div className="space-y-4 overflow-y-auto flex-1 pr-2 custom-scrollbar">
              {sessionEvents.length > 0 ? (
                sessionEvents.map((event) => (
                  <div key={event.id} className={`flex gap-4 p-4 rounded-2xl border animate-in slide-in-from-left-2 ${
                    event.type === 'improvement' ? 'bg-emerald-50 border-emerald-100' :
                    event.type === 'deterioration' ? 'bg-amber-50 border-amber-100' :
                    event.type === 'deviation' ? 'bg-red-50 border-red-100' :
                    'bg-slate-50 border-slate-100'
                  }`}>
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${
                      event.type === 'improvement' ? 'bg-emerald-100 text-emerald-600' : 
                      event.type === 'deterioration' ? 'bg-amber-100 text-amber-600' :
                      event.type === 'deviation' ? 'bg-red-100 text-red-600' :
                      'bg-indigo-100 text-indigo-600'
                    }`}>
                      {event.type === 'improvement' ? <ArrowUpRight size={20} /> : 
                       event.type === 'deterioration' ? <ArrowDownRight size={20} /> :
                       event.type === 'deviation' ? <AlertTriangle size={20} /> :
                       <ActivityIcon size={20} />}
                    </div>
                    <div className="flex-1">
                      <div className="flex justify-between items-start mb-1">
                        <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">{event.time}</p>
                        <span className={`text-[10px] font-black px-1.5 py-0.5 rounded shadow-sm ${
                           event.type === 'improvement' ? 'bg-emerald-600 text-white' : 
                           event.type === 'deterioration' ? 'bg-amber-600 text-white' : 
                           'bg-red-600 text-white'
                        }`}>
                           {event.delta > 0 ? '+' : ''}{event.delta}%
                        </span>
                      </div>
                      <p className="text-sm font-bold text-slate-800 leading-tight">{event.label}</p>
                      <p className="text-[11px] font-medium text-slate-500 mt-1 leading-relaxed italic">"{event.feedback}"</p>
                    </div>
                  </div>
                ))
              ) : (
                <div className="flex flex-col items-center justify-center py-20 text-slate-300 opacity-60">
                  <Clock size={32} className="mb-2" />
                  <p className="text-xs font-bold uppercase tracking-widest">Awaiting Events</p>
                </div>
              )}
              <div ref={logEndRef} />
            </div>
          </div>

          <div className="bg-indigo-50 p-6 rounded-[2rem] border border-indigo-100">
             <div className="flex items-center gap-3 mb-4">
                <Lightbulb size={20} className="text-indigo-600" />
                <h4 className="font-black text-xs uppercase tracking-widest text-indigo-800">Dynamic Guidance</h4>
             </div>
             <p className="text-sm text-indigo-700 leading-relaxed italic">
                {analysis?.feedback || "System standing by. Please align with camera for baseline vector mapping."}
             </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PostureLiveView;

import React, { useEffect, useRef, useState, useMemo } from 'react';
import { 
  Camera, 
  CameraOff, 
  Play, 
  Square, 
  RefreshCw, 
  Zap, 
  AlertCircle, 
  Activity,
  CheckCircle2,
  ScanEye,
  Target,
  ChevronRight,
  ShieldCheck,
  Dumbbell,
  Stethoscope,
  TrendingUp,
  AlertTriangle,
  ArrowUpRight,
  ArrowDownRight,
  Info,
  UserCheck,
  Undo2,
  Clock,
  History,
  Timer,
  Waves,
  Lightbulb,
  ArrowRight,
  MoveUp,
  MoveDown,
  Trash2,
  Settings,
  Activity as ActivityIcon,
  XCircle,
  Dna
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";
import { PostureAnalysis, Landmark, ScoliosisSeverity } from '../types';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceLine } from 'recharts';

type CalibrationStep = 'idle' | 'instruction' | 'preparing' | 'capturing' | 'complete';

interface Exercise {
  name: string;
  focus: string;
  reps: string;
  description: string;
}

interface SessionEvent {
  id: string;
  time: string;
  type: 'improvement' | 'deterioration' | 'deviation' | 'system';
  score: number;
  delta: number;
  label: string;
  feedback: string;
}

interface SessionDataPoint {
  time: string;
  timestamp: number;
  score: number;
  angle: number;
  landmarks?: Landmark[];
  isEvent?: boolean;
}

const PostureLiveView: React.FC = () => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const logEndRef = useRef<HTMLDivElement>(null);

  const [isActive, setIsActive] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<PostureAnalysis & { exercises?: Exercise[] } | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [sessionHistory, setSessionHistory] = useState<SessionDataPoint[]>([]);
  const [sessionEvents, setSessionEvents] = useState<SessionEvent[]>([]);
  const [startTime, setStartTime] = useState<number | null>(null);

  // Real-time Visual indicators
  const [lastGhostLandmarks, setLastGhostLandmarks] = useState<Landmark[] | null>(null);
  const [deltaIndicator, setDeltaIndicator] = useState<{ value: number, type: 'plus' | 'minus' | 'alert' } | null>(null);
  const [triggerRipple, setTriggerRipple] = useState(false);

  // Calibration State
  const [calibrationStep, setCalibrationStep] = useState<CalibrationStep>('idle');
  const [baselineLandmarks, setBaselineLandmarks] = useState<Landmark[] | null>(null);
  const [baselineScore, setBaselineScore] = useState<number | null>(null);
  const [countdown, setCountdown] = useState(0);

  // Auto-scroll log to bottom
  useEffect(() => {
    if (logEndRef.current) {
      logEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [sessionEvents]);

  const getSeverityStyles = (severity?: ScoliosisSeverity) => {
    switch (severity) {
      case ScoliosisSeverity.NORMAL: return 'bg-emerald-50 text-emerald-700 border-emerald-200';
      case ScoliosisSeverity.MILD: return 'bg-blue-50 text-blue-700 border-blue-200';
      case ScoliosisSeverity.MODERATE: return 'bg-amber-50 text-amber-700 border-amber-200';
      case ScoliosisSeverity.SEVERE: return 'bg-red-50 text-red-700 border-red-200';
      default: return 'bg-slate-50 text-slate-700 border-slate-200';
    }
  };

  const addEvent = (event: Omit<SessionEvent, 'id' | 'time'>) => {
    const newEvent: SessionEvent = {
      ...event,
      id: Math.random().toString(36).substr(2, 9),
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })
    };
    setSessionEvents(prev => [...prev.slice(-49), newEvent]);
  };

  const toggleCamera = async () => {
    if (isActive) {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
      setIsActive(false);
      setAnalysis(null);
      setCalibrationStep('idle');
      setLastGhostLandmarks(null);
      addEvent({ type: 'system', label: 'Monitoring Stopped', score: 0, delta: 0, feedback: 'User ended monitoring session.' });
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsActive(true);
          setStartTime(Date.now());
          setSessionHistory([]);
          setSessionEvents([]);
          setError(null);
          addEvent({ type: 'system', label: 'Monitoring Started', score: 0, delta: 0, feedback: 'Computer vision engine ready.' });
        }
      } catch (err) {
        setError("Camera access required for live monitoring.");
      }
    }
  };

  const captureCalibration = async () => {
    if (!videoRef.current) return;
    setCalibrationStep('capturing');

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `Locate skeletal landmarks: Head, shoulders, spine, hips. Calculate initial alignment score. Return JSON.` }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  },
                  required: ['x', 'y', 'label']
                }
              },
              alignmentScore: { type: Type.NUMBER }
            },
            required: ['landmarks', 'alignmentScore']
          }
        }
      });
      const result = JSON.parse(response.text || '{}');
      if (result.landmarks) {
        setBaselineLandmarks(result.landmarks);
        setBaselineScore(result.alignmentScore);
        setCalibrationStep('complete');
        addEvent({ type: 'system', label: 'Baseline Established', score: result.alignmentScore, delta: 0, feedback: 'Fixed clinical baseline locked.' });
        setTimeout(() => setCalibrationStep('idle'), 2000);
      }
    } catch (err) {
      setCalibrationStep('idle');
      setError("Calibration failed. Please try again.");
    }
  };

  const analyzeFrame = async () => {
    if (!isActive || !videoRef.current || isAnalyzing || calibrationStep !== 'idle') return;

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `Analyze posture skeletal landmarks. 
              1. Detect normalized landmarks.
              2. alignmentScore (0-100).
              3. estimatedCobbAngle.
              4. severity classification.
              5. feedback: one sentence clinical advice.
              6. exercises: 3 tailored exercises with focus area and description.
              Return JSON.` 
            }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  }
                }
              },
              alignmentScore: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              isDeviating: { type: Type.BOOLEAN },
              estimatedCobbAngle: { type: Type.NUMBER },
              severity: { type: Type.STRING },
              exercises: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    name: { type: Type.STRING },
                    focus: { type: Type.STRING },
                    reps: { type: Type.STRING },
                    description: { type: Type.STRING }
                  }
                }
              }
            },
            required: ['landmarks', 'alignmentScore', 'feedback', 'isDeviating', 'estimatedCobbAngle', 'severity', 'exercises']
          }
        }
      });

      const result = JSON.parse(response.text || '{}');

      // Handle Logging and UI Updates
      if (sessionHistory.length > 0) {
        const lastScore = sessionHistory[sessionHistory.length - 1].score;
        const delta = result.alignmentScore - lastScore;

        if (Math.abs(delta) > 10) {
          setDeltaIndicator({ value: Math.round(Math.abs(delta)), type: delta > 0 ? 'plus' : 'minus' });
          setTriggerRipple(true);
          addEvent({
            type: delta > 0 ? 'improvement' : 'deterioration',
            label: delta > 0 ? 'Posture Improvement' : 'Postural Regression',
            score: Math.round(result.alignmentScore),
            delta: Math.round(delta),
            feedback: result.feedback
          });
        }
        setTimeout(() => { setDeltaIndicator(null); setTriggerRipple(false); }, 3000);
      }

      setAnalysis(result);

      const currentTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
      setSessionHistory(prev => [...prev.slice(-44), {
        time: currentTime,
        timestamp: Date.now(),
        score: result.alignmentScore,
        angle: result.estimatedCobbAngle,
        landmarks: result.landmarks
      }]); 
    } catch (err) {
      console.error(err);
    } finally {
      setIsAnalyzing(false);
    }
  };

  useEffect(() => {
    let interval: number;
    if (isActive && calibrationStep === 'idle') {
      interval = window.setInterval(analyzeFrame, 4000); 
    }
    return () => clearInterval(interval);
  }, [isActive, isAnalyzing, calibrationStep, baselineLandmarks]);

  useEffect(() => {
    if (!canvasRef.current || (!analysis && !baselineLandmarks)) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const { width, height } = canvasRef.current;
    ctx.clearRect(0, 0, width, height);

    const drawSkeleton = (points: Landmark[], color: string, alpha: number = 1, isSolid: boolean = true) => {
      const getPt = (label: string) => points.find(p => p.label.toLowerCase().includes(label.toLowerCase()));
      const head = getPt('Head');
      const ls = getPt('LeftShoulder');
      const rs = getPt('RightShoulder');
      const spine = getPt('Spine');
      const lh = getPt('LeftHip');
      const rh = getPt('RightHip');

      ctx.globalAlpha = alpha;
      ctx.lineWidth = isSolid ? 4 : 2;
      ctx.strokeStyle = color;

      const drawLine = (p1?: Landmark, p2?: Landmark) => {
        if (p1 && p2) {
          ctx.beginPath();
          ctx.moveTo(p1.x * width / 100, p1.y * height / 100);
          ctx.lineTo(p2.x * width / 100, p2.y * height / 100);
          ctx.stroke();
        }
      };

      drawLine(head, spine);
      drawLine(ls, rs);
      drawLine(ls, lh);
      drawLine(rs, rh);
      drawLine(lh, rh);
      drawLine(spine, lh);
      drawLine(spine, rh);

      points.forEach(pt => {
        ctx.beginPath();
        ctx.arc(pt.x * width / 100, pt.y * height / 100, isSolid ? 6 : 4, 0, Math.PI * 2);
        ctx.fillStyle = color;
        ctx.fill();
      });
      ctx.globalAlpha = 1;
    };

    if (baselineLandmarks && isActive) {
      drawSkeleton(baselineLandmarks, 'rgba(99, 102, 241, 0.3)', 1, false);
    }
    if (analysis?.landmarks && isActive) {
      drawSkeleton(analysis.landmarks, analysis.isDeviating ? '#ef4444' : '#10b981', 1, true);
    }
  }, [analysis, baselineLandmarks, isActive]);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <style>{`
        @keyframes ripple {
          0% { transform: translate(-50%, -50%) scale(0); opacity: 0.8; }
          100% { transform: translate(-50%, -50%) scale(2.5); opacity: 0; }
        }
        @keyframes slide-up {
          0% { transform: translateY(0); opacity: 0; }
          20% { opacity: 1; }
          80% { opacity: 1; }
          100% { transform: translateY(-30px); opacity: 0; }
        }
        .animate-ripple { animation: ripple 1.5s ease-out forwards; }
        .animate-delta { animation: slide-up 3s ease-out forwards; }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }
      `}</style>

      <div className="flex flex-col xl:flex-row gap-8">
        {/* VIDEO MONITORING FEED */}
        <div className="flex-1 flex flex-col gap-6">
          <div className={`bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl relative aspect-video border-4 transition-all duration-700 ${analysis?.alignmentScore && analysis.alignmentScore > 80 ? 'border-emerald-500/40 shadow-emerald-500/10' : 'border-slate-800'}`}>
            <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity duration-700 ${isActive ? 'opacity-100' : 'opacity-20'}`} />

            {triggerRipple && <div className="absolute top-1/2 left-1/2 w-96 h-96 rounded-full border-4 border-white/50 pointer-events-none animate-ripple" />}

            {deltaIndicator && (
               <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 pointer-events-none z-30">
                  <div className={`flex items-center gap-2 px-6 py-3 rounded-full text-2xl font-black shadow-2xl backdrop-blur-md border-2 animate-delta ${
                    deltaIndicator.type === 'plus' ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500' : 'bg-red-500/20 text-red-400 border-red-500'
                  }`}>
                    {deltaIndicator.type === 'plus' ? <MoveUp size={28} /> : <MoveDown size={28} />}
                    {deltaIndicator.type === 'plus' ? '+' : '-'}{deltaIndicator.value}%
                  </div>
               </div>
            )}

            {isActive && (
              <div className="absolute right-6 top-1/2 -translate-y-1/2 w-2 h-48 bg-white/10 rounded-full border border-white/10 p-0.5">
                <div 
                  className="w-full rounded-full transition-all duration-1000 bg-gradient-to-t from-red-500 via-amber-400 to-emerald-500" 
                  style={{ height: `${analysis?.alignmentScore || 0}%`, marginTop: `${100 - (analysis?.alignmentScore || 0)}%` }}
                />
              </div>
            )}

            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none" width={640} height={480} />

            <div className="absolute top-8 left-8 flex items-center gap-3">
              <div className={`w-3 h-3 rounded-full ${isActive ? 'bg-red-500 animate-pulse' : 'bg-slate-600'}`}></div>
              <span className="text-white text-xs font-black tracking-widest uppercase opacity-80">
                {isActive ? 'Live Pathological Mapping' : 'Engine Standby'}
              </span>
            </div>

            {isActive && (
              <div className="absolute top-8 right-12 flex flex-col items-end gap-2">
                <div className="bg-black/40 backdrop-blur-md px-4 py-2 rounded-xl border border-white/10 flex items-center gap-3">
                  <Waves size={16} className="text-indigo-400" />
                  <p className="text-sm font-black text-white">{Math.round(analysis?.alignmentScore || 0)}% Match</p>
                </div>
                {baselineLandmarks && (
                   <div className="bg-indigo-600/90 px-3 py-1.5 rounded-lg text-white text-[10px] font-black uppercase tracking-widest shadow-lg flex items-center gap-2">
                      <ShieldCheck size={14} /> Baseline Active
                   </div>
                )}
              </div>
            )}

            {calibrationStep !== 'idle' && (
              <div className="absolute inset-0 bg-indigo-900/80 backdrop-blur-md flex flex-col items-center justify-center text-white z-20 animate-in fade-in p-12 text-center">
                {calibrationStep === 'instruction' && (
                  <div className="max-w-md space-y-6">
                    <div className="w-20 h-20 bg-white/10 rounded-3xl flex items-center justify-center mx-auto border border-white/20"><ScanEye size={40} className="text-indigo-400" /></div>
                    <h2 className="text-3xl font-black">Clinical Calibration</h2>
                    <p className="text-indigo-100 font-medium">Align your spine with the screen center to establish your neutral physiological baseline.</p>
                    <div className="flex gap-3">
                      <button onClick={() => setCalibrationStep('idle')} className="flex-1 py-4 bg-white/10 rounded-2xl font-bold">Cancel</button>
                      <button onClick={() => { setCalibrationStep('preparing'); setCountdown(5); }} className="flex-1 py-4 bg-indigo-500 rounded-2xl font-bold">Initiate Scan</button>
                    </div>
                  </div>
                )}
                {calibrationStep === 'preparing' && (
                   <><div className="w-32 h-32 rounded-full border-8 border-white/10 flex items-center justify-center mb-8"><span className="text-6xl font-black">{countdown}</span></div><h2 className="text-3xl font-black mb-2">Capturing Vector Base...</h2></>
                )}
                {calibrationStep === 'complete' && (
                  <div className="flex flex-col items-center gap-4"><div className="w-24 h-24 bg-emerald-500 rounded-full flex items-center justify-center"><CheckCircle2 size={48} /></div><p className="font-black text-3xl">Normalization Applied</p></div>
                )}
              </div>
            )}

            {!isActive && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-white space-y-4">
                <div className="w-20 h-20 bg-white/10 backdrop-blur-md rounded-3xl flex items-center justify-center text-slate-400"><CameraOff size={40} /></div>
                <div className="text-center px-8">
                  <p className="font-black text-xl mb-1">Standby Mode</p>
                  <p className="text-slate-400 text-sm font-medium">Start the camera for real-time skeletal analysis.</p>
                </div>
              </div>
            )}

            <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-4 group-hover:scale-105 transition-transform z-10">
              <button onClick={toggleCamera} className={`flex items-center gap-3 px-8 py-4 rounded-2xl font-black text-sm uppercase tracking-widest transition-all ${isActive ? 'bg-white/10 backdrop-blur-md text-white border border-white/20 hover:bg-white/20' : 'bg-indigo-600 text-white shadow-xl shadow-indigo-500/20'}`}>
                {isActive ? <><Square size={18} /> Exit</> : <><Play size={18} /> Start Monitoring</>}
              </button>
              {isActive && (
                <div className="flex gap-2">
                  <button onClick={() => setCalibrationStep('instruction')} disabled={calibrationStep !== 'idle'} className="flex items-center gap-3 px-8 py-4 bg-indigo-600 text-white rounded-2xl font-black text-sm uppercase tracking-widest shadow-lg shadow-indigo-500/30">
                    <Target size={18} /> {baselineLandmarks ? 'Adjust Base' : 'Set Baseline'}
                  </button>
                  {baselineLandmarks && (
                    <button onClick={() => setBaselineLandmarks(null)} className="p-4 bg-red-500/20 text-red-400 border border-red-500/20 rounded-2xl hover:bg-red-500 hover:text-white transition-all">
                      <XCircle size={20} />
                    </button>
                  )}
                </div>
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Cobb Angle</p>
              <p className="text-4xl font-black text-slate-800">{analysis?.estimatedCobbAngle ? `${analysis.estimatedCobbAngle.toFixed(1)}°` : '--°'}</p>
            </div>
            <div className={`p-6 rounded-3xl border shadow-sm ${getSeverityStyles(analysis?.severity as ScoliosisSeverity)}`}>
              <p className="text-[10px] font-black uppercase tracking-widest mb-1 opacity-70">Curvature Risk</p>
              <p className="text-3xl font-black">{analysis?.severity || '--'}</p>
            </div>
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Alignment Score</p>
              <p className="text-4xl font-black text-indigo-600">{analysis ? `${Math.round(analysis.alignmentScore)}%` : '--%'}</p>
            </div>
          </div>
        </div>

        {/* THERAPEUTIC RECOMMENDATIONS & HISTORY */}
        <div className="w-full xl:w-96 space-y-6 flex flex-col">
          <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-lg flex flex-col h-[500px]">
             <div className="flex items-center justify-between mb-6">
                <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><Dumbbell size={24} className="text-indigo-600" /> Exercise Plan</h3>
                {isAnalyzing && <RefreshCw size={16} className="text-indigo-400 animate-spin" />}
             </div>

             <div className="space-y-4 overflow-y-auto flex-1 pr-2 custom-scrollbar">
                {analysis?.exercises ? analysis.exercises.map((ex, i) => (
                  <div key={i} className="bg-slate-50 border border-slate-100 rounded-2xl p-4 group hover:border-indigo-200 transition-all animate-in slide-in-from-right-4">
                    <div className="flex items-start justify-between mb-2">
                       <h4 className="font-bold text-slate-800 text-sm leading-tight group-hover:text-indigo-600 transition-colors">{ex.name}</h4>
                       <span className="text-[10px] font-black uppercase tracking-widest bg-white border border-slate-200 px-2 py-0.5 rounded-lg text-slate-500 whitespace-nowrap">{ex.reps}</span>
                    </div>
                    <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest mb-2 flex items-center gap-1">
                       <Dna size={12} /> {ex.focus}
                    </p>
                    <p className="text-xs text-slate-500 leading-relaxed font-medium">
                       {ex.description}
                    </p>
                  </div>
                )) : (
                  <div className="flex flex-col items-center justify-center py-20 text-slate-300 opacity-60 text-center">
                    <ActivityIcon size={32} className="mb-2" />
                    <p className="text-xs font-black uppercase tracking-widest">Awaiting Pose Detection</p>
                    <p className="text-[10px] mt-1 font-medium italic">Personalized correctives generate live</p>
                  </div>
                )}
             </div>
          </div>

          <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-lg flex-1 min-h-[300px] flex flex-col overflow-hidden">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><History size={24} className="text-indigo-600" /> Monitoring Log</h3>
              <button onClick={() => setSessionEvents([])} className="p-2 hover:bg-slate-100 text-slate-400 rounded-lg transition-colors"><Trash2 size={16} /></button>
            </div>

            <div className="space-y-4 overflow-y-auto flex-1 pr-2 custom-scrollbar">
              {sessionEvents.length > 0 ? sessionEvents.map((event) => (
                  <div key={event.id} className={`flex gap-4 p-4 rounded-2xl border animate-in slide-in-from-left-2 ${
                    event.type === 'improvement' ? 'bg-emerald-50 border-emerald-100' :
                    event.type === 'deterioration' ? 'bg-amber-50 border-amber-100' :
                    'bg-slate-50 border-slate-100'
                  }`}>
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${
                      event.type === 'improvement' ? 'bg-emerald-100 text-emerald-600' : 'bg-indigo-100 text-indigo-600'
                    }`}>
                      {event.type === 'improvement' ? <ArrowUpRight size={20} /> : <ActivityIcon size={20} />}
                    </div>
                    <div className="flex-1">
                      <div className="flex justify-between items-start mb-1">
                        <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">{event.time}</p>
                        <span className={`text-[10px] font-black px-1.5 py-0.5 rounded shadow-sm ${event.delta > 0 ? 'bg-emerald-600 text-white' : 'bg-slate-200 text-slate-600'}`}>{event.delta}%</span>
                      </div>
                      <p className="text-sm font-bold text-slate-800 leading-tight">{event.label}</p>
                      <p className="text-[11px] font-medium text-slate-500 mt-1 leading-relaxed italic">"{event.feedback}"</p>
                    </div>
                  </div>
              )) : (
                <div className="flex flex-col items-center justify-center py-10 text-slate-300 opacity-60">
                  <Clock size={32} className="mb-2" />
                  <p className="text-xs font-bold uppercase tracking-widest">No Events Logged</p>
                </div>
              )}
              <div ref={logEndRef} />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PostureLiveView;

import React, { useEffect, useRef, useState, useMemo } from 'react';
import { 
  Camera, 
  CameraOff, 
  Play, 
  Square, 
  RefreshCw, 
  Zap, 
  AlertCircle, 
  Activity,
  CheckCircle2,
  ScanEye,
  Target,
  ChevronRight,
  ShieldCheck,
  Dumbbell,
  Stethoscope,
  TrendingUp,
  AlertTriangle,
  ArrowUpRight,
  ArrowDownRight,
  Info,
  UserCheck,
  Undo2,
  Clock,
  History,
  Timer,
  Waves,
  Lightbulb,
  ArrowRight,
  MoveUp,
  MoveDown,
  Trash2,
  Settings,
  Activity as ActivityIcon,
  XCircle,
  Dna
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";
import { PostureAnalysis, Landmark, ScoliosisSeverity } from '../types';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceLine } from 'recharts';

type CalibrationStep = 'idle' | 'instruction' | 'preparing' | 'capturing' | 'complete';

interface Exercise {
  name: string;
  focus: string;
  reps: string;
  description: string;
}

interface SessionEvent {
  id: string;
  time: string;
  type: 'improvement' | 'deterioration' | 'deviation' | 'system';
  score: number;
  delta: number;
  label: string;
  feedback: string;
}

interface SessionDataPoint {
  time: string;
  timestamp: number;
  score: number;
  angle: number;
  landmarks?: Landmark[];
  isEvent?: boolean;
}

const PostureLiveView: React.FC = () => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const logEndRef = useRef<HTMLDivElement>(null);

  const [isActive, setIsActive] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<PostureAnalysis & { exercises?: Exercise[] } | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [sessionHistory, setSessionHistory] = useState<SessionDataPoint[]>([]);
  const [sessionEvents, setSessionEvents] = useState<SessionEvent[]>([]);
  const [startTime, setStartTime] = useState<number | null>(null);

  // Real-time Visual indicators
  const [lastGhostLandmarks, setLastGhostLandmarks] = useState<Landmark[] | null>(null);
  const [deltaIndicator, setDeltaIndicator] = useState<{ value: number, type: 'plus' | 'minus' | 'alert' } | null>(null);
  const [triggerRipple, setTriggerRipple] = useState(false);

  // Calibration State
  const [calibrationStep, setCalibrationStep] = useState<CalibrationStep>('idle');
  const [baselineLandmarks, setBaselineLandmarks] = useState<Landmark[] | null>(null);
  const [baselineScore, setBaselineScore] = useState<number | null>(null);
  const [countdown, setCountdown] = useState(0);

  // Auto-scroll log to bottom
  useEffect(() => {
    if (logEndRef.current) {
      logEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [sessionEvents]);

  const getSeverityStyles = (severity?: ScoliosisSeverity) => {
    switch (severity) {
      case ScoliosisSeverity.NORMAL: return 'bg-emerald-50 text-emerald-700 border-emerald-200';
      case ScoliosisSeverity.MILD: return 'bg-blue-50 text-blue-700 border-blue-200';
      case ScoliosisSeverity.MODERATE: return 'bg-amber-50 text-amber-700 border-amber-200';
      case ScoliosisSeverity.SEVERE: return 'bg-red-50 text-red-700 border-red-200';
      default: return 'bg-slate-50 text-slate-700 border-slate-200';
    }
  };

  const addEvent = (event: Omit<SessionEvent, 'id' | 'time'>) => {
    const newEvent: SessionEvent = {
      ...event,
      id: Math.random().toString(36).substr(2, 9),
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })
    };
    setSessionEvents(prev => [...prev.slice(-49), newEvent]);
  };

  const toggleCamera = async () => {
    if (isActive) {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
      setIsActive(false);
      setAnalysis(null);
      setCalibrationStep('idle');
      setLastGhostLandmarks(null);
      addEvent({ type: 'system', label: 'Monitoring Stopped', score: 0, delta: 0, feedback: 'User ended monitoring session.' });
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsActive(true);
          setStartTime(Date.now());
          setSessionHistory([]);
          setSessionEvents([]);
          setError(null);
          addEvent({ type: 'system', label: 'Monitoring Started', score: 0, delta: 0, feedback: 'Computer vision engine ready.' });
        }
      } catch (err) {
        setError("Camera access required for live monitoring.");
      }
    }
  };

  const captureCalibration = async () => {
    if (!videoRef.current) return;
    setCalibrationStep('capturing');

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `Locate skeletal landmarks: Head, shoulders, spine, hips. Calculate initial alignment score. Return JSON.` }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  },
                  required: ['x', 'y', 'label']
                }
              },
              alignmentScore: { type: Type.NUMBER }
            },
            required: ['landmarks', 'alignmentScore']
          }
        }
      });
      const result = JSON.parse(response.text || '{}');
      if (result.landmarks) {
        setBaselineLandmarks(result.landmarks);
        setBaselineScore(result.alignmentScore);
        setCalibrationStep('complete');
        addEvent({ type: 'system', label: 'Baseline Established', score: result.alignmentScore, delta: 0, feedback: 'Fixed clinical baseline locked.' });
        setTimeout(() => setCalibrationStep('idle'), 2000);
      }
    } catch (err) {
      setCalibrationStep('idle');
      setError("Calibration failed. Please try again.");
    }
  };

  const analyzeFrame = async () => {
    if (!isActive || !videoRef.current || isAnalyzing || calibrationStep !== 'idle') return;

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `Analyze posture skeletal landmarks. 
              1. Detect normalized landmarks.
              2. alignmentScore (0-100).
              3. estimatedCobbAngle.
              4. severity classification.
              5. feedback: one sentence clinical advice.
              6. exercises: 3 tailored exercises with focus area and description.
              Return JSON.` 
            }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  }
                }
              },
              alignmentScore: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              isDeviating: { type: Type.BOOLEAN },
              estimatedCobbAngle: { type: Type.NUMBER },
              severity: { type: Type.STRING },
              exercises: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    name: { type: Type.STRING },
                    focus: { type: Type.STRING },
                    reps: { type: Type.STRING },
                    description: { type: Type.STRING }
                  }
                }
              }
            },
            required: ['landmarks', 'alignmentScore', 'feedback', 'isDeviating', 'estimatedCobbAngle', 'severity', 'exercises']
          }
        }
      });

      const result = JSON.parse(response.text || '{}');

      // Handle Logging and UI Updates
      if (sessionHistory.length > 0) {
        const lastScore = sessionHistory[sessionHistory.length - 1].score;
        const delta = result.alignmentScore - lastScore;

        if (Math.abs(delta) > 10) {
          setDeltaIndicator({ value: Math.round(Math.abs(delta)), type: delta > 0 ? 'plus' : 'minus' });
          setTriggerRipple(true);
          addEvent({
            type: delta > 0 ? 'improvement' : 'deterioration',
            label: delta > 0 ? 'Posture Improvement' : 'Postural Regression',
            score: Math.round(result.alignmentScore),
            delta: Math.round(delta),
            feedback: result.feedback
          });
        }
        setTimeout(() => { setDeltaIndicator(null); setTriggerRipple(false); }, 3000);
      }

      setAnalysis(result);

      const currentTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
      setSessionHistory(prev => [...prev.slice(-44), {
        time: currentTime,
        timestamp: Date.now(),
        score: result.alignmentScore,
        angle: result.estimatedCobbAngle,
        landmarks: result.landmarks
      }]); 
    } catch (err) {
      console.error(err);
    } finally {
      setIsAnalyzing(false);
    }
  };

  useEffect(() => {
    let interval: number;
    if (isActive && calibrationStep === 'idle') {
      interval = window.setInterval(analyzeFrame, 4000); 
    }
    return () => clearInterval(interval);
  }, [isActive, isAnalyzing, calibrationStep, baselineLandmarks]);

  useEffect(() => {
    if (!canvasRef.current || (!analysis && !baselineLandmarks)) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const { width, height } = canvasRef.current;
    ctx.clearRect(0, 0, width, height);

    const drawSkeleton = (points: Landmark[], color: string, alpha: number = 1, isSolid: boolean = true) => {
      const getPt = (label: string) => points.find(p => p.label.toLowerCase().includes(label.toLowerCase()));
      const head = getPt('Head');
      const ls = getPt('LeftShoulder');
      const rs = getPt('RightShoulder');
      const spine = getPt('Spine');
      const lh = getPt('LeftHip');
      const rh = getPt('RightHip');

      ctx.globalAlpha = alpha;
      ctx.lineWidth = isSolid ? 4 : 2;
      ctx.strokeStyle = color;

      const drawLine = (p1?: Landmark, p2?: Landmark) => {
        if (p1 && p2) {
          ctx.beginPath();
          ctx.moveTo(p1.x * width / 100, p1.y * height / 100);
          ctx.lineTo(p2.x * width / 100, p2.y * height / 100);
          ctx.stroke();
        }
      };

      drawLine(head, spine);
      drawLine(ls, rs);
      drawLine(ls, lh);
      drawLine(rs, rh);
      drawLine(lh, rh);
      drawLine(spine, lh);
      drawLine(spine, rh);

      points.forEach(pt => {
        ctx.beginPath();
        ctx.arc(pt.x * width / 100, pt.y * height / 100, isSolid ? 6 : 4, 0, Math.PI * 2);
        ctx.fillStyle = color;
        ctx.fill();
      });
      ctx.globalAlpha = 1;
    };

    if (baselineLandmarks && isActive) {
      drawSkeleton(baselineLandmarks, 'rgba(99, 102, 241, 0.3)', 1, false);
    }
    if (analysis?.landmarks && isActive) {
      drawSkeleton(analysis.landmarks, analysis.isDeviating ? '#ef4444' : '#10b981', 1, true);
    }
  }, [analysis, baselineLandmarks, isActive]);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <style>{`
        @keyframes ripple {
          0% { transform: translate(-50%, -50%) scale(0); opacity: 0.8; }
          100% { transform: translate(-50%, -50%) scale(2.5); opacity: 0; }
        }
        @keyframes slide-up {
          0% { transform: translateY(0); opacity: 0; }
          20% { opacity: 1; }
          80% { opacity: 1; }
          100% { transform: translateY(-30px); opacity: 0; }
        }
        .animate-ripple { animation: ripple 1.5s ease-out forwards; }
        .animate-delta { animation: slide-up 3s ease-out forwards; }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }
      `}</style>

      <div className="flex flex-col xl:flex-row gap-8">
        {/* VIDEO MONITORING FEED */}
        <div className="flex-1 flex flex-col gap-6">
          <div className={`bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl relative aspect-video border-4 transition-all duration-700 ${analysis?.alignmentScore && analysis.alignmentScore > 80 ? 'border-emerald-500/40 shadow-emerald-500/10' : 'border-slate-800'}`}>
            <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity duration-700 ${isActive ? 'opacity-100' : 'opacity-20'}`} />

            {triggerRipple && <div className="absolute top-1/2 left-1/2 w-96 h-96 rounded-full border-4 border-white/50 pointer-events-none animate-ripple" />}

            {deltaIndicator && (
               <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 pointer-events-none z-30">
                  <div className={`flex items-center gap-2 px-6 py-3 rounded-full text-2xl font-black shadow-2xl backdrop-blur-md border-2 animate-delta ${
                    deltaIndicator.type === 'plus' ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500' : 'bg-red-500/20 text-red-400 border-red-500'
                  }`}>
                    {deltaIndicator.type === 'plus' ? <MoveUp size={28} /> : <MoveDown size={28} />}
                    {deltaIndicator.type === 'plus' ? '+' : '-'}{deltaIndicator.value}%
                  </div>
               </div>
            )}

            {/* Real-time Graph Overlay */}
            {isActive && sessionHistory.length > 1 && (
              <div className="absolute inset-x-0 bottom-0 h-1/4 pointer-events-none opacity-40 z-0">
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={sessionHistory} margin={{ top: 0, right: 0, left: 0, bottom: 0 }}>
                    <defs>
                      <linearGradient id="scoreOverlay" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#818cf8" stopOpacity={0.6}/>
                        <stop offset="95%" stopColor="#818cf8" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <Area 
                      type="monotone" 
                      dataKey="score" 
                      stroke="#ffffff" 
                      strokeWidth={1} 
                      fillOpacity={1} 
                      fill="url(#scoreOverlay)" 
                      isAnimationActive={true}
                      animationDuration={1500}
                    />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
            )}

            {isActive && (
              <div className="absolute right-6 top-1/2 -translate-y-1/2 w-2 h-48 bg-white/10 rounded-full border border-white/10 p-0.5">
                <div 
                  className="w-full rounded-full transition-all duration-1000 bg-gradient-to-t from-red-500 via-amber-400 to-emerald-500" 
                  style={{ height: `${analysis?.alignmentScore || 0}%`, marginTop: `${100 - (analysis?.alignmentScore || 0)}%` }}
                />
              </div>
            )}

            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none" width={640} height={480} />

            <div className="absolute top-8 left-8 flex items-center gap-3">
              <div className={`w-3 h-3 rounded-full ${isActive ? 'bg-red-500 animate-pulse' : 'bg-slate-600'}`}></div>
              <span className="text-white text-xs font-black tracking-widest uppercase opacity-80">
                {isActive ? 'Live Pathological Mapping' : 'Engine Standby'}
              </span>
            </div>

            {isActive && (
              <div className="absolute top-8 right-12 flex flex-col items-end gap-2">
                <div className="bg-black/40 backdrop-blur-md px-4 py-2 rounded-xl border border-white/10 flex items-center gap-3">
                  <Waves size={16} className="text-indigo-400" />
                  <p className="text-sm font-black text-white">{Math.round(analysis?.alignmentScore || 0)}% Match</p>
                </div>
                {baselineLandmarks && (
                   <div className="bg-indigo-600/90 px-3 py-1.5 rounded-lg text-white text-[10px] font-black uppercase tracking-widest shadow-lg flex items-center gap-2">
                      <ShieldCheck size={14} /> Baseline Active
                   </div>
                )}
              </div>
            )}

            {calibrationStep !== 'idle' && (
              <div className="absolute inset-0 bg-indigo-900/80 backdrop-blur-md flex flex-col items-center justify-center text-white z-20 animate-in fade-in p-12 text-center">
                {calibrationStep === 'instruction' && (
                  <div className="max-w-md space-y-6">
                    <div className="w-20 h-20 bg-white/10 rounded-3xl flex items-center justify-center mx-auto border border-white/20"><ScanEye size={40} className="text-indigo-400" /></div>
                    <h2 className="text-3xl font-black">Clinical Calibration</h2>
                    <p className="text-indigo-100 font-medium">Align your spine with the screen center to establish your neutral physiological baseline.</p>
                    <div className="flex gap-3">
                      <button onClick={() => setCalibrationStep('idle')} className="flex-1 py-4 bg-white/10 rounded-2xl font-bold">Cancel</button>
                      <button onClick={() => { setCalibrationStep('preparing'); setCountdown(5); }} className="flex-1 py-4 bg-indigo-500 rounded-2xl font-bold">Initiate Scan</button>
                    </div>
                  </div>
                )}
                {calibrationStep === 'preparing' && (
                   <><div className="w-32 h-32 rounded-full border-8 border-white/10 flex items-center justify-center mb-8"><span className="text-6xl font-black">{countdown}</span></div><h2 className="text-3xl font-black mb-2">Capturing Vector Base...</h2></>
                )}
                {calibrationStep === 'complete' && (
                  <div className="flex flex-col items-center gap-4"><div className="w-24 h-24 bg-emerald-500 rounded-full flex items-center justify-center"><CheckCircle2 size={48} /></div><p className="font-black text-3xl">Normalization Applied</p></div>
                )}
              </div>
            )}

            {!isActive && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-white space-y-4">
                <div className="w-20 h-20 bg-white/10 backdrop-blur-md rounded-3xl flex items-center justify-center text-slate-400"><CameraOff size={40} /></div>
                <div className="text-center px-8">
                  <p className="font-black text-xl mb-1">Standby Mode</p>
                  <p className="text-slate-400 text-sm font-medium">Start the camera for real-time skeletal analysis.</p>
                </div>
              </div>
            )}

            <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-4 group-hover:scale-105 transition-transform z-10">
              <button onClick={toggleCamera} className={`flex items-center gap-3 px-8 py-4 rounded-2xl font-black text-sm uppercase tracking-widest transition-all ${isActive ? 'bg-white/10 backdrop-blur-md text-white border border-white/20 hover:bg-white/20' : 'bg-indigo-600 text-white shadow-xl shadow-indigo-500/20'}`}>
                {isActive ? <><Square size={18} /> Exit</> : <><Play size={18} /> Start Monitoring</>}
              </button>
              {isActive && (
                <div className="flex gap-2">
                  <button onClick={() => setCalibrationStep('instruction')} disabled={calibrationStep !== 'idle'} className="flex items-center gap-3 px-8 py-4 bg-indigo-600 text-white rounded-2xl font-black text-sm uppercase tracking-widest shadow-lg shadow-indigo-500/30">
                    <Target size={18} /> {baselineLandmarks ? 'Adjust Base' : 'Set Baseline'}
                  </button>
                  {baselineLandmarks && (
                    <button onClick={() => setBaselineLandmarks(null)} className="p-4 bg-red-500/20 text-red-400 border border-red-500/20 rounded-2xl hover:bg-red-500 hover:text-white transition-all">
                      <XCircle size={20} />
                    </button>
                  )}
                </div>
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Cobb Angle</p>
              <p className="text-4xl font-black text-slate-800">{analysis?.estimatedCobbAngle ? `${analysis.estimatedCobbAngle.toFixed(1)}°` : '--°'}</p>
            </div>
            <div className={`p-6 rounded-3xl border shadow-sm ${getSeverityStyles(analysis?.severity as ScoliosisSeverity)}`}>
              <p className="text-[10px] font-black uppercase tracking-widest mb-1 opacity-70">Curvature Risk</p>
              <p className="text-3xl font-black">{analysis?.severity || '--'}</p>
            </div>
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Alignment Score</p>
              <p className="text-4xl font-black text-indigo-600">{analysis ? `${Math.round(analysis.alignmentScore)}%` : '--%'}</p>
            </div>
          </div>
        </div>

        {/* THERAPEUTIC RECOMMENDATIONS & HISTORY */}
        <div className="w-full xl:w-96 space-y-6 flex flex-col">
          <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-lg flex flex-col h-[500px]">
             <div className="flex items-center justify-between mb-6">
                <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><Dumbbell size={24} className="text-indigo-600" /> Exercise Plan</h3>
                {isAnalyzing && <RefreshCw size={16} className="text-indigo-400 animate-spin" />}
             </div>

             <div className="space-y-4 overflow-y-auto flex-1 pr-2 custom-scrollbar">
                {analysis?.exercises ? analysis.exercises.map((ex, i) => (
                  <div key={i} className="bg-slate-50 border border-slate-100 rounded-2xl p-4 group hover:border-indigo-200 transition-all animate-in slide-in-from-right-4">
                    <div className="flex items-start justify-between mb-2">
                       <h4 className="font-bold text-slate-800 text-sm leading-tight group-hover:text-indigo-600 transition-colors">{ex.name}</h4>
                       <span className="text-[10px] font-black uppercase tracking-widest bg-white border border-slate-200 px-2 py-0.5 rounded-lg text-slate-500 whitespace-nowrap">{ex.reps}</span>
                    </div>
                    <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest mb-2 flex items-center gap-1">
                       <Dna size={12} /> {ex.focus}
                    </p>
                    <p className="text-xs text-slate-500 leading-relaxed font-medium">
                       {ex.description}
                    </p>
                  </div>
                )) : (
                  <div className="flex flex-col items-center justify-center py-20 text-slate-300 opacity-60 text-center">
                    <ActivityIcon size={32} className="mb-2" />
                    <p className="text-xs font-black uppercase tracking-widest">Awaiting Pose Detection</p>
                    <p className="text-[10px] mt-1 font-medium italic">Personalized correctives generate live</p>
                  </div>
                )}
             </div>
          </div>

          <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-lg flex-1 min-h-[300px] flex flex-col overflow-hidden">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><History size={24} className="text-indigo-600" /> Monitoring Log</h3>
              <button onClick={() => setSessionEvents([])} className="p-2 hover:bg-slate-100 text-slate-400 rounded-lg transition-colors"><Trash2 size={16} /></button>
            </div>

            <div className="space-y-4 overflow-y-auto flex-1 pr-2 custom-scrollbar">
              {sessionEvents.length > 0 ? sessionEvents.map((event) => (
                  <div key={event.id} className={`flex gap-4 p-4 rounded-2xl border animate-in slide-in-from-left-2 ${
                    event.type === 'improvement' ? 'bg-emerald-50 border-emerald-100' :
                    event.type === 'deterioration' ? 'bg-amber-50 border-amber-100' :
                    'bg-slate-50 border-slate-100'
                  }`}>
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${
                      event.type === 'improvement' ? 'bg-emerald-100 text-emerald-600' : 'bg-indigo-100 text-indigo-600'
                    }`}>
                      {event.type === 'improvement' ? <ArrowUpRight size={20} /> : <ActivityIcon size={20} />}
                    </div>
                    <div className="flex-1">
                      <div className="flex justify-between items-start mb-1">
                        <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">{event.time}</p>
                        <span className={`text-[10px] font-black px-1.5 py-0.5 rounded shadow-sm ${event.delta > 0 ? 'bg-emerald-600 text-white' : 'bg-slate-200 text-slate-600'}`}>{event.delta}%</span>
                      </div>
                      <p className="text-sm font-bold text-slate-800 leading-tight">{event.label}</p>
                      <p className="text-[11px] font-medium text-slate-500 mt-1 leading-relaxed italic">"{event.feedback}"</p>
                    </div>
                  </div>
              )) : (
                <div className="flex flex-col items-center justify-center py-10 text-slate-300 opacity-60">
                  <Clock size={32} className="mb-2" />
                  <p className="text-xs font-bold uppercase tracking-widest">No Events Logged</p>
                </div>
              )}
              <div ref={logEndRef} />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PostureLiveView;

import React, { useEffect, useRef, useState, useMemo } from 'react';
import { 
  Camera, 
  CameraOff, 
  Play, 
  Square, 
  RefreshCw, 
  Zap, 
  AlertCircle, 
  Activity,
  CheckCircle2,
  ScanEye,
  Target,
  ChevronRight,
  ShieldCheck,
  Dumbbell,
  Stethoscope,
  TrendingUp,
  AlertTriangle,
  ArrowUpRight,
  ArrowDownRight,
  Info,
  UserCheck,
  Undo2,
  Clock,
  History,
  Timer,
  Waves,
  Lightbulb,
  ArrowRight,
  MoveUp,
  MoveDown,
  Trash2,
  Settings,
  Activity as ActivityIcon,
  XCircle,
  Dna,
  LocateFixed
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";
import { PostureAnalysis, Landmark, ScoliosisSeverity } from '../types';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceLine } from 'recharts';

type CalibrationStep = 'idle' | 'instruction' | 'preparing' | 'capturing' | 'complete';

interface Exercise {
  name: string;
  focus: string;
  reps: string;
  description: string;
}

interface SessionEvent {
  id: string;
  time: string;
  type: 'improvement' | 'deterioration' | 'deviation' | 'system';
  score: number;
  delta: number;
  label: string;
  feedback: string;
}

interface SessionDataPoint {
  time: string;
  timestamp: number;
  score: number;
  angle: number;
  landmarks?: Landmark[];
  isEvent?: boolean;
}

const PostureLiveView: React.FC = () => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const logEndRef = useRef<HTMLDivElement>(null);

  const [isActive, setIsActive] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<PostureAnalysis & { exercises?: Exercise[] } | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [sessionHistory, setSessionHistory] = useState<SessionDataPoint[]>([]);
  const [sessionEvents, setSessionEvents] = useState<SessionEvent[]>([]);
  const [startTime, setStartTime] = useState<number | null>(null);

  // Real-time Visual indicators
  const [deltaIndicator, setDeltaIndicator] = useState<{ value: number, type: 'plus' | 'minus' | 'alert' } | null>(null);
  const [triggerRipple, setTriggerRipple] = useState(false);

  // Calibration State
  const [calibrationStep, setCalibrationStep] = useState<CalibrationStep>('idle');
  const [baselineLandmarks, setBaselineLandmarks] = useState<Landmark[] | null>(null);
  const [baselineScore, setBaselineScore] = useState<number | null>(null);
  const [countdown, setCountdown] = useState(0);

  // Auto-scroll log to bottom
  useEffect(() => {
    if (logEndRef.current) {
      logEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [sessionEvents]);

  const getSeverityStyles = (severity?: ScoliosisSeverity) => {
    switch (severity) {
      case ScoliosisSeverity.NORMAL: return 'bg-emerald-50 text-emerald-700 border-emerald-200';
      case ScoliosisSeverity.MILD: return 'bg-blue-50 text-blue-700 border-blue-200';
      case ScoliosisSeverity.MODERATE: return 'bg-amber-50 text-amber-700 border-amber-200';
      case ScoliosisSeverity.SEVERE: return 'bg-red-50 text-red-700 border-red-200';
      default: return 'bg-slate-50 text-slate-700 border-slate-200';
    }
  };

  const addEvent = (event: Omit<SessionEvent, 'id' | 'time'>) => {
    const newEvent: SessionEvent = {
      ...event,
      id: Math.random().toString(36).substr(2, 9),
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })
    };
    setSessionEvents(prev => [...prev.slice(-49), newEvent]);
  };

  const toggleCamera = async () => {
    if (isActive) {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
      setIsActive(false);
      setAnalysis(null);
      setCalibrationStep('idle');
      addEvent({ type: 'system', label: 'Monitoring Stopped', score: 0, delta: 0, feedback: 'User ended monitoring session.' });
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsActive(true);
          setStartTime(Date.now());
          setSessionHistory([]);
          setSessionEvents([]);
          setError(null);
          addEvent({ type: 'system', label: 'Monitoring Started', score: 0, delta: 0, feedback: 'Computer vision engine ready.' });
        }
      } catch (err) {
        setError("Camera access required for live monitoring.");
      }
    }
  };

  const captureCalibration = async () => {
    if (!videoRef.current) return;
    setCalibrationStep('capturing');

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `Locate skeletal landmarks: Head, LeftShoulder, RightShoulder, SpineCenter, LeftHip, RightHip. Return JSON.` }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  },
                  required: ['x', 'y', 'label']
                }
              },
              alignmentScore: { type: Type.NUMBER }
            },
            required: ['landmarks', 'alignmentScore']
          }
        }
      });
      const result = JSON.parse(response.text || '{}');
      if (result.landmarks) {
        setBaselineLandmarks(result.landmarks);
        setBaselineScore(result.alignmentScore);
        setCalibrationStep('complete');
        addEvent({ type: 'system', label: 'Baseline Established', score: result.alignmentScore, delta: 0, feedback: 'Fixed clinical baseline locked.' });
        setTimeout(() => setCalibrationStep('idle'), 2000);
      }
    } catch (err) {
      setCalibrationStep('idle');
      setError("Calibration failed. Please try again.");
    }
  };

  const analyzeFrame = async () => {
    if (!isActive || !videoRef.current || isAnalyzing || calibrationStep !== 'idle') return;

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `Analyze posture skeletal landmarks. 
              1. Detect normalized landmarks (Head, LeftShoulder, RightShoulder, SpineCenter, LeftHip, RightHip).
              2. alignmentScore (0-100).
              3. estimatedCobbAngle.
              4. severity classification.
              5. feedback: one sentence clinical advice.
              6. exercises: 3 tailored exercises.
              Return JSON.` 
            }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  }
                }
              },
              alignmentScore: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              isDeviating: { type: Type.BOOLEAN },
              estimatedCobbAngle: { type: Type.NUMBER },
              severity: { type: Type.STRING },
              exercises: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    name: { type: Type.STRING },
                    focus: { type: Type.STRING },
                    reps: { type: Type.STRING },
                    description: { type: Type.STRING }
                  }
                }
              }
            },
            required: ['landmarks', 'alignmentScore', 'feedback', 'isDeviating', 'estimatedCobbAngle', 'severity', 'exercises']
          }
        }
      });

      const result = JSON.parse(response.text || '{}');

      // Handle Logging and UI Updates
      if (sessionHistory.length > 0) {
        const lastScore = sessionHistory[sessionHistory.length - 1].score;
        const delta = result.alignmentScore - lastScore;

        if (Math.abs(delta) > 10) {
          setDeltaIndicator({ value: Math.round(Math.abs(delta)), type: delta > 0 ? 'plus' : 'minus' });
          setTriggerRipple(true);
          addEvent({
            type: delta > 0 ? 'improvement' : 'deterioration',
            label: delta > 0 ? 'Posture Correction' : 'Postural Regression',
            score: Math.round(result.alignmentScore),
            delta: Math.round(delta),
            feedback: result.feedback
          });
        }
        setTimeout(() => { setDeltaIndicator(null); setTriggerRipple(false); }, 3000);
      }

      setAnalysis(result);

      const currentTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
      setSessionHistory(prev => [...prev.slice(-44), {
        time: currentTime,
        timestamp: Date.now(),
        score: result.alignmentScore,
        angle: result.estimatedCobbAngle,
        landmarks: result.landmarks
      }]); 
    } catch (err) {
      console.error(err);
    } finally {
      setIsAnalyzing(false);
    }
  };

  useEffect(() => {
    let interval: number;
    if (isActive && calibrationStep === 'idle') {
      interval = window.setInterval(analyzeFrame, 4000); 
    }
    return () => clearInterval(interval);
  }, [isActive, isAnalyzing, calibrationStep, baselineLandmarks]);

  useEffect(() => {
    if (!canvasRef.current || (!analysis && !baselineLandmarks)) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const { width, height } = canvasRef.current;
    ctx.clearRect(0, 0, width, height);

    const getPt = (points: Landmark[], label: string) => 
      points.find(p => p.label.toLowerCase().replace(/[^a-z]/g, '').includes(label.toLowerCase()));

    const drawSkeleton = (points: Landmark[], isBaseline: boolean) => {
      const head = getPt(points, 'head');
      const ls = getPt(points, 'leftshoulder');
      const rs = getPt(points, 'rightshoulder');
      const spine = getPt(points, 'spine');
      const lh = getPt(points, 'lefthip');
      const rh = getPt(points, 'righthip');

      const drawLine = (p1?: Landmark, p2?: Landmark, color: string = 'rgba(255,255,255,0.5)', width: number = 2) => {
        if (p1 && p2) {
          ctx.beginPath();
          ctx.lineWidth = width;
          ctx.strokeStyle = color;
          ctx.moveTo(p1.x * canvasRef.current!.width / 100, p1.y * canvasRef.current!.height / 100);
          ctx.lineTo(p2.x * canvasRef.current!.width / 100, p2.y * canvasRef.current!.height / 100);
          ctx.stroke();
        }
      };

      if (isBaseline) {
        ctx.setLineDash([5, 5]);
        const baselineColor = 'rgba(99, 102, 241, 0.4)';
        drawLine(head, spine, baselineColor, 1);
        drawLine(ls, rs, baselineColor, 1);
        drawLine(ls, lh, baselineColor, 1);
        drawLine(rs, rh, baselineColor, 1);
        drawLine(lh, rh, baselineColor, 1);
        ctx.setLineDash([]);
      } else {
        points.forEach(pt => {
          let jointColor = '#10b981'; // Green
          let deviation = 0;

          if (baselineLandmarks) {
            const basePt = getPt(baselineLandmarks, pt.label.toLowerCase().replace(/[^a-z]/g, ''));
            if (basePt) {
              deviation = Math.sqrt(Math.pow(pt.x - basePt.x, 2) + Math.pow(pt.y - basePt.y, 2));
              // Map deviation to color: 0-5 (green), 5-15 (amber), 15+ (red)
              if (deviation > 12) jointColor = '#ef4444';
              else if (deviation > 6) jointColor = '#f59e0b';
            }
          }

          const x = pt.x * canvasRef.current!.width / 100;
          const y = pt.y * canvasRef.current!.height / 100;

          // Tension Aura for high deviation
          if (deviation > 10) {
            ctx.beginPath();
            ctx.arc(x, y, 12 + Math.sin(Date.now() / 200) * 4, 0, Math.PI * 2);
            ctx.fillStyle = `${jointColor}33`; // Transparent version of color
            ctx.fill();
          }

          // Main Joint Dot
          ctx.beginPath();
          ctx.arc(x, y, 6, 0, Math.PI * 2);
          ctx.fillStyle = jointColor;
          ctx.fill();
          ctx.strokeStyle = 'white';
          ctx.lineWidth = 2;
          ctx.stroke();
        });

        // Skeleton Lines
        const lineColor = analysis?.isDeviating ? 'rgba(239, 68, 68, 0.5)' : 'rgba(16, 185, 129, 0.5)';
        drawLine(head, spine, lineColor, 3);
        drawLine(ls, rs, lineColor, 3);
        drawLine(ls, lh, lineColor, 3);
        drawLine(rs, rh, lineColor, 3);
        drawLine(lh, rh, lineColor, 3);
      }
    };

    if (baselineLandmarks && isActive) {
      drawSkeleton(baselineLandmarks, true);
    }
    if (analysis?.landmarks && isActive) {
      drawSkeleton(analysis.landmarks, false);
    }
  }, [analysis, baselineLandmarks, isActive]);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <style>{`
        @keyframes ripple {
          0% { transform: translate(-50%, -50%) scale(0); opacity: 0.8; }
          100% { transform: translate(-50%, -50%) scale(2.5); opacity: 0; }
        }
        @keyframes slide-up {
          0% { transform: translateY(0); opacity: 0; }
          20% { opacity: 1; }
          80% { opacity: 1; }
          100% { transform: translateY(-30px); opacity: 0; }
        }
        .animate-ripple { animation: ripple 1.5s ease-out forwards; }
        .animate-delta { animation: slide-up 3s ease-out forwards; }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }
      `}</style>

      <div className="flex flex-col xl:flex-row gap-8">
        {/* VIDEO MONITORING FEED */}
        <div className="flex-1 flex flex-col gap-6">
          <div className={`bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl relative aspect-video border-4 transition-all duration-700 ${analysis?.alignmentScore && analysis.alignmentScore > 80 ? 'border-emerald-500/40 shadow-emerald-500/10' : analysis?.isDeviating ? 'border-red-500/40 shadow-red-500/10' : 'border-slate-800'}`}>
            <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity duration-700 ${isActive ? 'opacity-100' : 'opacity-20'}`} />

            {triggerRipple && <div className="absolute top-1/2 left-1/2 w-96 h-96 rounded-full border-4 border-white/50 pointer-events-none animate-ripple" />}

            {deltaIndicator && (
               <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 pointer-events-none z-30">
                  <div className={`flex items-center gap-2 px-6 py-3 rounded-full text-2xl font-black shadow-2xl backdrop-blur-md border-2 animate-delta ${
                    deltaIndicator.type === 'plus' ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500' : 'bg-red-500/20 text-red-400 border-red-500'
                  }`}>
                    {deltaIndicator.type === 'plus' ? <MoveUp size={28} /> : <MoveDown size={28} />}
                    {deltaIndicator.type === 'plus' ? '+' : '-'}{deltaIndicator.value}%
                  </div>
               </div>
            )}

            {/* Real-time Graph Overlay */}
            {isActive && sessionHistory.length > 1 && (
              <div className="absolute inset-x-0 bottom-0 h-1/4 pointer-events-none opacity-30 z-0">
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={sessionHistory} margin={{ top: 0, right: 0, left: 0, bottom: 0 }}>
                    <defs>
                      <linearGradient id="scoreOverlay" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#818cf8" stopOpacity={0.6}/>
                        <stop offset="95%" stopColor="#818cf8" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <Area 
                      type="monotone" 
                      dataKey="score" 
                      stroke="#ffffff" 
                      strokeWidth={1} 
                      fillOpacity={1} 
                      fill="url(#scoreOverlay)" 
                      isAnimationActive={true}
                      animationDuration={1500}
                    />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
            )}

            {isActive && (
              <div className="absolute right-6 top-1/2 -translate-y-1/2 w-2 h-48 bg-white/10 rounded-full border border-white/10 p-0.5">
                <div 
                  className="w-full rounded-full transition-all duration-1000 bg-gradient-to-t from-red-500 via-amber-400 to-emerald-500" 
                  style={{ height: `${analysis?.alignmentScore || 0}%`, marginTop: `${100 - (analysis?.alignmentScore || 0)}%` }}
                />
              </div>
            )}

            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none" width={640} height={480} />

            <div className="absolute top-8 left-8 flex items-center gap-3">
              <div className={`w-3 h-3 rounded-full ${isActive ? 'bg-red-500 animate-pulse' : 'bg-slate-600'}`}></div>
              <span className="text-white text-xs font-black tracking-widest uppercase opacity-80">
                {isActive ? 'Pathological Heatmapping' : 'Engine Standby'}
              </span>
            </div>

            {isActive && (
              <div className="absolute top-8 right-12 flex flex-col items-end gap-2">
                <div className="bg-black/40 backdrop-blur-md px-4 py-2 rounded-xl border border-white/10 flex items-center gap-3">
                  <Waves size={16} className="text-indigo-400" />
                  <p className="text-sm font-black text-white">{Math.round(analysis?.alignmentScore || 0)}% Match</p>
                </div>
                {baselineLandmarks && (
                   <div className="bg-indigo-600/90 px-3 py-1.5 rounded-lg text-white text-[10px] font-black uppercase tracking-widest shadow-lg flex items-center gap-2">
                      <LocateFixed size={14} /> Heatmap Tracking Active
                   </div>
                )}
              </div>
            )}

            {calibrationStep !== 'idle' && (
              <div className="absolute inset-0 bg-indigo-900/80 backdrop-blur-md flex flex-col items-center justify-center text-white z-20 animate-in fade-in p-12 text-center">
                {calibrationStep === 'instruction' && (
                  <div className="max-w-md space-y-6">
                    <div className="w-20 h-20 bg-white/10 rounded-3xl flex items-center justify-center mx-auto border border-white/20"><ScanEye size={40} className="text-indigo-400" /></div>
                    <h2 className="text-3xl font-black">Skeletal Calibration</h2>
                    <p className="text-indigo-100 font-medium">Stand centered to lock your optimal skeletal baseline for real-time heatmap tracking.</p>
                    <div className="flex gap-3">
                      <button onClick={() => setCalibrationStep('idle')} className="flex-1 py-4 bg-white/10 rounded-2xl font-bold">Cancel</button>
                      <button onClick={() => { setCalibrationStep('preparing'); setCountdown(5); }} className="flex-1 py-4 bg-indigo-50 rounded-2xl font-bold">Initiate Scan</button>
                    </div>
                  </div>
                )}
                {calibrationStep === 'preparing' && (
                   <><div className="w-32 h-32 rounded-full border-8 border-white/10 flex items-center justify-center mb-8"><span className="text-6xl font-black">{countdown}</span></div><h2 className="text-3xl font-black mb-2">Capturing Vector Base...</h2></>
                )}
                {calibrationStep === 'complete' && (
                  <div className="flex flex-col items-center gap-4"><div className="w-24 h-24 bg-emerald-500 rounded-full flex items-center justify-center"><CheckCircle2 size={48} /></div><p className="font-black text-3xl">Normalization Applied</p></div>
                )}
              </div>
            )}

            {!isActive && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-white space-y-4">
                <div className="w-20 h-20 bg-white/10 backdrop-blur-md rounded-3xl flex items-center justify-center text-slate-400"><CameraOff size={40} /></div>
                <div className="text-center px-8">
                  <p className="font-black text-xl mb-1">Optical Standby</p>
                  <p className="text-slate-400 text-sm font-medium">Enable camera for skeletal heatmap analysis.</p>
                </div>
              </div>
            )}

            <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-4 group-hover:scale-105 transition-transform z-10">
              <button onClick={toggleCamera} className={`flex items-center gap-3 px-8 py-4 rounded-2xl font-black text-sm uppercase tracking-widest transition-all ${isActive ? 'bg-white/10 backdrop-blur-md text-white border border-white/20 hover:bg-white/20' : 'bg-indigo-600 text-white shadow-xl shadow-indigo-500/20'}`}>
                {isActive ? <><Square size={18} /> Exit</> : <><Play size={18} /> Start Monitoring</>}
              </button>
              {isActive && (
                <div className="flex gap-2">
                  <button onClick={() => setCalibrationStep('instruction')} disabled={calibrationStep !== 'idle'} className="flex items-center gap-3 px-8 py-4 bg-indigo-600 text-white rounded-2xl font-black text-sm uppercase tracking-widest shadow-lg shadow-indigo-500/30">
                    <Target size={18} /> {baselineLandmarks ? 'Adjust Base' : 'Set Baseline'}
                  </button>
                  {baselineLandmarks && (
                    <button onClick={() => setBaselineLandmarks(null)} className="p-4 bg-red-500/20 text-red-400 border border-red-500/20 rounded-2xl hover:bg-red-500 hover:text-white transition-all">
                      <XCircle size={20} />
                    </button>
                  )}
                </div>
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Cobb Angle Estimate</p>
              <p className="text-4xl font-black text-slate-800">{analysis?.estimatedCobbAngle ? `${analysis.estimatedCobbAngle.toFixed(1)}°` : '--°'}</p>
            </div>
            <div className={`p-6 rounded-3xl border shadow-sm ${getSeverityStyles(analysis?.severity as ScoliosisSeverity)}`}>
              <p className="text-[10px] font-black uppercase tracking-widest mb-1 opacity-70">Curvature Risk</p>
              <p className="text-3xl font-black">{analysis?.severity || '--'}</p>
            </div>
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Stability Score</p>
              <p className="text-4xl font-black text-indigo-600">{analysis ? `${Math.round(analysis.alignmentScore)}%` : '--%'}</p>
            </div>
          </div>
        </div>

        {/* THERAPEUTIC RECOMMENDATIONS & HISTORY */}
        <div className="w-full xl:w-96 space-y-6 flex flex-col">
          <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-lg flex flex-col h-[400px]">
             <div className="flex items-center justify-between mb-6">
                <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><Dumbbell size={24} className="text-indigo-600" /> Active Correctives</h3>
                {isAnalyzing && <RefreshCw size={16} className="text-indigo-400 animate-spin" />}
             </div>

             <div className="space-y-4 overflow-y-auto flex-1 pr-2 custom-scrollbar">
                {analysis?.exercises ? analysis.exercises.map((ex, i) => (
                  <div key={i} className="bg-slate-50 border border-slate-100 rounded-2xl p-4 group hover:border-indigo-200 transition-all animate-in slide-in-from-right-4">
                    <div className="flex items-start justify-between mb-2">
                       <h4 className="font-bold text-slate-800 text-sm leading-tight group-hover:text-indigo-600 transition-colors">{ex.name}</h4>
                       <span className="text-[10px] font-black uppercase tracking-widest bg-white border border-slate-200 px-2 py-0.5 rounded-lg text-slate-500 whitespace-nowrap">{ex.reps}</span>
                    </div>
                    <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest mb-2 flex items-center gap-1">
                       <Dna size={12} /> {ex.focus}
                    </p>
                    <p className="text-xs text-slate-500 leading-relaxed font-medium">
                       {ex.description}
                    </p>
                  </div>
                )) : (
                  <div className="flex flex-col items-center justify-center py-20 text-slate-300 opacity-60 text-center">
                    <ActivityIcon size={32} className="mb-2" />
                    <p className="text-xs font-black uppercase tracking-widest">Awaiting Bio-Feedback</p>
                    <p className="text-[10px] mt-1 font-medium italic">Corrective plan adapts to your pose</p>
                  </div>
                )}
             </div>
          </div>

          <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-lg flex-1 min-h-[300px] flex flex-col overflow-hidden">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><History size={24} className="text-indigo-600" /> Bio-Metric Log</h3>
              <button onClick={() => setSessionEvents([])} className="p-2 hover:bg-slate-100 text-slate-400 rounded-lg transition-colors"><Trash2 size={16} /></button>
            </div>

            <div className="space-y-4 overflow-y-auto flex-1 pr-2 custom-scrollbar">
              {sessionEvents.length > 0 ? sessionEvents.map((event) => (
                  <div key={event.id} className={`flex gap-4 p-4 rounded-2xl border animate-in slide-in-from-left-2 ${
                    event.type === 'improvement' ? 'bg-emerald-50 border-emerald-100' :
                    event.type === 'deterioration' ? 'bg-amber-50 border-amber-100' :
                    'bg-slate-50 border-slate-100'
                  }`}>
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${
                      event.type === 'improvement' ? 'bg-emerald-100 text-emerald-600' : 'bg-indigo-100 text-indigo-600'
                    }`}>
                      {event.type === 'improvement' ? <ArrowUpRight size={20} /> : <ActivityIcon size={20} />}
                    </div>
                    <div className="flex-1">
                      <div className="flex justify-between items-start mb-1">
                        <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">{event.time}</p>
                        <span className={`text-[10px] font-black px-1.5 py-0.5 rounded shadow-sm ${event.delta > 0 ? 'bg-emerald-600 text-white' : 'bg-slate-200 text-slate-600'}`}>{event.delta}%</span>
                      </div>
                      <p className="text-sm font-bold text-slate-800 leading-tight">{event.label}</p>
                      <p className="text-[11px] font-medium text-slate-500 mt-1 leading-relaxed italic">"{event.feedback}"</p>
                    </div>
                  </div>
              )) : (
                <div className="flex flex-col items-center justify-center py-10 text-slate-300 opacity-60">
                  <Clock size={32} className="mb-2" />
                  <p className="text-xs font-bold uppercase tracking-widest">Awaiting Events</p>
                </div>
              )}
              <div ref={logEndRef} />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PostureLiveView;

import React, { useEffect, useRef, useState, useMemo } from 'react';
import { 
  Camera, 
  CameraOff, 
  Play, 
  Square, 
  RefreshCw, 
  Zap, 
  AlertCircle, 
  Activity,
  CheckCircle2,
  ScanEye,
  Target,
  ChevronRight,
  ShieldCheck,
  Dumbbell,
  Stethoscope,
  TrendingUp,
  AlertTriangle,
  ArrowUpRight,
  ArrowDownRight,
  Info,
  UserCheck,
  Undo2,
  Clock,
  History,
  Timer,
  Waves,
  Lightbulb,
  ArrowRight,
  MoveUp,
  MoveDown,
  Trash2,
  Settings,
  Activity as ActivityIcon,
  XCircle,
  Dna,
  LocateFixed,
  Focus
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";
import { PostureAnalysis, Landmark, ScoliosisSeverity } from '../types';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceLine } from 'recharts';

type CalibrationStep = 'idle' | 'instruction' | 'preparing' | 'capturing' | 'complete';

interface Exercise {
  name: string;
  focus: string;
  reps: string;
  description: string;
}

interface SessionEvent {
  id: string;
  time: string;
  type: 'improvement' | 'deterioration' | 'deviation' | 'system';
  score: number;
  delta: number;
  label: string;
  feedback: string;
}

interface SessionDataPoint {
  time: string;
  timestamp: number;
  score: number;
  angle: number;
  landmarks?: Landmark[];
  isEvent?: boolean;
}

const PostureLiveView: React.FC = () => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const logEndRef = useRef<HTMLDivElement>(null);

  const [isActive, setIsActive] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<PostureAnalysis & { exercises?: Exercise[] } | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [sessionHistory, setSessionHistory] = useState<SessionDataPoint[]>([]);
  const [sessionEvents, setSessionEvents] = useState<SessionEvent[]>([]);
  const [startTime, setStartTime] = useState<number | null>(null);

  // Real-time Visual indicators
  const [deltaIndicator, setDeltaIndicator] = useState<{ value: number, type: 'plus' | 'minus' | 'alert' } | null>(null);
  const [triggerRipple, setTriggerRipple] = useState(false);

  // Calibration State
  const [calibrationStep, setCalibrationStep] = useState<CalibrationStep>('idle');
  const [baselineLandmarks, setBaselineLandmarks] = useState<Landmark[] | null>(null);
  const [baselineScore, setBaselineScore] = useState<number | null>(null);
  const [countdown, setCountdown] = useState(0);

  // Auto-scroll log to bottom
  useEffect(() => {
    if (logEndRef.current) {
      logEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [sessionEvents]);

  const getSeverityStyles = (severity?: ScoliosisSeverity) => {
    switch (severity) {
      case ScoliosisSeverity.NORMAL: return 'bg-emerald-50 text-emerald-700 border-emerald-200';
      case ScoliosisSeverity.MILD: return 'bg-blue-50 text-blue-700 border-blue-200';
      case ScoliosisSeverity.MODERATE: return 'bg-amber-50 text-amber-700 border-amber-200';
      case ScoliosisSeverity.SEVERE: return 'bg-red-50 text-red-700 border-red-200';
      default: return 'bg-slate-50 text-slate-700 border-slate-200';
    }
  };

  const addEvent = (event: Omit<SessionEvent, 'id' | 'time'>) => {
    const newEvent: SessionEvent = {
      ...event,
      id: Math.random().toString(36).substr(2, 9),
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })
    };
    setSessionEvents(prev => [...prev.slice(-49), newEvent]);
  };

  const toggleCamera = async () => {
    if (isActive) {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
      setIsActive(false);
      setAnalysis(null);
      setCalibrationStep('idle');
      addEvent({ type: 'system', label: 'Monitoring Stopped', score: 0, delta: 0, feedback: 'User ended monitoring session.' });
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsActive(true);
          setStartTime(Date.now());
          setSessionHistory([]);
          setSessionEvents([]);
          setError(null);
          addEvent({ type: 'system', label: 'Monitoring Started', score: 0, delta: 0, feedback: 'Computer vision engine ready.' });
        }
      } catch (err) {
        setError("Camera access required for live monitoring.");
      }
    }
  };

  const captureCalibration = async () => {
    if (!videoRef.current) return;
    setCalibrationStep('capturing');

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `Locate skeletal landmarks: Head, LeftShoulder, RightShoulder, SpineCenter, LeftHip, RightHip. Return JSON.` }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  },
                  required: ['x', 'y', 'label']
                }
              },
              alignmentScore: { type: Type.NUMBER }
            },
            required: ['landmarks', 'alignmentScore']
          }
        }
      });
      const result = JSON.parse(response.text || '{}');
      if (result.landmarks) {
        setBaselineLandmarks(result.landmarks);
        setBaselineScore(result.alignmentScore);
        setCalibrationStep('complete');
        addEvent({ type: 'system', label: 'Baseline Established', score: result.alignmentScore, delta: 0, feedback: 'Fixed clinical baseline locked.' });
        setTimeout(() => setCalibrationStep('idle'), 2000);
      }
    } catch (err) {
      setCalibrationStep('idle');
      setError("Calibration failed. Please try again.");
    }
  };

  const analyzeFrame = async () => {
    if (!isActive || !videoRef.current || isAnalyzing || calibrationStep !== 'idle') return;

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `Analyze posture skeletal landmarks. 
              1. Detect normalized landmarks (Head, LeftShoulder, RightShoulder, SpineCenter, LeftHip, RightHip).
              2. alignmentScore (0-100).
              3. estimatedCobbAngle.
              4. severity classification.
              5. feedback: one sentence clinical advice.
              6. exercises: 3 tailored exercises.
              Return JSON.` 
            }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  }
                }
              },
              alignmentScore: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              isDeviating: { type: Type.BOOLEAN },
              estimatedCobbAngle: { type: Type.NUMBER },
              severity: { type: Type.STRING },
              exercises: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    name: { type: Type.STRING },
                    focus: { type: Type.STRING },
                    reps: { type: Type.STRING },
                    description: { type: Type.STRING }
                  }
                }
              }
            },
            required: ['landmarks', 'alignmentScore', 'feedback', 'isDeviating', 'estimatedCobbAngle', 'severity', 'exercises']
          }
        }
      });

      const result = JSON.parse(response.text || '{}');

      // Handle Logging and UI Updates
      if (sessionHistory.length > 0) {
        const lastScore = sessionHistory[sessionHistory.length - 1].score;
        const delta = result.alignmentScore - lastScore;

        if (Math.abs(delta) > 10) {
          setDeltaIndicator({ value: Math.round(Math.abs(delta)), type: delta > 0 ? 'plus' : 'minus' });
          setTriggerRipple(true);
          addEvent({
            type: delta > 0 ? 'improvement' : 'deterioration',
            label: delta > 0 ? 'Posture Correction' : 'Postural Regression',
            score: Math.round(result.alignmentScore),
            delta: Math.round(delta),
            feedback: result.feedback
          });
        }
        setTimeout(() => { setDeltaIndicator(null); setTriggerRipple(false); }, 3000);
      }

      setAnalysis(result);

      const currentTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
      setSessionHistory(prev => [...prev.slice(-44), {
        time: currentTime,
        timestamp: Date.now(),
        score: result.alignmentScore,
        angle: result.estimatedCobbAngle,
        landmarks: result.landmarks
      }]); 
    } catch (err) {
      console.error(err);
    } finally {
      setIsAnalyzing(false);
    }
  };

  useEffect(() => {
    let interval: number;
    if (isActive && calibrationStep === 'idle') {
      interval = window.setInterval(analyzeFrame, 4000); 
    }
    return () => clearInterval(interval);
  }, [isActive, isAnalyzing, calibrationStep, baselineLandmarks]);

  useEffect(() => {
    if (!canvasRef.current || (!analysis && !baselineLandmarks)) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const { width, height } = canvasRef.current;
    ctx.clearRect(0, 0, width, height);

    const getPt = (points: Landmark[], label: string) => 
      points.find(p => p.label.toLowerCase().replace(/[^a-z]/g, '').includes(label.toLowerCase()));

    const drawSkeleton = (points: Landmark[], isBaseline: boolean) => {
      const head = getPt(points, 'head');
      const ls = getPt(points, 'leftshoulder');
      const rs = getPt(points, 'rightshoulder');
      const spine = getPt(points, 'spine');
      const lh = getPt(points, 'lefthip');
      const rh = getPt(points, 'righthip');

      const drawLine = (p1?: Landmark, p2?: Landmark, color: string = 'rgba(255,255,255,0.5)', lineWidth: number = 2, isMainSpine: boolean = false) => {
        if (p1 && p2) {
          const x1 = p1.x * width / 100;
          const y1 = p1.y * height / 100;
          const x2 = p2.x * width / 100;
          const y2 = p2.y * height / 100;

          if (isMainSpine && !isBaseline && analysis) {
            // Dynamic Spine Glow
            ctx.shadowBlur = 15 * (1 - analysis.alignmentScore / 100);
            ctx.shadowColor = analysis.isDeviating ? '#ef4444' : '#10b981';
          }

          ctx.beginPath();
          ctx.lineWidth = lineWidth;
          ctx.strokeStyle = color;
          ctx.moveTo(x1, y1);
          ctx.lineTo(x2, y2);
          ctx.stroke();

          ctx.shadowBlur = 0; // Reset shadow
        }
      };

      if (isBaseline) {
        ctx.setLineDash([5, 5]);
        const baselineColor = 'rgba(99, 102, 241, 0.25)';
        drawLine(head, spine, baselineColor, 1);
        drawLine(ls, rs, baselineColor, 1);
        drawLine(ls, lh, baselineColor, 1);
        drawLine(rs, rh, baselineColor, 1);
        drawLine(lh, rh, baselineColor, 1);
        ctx.setLineDash([]);
      } else {
        // Draw real-time connections
        const lineColor = analysis?.isDeviating ? 'rgba(239, 68, 68, 0.4)' : 'rgba(16, 185, 129, 0.4)';
        drawLine(head, spine, analysis?.isDeviating ? 'rgba(239, 68, 68, 0.8)' : 'rgba(16, 185, 129, 0.8)', 4, true);
        drawLine(ls, rs, lineColor, 2);
        drawLine(ls, lh, lineColor, 2);
        drawLine(rs, rh, lineColor, 2);
        drawLine(lh, rh, lineColor, 2);

        points.forEach(pt => {
          let jointColor = '#10b981'; 
          let deviation = 0;

          if (baselineLandmarks) {
            const basePt = getPt(baselineLandmarks, pt.label.toLowerCase().replace(/[^a-z]/g, ''));
            if (basePt) {
              deviation = Math.sqrt(Math.pow(pt.x - basePt.x, 2) + Math.pow(pt.y - basePt.y, 2));
              if (deviation > 12) jointColor = '#ef4444';
              else if (deviation > 6) jointColor = '#f59e0b';
            }
          }

          const x = pt.x * width / 100;
          const y = pt.y * height / 100;

          // Subtle Pulsing Joint Aura
          const auraPulse = Math.sin(Date.now() / 300) * 5;
          ctx.beginPath();
          ctx.arc(x, y, 8 + auraPulse, 0, Math.PI * 2);
          ctx.fillStyle = `${jointColor}22`;
          ctx.fill();

          // Core Joint Dot
          ctx.beginPath();
          ctx.arc(x, y, 5, 0, Math.PI * 2);
          ctx.fillStyle = jointColor;
          ctx.fill();
          ctx.strokeStyle = 'white';
          ctx.lineWidth = 1.5;
          ctx.stroke();

          // HUD element for Head
          if (pt.label.toLowerCase().includes('head') && deviation > 8) {
             ctx.beginPath();
             ctx.setLineDash([2, 2]);
             ctx.arc(x, y, 25, 0, Math.PI * 2);
             ctx.strokeStyle = 'rgba(255,255,255,0.3)';
             ctx.stroke();
             ctx.setLineDash([]);
          }
        });
      }
    };

    if (baselineLandmarks && isActive) {
      drawSkeleton(baselineLandmarks, true);
    }
    if (analysis?.landmarks && isActive) {
      drawSkeleton(analysis.landmarks, false);
    }
  }, [analysis, baselineLandmarks, isActive]);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <style>{`
        @keyframes ripple {
          0% { transform: translate(-50%, -50%) scale(0); opacity: 0.8; }
          100% { transform: translate(-50%, -50%) scale(2.5); opacity: 0; }
        }
        @keyframes slide-up {
          0% { transform: translateY(0); opacity: 0; }
          20% { opacity: 1; }
          80% { opacity: 1; }
          100% { transform: translateY(-30px); opacity: 0; }
        }
        .animate-ripple { animation: ripple 1.5s ease-out forwards; }
        .animate-delta { animation: slide-up 3s ease-out forwards; }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }
      `}</style>

      <div className="flex flex-col xl:flex-row gap-8">
        {/* VIDEO MONITORING FEED */}
        <div className="flex-1 flex flex-col gap-6">
          <div className={`bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl relative aspect-video border-4 transition-all duration-700 ${analysis?.alignmentScore && analysis.alignmentScore > 80 ? 'border-emerald-500/30 shadow-emerald-500/5' : analysis?.isDeviating ? 'border-red-500/40 shadow-red-500/10' : 'border-slate-800'}`}>
            <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity duration-700 ${isActive ? 'opacity-100' : 'opacity-20'}`} />

            {triggerRipple && <div className="absolute top-1/2 left-1/2 w-96 h-96 rounded-full border-4 border-white/50 pointer-events-none animate-ripple" />}

            {deltaIndicator && (
               <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 pointer-events-none z-30">
                  <div className={`flex items-center gap-2 px-6 py-3 rounded-full text-2xl font-black shadow-2xl backdrop-blur-md border-2 animate-delta ${
                    deltaIndicator.type === 'plus' ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500' : 'bg-red-500/20 text-red-400 border-red-500'
                  }`}>
                    {deltaIndicator.type === 'plus' ? <MoveUp size={28} /> : <MoveDown size={28} />}
                    {deltaIndicator.type === 'plus' ? '+' : '-'}{deltaIndicator.value}%
                  </div>
               </div>
            )}

            {/* Real-time Graph Overlay */}
            {isActive && sessionHistory.length > 1 && (
              <div className="absolute inset-x-0 bottom-0 h-1/4 pointer-events-none opacity-20 z-0">
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={sessionHistory} margin={{ top: 0, right: 0, left: 0, bottom: 0 }}>
                    <defs>
                      <linearGradient id="scoreOverlay" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#818cf8" stopOpacity={0.6}/>
                        <stop offset="95%" stopColor="#818cf8" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <Area 
                      type="monotone" 
                      dataKey="score" 
                      stroke="#ffffff" 
                      strokeWidth={1} 
                      fillOpacity={1} 
                      fill="url(#scoreOverlay)" 
                      isAnimationActive={true}
                      animationDuration={1500}
                    />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
            )}

            {isActive && (
              <div className="absolute right-6 top-1/2 -translate-y-1/2 w-2 h-48 bg-white/10 rounded-full border border-white/10 p-0.5">
                <div 
                  className="w-full rounded-full transition-all duration-1000 bg-gradient-to-t from-red-500 via-amber-400 to-emerald-500" 
                  style={{ height: `${analysis?.alignmentScore || 0}%`, marginTop: `${100 - (analysis?.alignmentScore || 0)}%` }}
                />
              </div>
            )}

            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none" width={640} height={480} />

            {/* Visual HUD Corner Markers */}
            <div className="absolute inset-8 pointer-events-none border-x border-white/5 opacity-50"></div>
            <div className="absolute inset-8 pointer-events-none border-y border-white/5 opacity-50"></div>

            <div className="absolute top-8 left-8 flex items-center gap-3">
              <div className={`w-3 h-3 rounded-full ${isActive ? 'bg-red-500 animate-pulse' : 'bg-slate-600'}`}></div>
              <span className="text-white text-xs font-black tracking-widest uppercase opacity-80">
                {isActive ? 'Real-Time Bio-Feedback' : 'Optical Engine Idle'}
              </span>
            </div>

            {isActive && (
              <div className="absolute top-8 right-12 flex flex-col items-end gap-2">
                <div className="bg-black/40 backdrop-blur-md px-4 py-2 rounded-xl border border-white/10 flex items-center gap-3">
                  <Waves size={16} className="text-indigo-400" />
                  <p className="text-sm font-black text-white">{Math.round(analysis?.alignmentScore || 0)}% Stability</p>
                </div>
                {baselineLandmarks && (
                   <div className="bg-indigo-600/90 px-3 py-1.5 rounded-lg text-white text-[10px] font-black uppercase tracking-widest shadow-lg flex items-center gap-2">
                      <ShieldCheck size={14} /> Tracking Clinical Base
                   </div>
                )}
              </div>
            )}

            {calibrationStep !== 'idle' && (
              <div className="absolute inset-0 bg-indigo-900/90 backdrop-blur-md flex flex-col items-center justify-center text-white z-20 animate-in fade-in p-12 text-center">
                {calibrationStep === 'instruction' && (
                  <div className="max-w-md space-y-6">
                    <div className="w-20 h-20 bg-white/10 rounded-3xl flex items-center justify-center mx-auto border border-white/20"><ScanEye size={40} className="text-indigo-400" /></div>
                    <h2 className="text-3xl font-black">Clinical Normalization</h2>
                    <p className="text-indigo-100 font-medium">Please stand centered and maintain your most comfortable upright posture to lock your skeletal baseline.</p>
                    <div className="flex gap-3">
                      <button onClick={() => setCalibrationStep('idle')} className="flex-1 py-4 bg-white/10 rounded-2xl font-bold">Cancel</button>
                      <button onClick={() => { setCalibrationStep('preparing'); setCountdown(5); }} className="flex-1 py-4 bg-indigo-500 rounded-2xl font-bold">Start Capture</button>
                    </div>
                  </div>
                )}
                {calibrationStep === 'preparing' && (
                   <><div className="w-32 h-32 rounded-full border-8 border-white/10 flex items-center justify-center mb-8"><span className="text-6xl font-black">{countdown}</span></div><h2 className="text-3xl font-black mb-2 text-indigo-100">Analyzing Body Vectors...</h2></>
                )}
                {calibrationStep === 'complete' && (
                  <div className="flex flex-col items-center gap-4"><div className="w-24 h-24 bg-emerald-500 rounded-full flex items-center justify-center"><CheckCircle2 size={48} /></div><p className="font-black text-3xl">Baseline Locked</p></div>
                )}
              </div>
            )}

            {!isActive && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-white space-y-4">
                <div className="w-20 h-20 bg-white/10 backdrop-blur-md rounded-3xl flex items-center justify-center text-slate-400"><CameraOff size={40} /></div>
                <div className="text-center px-8">
                  <p className="font-black text-xl mb-1">Optical Engine Ready</p>
                  <p className="text-slate-400 text-sm font-medium">Initiate camera feed for spinal curvature tracking.</p>
                </div>
              </div>
            )}

            <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-4 group-hover:scale-105 transition-transform z-10">
              <button onClick={toggleCamera} className={`flex items-center gap-3 px-8 py-4 rounded-2xl font-black text-sm uppercase tracking-widest transition-all ${isActive ? 'bg-white/10 backdrop-blur-md text-white border border-white/20 hover:bg-white/20' : 'bg-indigo-600 text-white shadow-xl shadow-indigo-500/20'}`}>
                {isActive ? <><Square size={18} /> Stop Session</> : <><Play size={18} /> Start Monitoring</>}
              </button>
              {isActive && (
                <div className="flex gap-2">
                  <button onClick={() => setCalibrationStep('instruction')} disabled={calibrationStep !== 'idle'} className="flex items-center gap-3 px-8 py-4 bg-indigo-600 text-white rounded-2xl font-black text-sm uppercase tracking-widest shadow-lg shadow-indigo-500/30">
                    <Target size={18} /> {baselineLandmarks ? 'Adjust Base' : 'Set Baseline'}
                  </button>
                  {baselineLandmarks && (
                    <button onClick={() => setBaselineLandmarks(null)} className="p-4 bg-red-500/20 text-red-400 border border-red-500/20 rounded-2xl hover:bg-red-500 hover:text-white transition-all" title="Clear Baseline">
                      <XCircle size={20} />
                    </button>
                  )}
                </div>
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm group">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 group-hover:text-indigo-600 transition-colors">Cobb Angle (AI-Est)</p>
              <p className="text-4xl font-black text-slate-800">{analysis?.estimatedCobbAngle ? `${analysis.estimatedCobbAngle.toFixed(1)}°` : '--°'}</p>
            </div>
            <div className={`p-6 rounded-3xl border shadow-sm transition-all duration-500 ${getSeverityStyles(analysis?.severity as ScoliosisSeverity)}`}>
              <p className="text-[10px] font-black uppercase tracking-widest mb-1 opacity-70">Scoliosis Risk</p>
              <p className="text-3xl font-black">{analysis?.severity || '--'}</p>
            </div>
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm group">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 group-hover:text-indigo-600 transition-colors">Alignment Score</p>
              <p className="text-4xl font-black text-indigo-600">{analysis ? `${Math.round(analysis.alignmentScore)}%` : '--%'}</p>
            </div>
          </div>
        </div>

        {/* ADAPTIVE THERAPEUTICS */}
        <div className="w-full xl:w-96 space-y-6 flex flex-col">
          <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-lg flex flex-col h-[400px]">
             <div className="flex items-center justify-between mb-6">
                <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><Dumbbell size={24} className="text-indigo-600" /> Prescribed Exercises</h3>
                {isAnalyzing && <RefreshCw size={16} className="text-indigo-400 animate-spin" />}
             </div>

             <div className="space-y-4 overflow-y-auto flex-1 pr-2 custom-scrollbar">
                {analysis?.exercises ? analysis.exercises.map((ex, i) => (
                  <div key={i} className="bg-slate-50 border border-slate-100 rounded-2xl p-4 group hover:border-indigo-200 transition-all animate-in slide-in-from-right-4">
                    <div className="flex items-start justify-between mb-2">
                       <h4 className="font-bold text-slate-800 text-sm leading-tight group-hover:text-indigo-600 transition-colors">{ex.name}</h4>
                       <span className="text-[10px] font-black uppercase tracking-widest bg-white border border-slate-200 px-2 py-0.5 rounded-lg text-slate-500 whitespace-nowrap">{ex.reps}</span>
                    </div>
                    <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest mb-2 flex items-center gap-1">
                       <Dna size={12} /> {ex.focus}
                    </p>
                    <p className="text-xs text-slate-500 leading-relaxed font-medium">
                       {ex.description}
                    </p>
                  </div>
                )) : (
                  <div className="flex flex-col items-center justify-center py-20 text-slate-300 opacity-60 text-center">
                    <Focus size={32} className="mb-2" />
                    <p className="text-xs font-black uppercase tracking-widest">Awaiting Pose Detection</p>
                    <p className="text-[10px] mt-1 font-medium italic">Corrective plan adapts to your body vectors</p>
                  </div>
                )}
             </div>
          </div>

          <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-lg flex-1 min-h-[300px] flex flex-col overflow-hidden">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><History size={24} className="text-indigo-600" /> Bio-Metric Log</h3>
              <button onClick={() => setSessionEvents([])} className="p-2 hover:bg-slate-100 text-slate-400 rounded-lg transition-colors" title="Clear Log"><Trash2 size={16} /></button>
            </div>

            <div className="space-y-4 overflow-y-auto flex-1 pr-2 custom-scrollbar">
              {sessionEvents.length > 0 ? sessionEvents.map((event) => (
                  <div key={event.id} className={`flex gap-4 p-4 rounded-2xl border animate-in slide-in-from-left-2 ${
                    event.type === 'improvement' ? 'bg-emerald-50 border-emerald-100' :
                    event.type === 'deterioration' ? 'bg-amber-50 border-amber-100' :
                    event.type === 'deviation' ? 'bg-red-50 border-red-100' :
                    'bg-slate-50 border-slate-100'
                  }`}>
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${
                      event.type === 'improvement' ? 'bg-emerald-100 text-emerald-600' : 
                      event.type === 'deterioration' ? 'bg-amber-100 text-amber-600' :
                      event.type === 'deviation' ? 'bg-red-100 text-red-600' :
                      'bg-indigo-100 text-indigo-600'
                    }`}>
                      {event.type === 'improvement' ? <ArrowUpRight size={20} /> : 
                       event.type === 'deterioration' ? <ArrowDownRight size={20} /> :
                       <ActivityIcon size={20} />}
                    </div>
                    <div className="flex-1">
                      <div className="flex justify-between items-start mb-1">
                        <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">{event.time}</p>
                        <span className={`text-[10px] font-black px-1.5 py-0.5 rounded shadow-sm ${event.delta > 0 ? 'bg-emerald-600 text-white' : 'bg-slate-200 text-slate-600'}`}>{event.delta > 0 ? '+' : ''}{event.delta}%</span>
                      </div>
                      <p className="text-sm font-bold text-slate-800 leading-tight">{event.label}</p>
                      <p className="text-[11px] font-medium text-slate-500 mt-1 leading-relaxed italic">"{event.feedback}"</p>
                    </div>
                  </div>
              )) : (
                <div className="flex flex-col items-center justify-center py-10 text-slate-300 opacity-60">
                  <Clock size={32} className="mb-2" />
                  <p className="text-xs font-bold uppercase tracking-widest">No Events Logged</p>
                </div>
              )}
              <div ref={logEndRef} />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PostureLiveView;

import React, { useEffect, useRef, useState, useMemo } from 'react';
import { 
  Camera, 
  CameraOff, 
  Play, 
  Square, 
  RefreshCw, 
  Zap, 
  AlertCircle, 
  Activity,
  CheckCircle2,
  ScanEye,
  Target,
  ChevronRight,
  ShieldCheck,
  Dumbbell,
  Stethoscope,
  TrendingUp,
  AlertTriangle,
  ArrowUpRight,
  ArrowDownRight,
  Info,
  UserCheck,
  Undo2,
  Clock,
  History,
  Timer,
  Waves,
  Lightbulb,
  ArrowRight,
  MoveUp,
  MoveDown,
  Trash2,
  Settings,
  Activity as ActivityIcon,
  XCircle,
  Dna,
  LocateFixed,
  Focus
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";
import { PostureAnalysis, Landmark, ScoliosisSeverity } from '../types';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceLine } from 'recharts';

type CalibrationStep = 'idle' | 'instruction' | 'preparing' | 'capturing' | 'complete';

interface Exercise {
  name: string;
  focus: string;
  reps: string;
  description: string;
}

interface SessionEvent {
  id: string;
  time: string;
  type: 'improvement' | 'deterioration' | 'deviation' | 'system';
  score: number;
  delta: number;
  label: string;
  feedback: string;
}

interface SessionDataPoint {
  time: string;
  timestamp: number;
  score: number;
  angle: number;
  landmarks?: Landmark[];
  isEvent?: boolean;
}

const PostureLiveView: React.FC = () => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const logEndRef = useRef<HTMLDivElement>(null);

  const [isActive, setIsActive] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<PostureAnalysis & { exercises?: Exercise[] } | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [sessionHistory, setSessionHistory] = useState<SessionDataPoint[]>([]);
  const [sessionEvents, setSessionEvents] = useState<SessionEvent[]>([]);
  const [startTime, setStartTime] = useState<number | null>(null);

  // Real-time Visual indicators
  const [deltaIndicator, setDeltaIndicator] = useState<{ value: number, type: 'plus' | 'minus' | 'alert' } | null>(null);
  const [triggerRipple, setTriggerRipple] = useState(false);

  // Calibration State
  const [calibrationStep, setCalibrationStep] = useState<CalibrationStep>('idle');
  const [baselineLandmarks, setBaselineLandmarks] = useState<Landmark[] | null>(null);
  const [baselineScore, setBaselineScore] = useState<number | null>(null);
  const [countdown, setCountdown] = useState(0);

  // Auto-scroll log to bottom
  useEffect(() => {
    if (logEndRef.current) {
      logEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [sessionEvents]);

  const getSeverityStyles = (severity?: ScoliosisSeverity) => {
    switch (severity) {
      case ScoliosisSeverity.NORMAL: return 'bg-emerald-50 text-emerald-700 border-emerald-200';
      case ScoliosisSeverity.MILD: return 'bg-blue-50 text-blue-700 border-blue-200';
      case ScoliosisSeverity.MODERATE: return 'bg-amber-50 text-amber-700 border-amber-200';
      case ScoliosisSeverity.SEVERE: return 'bg-red-50 text-red-700 border-red-200';
      default: return 'bg-slate-50 text-slate-700 border-slate-200';
    }
  };

  const addEvent = (event: Omit<SessionEvent, 'id' | 'time'>) => {
    const newEvent: SessionEvent = {
      ...event,
      id: Math.random().toString(36).substr(2, 9),
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })
    };
    setSessionEvents(prev => [...prev.slice(-49), newEvent]);
  };

  const toggleCamera = async () => {
    if (isActive) {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
      setIsActive(false);
      setAnalysis(null);
      setCalibrationStep('idle');
      addEvent({ type: 'system', label: 'Monitoring Stopped', score: 0, delta: 0, feedback: 'User ended monitoring session.' });
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsActive(true);
          setStartTime(Date.now());
          setSessionHistory([]);
          setSessionEvents([]);
          setError(null);
          addEvent({ type: 'system', label: 'Monitoring Started', score: 0, delta: 0, feedback: 'Computer vision engine ready.' });
        }
      } catch (err) {
        setError("Camera access required for live monitoring.");
      }
    }
  };

  const captureCalibration = async () => {
    if (!videoRef.current) return;
    setCalibrationStep('capturing');

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `Locate skeletal landmarks: Head, LeftShoulder, RightShoulder, SpineCenter, LeftHip, RightHip. Return JSON.` }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  },
                  required: ['x', 'y', 'label']
                }
              },
              alignmentScore: { type: Type.NUMBER }
            },
            required: ['landmarks', 'alignmentScore']
          }
        }
      });
      const result = JSON.parse(response.text || '{}');
      if (result.landmarks) {
        setBaselineLandmarks(result.landmarks);
        setBaselineScore(result.alignmentScore);
        setCalibrationStep('complete');
        addEvent({ type: 'system', label: 'Baseline Established', score: result.alignmentScore, delta: 0, feedback: 'Fixed clinical baseline locked.' });
        setTimeout(() => setCalibrationStep('idle'), 2000);
      }
    } catch (err) {
      setCalibrationStep('idle');
      setError("Calibration failed. Please try again.");
    }
  };

  const analyzeFrame = async () => {
    if (!isActive || !videoRef.current || isAnalyzing || calibrationStep !== 'idle') return;

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `Analyze posture skeletal landmarks. 
              1. Detect normalized landmarks (Head, LeftShoulder, RightShoulder, SpineCenter, LeftHip, RightHip).
              2. alignmentScore (0-100).
              3. estimatedCobbAngle.
              4. severity classification.
              5. feedback: one sentence clinical advice.
              6. exercises: 3 tailored exercises.
              Return JSON.` 
            }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  }
                }
              },
              alignmentScore: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              isDeviating: { type: Type.BOOLEAN },
              estimatedCobbAngle: { type: Type.NUMBER },
              severity: { type: Type.STRING },
              exercises: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    name: { type: Type.STRING },
                    focus: { type: Type.STRING },
                    reps: { type: Type.STRING },
                    description: { type: Type.STRING }
                  }
                }
              }
            },
            required: ['landmarks', 'alignmentScore', 'feedback', 'isDeviating', 'estimatedCobbAngle', 'severity', 'exercises']
          }
        }
      });

      const result = JSON.parse(response.text || '{}');

      // Handle Logging and UI Updates
      if (sessionHistory.length > 0) {
        const lastScore = sessionHistory[sessionHistory.length - 1].score;
        const delta = result.alignmentScore - lastScore;

        if (Math.abs(delta) > 10) {
          setDeltaIndicator({ value: Math.round(Math.abs(delta)), type: delta > 0 ? 'plus' : 'minus' });
          setTriggerRipple(true);
          addEvent({
            type: delta > 0 ? 'improvement' : 'deterioration',
            label: delta > 0 ? 'Posture Correction' : 'Postural Regression',
            score: Math.round(result.alignmentScore),
            delta: Math.round(delta),
            feedback: result.feedback
          });
        }
        setTimeout(() => { setDeltaIndicator(null); setTriggerRipple(false); }, 3000);
      }

      setAnalysis(result);

      const currentTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
      // Keep last 30 data points (~2 minutes at 4s intervals)
      setSessionHistory(prev => [...prev.slice(-29), {
        time: currentTime,
        timestamp: Date.now(),
        score: result.alignmentScore,
        angle: result.estimatedCobbAngle,
        landmarks: result.landmarks
      }]); 
    } catch (err) {
      console.error(err);
    } finally {
      setIsAnalyzing(false);
    }
  };

  useEffect(() => {
    let interval: number;
    if (isActive && calibrationStep === 'idle') {
      interval = window.setInterval(analyzeFrame, 4000); 
    }
    return () => clearInterval(interval);
  }, [isActive, isAnalyzing, calibrationStep, baselineLandmarks]);

  useEffect(() => {
    if (!canvasRef.current || (!analysis && !baselineLandmarks)) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const { width, height } = canvasRef.current;
    ctx.clearRect(0, 0, width, height);

    const getPt = (points: Landmark[], label: string) => 
      points.find(p => p.label.toLowerCase().replace(/[^a-z]/g, '').includes(label.toLowerCase()));

    const drawSkeleton = (points: Landmark[], isBaseline: boolean) => {
      const head = getPt(points, 'head');
      const ls = getPt(points, 'leftshoulder');
      const rs = getPt(points, 'rightshoulder');
      const spine = getPt(points, 'spine');
      const lh = getPt(points, 'lefthip');
      const rh = getPt(points, 'righthip');

      const drawLine = (p1?: Landmark, p2?: Landmark, color: string = 'rgba(255,255,255,0.5)', lineWidth: number = 2, isMainSpine: boolean = false) => {
        if (p1 && p2) {
          const x1 = p1.x * width / 100;
          const y1 = p1.y * height / 100;
          const x2 = p2.x * width / 100;
          const y2 = p2.y * height / 100;

          if (isMainSpine && !isBaseline && analysis) {
            // Dynamic Spine Glow
            ctx.shadowBlur = 15 * (1 - analysis.alignmentScore / 100);
            ctx.shadowColor = analysis.isDeviating ? '#ef4444' : '#10b981';
          }

          ctx.beginPath();
          ctx.lineWidth = lineWidth;
          ctx.strokeStyle = color;
          ctx.moveTo(x1, y1);
          ctx.lineTo(x2, y2);
          ctx.stroke();

          ctx.shadowBlur = 0; // Reset shadow
        }
      };

      if (isBaseline) {
        ctx.setLineDash([5, 5]);
        const baselineColor = 'rgba(99, 102, 241, 0.25)';
        drawLine(head, spine, baselineColor, 1);
        drawLine(ls, rs, baselineColor, 1);
        drawLine(ls, lh, baselineColor, 1);
        drawLine(rs, rh, baselineColor, 1);
        drawLine(lh, rh, baselineColor, 1);
        ctx.setLineDash([]);
      } else {
        // Draw real-time connections
        const lineColor = analysis?.isDeviating ? 'rgba(239, 68, 68, 0.4)' : 'rgba(16, 185, 129, 0.4)';
        drawLine(head, spine, analysis?.isDeviating ? 'rgba(239, 68, 68, 0.8)' : 'rgba(16, 185, 129, 0.8)', 4, true);
        drawLine(ls, rs, lineColor, 2);
        drawLine(ls, lh, lineColor, 2);
        drawLine(rs, rh, lineColor, 2);
        drawLine(lh, rh, lineColor, 2);

        points.forEach(pt => {
          let jointColor = '#10b981'; 
          let deviation = 0;

          if (baselineLandmarks) {
            const basePt = getPt(baselineLandmarks, pt.label.toLowerCase().replace(/[^a-z]/g, ''));
            if (basePt) {
              deviation = Math.sqrt(Math.pow(pt.x - basePt.x, 2) + Math.pow(pt.y - basePt.y, 2));
              if (deviation > 12) jointColor = '#ef4444';
              else if (deviation > 6) jointColor = '#f59e0b';
            }
          }

          const x = pt.x * width / 100;
          const y = pt.y * height / 100;

          // Subtle Pulsing Joint Aura
          const auraPulse = Math.sin(Date.now() / 300) * 5;
          ctx.beginPath();
          ctx.arc(x, y, 8 + auraPulse, 0, Math.PI * 2);
          ctx.fillStyle = `${jointColor}22`;
          ctx.fill();

          // Core Joint Dot
          ctx.beginPath();
          ctx.arc(x, y, 5, 0, Math.PI * 2);
          ctx.fillStyle = jointColor;
          ctx.fill();
          ctx.strokeStyle = 'white';
          ctx.lineWidth = 1.5;
          ctx.stroke();

          // HUD element for Head
          if (pt.label.toLowerCase().includes('head') && deviation > 8) {
             ctx.beginPath();
             ctx.setLineDash([2, 2]);
             ctx.arc(x, y, 25, 0, Math.PI * 2);
             ctx.strokeStyle = 'rgba(255,255,255,0.3)';
             ctx.stroke();
             ctx.setLineDash([]);
          }
        });
      }
    };

    if (baselineLandmarks && isActive) {
      drawSkeleton(baselineLandmarks, true);
    }
    if (analysis?.landmarks && isActive) {
      drawSkeleton(analysis.landmarks, false);
    }
  }, [analysis, baselineLandmarks, isActive]);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <style>{`
        @keyframes ripple {
          0% { transform: translate(-50%, -50%) scale(0); opacity: 0.8; }
          100% { transform: translate(-50%, -50%) scale(2.5); opacity: 0; }
        }
        @keyframes slide-up {
          0% { transform: translateY(0); opacity: 0; }
          20% { opacity: 1; }
          80% { opacity: 1; }
          100% { transform: translateY(-30px); opacity: 0; }
        }
        .animate-ripple { animation: ripple 1.5s ease-out forwards; }
        .animate-delta { animation: slide-up 3s ease-out forwards; }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }
      `}</style>

      <div className="flex flex-col xl:flex-row gap-8">
        {/* VIDEO MONITORING FEED */}
        <div className="flex-1 flex flex-col gap-6">
          <div className={`bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl relative aspect-video border-4 transition-all duration-700 ${analysis?.alignmentScore && analysis.alignmentScore > 80 ? 'border-emerald-500/30 shadow-emerald-500/5' : analysis?.isDeviating ? 'border-red-500/40 shadow-red-500/10' : 'border-slate-800'}`}>
            <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity duration-700 ${isActive ? 'opacity-100' : 'opacity-20'}`} />

            {triggerRipple && <div className="absolute top-1/2 left-1/2 w-96 h-96 rounded-full border-4 border-white/50 pointer-events-none animate-ripple" />}

            {deltaIndicator && (
               <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 pointer-events-none z-30">
                  <div className={`flex items-center gap-2 px-6 py-3 rounded-full text-2xl font-black shadow-2xl backdrop-blur-md border-2 animate-delta ${
                    deltaIndicator.type === 'plus' ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500' : 'bg-red-500/20 text-red-400 border-red-500'
                  }`}>
                    {deltaIndicator.type === 'plus' ? <MoveUp size={28} /> : <MoveDown size={28} />}
                    {deltaIndicator.type === 'plus' ? '+' : '-'}{deltaIndicator.value}%
                  </div>
               </div>
            )}

            {/* Enhanced Real-time Graph Overlay */}
            {isActive && sessionHistory.length > 1 && (
              <div className="absolute inset-x-0 bottom-0 h-1/4 pointer-events-none z-0">
                <div className="absolute top-2 left-8 text-[10px] font-black text-white/20 uppercase tracking-[0.2em] flex items-center gap-2">
                  <TrendingUp size={10} /> 2m Stability Trend
                </div>
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={sessionHistory} margin={{ top: 20, right: 0, left: 0, bottom: 0 }}>
                    <defs>
                      <linearGradient id="scoreOverlay" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#6366f1" stopOpacity={0.4}/>
                        <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <ReferenceLine y={85} stroke="#10b981" strokeDasharray="5 5" opacity={0.15} />
                    <ReferenceLine y={60} stroke="#ef4444" strokeDasharray="5 5" opacity={0.15} />
                    <Area 
                      type="monotone" 
                      dataKey="score" 
                      stroke="rgba(255,255,255,0.4)" 
                      strokeWidth={1.5} 
                      fillOpacity={1} 
                      fill="url(#scoreOverlay)" 
                      isAnimationActive={true}
                      animationDuration={1500}
                    />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
            )}

            {isActive && (
              <div className="absolute right-6 top-1/2 -translate-y-1/2 w-2 h-48 bg-white/10 rounded-full border border-white/10 p-0.5">
                <div 
                  className="w-full rounded-full transition-all duration-1000 bg-gradient-to-t from-red-500 via-amber-400 to-emerald-500" 
                  style={{ height: `${analysis?.alignmentScore || 0}%`, marginTop: `${100 - (analysis?.alignmentScore || 0)}%` }}
                />
              </div>
            )}

            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none" width={640} height={480} />

            {/* Visual HUD Corner Markers */}
            <div className="absolute inset-8 pointer-events-none border-x border-white/5 opacity-50"></div>
            <div className="absolute inset-8 pointer-events-none border-y border-white/5 opacity-50"></div>

            <div className="absolute top-8 left-8 flex items-center gap-3">
              <div className={`w-3 h-3 rounded-full ${isActive ? 'bg-red-500 animate-pulse' : 'bg-slate-600'}`}></div>
              <span className="text-white text-xs font-black tracking-widest uppercase opacity-80">
                {isActive ? 'Real-Time Bio-Feedback' : 'Optical Engine Idle'}
              </span>
            </div>

            {isActive && (
              <div className="absolute top-8 right-12 flex flex-col items-end gap-2">
                <div className="bg-black/40 backdrop-blur-md px-4 py-2 rounded-xl border border-white/10 flex items-center gap-3">
                  <Waves size={16} className="text-indigo-400" />
                  <p className="text-sm font-black text-white">{Math.round(analysis?.alignmentScore || 0)}% Stability</p>
                </div>
                {baselineLandmarks && (
                   <div className="bg-indigo-600/90 px-3 py-1.5 rounded-lg text-white text-[10px] font-black uppercase tracking-widest shadow-lg flex items-center gap-2">
                      <ShieldCheck size={14} /> Tracking Clinical Base
                   </div>
                )}
              </div>
            )}

            {calibrationStep !== 'idle' && (
              <div className="absolute inset-0 bg-indigo-900/90 backdrop-blur-md flex flex-col items-center justify-center text-white z-20 animate-in fade-in p-12 text-center">
                {calibrationStep === 'instruction' && (
                  <div className="max-w-md space-y-6">
                    <div className="w-20 h-20 bg-white/10 rounded-3xl flex items-center justify-center mx-auto border border-white/20"><ScanEye size={40} className="text-indigo-400" /></div>
                    <h2 className="text-3xl font-black">Clinical Normalization</h2>
                    <p className="text-indigo-100 font-medium">Please stand centered and maintain your most comfortable upright posture to lock your skeletal baseline.</p>
                    <div className="flex gap-3">
                      <button onClick={() => setCalibrationStep('idle')} className="flex-1 py-4 bg-white/10 rounded-2xl font-bold">Cancel</button>
                      <button onClick={() => { setCalibrationStep('preparing'); setCountdown(5); }} className="flex-1 py-4 bg-indigo-500 rounded-2xl font-bold">Start Capture</button>
                    </div>
                  </div>
                )}
                {calibrationStep === 'preparing' && (
                   <><div className="w-32 h-32 rounded-full border-8 border-white/10 flex items-center justify-center mb-8"><span className="text-6xl font-black">{countdown}</span></div><h2 className="text-3xl font-black mb-2 text-indigo-100">Analyzing Body Vectors...</h2></>
                )}
                {calibrationStep === 'complete' && (
                  <div className="flex flex-col items-center gap-4"><div className="w-24 h-24 bg-emerald-500 rounded-full flex items-center justify-center"><CheckCircle2 size={48} /></div><p className="font-black text-3xl">Baseline Locked</p></div>
                )}
              </div>
            )}

            {!isActive && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-white space-y-4">
                <div className="w-20 h-20 bg-white/10 backdrop-blur-md rounded-3xl flex items-center justify-center text-slate-400"><CameraOff size={40} /></div>
                <div className="text-center px-8">
                  <p className="font-black text-xl mb-1">Optical Engine Ready</p>
                  <p className="text-slate-400 text-sm font-medium">Initiate camera feed for spinal curvature tracking.</p>
                </div>
              </div>
            )}

            <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-4 group-hover:scale-105 transition-transform z-10">
              <button onClick={toggleCamera} className={`flex items-center gap-3 px-8 py-4 rounded-2xl font-black text-sm uppercase tracking-widest transition-all ${isActive ? 'bg-white/10 backdrop-blur-md text-white border border-white/20 hover:bg-white/20' : 'bg-indigo-600 text-white shadow-xl shadow-indigo-500/20'}`}>
                {isActive ? <><Square size={18} /> Stop Session</> : <><Play size={18} /> Start Monitoring</>}
              </button>
              {isActive && (
                <div className="flex gap-2">
                  <button onClick={() => setCalibrationStep('instruction')} disabled={calibrationStep !== 'idle'} className="flex items-center gap-3 px-8 py-4 bg-indigo-600 text-white rounded-2xl font-black text-sm uppercase tracking-widest shadow-lg shadow-indigo-500/30">
                    <Target size={18} /> {baselineLandmarks ? 'Adjust Base' : 'Set Baseline'}
                  </button>
                  {baselineLandmarks && (
                    <button onClick={() => setBaselineLandmarks(null)} className="p-4 bg-red-500/20 text-red-400 border border-red-500/20 rounded-2xl hover:bg-red-500 hover:text-white transition-all" title="Clear Baseline">
                      <XCircle size={20} />
                    </button>
                  )}
                </div>
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm group">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 group-hover:text-indigo-600 transition-colors">Cobb Angle (AI-Est)</p>
              <p className="text-4xl font-black text-slate-800">{analysis?.estimatedCobbAngle ? `${analysis.estimatedCobbAngle.toFixed(1)}°` : '--°'}</p>
            </div>
            <div className={`p-6 rounded-3xl border shadow-sm transition-all duration-500 ${getSeverityStyles(analysis?.severity as ScoliosisSeverity)}`}>
              <p className="text-[10px] font-black uppercase tracking-widest mb-1 opacity-70">Scoliosis Risk</p>
              <p className="text-3xl font-black">{analysis?.severity || '--'}</p>
            </div>
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm group">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 group-hover:text-indigo-600 transition-colors">Alignment Score</p>
              <p className="text-4xl font-black text-indigo-600">{analysis ? `${Math.round(analysis.alignmentScore)}%` : '--%'}</p>
            </div>
          </div>
        </div>

        {/* ADAPTIVE THERAPEUTICS */}
        <div className="w-full xl:w-96 space-y-6 flex flex-col">
          <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-lg flex flex-col h-[400px]">
             <div className="flex items-center justify-between mb-6">
                <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><Dumbbell size={24} className="text-indigo-600" /> Prescribed Exercises</h3>
                {isAnalyzing && <RefreshCw size={16} className="text-indigo-400 animate-spin" />}
             </div>

             <div className="space-y-4 overflow-y-auto flex-1 pr-2 custom-scrollbar">
                {analysis?.exercises ? analysis.exercises.map((ex, i) => (
                  <div key={i} className="bg-slate-50 border border-slate-100 rounded-2xl p-4 group hover:border-indigo-200 transition-all animate-in slide-in-from-right-4">
                    <div className="flex items-start justify-between mb-2">
                       <h4 className="font-bold text-slate-800 text-sm leading-tight group-hover:text-indigo-600 transition-colors">{ex.name}</h4>
                       <span className="text-[10px] font-black uppercase tracking-widest bg-white border border-slate-200 px-2 py-0.5 rounded-lg text-slate-500 whitespace-nowrap">{ex.reps}</span>
                    </div>
                    <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest mb-2 flex items-center gap-1">
                       <Dna size={12} /> {ex.focus}
                    </p>
                    <p className="text-xs text-slate-500 leading-relaxed font-medium">
                       {ex.description}
                    </p>
                  </div>
                )) : (
                  <div className="flex flex-col items-center justify-center py-20 text-slate-300 opacity-60 text-center">
                    <Focus size={32} className="mb-2" />
                    <p className="text-xs font-black uppercase tracking-widest">Awaiting Pose Detection</p>
                    <p className="text-[10px] mt-1 font-medium italic">Corrective plan adapts to your body vectors</p>
                  </div>
                )}
             </div>
          </div>

          <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-lg flex-1 min-h-[300px] flex flex-col overflow-hidden">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><History size={24} className="text-indigo-600" /> Bio-Metric Log</h3>
              <button onClick={() => setSessionEvents([])} className="p-2 hover:bg-slate-100 text-slate-400 rounded-lg transition-colors" title="Clear Log"><Trash2 size={16} /></button>
            </div>

            <div className="space-y-4 overflow-y-auto flex-1 pr-2 custom-scrollbar">
              {sessionEvents.length > 0 ? sessionEvents.map((event) => (
                  <div key={event.id} className={`flex gap-4 p-4 rounded-2xl border animate-in slide-in-from-left-2 ${
                    event.type === 'improvement' ? 'bg-emerald-50 border-emerald-100' :
                    event.type === 'deterioration' ? 'bg-amber-50 border-amber-100' :
                    event.type === 'deviation' ? 'bg-red-50 border-red-100' :
                    'bg-slate-50 border-slate-100'
                  }`}>
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${
                      event.type === 'improvement' ? 'bg-emerald-100 text-emerald-600' : 
                      event.type === 'deterioration' ? 'bg-amber-100 text-amber-600' :
                      event.type === 'deviation' ? 'bg-red-100 text-red-600' :
                      'bg-indigo-100 text-indigo-600'
                    }`}>
                      {event.type === 'improvement' ? <ArrowUpRight size={20} /> : 
                       event.type === 'deterioration' ? <ArrowDownRight size={20} /> :
                       <ActivityIcon size={20} />}
                    </div>
                    <div className="flex-1">
                      <div className="flex justify-between items-start mb-1">
                        <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">{event.time}</p>
                        <span className={`text-[10px] font-black px-1.5 py-0.5 rounded shadow-sm ${event.delta > 0 ? 'bg-emerald-600 text-white' : 'bg-slate-200 text-slate-600'}`}>{event.delta > 0 ? '+' : ''}{event.delta}%</span>
                      </div>
                      <p className="text-sm font-bold text-slate-800 leading-tight">{event.label}</p>
                      <p className="text-[11px] font-medium text-slate-500 mt-1 leading-relaxed italic">"{event.feedback}"</p>
                    </div>
                  </div>
              )) : (
                <div className="flex flex-col items-center justify-center py-10 text-slate-300 opacity-60">
                  <Clock size={32} className="mb-2" />
                  <p className="text-xs font-bold uppercase tracking-widest">No Events Logged</p>
                </div>
              )}
              <div ref={logEndRef} />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

