import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult, ScoliosisSeverity } from "../types";

export async function analyzeXRay(base64Image: string): Promise<AnalysisResult> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'image/png',
            data: base64Image,
          },
        },
        {
          text: `You are a radiologist assistant. Analyze this spinal X-ray for Scoliosis. 
          1. Identify the most significant lateral curvature.
          2. Calculate the simulated Cobb Angle (the angle between the most tilted vertebrae).
          3. Classify severity: <10° is Normal, 10-25° is Mild, 25-45° is Moderate, >45° is Severe.
          4. Provide 3 specific physical therapy exercises suitable for this condition.
          5. Identify the top endplate and bottom endplate of the curve. Provide their coordinates (x1, y1, x2, y2) on a scale of 0-100 where 0,0 is top-left and 100,100 is bottom-right.
          Return ONLY a JSON object.`
        }
      ],
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          cobbAngle: { type: Type.NUMBER, description: 'Calculated Cobb angle in degrees' },
          severity: { type: Type.STRING, enum: ['Normal', 'Mild', 'Moderate', 'Severe'] },
          recommendations: { type: Type.ARRAY, items: { type: Type.STRING } },
          visualObservations: { type: Type.STRING, description: 'Summary of visual findings' },
          markers: {
            type: Type.OBJECT,
            properties: {
              topLine: {
                type: Type.OBJECT,
                properties: {
                  x1: { type: Type.NUMBER }, y1: { type: Type.NUMBER },
                  x2: { type: Type.NUMBER }, y2: { type: Type.NUMBER }
                },
                required: ['x1', 'y1', 'x2', 'y2']
              },
              bottomLine: {
                type: Type.OBJECT,
                properties: {
                  x1: { type: Type.NUMBER }, y1: { type: Type.NUMBER },
                  x2: { type: Type.NUMBER }, y2: { type: Type.NUMBER }
                },
                required: ['x1', 'y1', 'x2', 'y2']
              }
            },
            required: ['topLine', 'bottomLine']
          }
        },
        required: ['cobbAngle', 'severity', 'recommendations', 'visualObservations', 'markers']
      }
    }
  });

  const rawResult = JSON.parse(response.text || '{}');

  return {
    id: Math.random().toString(36).substr(2, 9),
    timestamp: new Date().toISOString(),
    cobbAngle: rawResult.cobbAngle,
    severity: rawResult.severity as ScoliosisSeverity,
    recommendations: rawResult.recommendations,
    visualObservations: rawResult.visualObservations,
    markers: rawResult.markers,
    source: 'XRAY'
  };
}

