import React from 'react';
import { 
  ArrowRight, 
  Users, 
  Activity, 
  AlertTriangle,
  Clock,
  Plus,
  TrendingUp,
  TrendingDown
} from 'lucide-react';
import { PatientRecord, AppView, ScoliosisSeverity, User } from '../types';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface DashboardViewProps {
  records: PatientRecord[];
  setView: (view: AppView) => void;
  user: User;
}

const DashboardView: React.FC<DashboardViewProps> = ({ records, setView, user }) => {
  const stats = [
    { label: 'Total Analyses', value: records.length, icon: Users, color: 'text-indigo-600', bg: 'bg-indigo-100' },
    { label: 'Avg. Cobb Angle', value: records.length ? (records.reduce((a, b) => a + b.cobbAngle, 0) / records.length).toFixed(1) + '°' : '0°', icon: Activity, color: 'text-emerald-600', bg: 'bg-emerald-100' },
    { label: 'Severe Cases', value: records.filter(r => r.severity === ScoliosisSeverity.SEVERE).length, icon: AlertTriangle, color: 'text-amber-600', bg: 'bg-amber-100' },
    { label: 'Live Monitoring', value: records.filter(r => r.source === 'LIVE').length, icon: Clock, color: 'text-blue-600', bg: 'bg-blue-100' },
  ];

  const chartData = [...records].sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime()).map(r => ({
    date: new Date(r.timestamp).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
    angle: r.cobbAngle,
    name: r.patientName
  })).slice(-15);

  const calculateTrend = () => {
    if (records.length < 2) return null;
    const sorted = [...records].sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
    const latest = sorted[0].cobbAngle;
    const previous = sorted[1].cobbAngle;
    const diff = latest - previous;
    return {
      value: Math.abs(diff).toFixed(1),
      isUp: diff > 0
    };
  };

  const trend = calculateTrend();

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      {/* Welcome Section */}
      <div className="flex flex-col md:flex-row items-center justify-between gap-6 bg-gradient-to-br from-indigo-700 to-indigo-900 rounded-[2.5rem] p-8 md:p-12 text-white shadow-2xl shadow-indigo-200 relative overflow-hidden">
        <div className="absolute top-0 right-0 w-96 h-96 bg-white/5 rounded-full -mr-32 -mt-32 blur-3xl"></div>
        <div className="space-y-4 text-center md:text-left relative">
          <div className="inline-block px-4 py-1.5 bg-indigo-500/30 backdrop-blur-md rounded-full text-xs font-bold uppercase tracking-widest border border-white/10 mb-2">
            System Online • {user.department}
          </div>
          <h2 className="text-3xl md:text-4xl font-black tracking-tight">Welcome, {user.name.split(' ')[0]}</h2>
