        <div className="hidden lg:block relative">
          <div className="w-64 h-48 bg-white/10 rounded-3xl backdrop-blur-lg border border-white/20 p-4 transform -rotate-3 hover:rotate-0 transition-transform cursor-pointer overflow-hidden group">
            <div className="h-full w-full border-2 border-dashed border-white/30 rounded-2xl flex items-center justify-center">
              <Activity className="text-white/40 group-hover:scale-110 transition-transform" size={48} />
            </div>
          </div>
          <div className="absolute -bottom-8 -right-8 w-40 h-40 bg-emerald-400 rounded-full blur-[80px] opacity-30"></div>
        </div>
      </div>

