                  <Area type="monotone" dataKey="angle" stroke="#4f46e5" strokeWidth={4} fillOpacity={1} fill="url(#colorAngleDashboard)" animationDuration={1500} />
                </AreaChart>
              </ResponsiveContainer>
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-slate-400">
                <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center mb-4">
                  <Activity size={32} />
                </div>
                <p className="italic font-medium">No diagnostic data available.</p>
                <p className="text-sm">Initiate an AI scan to begin data tracking.</p>
              </div>
            )}
          </div>
        </div>

        {/* Recent Activity */}
        <div className="bg-white p-10 rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col">
          <div className="flex items-center justify-between mb-8">
            <h3 className="text-2xl font-bold text-slate-800 tracking-tight">Recent Reports</h3>
            <button onClick={() => setView('HISTORY')} className="text-indigo-600 text-sm font-bold hover:underline transition-all">View All</button>
          </div>
          <div className="space-y-6 flex-1 overflow-y-auto max-h-[400px] pr-2 custom-scrollbar">
            {records.slice(0, 5).length > 0 ? records.slice(0, 5).map((record, i) => (
              <div key={record.id} className="flex items-center gap-5 group cursor-pointer p-2 hover:bg-slate-50 rounded-2xl transition-all" onClick={() => setView('HISTORY')}>
                <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shrink-0 shadow-sm transition-transform group-hover:scale-105 ${
                  record.severity === ScoliosisSeverity.SEVERE ? 'bg-red-50 text-red-600' :
                  record.severity === ScoliosisSeverity.MODERATE ? 'bg-amber-50 text-amber-600' :
                  'bg-emerald-50 text-emerald-600'
                }`}>
                  <Activity size={24} />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="font-bold text-slate-800 truncate leading-tight">{record.patientName}</p>
                  <div className="flex items-center gap-2 mt-1">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">{record.severity}</span>
                    <span className="w-1 h-1 bg-slate-200 rounded-full"></span>
                    <span className="text-[10px] font-black text-indigo-500 uppercase tracking-tighter">{record.source || 'XRAY'}</span>
                  </div>
                </div>
                <div className="text-[10px] font-black text-slate-300 uppercase vertical-text">
                  {new Date(record.timestamp).toLocaleDateString('en-US', { day: '2-digit', month: 'short' })}
                </div>
              </div>
            )) : (
              <div className="flex flex-col items-center justify-center h-full text-slate-400 text-center py-10">
                <Users size={48} className="opacity-20 mb-4" />
                <p className="italic text-sm font-medium">No recent patient activity found.</p>
              </div>
            )}
          </div>

          <button 
            onClick={() => setView('ANALYSIS')}
            className="mt-8 w-full py-4 bg-indigo-50 text-indigo-700 rounded-2xl font-bold hover:bg-indigo-100 transition-all flex items-center justify-center gap-2"
          >
            Run New Diagnostic
            <ArrowRight size={18} />
          </button>
        </div>
      </div>
    </div>
  );
};

export default DashboardView;

import React, { useState, useMemo } from 'react';
import { 
  Search, 
  Filter, 
  Trash2, 
  ExternalLink,
  Calendar,
  Video,
  FileText,
  X,
  ChevronDown,
  Printer,
  Share2,
  Activity,
  CheckCircle,
  FileDown
} from 'lucide-react';
import { PatientRecord, ScoliosisSeverity, AnalysisSource, LineCoords } from '../types';

interface HistoryViewProps {
  records: PatientRecord[];
  onDelete: (id: string) => void;
}

const HistoryView: React.FC<HistoryViewProps> = ({ records, onDelete }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [severityFilter, setSeverityFilter] = useState<ScoliosisSeverity | 'All'>('All');
  const [modalityFilter, setModalityFilter] = useState<AnalysisSource | 'All'>('All');
  const [dateFilter, setDateFilter] = useState<'All' | 'Today' | 'Week' | 'Month'>('All');
  const [selectedRecord, setSelectedRecord] = useState<PatientRecord | null>(null);

  const filteredRecords = useMemo(() => {
    return records.filter(r => {
      const matchesSearch = r.patientName.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesSeverity = severityFilter === 'All' || r.severity === severityFilter;
      const matchesModality = modalityFilter === 'All' || r.source === modalityFilter || (modalityFilter === 'XRAY' && !r.source);

      let matchesDate = true;
      if (dateFilter !== 'All') {
        const recordDate = new Date(r.timestamp);
        const now = new Date();
        if (dateFilter === 'Today') {
          matchesDate = recordDate.toDateString() === now.toDateString();
        } else if (dateFilter === 'Week') {
          const weekAgo = new Date(now.setDate(now.getDate() - 7));
          matchesDate = recordDate >= weekAgo;
        } else if (dateFilter === 'Month') {
          const monthAgo = new Date(now.setMonth(now.getMonth() - 1));
          matchesDate = recordDate >= monthAgo;
        }
      }

      return matchesSearch && matchesSeverity && matchesModality && matchesDate;
    });
  }, [records, searchTerm, severityFilter, modalityFilter, dateFilter]);

  const getSeverityColor = (severity: ScoliosisSeverity) => {
    switch (severity) {
      case ScoliosisSeverity.NORMAL: return 'text-emerald-600 bg-emerald-50 border-emerald-100';
      case ScoliosisSeverity.MILD: return 'text-blue-600 bg-blue-50 border-blue-100';
      case ScoliosisSeverity.MODERATE: return 'text-amber-600 bg-amber-50 border-amber-100';
      case ScoliosisSeverity.SEVERE: return 'text-red-600 bg-red-50 border-red-100';
    }
  };

  const getSourceStyles = (source?: string) => {
    if (source === 'LIVE') return 'text-indigo-600 bg-indigo-50 border-indigo-100';
    return 'text-blue-600 bg-blue-50 border-blue-100';
  };

  const renderMarker = (line: LineCoords, label: string, color: string) => {
    return (
      <g key={label}>
        <line x1={`${line.x1}%`} y1={`${line.y1}%`} x2={`${line.x2}%`} y2={`${line.y2}%`} stroke={color} strokeWidth="3" strokeDasharray="5 3" />
        <circle cx={`${line.x1}%`} cy={`${line.y1}%`} r="3" fill={color} />
        <circle cx={`${line.x2}%`} cy={`${line.y2}%`} r="3" fill={color} />
      </g>
    );
  };

  return (
    <div className="space-y-6 relative">
      {/* Search and Filters */}
      <div className="bg-white rounded-3xl border border-slate-100 shadow-sm p-6 space-y-4">
        <div className="flex flex-col md:flex-row gap-4 items-center justify-between">
          <div className="relative w-full md:w-96">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder="Search patient name..."
              className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-medium text-slate-700"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="flex flex-wrap items-center gap-3 w-full md:w-auto">
            {/* Severity Filter */}
            <div className="relative group">
              <select 
                value={severityFilter}
                onChange={(e) => setSeverityFilter(e.target.value as any)}
                className="appearance-none bg-white border border-slate-200 rounded-2xl px-5 py-3 pr-10 text-sm font-bold text-slate-600 hover:bg-slate-50 transition-colors focus:outline-none focus:ring-2 focus:ring-indigo-500 cursor-pointer"
              >
                <option value="All">All Severities</option>
                <option value={ScoliosisSeverity.NORMAL}>Normal</option>
                <option value={ScoliosisSeverity.MILD}>Mild</option>
                <option value={ScoliosisSeverity.MODERATE}>Moderate</option>
                <option value={ScoliosisSeverity.SEVERE}>Severe</option>
              </select>
              <ChevronDown size={14} className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
            </div>

            {/* Modality Filter */}
            <div className="relative group">
              <select 
                value={modalityFilter}
                onChange={(e) => setModalityFilter(e.target.value as any)}
                className="appearance-none bg-white border border-slate-200 rounded-2xl px-5 py-3 pr-10 text-sm font-bold text-slate-600 hover:bg-slate-50 transition-colors focus:outline-none focus:ring-2 focus:ring-indigo-500 cursor-pointer"
              >
                <option value="All">All Modalities</option>
                <option value="XRAY">X-Ray Analysis</option>
                <option value="LIVE">Live Monitor</option>
              </select>
              <ChevronDown size={14} className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
            </div>

            {/* Date Filter */}
            <div className="relative group">
              <select 
                value={dateFilter}
                onChange={(e) => setDateFilter(e.target.value as any)}
                className="appearance-none bg-white border border-slate-200 rounded-2xl px-5 py-3 pr-10 text-sm font-bold text-slate-600 hover:bg-slate-50 transition-colors focus:outline-none focus:ring-2 focus:ring-indigo-500 cursor-pointer"
              >
                <option value="All">Any Time</option>
                <option value="Today">Today</option>
                <option value="Week">Last 7 Days</option>
                <option value="Month">Last 30 Days</option>
              </select>
              <Calendar size={14} className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
            </div>
          </div>
        </div>
      </div>

      {/* History Table */}
      <div className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden animate-in fade-in slide-in-from-bottom-2 duration-500">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Patient Identity</th>
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Modality</th>
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Date / Time</th>
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Classification</th>
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Cobb Angle</th>
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredRecords.length > 0 ? filteredRecords.map((record) => (
                <tr key={record.id} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="px-8 py-5">
                    <div className="flex items-center gap-4">
                      <div className={`w-12 h-12 rounded-2xl flex items-center justify-center font-bold text-sm shadow-sm transition-transform group-hover:scale-110 ${record.source === 'LIVE' ? 'bg-indigo-600 text-white' : 'bg-blue-600 text-white'}`}>
                        {record.patientName.charAt(0)}
                      </div>
                      <div>
                        <span className="font-bold text-slate-800 block leading-tight">{record.patientName}</span>
                        <span className="text-[10px] text-slate-400 font-black uppercase tracking-widest">ID: {record.id}</span>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-5">
                    <div className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-xl border text-[10px] font-black uppercase tracking-widest ${getSourceStyles(record.source)}`}>
                      {record.source === 'LIVE' ? <Video size={12} /> : <FileText size={12} />}
                      {record.source || 'XRAY'}
                    </div>
                  </td>
                  <td className="px-8 py-5">
                    <div className="flex flex-col">
                      <span className="text-sm font-bold text-slate-700">{new Date(record.timestamp).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' })}</span>
                      <span className="text-[10px] font-black text-slate-400 uppercase">{new Date(record.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                    </div>
                  </td>
                  <td className="px-8 py-5">
                    <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border ${getSeverityColor(record.severity)}`}>
                      {record.severity}
                    </span>
                  </td>
                  <td className="px-8 py-5 text-center">
                    <span className="font-black text-slate-700 text-lg">
                      {record.cobbAngle ? `${record.cobbAngle.toFixed(1)}°` : 'N/A'}
                    </span>
                  </td>
                  <td className="px-8 py-5 text-right">
                    <div className="flex items-center justify-end gap-2">
                      <button 
                        onClick={() => setSelectedRecord(record)}
                        className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all" 
                        title="View Full Report"
                      >
                        <ExternalLink size={18} />
                      </button>
                      <button 
                        onClick={() => onDelete(record.id)}
                        className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all"
                        title="Delete Record"
                      >
                        <Trash2 size={18} />
                      </button>
                    </div>
                  </td>
                </tr>
              )) : (
                <tr>
                  <td colSpan={6} className="px-8 py-20 text-center">
                    <div className="flex flex-col items-center justify-center text-slate-400">
                      <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center mb-4">
                        <Search size={32} />
                      </div>
                      <p className="font-bold text-slate-800">No diagnostic history matched your filters</p>
                      <p className="text-sm">Try adjusting your filters or search term.</p>
                      <button 
                        onClick={() => { setSearchTerm(''); setSeverityFilter('All'); setModalityFilter('All'); setDateFilter('All'); }}
                        className="mt-4 text-indigo-600 font-bold hover:underline"
                      >
                        Reset all filters
                      </button>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Report Modal */}
      {selectedRecord && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 md:p-8 animate-in fade-in duration-300">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setSelectedRecord(null)}></div>
          <div className="bg-white w-full max-w-5xl max-h-[90vh] rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden flex flex-col animate-in zoom-in-95 duration-300">
            {/* Modal Header */}
            <div className="px-8 py-6 border-b border-slate-100 flex items-center justify-between shrink-0">
              <div className="flex items-center gap-4">
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center font-bold text-white shadow-lg ${selectedRecord.source === 'LIVE' ? 'bg-indigo-600' : 'bg-blue-600'}`}>
                  {selectedRecord.patientName.charAt(0)}
                </div>
                <div>
                  <h3 className="text-xl font-bold text-slate-800">{selectedRecord.patientName}</h3>
                  <div className="flex items-center gap-3">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Diagnostic ID: {selectedRecord.id}</span>
                    <span className="w-1 h-1 bg-slate-200 rounded-full"></span>
                    <span className="text-[10px] font-black text-indigo-500 uppercase tracking-widest">{new Date(selectedRecord.timestamp).toLocaleString()}</span>
                  </div>
                </div>
              </div>
              <button 
                onClick={() => setSelectedRecord(null)}
                className="w-10 h-10 rounded-full hover:bg-slate-100 flex items-center justify-center text-slate-400 transition-colors"
              >
                <X size={24} />
              </button>
            </div>

            {/* Modal Content */}
            <div className="flex-1 overflow-y-auto p-8 custom-scrollbar">
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                {/* Visual Area */}
                <div className="space-y-6">
                  <div className="relative rounded-[2rem] overflow-hidden shadow-xl border border-slate-100 bg-slate-900 group">
                    <img 
                      src={selectedRecord.imageUrl} 
                      className="w-full h-auto object-contain transition-transform duration-500 group-hover:scale-[1.02]" 
                      alt="Clinical Scan" 
                    />
                    {selectedRecord.markers && (
                      <svg className="absolute inset-0 w-full h-full pointer-events-none" viewBox="0 0 100 100" preserveAspectRatio="none">
                        {renderMarker(selectedRecord.markers.topLine, 'Top', '#4f46e5')}
                        {renderMarker(selectedRecord.markers.bottomLine, 'Bottom', '#4f46e5')}
                      </svg>
                    )}
                    <div className="absolute top-6 left-6 flex flex-col gap-2">
                      <div className="bg-black/40 backdrop-blur-md border border-white/20 px-3 py-1.5 rounded-xl text-[10px] font-black text-white uppercase tracking-widest">
                        {selectedRecord.source || 'XRAY'} Modality
                      </div>
                    </div>
                  </div>

                  <div className="bg-slate-50 p-6 rounded-3xl border border-slate-100">
                    <h4 className="font-black text-[10px] text-slate-400 uppercase tracking-widest mb-4">Geometric Findings</h4>
                    <div className="flex items-center justify-between mb-4">
                      <span className="text-sm font-bold text-slate-600">Calculated Cobb Angle</span>
                      <span className="text-2xl font-black text-slate-800">{selectedRecord.cobbAngle.toFixed(1)}°</span>
                    </div>
                    <div className="flex items-center justify-between">
                      <span className="text-sm font-bold text-slate-600">Severity Class</span>
                      <span className={`px-4 py-1.5 rounded-xl border text-[10px] font-black uppercase tracking-widest ${getSeverityColor(selectedRecord.severity)}`}>
                        {selectedRecord.severity}
                      </span>
                    </div>
                  </div>
                </div>

                {/* Narrative Area */}
                <div className="space-y-8">
                  <div className="space-y-4">
                    <h4 className="text-sm font-black text-slate-800 flex items-center gap-2">
                      <Activity size={18} className="text-indigo-600" />
                      Radiological Interpretation
                    </h4>
                    <div className="bg-white p-6 rounded-3xl border border-slate-100 text-sm text-slate-600 leading-relaxed italic shadow-sm">
                      "{selectedRecord.visualObservations}"
                    </div>
                  </div>

                  <div className="space-y-4">
                    <h4 className="text-sm font-black text-slate-800 flex items-center gap-2">
                      <CheckCircle size={18} className="text-emerald-500" />
                      Prescribed Corrections
                    </h4>
                    <div className="grid grid-cols-1 gap-3">
                      {selectedRecord.recommendations.map((rec, i) => (
                        <div key={i} className="bg-emerald-50/50 border border-emerald-100 p-4 rounded-2xl flex items-center gap-4 transition-all hover:bg-emerald-50">
                          <div className="w-8 h-8 rounded-full bg-emerald-100 text-emerald-600 flex items-center justify-center font-black text-xs shrink-0">
                            {i + 1}
                          </div>
                          <p className="text-sm font-bold text-slate-700">{rec}</p>
                        </div>
                      ))}
                    </div>
                  </div>

                  <div className="flex gap-4 pt-4">
                    <button 
                      onClick={() => window.print()}
                      className="flex-1 py-4 bg-indigo-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest flex items-center justify-center gap-3 shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all"
                    >
                      <Printer size={18} />
                      Export PDF
                    </button>
                    <button className="flex-1 py-4 bg-slate-100 text-slate-600 rounded-2xl font-black text-xs uppercase tracking-widest flex items-center justify-center gap-3 hover:bg-slate-200 transition-all">
                      <Share2 size={18} />
                      Share Case
                    </button>
                  </div>
                </div>
              </div>
            </div>

            {/* Modal Footer */}
            <div className="px-8 py-6 bg-slate-50 border-t border-slate-100 flex items-center justify-between text-[10px] font-black text-slate-400 uppercase tracking-widest">
              <span>Diagnostic System v4.2.0 • HIPAA Compliant</span>
              <span className="flex items-center gap-2">
                <FileDown size={14} className="text-indigo-500" />
                Case Records Secured
              </span>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default HistoryView;

import React, { useEffect, useRef, useState, useMemo } from 'react';
import { 
  Camera, 
  CameraOff, 
  Play, 
  Square, 
  RefreshCw, 
  Activity,
  CheckCircle2,
  ScanEye,
  Target,
  ShieldCheck,
  Dumbbell,
  TrendingUp,
  AlertTriangle,
  ArrowUpRight,
  ArrowDownRight,
  History,
  Clock,
  Waves,
  MoveUp,
  MoveDown,
  Trash2,
  Activity as ActivityIcon,
  XCircle,
  Dna,
  Focus,
  FileDown,
  User,
  CheckCircle,
  Pause,
  X
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";
import { PostureAnalysis, Landmark, ScoliosisSeverity, PatientRecord } from '../types';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceLine } from 'recharts';

type CalibrationStep = 'idle' | 'instruction' | 'preparing' | 'capturing' | 'complete';

interface Exercise {
  name: string;
  focus: string;
  reps: string;
  description: string;
}

interface SessionEvent {
  id: string;
  time: string;
  type: 'improvement' | 'deterioration' | 'deviation' | 'system';
  score: number;
  delta: number;
  label: string;
  feedback: string;
}

interface SessionDataPoint {
  time: string;
  timestamp: number;
  score: number;
  angle: number;
  landmarks?: Landmark[];
  isEvent?: boolean;
}

interface PostureLiveViewProps {
  onSaveReport?: (record: PatientRecord) => void;
}

const PostureLiveView: React.FC<PostureLiveViewProps> = ({ onSaveReport }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const logEndRef = useRef<HTMLDivElement>(null);

  const [isActive, setIsActive] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<PostureAnalysis & { exercises?: Exercise[] } | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [sessionHistory, setSessionHistory] = useState<SessionDataPoint[]>([]);
  const [sessionEvents, setSessionEvents] = useState<SessionEvent[]>([]);
  const [startTime, setStartTime] = useState<number | null>(null);
  const [patientName, setPatientName] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  // Real-time Visual indicators
  const [deltaIndicator, setDeltaIndicator] = useState<{ value: number, type: 'plus' | 'minus' | 'alert' } | null>(null);
  const [triggerRipple, setTriggerRipple] = useState(false);

  // Calibration State
  const [calibrationStep, setCalibrationStep] = useState<CalibrationStep>('idle');
  const [baselineLandmarks, setBaselineLandmarks] = useState<Landmark[] | null>(null);
  const [baselineScore, setBaselineScore] = useState<number | null>(null);
  const [countdown, setCountdown] = useState(0);

  // Auto-scroll log to bottom
  useEffect(() => {
    if (logEndRef.current) {
      logEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [sessionEvents]);

  // Calibration Countdown Logic
  useEffect(() => {
    let timer: number;
    if (calibrationStep === 'preparing' && countdown > 0) {
      timer = window.setInterval(() => {
        setCountdown(prev => prev - 1);
      }, 1000);
    } else if (calibrationStep === 'preparing' && countdown === 0) {
      captureCalibration();
    }
    return () => clearInterval(timer);
  }, [calibrationStep, countdown]);

  const getSeverityStyles = (severity?: ScoliosisSeverity) => {
    switch (severity) {
      case ScoliosisSeverity.NORMAL: return 'bg-emerald-50 text-emerald-700 border-emerald-200';
      case ScoliosisSeverity.MILD: return 'bg-blue-50 text-blue-700 border-blue-200';
      case ScoliosisSeverity.MODERATE: return 'bg-amber-50 text-amber-700 border-amber-200';
      case ScoliosisSeverity.SEVERE: return 'bg-red-50 text-red-700 border-red-200';
      default: return 'bg-slate-50 text-slate-700 border-slate-200';
    }
  };

  const addEvent = (event: Omit<SessionEvent, 'id' | 'time'>) => {
    const newEvent: SessionEvent = {
      ...event,
      id: Math.random().toString(36).substr(2, 9),
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })
    };
    setSessionEvents(prev => [...prev.slice(-49), newEvent]);
  };

  const toggleCamera = async () => {
    if (isActive) {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
      setIsActive(false);
      setIsPaused(false);
      setAnalysis(null);
      setCalibrationStep('idle');
      addEvent({ type: 'system', label: 'Monitoring Stopped', score: 0, delta: 0, feedback: 'User ended monitoring session.' });
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsActive(true);
          setIsPaused(false);
          setStartTime(Date.now());
          setSessionHistory([]);
          setSessionEvents([]);
          setError(null);
          addEvent({ type: 'system', label: 'Monitoring Started', score: 0, delta: 0, feedback: 'Computer vision engine ready.' });
        }
      } catch (err) {
        setError("Camera access required for live monitoring.");
      }
    }
  };

  const saveSessionReport = async () => {
    if (!analysis || !onSaveReport) return;
    if (!patientName.trim()) {
      setError("Please provide a Patient Name to save the session.");
      return;
    }

    setIsSaving(true);
    try {
      const snapshotCanvas = document.createElement('canvas');
      snapshotCanvas.width = 640;
      snapshotCanvas.height = 480;
      const sCtx = snapshotCanvas.getContext('2d');
      if (sCtx && videoRef.current && canvasRef.current) {
        sCtx.drawImage(videoRef.current, 0, 0, 640, 480);
        sCtx.drawImage(canvasRef.current, 0, 0, 640, 480);
      }
      const dataUrl = snapshotCanvas.toDataURL('image/jpeg', 0.8);

      const record: PatientRecord = {
        id: Math.random().toString(36).substr(2, 9),
        patientName: patientName,
        timestamp: new Date().toISOString(),
        cobbAngle: analysis.estimatedCobbAngle || 0,
        severity: analysis.severity || ScoliosisSeverity.NORMAL,
        recommendations: analysis.exercises?.map(ex => `${ex.name}: ${ex.description}`) || [],
        visualObservations: `Live stability: ${Math.round(analysis.alignmentScore)}%. ${analysis.feedback}. trend: ${analysis.isDeviating ? 'instability' : 'consistent'}.`,
        imageUrl: dataUrl,
        source: 'LIVE'
      };

      onSaveReport(record);
      setSaveSuccess(true);
      setError(null);
      setPatientName('');
      setTimeout(() => setSaveSuccess(false), 3000);
    } catch (err) {
      setError("Failed to save report.");
    } finally {
      setIsSaving(false);
    }
  };

  const captureCalibration = async () => {
    if (!videoRef.current) return;
    setCalibrationStep('capturing');

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `Locate skeletal landmarks: Head, LeftShoulder, RightShoulder, SpineCenter, LeftHip, RightHip. Return JSON.` }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  },
                  required: ['x', 'y', 'label']
                }
              },
              alignmentScore: { type: Type.NUMBER }
            },
            required: ['landmarks', 'alignmentScore']
          }
        }
      });
      const result = JSON.parse(response.text || '{}');
      if (result.landmarks) {
        setBaselineLandmarks(result.landmarks);
        setBaselineScore(result.alignmentScore);
        setCalibrationStep('complete');
        addEvent({ type: 'system', label: 'Baseline Established', score: result.alignmentScore, delta: 0, feedback: 'Fixed clinical baseline locked.' });
        setTimeout(() => setCalibrationStep('idle'), 2000);
      }
    } catch (err) {
      setCalibrationStep('idle');
      setError("Calibration failed. Please try again.");
    }
  };

  const analyzeFrame = async () => {
    if (!isActive || isPaused || !videoRef.current || isAnalyzing || calibrationStep !== 'idle') return;

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `Analyze posture skeletal landmarks. 
              1. Detect normalized landmarks (Head, LeftShoulder, RightShoulder, SpineCenter, LeftHip, RightHip).
              2. alignmentScore (0-100).
              3. estimatedCobbAngle.
              4. severity classification.
              5. feedback: one sentence clinical advice.
              6. exercises: 3 tailored exercises.
              Return JSON.` 
            }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  }
                }
              },
              alignmentScore: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              isDeviating: { type: Type.BOOLEAN },
              estimatedCobbAngle: { type: Type.NUMBER },
              severity: { type: Type.STRING },
              exercises: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    name: { type: Type.STRING },
                    focus: { type: Type.STRING },
                    reps: { type: Type.STRING },
                    description: { type: Type.STRING }
                  }
                }
              }
            },
            required: ['landmarks', 'alignmentScore', 'feedback', 'isDeviating', 'estimatedCobbAngle', 'severity', 'exercises']
          }
        }
      });

      const result = JSON.parse(response.text || '{}');

      if (sessionHistory.length > 0) {
        const lastScore = sessionHistory[sessionHistory.length - 1].score;
        const delta = result.alignmentScore - lastScore;

        if (Math.abs(delta) > 10) {
          setDeltaIndicator({ value: Math.round(Math.abs(delta)), type: delta > 0 ? 'plus' : 'minus' });
          setTriggerRipple(true);
          addEvent({
            type: delta > 0 ? 'improvement' : 'deterioration',
            label: delta > 0 ? 'Posture Correction' : 'Postural Regression',
            score: Math.round(result.alignmentScore),
            delta: Math.round(delta),
            feedback: result.feedback
          });
        }
        setTimeout(() => { setDeltaIndicator(null); setTriggerRipple(false); }, 3000);
      }

      setAnalysis(result);

      const currentTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
      setSessionHistory(prev => [...prev.slice(-29), {
        time: currentTime,
        timestamp: Date.now(),
        score: result.alignmentScore,
        angle: result.estimatedCobbAngle,
        landmarks: result.landmarks
      }]); 
    } catch (err) {
      console.error(err);
    } finally {
      setIsAnalyzing(false);
    }
  };

  useEffect(() => {
    let interval: number;
    if (isActive && !isPaused && calibrationStep === 'idle') {
      interval = window.setInterval(analyzeFrame, 4000); 
    }
    return () => clearInterval(interval);
  }, [isActive, isPaused, isAnalyzing, calibrationStep, baselineLandmarks]);

  useEffect(() => {
    if (!canvasRef.current || (!analysis && !baselineLandmarks)) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const { width, height } = canvasRef.current;
    ctx.clearRect(0, 0, width, height);

    const getPt = (points: Landmark[], label: string) => 
      points.find(p => p.label.toLowerCase().replace(/[^a-z]/g, '').includes(label.toLowerCase()));

    const drawSkeleton = (points: Landmark[], isBaseline: boolean) => {
      const head = getPt(points, 'head');
      const ls = getPt(points, 'leftshoulder');
      const rs = getPt(points, 'rightshoulder');
      const spine = getPt(points, 'spine');
      const lh = getPt(points, 'lefthip');
      const rh = getPt(points, 'righthip');

      const drawLine = (p1?: Landmark, p2?: Landmark, color: string = 'rgba(255,255,255,0.5)', lineWidth: number = 2) => {
        if (p1 && p2) {
          ctx.beginPath();
          ctx.lineWidth = lineWidth;
          ctx.strokeStyle = color;
          ctx.moveTo(p1.x * width / 100, p1.y * height / 100);
          ctx.lineTo(p2.x * width / 100, p2.y * height / 100);
          ctx.stroke();
        }
      };

      const drawSpineCurve = (h?: Landmark, s?: Landmark, lhp?: Landmark, rhp?: Landmark) => {
        if (!h || !s || !lhp || !rhp) return;
        const midHip = { x: (lhp.x + rhp.x) / 2, y: (lhp.y + rhp.y) / 2 };

        ctx.beginPath();
        ctx.lineWidth = isBaseline ? 1 : 4;
        ctx.strokeStyle = isBaseline ? 'rgba(99, 102, 241, 0.2)' : (analysis?.isDeviating ? '#ef4444' : '#10b981');

        if (!isBaseline) {
          ctx.shadowBlur = 15;
          ctx.shadowColor = analysis?.isDeviating ? '#ef4444' : '#10b981';
        }

        ctx.moveTo(h.x * width / 100, h.y * height / 100);
        ctx.quadraticCurveTo(
          s.x * width / 100, s.y * height / 100,
          midHip.x * width / 100, midHip.y * height / 100
        );
        ctx.stroke();
        ctx.shadowBlur = 0;

        if (!isBaseline && analysis?.estimatedCobbAngle) {
          ctx.fillStyle = 'white';
          ctx.font = 'black 12px Inter';
          ctx.fillText(`${analysis.estimatedCobbAngle.toFixed(1)}°`, s.x * width / 100 + 10, s.y * height / 100);
        }
      };

      if (isBaseline) {
        ctx.setLineDash([5, 5]);
        const baselineColor = 'rgba(99, 102, 241, 0.25)';
        drawSpineCurve(head, spine, lh, rh);
        drawLine(ls, rs, baselineColor, 1);
        drawLine(ls, lh, baselineColor, 1);
        drawLine(rs, rh, baselineColor, 1);
        ctx.setLineDash([]);
      } else {
        const lineColor = analysis?.isDeviating ? 'rgba(239, 68, 68, 0.4)' : 'rgba(16, 185, 129, 0.4)';
        drawSpineCurve(head, spine, lh, rh);
        drawLine(ls, rs, lineColor, 2);
        drawLine(ls, lh, lineColor, 2);
        drawLine(rs, rh, lineColor, 2);

        points.forEach(pt => {
          const x = pt.x * width / 100;
          const y = pt.y * height / 100;
          const pulse = Math.sin(Date.now() / 200) * 2;

          ctx.beginPath();
          ctx.arc(x, y, 6 + pulse, 0, Math.PI * 2);
          ctx.fillStyle = analysis?.isDeviating ? 'rgba(239, 68, 68, 0.2)' : 'rgba(16, 185, 129, 0.2)';
          ctx.fill();

          ctx.beginPath();
          ctx.arc(x, y, 4, 0, Math.PI * 2);
          ctx.fillStyle = analysis?.isDeviating ? '#ef4444' : '#10b981';
          ctx.fill();
          ctx.strokeStyle = 'white';
          ctx.lineWidth = 1.5;
          ctx.stroke();
        });
      }
    };

    const frame = requestAnimationFrame(() => {
      if (baselineLandmarks && isActive) drawSkeleton(baselineLandmarks, true);
      if (analysis?.landmarks && isActive) drawSkeleton(analysis.landmarks, false);
    });

    return () => cancelAnimationFrame(frame);
  }, [analysis, baselineLandmarks, isActive]);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <style>{`
        @keyframes ripple {
          0% { transform: translate(-50%, -50%) scale(0); opacity: 0.8; }
          100% { transform: translate(-50%, -50%) scale(2.5); opacity: 0; }
        }
        @keyframes slide-up {
          0% { transform: translateY(0); opacity: 0; }
          20% { opacity: 1; }
          80% { opacity: 1; }
          100% { transform: translateY(-30px); opacity: 0; }
        }
        .animate-ripple { animation: ripple 1.5s ease-out forwards; }
        .animate-delta { animation: slide-up 3s ease-out forwards; }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }
      `}</style>

      {/* TOP HEADER CONTROLS */}
      <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col md:flex-row items-center justify-between gap-6">
        <div className="flex-1 w-full relative">
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Active Patient Session</label>
          <div className="relative">
            <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
            <input 
              type="text" 
              placeholder="Enter Patient Full Name..." 
              value={patientName}
              onChange={(e) => setPatientName(e.target.value)}
              className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none font-bold text-slate-700"
            />
          </div>
        </div>
        <div className="flex items-center gap-3 shrink-0">
          <button 
            onClick={saveSessionReport}
            disabled={!analysis || isSaving}
            className={`flex items-center gap-2 px-6 py-3 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${
              saveSuccess 
                ? 'bg-emerald-500 text-white' 
                : !analysis || isSaving 
                ? 'bg-slate-100 text-slate-400 cursor-not-allowed' 
                : 'bg-emerald-600 text-white shadow-lg shadow-emerald-500/20 hover:bg-emerald-700'
            }`}
          >
            {saveSuccess ? <CheckCircle size={14} /> : isSaving ? <RefreshCw size={14} className="animate-spin" /> : <FileDown size={14} />}
            {saveSuccess ? 'Session Saved' : 'Archive Session'}
          </button>
        </div>
      </div>

      {error && (
        <div className="bg-red-50 border border-red-100 p-4 rounded-2xl flex items-center gap-3 text-red-600 text-sm font-bold">
          <AlertTriangle size={18} />
          {error}
        </div>
      )}

      <div className="flex flex-col xl:flex-row gap-8">
        <div className="flex-1 flex flex-col gap-6">
          <div className={`bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl relative aspect-video border-4 transition-all duration-700 ${analysis?.alignmentScore && analysis.alignmentScore > 80 ? 'border-emerald-500/30 shadow-emerald-500/5' : analysis?.isDeviating ? 'border-red-500/40 shadow-red-500/10' : 'border-slate-800'}`}>
            <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity duration-700 ${isActive ? 'opacity-100' : 'opacity-20'}`} />

            {triggerRipple && <div className="absolute top-1/2 left-1/2 w-96 h-96 rounded-full border-4 border-white/50 pointer-events-none animate-ripple" />}

            {deltaIndicator && (
               <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 pointer-events-none z-30">
                  <div className={`flex items-center gap-2 px-6 py-3 rounded-full text-2xl font-black shadow-2xl backdrop-blur-md border-2 animate-delta ${
                    deltaIndicator.type === 'plus' ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500' : 'bg-red-500/20 text-red-400 border-red-500'
                  }`}>
                    {deltaIndicator.type === 'plus' ? <MoveUp size={28} /> : <MoveDown size={28} />}
                    {deltaIndicator.type === 'plus' ? '+' : '-'}{deltaIndicator.value}%
                  </div>
               </div>
            )}

            {/* HUD-Style Real-time Graph Overlay */}
            {isActive && sessionHistory.length > 1 && (
              <div className="absolute inset-x-0 bottom-0 h-[30%] pointer-events-none z-0">
                <div className="absolute top-4 left-10 text-[9px] font-black text-indigo-400/40 uppercase tracking-[0.3em] flex items-center gap-2">
                  <TrendingUp size={10} className="text-indigo-500/40" /> Bio-Stability Index (120s window)
                </div>
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={sessionHistory} margin={{ top: 20, right: 0, left: 0, bottom: 0 }}>
                    <defs>
                      <linearGradient id="scoreHUD" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#6366f1" stopOpacity={0.25}/>
                        <stop offset="100%" stopColor="#6366f1" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <ReferenceLine y={85} stroke="rgba(16, 185, 129, 0.2)" strokeDasharray="3 3" />
                    <ReferenceLine y={60} stroke="rgba(239, 68, 68, 0.2)" strokeDasharray="3 3" />
                    <Area 
                      type="monotone" 
                      dataKey="score" 
                      stroke="rgba(99, 102, 241, 0.5)" 
                      strokeWidth={2} 
                      fillOpacity={1} 
                      fill="url(#scoreHUD)" 
                      isAnimationActive={true}
                      animationDuration={1500}
                    />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
            )}

            {isActive && (
              <div className="absolute right-6 top-1/2 -translate-y-1/2 w-2 h-48 bg-white/10 rounded-full border border-white/10 p-0.5">
                <div 
                  className="w-full rounded-full transition-all duration-1000 bg-gradient-to-t from-red-500 via-amber-400 to-emerald-500" 
                  style={{ height: `${analysis?.alignmentScore || 0}%`, marginTop: `${100 - (analysis?.alignmentScore || 0)}%` }}
                />
              </div>
            )}

            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none" width={640} height={480} />

            <div className="absolute inset-8 pointer-events-none border-x border-white/5 opacity-50"></div>
            <div className="absolute inset-8 pointer-events-none border-y border-white/5 opacity-50"></div>

            <div className="absolute top-8 left-8 flex flex-col gap-2">
              <div className="flex items-center gap-3">
                <div className={`w-3 h-3 rounded-full ${isActive && !isPaused ? 'bg-red-500 animate-pulse' : 'bg-slate-600'}`}></div>
                <span className="text-white text-xs font-black tracking-widest uppercase opacity-80">
                  {isPaused ? 'Analysis Suspended' : isActive ? 'Real-Time Bio-Feedback' : 'Optical Engine Idle'}
                </span>
              </div>
              {isPaused && (
                <div className="bg-amber-500/20 border border-amber-500/50 px-3 py-1 rounded-lg flex items-center gap-2">
                   <Pause size={10} className="text-amber-400" />
                   <span className="text-[10px] font-black text-amber-400 uppercase tracking-widest">AI Core Paused</span>
                </div>
              )}
            </div>

            {isActive && (
              <div className="absolute top-8 right-12 flex flex-col items-end gap-2">
                <div className={`bg-black/40 backdrop-blur-md px-4 py-2 rounded-xl border border-white/10 flex items-center gap-3 transition-opacity ${isPaused ? 'opacity-40' : 'opacity-100'}`}>
                  <Waves size={16} className="text-indigo-400" />
                  <p className="text-sm font-black text-white">{Math.round(analysis?.alignmentScore || 0)}% Stability</p>
                </div>
                {baselineLandmarks && (
                   <div className="bg-indigo-600/90 px-3 py-1.5 rounded-lg text-white text-[10px] font-black uppercase tracking-widest shadow-lg flex items-center gap-2">
                      <ShieldCheck size={14} /> Tracking Clinical Base
                   </div>
                )}
              </div>
            )}

            {calibrationStep !== 'idle' && (
              <div className="absolute inset-0 bg-indigo-900/90 backdrop-blur-md flex flex-col items-center justify-center text-white z-20 animate-in fade-in p-12 text-center">
                {(calibrationStep === 'preparing' || calibrationStep === 'capturing') && (
                  <button 
                    onClick={() => setCalibrationStep('idle')}
                    className="absolute top-10 right-10 w-12 h-12 bg-white/10 rounded-full flex items-center justify-center hover:bg-white/20 transition-colors"
                  >
                    <X size={24} />
                  </button>
                )}

                {calibrationStep === 'instruction' && (
                  <div className="max-w-md space-y-6">
                    <div className="w-20 h-20 bg-white/10 rounded-3xl flex items-center justify-center mx-auto border border-white/20"><ScanEye size={40} className="text-indigo-400" /></div>
                    <h2 className="text-3xl font-black">Clinical Normalization</h2>
                    <p className="text-indigo-100 font-medium">Please stand centered and maintain your most comfortable upright posture to lock your skeletal baseline.</p>
                    <div className="flex gap-3">
                      <button onClick={() => setCalibrationStep('idle')} className="flex-1 py-4 bg-white/10 rounded-2xl font-bold">Cancel</button>
                      <button onClick={() => { setCalibrationStep('preparing'); setCountdown(5); }} className="flex-1 py-4 bg-indigo-500 rounded-2xl font-bold">Start Capture</button>
                    </div>
                  </div>
                )}
                {calibrationStep === 'preparing' && (
                   <><div className="w-32 h-32 rounded-full border-8 border-white/10 flex items-center justify-center mb-8"><span className="text-6xl font-black">{countdown}</span></div><h2 className="text-3xl font-black mb-2 text-indigo-100">Analyzing Body Vectors...</h2><p className="text-xs text-indigo-300 font-bold uppercase tracking-widest mt-4">Hold Still for Snapshot</p></>
                )}
                {calibrationStep === 'complete' && (
                  <div className="flex flex-col items-center gap-4"><div className="w-24 h-24 bg-emerald-500 rounded-full flex items-center justify-center"><CheckCircle2 size={48} /></div><p className="font-black text-3xl">Baseline Locked</p></div>
                )}
              </div>
            )}

            {!isActive && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-white space-y-4">
                <div className="w-20 h-20 bg-white/10 backdrop-blur-md rounded-3xl flex items-center justify-center text-slate-400"><CameraOff size={40} /></div>
                <div className="text-center px-8">
                  <p className="font-black text-xl mb-1">Optical Engine Ready</p>
                  <p className="text-slate-400 text-sm font-medium">Initiate camera feed for spinal curvature tracking.</p>
                </div>
              </div>
            )}

            <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-4 group-hover:scale-105 transition-transform z-10">
              <button onClick={toggleCamera} className={`flex items-center gap-3 px-8 py-4 rounded-2xl font-black text-sm uppercase tracking-widest transition-all ${isActive ? 'bg-white/10 backdrop-blur-md text-white border border-white/20 hover:bg-white/20' : 'bg-indigo-600 text-white shadow-xl shadow-indigo-500/20'}`}>
                {isActive ? <><Square size={18} /> Stop Session</> : <><Play size={18} /> Start Monitoring</>}
              </button>

              {isActive && (
                <>
                  <button 
                    onClick={() => setIsPaused(!isPaused)} 
                    className={`flex items-center gap-3 px-8 py-4 rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl transition-all ${isPaused ? 'bg-amber-600 text-white' : 'bg-white/20 backdrop-blur-md text-white border border-white/20'}`}
                  >
                    {isPaused ? <><Play size={18} /> Resume AI</> : <><Pause size={18} /> Pause AI</>}
                  </button>
                  <button onClick={() => setCalibrationStep('instruction')} disabled={calibrationStep !== 'idle'} className="flex items-center gap-3 px-8 py-4 bg-indigo-600 text-white rounded-2xl font-black text-sm uppercase tracking-widest shadow-lg shadow-indigo-500/30">
                    <Target size={18} /> {baselineLandmarks ? 'Adjust Base' : 'Set Baseline'}
                  </button>
                </>
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm group">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 group-hover:text-indigo-600 transition-colors">Cobb Angle (AI-Est)</p>
              <p className={`text-4xl font-black text-slate-800 transition-opacity ${isPaused ? 'opacity-30' : 'opacity-100'}`}>{analysis?.estimatedCobbAngle ? `${analysis.estimatedCobbAngle.toFixed(1)}°` : '--°'}</p>
            </div>
            <div className={`p-6 rounded-3xl border shadow-sm transition-all duration-500 ${isPaused ? 'bg-slate-50 opacity-50' : getSeverityStyles(analysis?.severity as ScoliosisSeverity)}`}>
              <p className="text-[10px] font-black uppercase tracking-widest mb-1 opacity-70">Scoliosis Risk</p>
              <p className="text-3xl font-black">{isPaused ? 'Paused' : (analysis?.severity || '--')}</p>
            </div>
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm group">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 group-hover:text-indigo-600 transition-colors">Stability Score</p>
              <p className={`text-4xl font-black text-indigo-600 transition-opacity ${isPaused ? 'opacity-30' : 'opacity-100'}`}>{analysis ? `${Math.round(analysis.alignmentScore)}%` : '--%'}</p>
            </div>
          </div>
        </div>

        <div className="w-full xl:w-96 space-y-6 flex flex-col">
          <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-lg flex flex-col h-[400px]">
             <div className="flex items-center justify-between mb-6">
                <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><Dumbbell size={24} className="text-indigo-600" /> Prescribed Exercises</h3>
                {isAnalyzing && <RefreshCw size={16} className="text-indigo-400 animate-spin" />}
             </div>

             <div className="space-y-4 overflow-y-auto flex-1 pr-2 custom-scrollbar">
                {analysis?.exercises ? analysis.exercises.map((ex, i) => (
                  <div key={i} className="bg-slate-50 border border-slate-100 rounded-2xl p-4 group hover:border-indigo-200 transition-all animate-in slide-in-from-right-4">
                    <div className="flex items-start justify-between mb-2">
                       <h4 className="font-bold text-slate-800 text-sm leading-tight group-hover:text-indigo-600 transition-colors">{ex.name}</h4>
                       <span className="text-[10px] font-black uppercase tracking-widest bg-white border border-slate-200 px-2 py-0.5 rounded-lg text-slate-500 whitespace-nowrap">{ex.reps}</span>
                    </div>
                    <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest mb-2 flex items-center gap-1">
                       <Dna size={12} /> {ex.focus}
                    </p>
                    <p className="text-xs text-slate-500 leading-relaxed font-medium">
                       {ex.description}
                    </p>
                  </div>
                )) : (
                  <div className="flex flex-col items-center justify-center py-20 text-slate-300 opacity-60 text-center">
                    <Focus size={32} className="mb-2" />
                    <p className="text-xs font-black uppercase tracking-widest">Awaiting Pose Detection</p>
                    <p className="text-[10px] mt-1 font-medium italic">Corrective plan adapts to your body vectors</p>
                  </div>
                )}
             </div>
          </div>

          <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-lg flex-1 min-h-[300px] flex flex-col overflow-hidden">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><History size={24} className="text-indigo-600" /> Bio-Metric Log</h3>
              <button onClick={() => setSessionEvents([])} className="p-2 hover:bg-slate-100 text-slate-400 rounded-lg transition-colors" title="Clear Log"><Trash2 size={16} /></button>
            </div>

            <div className="space-y-4 overflow-y-auto flex-1 pr-2 custom-scrollbar">
              {sessionEvents.length > 0 ? sessionEvents.map((event) => (
                  <div key={event.id} className={`flex gap-4 p-4 rounded-2xl border animate-in slide-in-from-left-2 ${
                    event.type === 'improvement' ? 'bg-emerald-50 border-emerald-100' :
                    event.type === 'deterioration' ? 'bg-amber-50 border-amber-100' :
                    event.type === 'deviation' ? 'bg-red-50 border-red-100' :
                    'bg-slate-50 border-slate-100'
                  }`}>
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${
                      event.type === 'improvement' ? 'bg-emerald-100 text-emerald-600' : 
                      event.type === 'deterioration' ? 'bg-amber-100 text-amber-600' :
                      event.type === 'deviation' ? 'bg-red-100 text-red-600' :
                      'bg-indigo-100 text-indigo-600'
                    }`}>
                      {event.type === 'improvement' ? <ArrowUpRight size={20} /> : 
                       event.type === 'deterioration' ? <ArrowDownRight size={20} /> :
                       <ActivityIcon size={20} />}
                    </div>
                    <div className="flex-1">
                      <div className="flex justify-between items-start mb-1">
                        <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">{event.time}</p>
                        <span className={`text-[10px] font-black px-1.5 py-0.5 rounded shadow-sm ${event.delta > 0 ? 'bg-emerald-600 text-white' : 'bg-slate-200 text-slate-600'}`}>{event.delta > 0 ? '+' : ''}{event.delta}%</span>
                      </div>
                      <p className="text-sm font-bold text-slate-800 leading-tight">{event.label}</p>
                      <p className="text-[11px] font-medium text-slate-500 mt-1 leading-relaxed italic">"{event.feedback}"</p>
                    </div>
                  </div>
              )) : (
                <div className="flex flex-col items-center justify-center py-10 text-slate-300 opacity-60">
                  <Clock size={32} className="mb-2" />
                  <p className="text-xs font-bold uppercase tracking-widest">No Events Logged</p>
                </div>
              )}
              <div ref={logEndRef} />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PostureLiveView;

import React, { useEffect, useRef, useState, useMemo } from 'react';
import { 
  Camera, 
  CameraOff, 
  Play, 
  Square, 
  RefreshCw, 
  Activity,
  CheckCircle2,
  ScanEye,
  Target,
  ShieldCheck,
  Dumbbell,
  TrendingUp,
  AlertTriangle,
  ArrowUpRight,
  ArrowDownRight,
  History,
  Clock,
  Waves,
  MoveUp,
  MoveDown,
  Trash2,
  Activity as ActivityIcon,
  XCircle,
  Dna,
  Focus,
  FileDown,
  User,
  CheckCircle,
  Pause,
  X
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";
import { PostureAnalysis, Landmark, ScoliosisSeverity, PatientRecord } from '../types';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceLine } from 'recharts';

type CalibrationStep = 'idle' | 'instruction' | 'preparing' | 'capturing' | 'complete';

interface Exercise {
  name: string;
  focus: string;
  reps: string;
  description: string;
}

interface SessionEvent {
  id: string;
  time: string;
  type: 'improvement' | 'deterioration' | 'deviation' | 'system';
  score: number;
  delta: number;
  label: string;
  feedback: string;
}

interface SessionDataPoint {
  time: string;
  timestamp: number;
  score: number;
  angle: number;
  landmarks?: Landmark[];
  isEvent?: boolean;
}

interface PostureLiveViewProps {
  onSaveReport?: (record: PatientRecord) => void;
}

const PostureLiveView: React.FC<PostureLiveViewProps> = ({ onSaveReport }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const logEndRef = useRef<HTMLDivElement>(null);

  const [isActive, setIsActive] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<PostureAnalysis & { exercises?: Exercise[] } | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [sessionHistory, setSessionHistory] = useState<SessionDataPoint[]>([]);
  const [sessionEvents, setSessionEvents] = useState<SessionEvent[]>([]);
  const [startTime, setStartTime] = useState<number | null>(null);
  const [patientName, setPatientName] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  // Real-time Visual indicators
  const [deltaIndicator, setDeltaIndicator] = useState<{ value: number, type: 'plus' | 'minus' | 'alert' } | null>(null);
  const [triggerRipple, setTriggerRipple] = useState(false);

  // Calibration State
  const [calibrationStep, setCalibrationStep] = useState<CalibrationStep>('idle');
  const [baselineLandmarks, setBaselineLandmarks] = useState<Landmark[] | null>(null);
  const [baselineScore, setBaselineScore] = useState<number | null>(null);
  const [countdown, setCountdown] = useState(0);

  // Auto-scroll log to bottom
  useEffect(() => {
    if (logEndRef.current) {
      logEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [sessionEvents]);

  // Calibration Countdown Logic
  useEffect(() => {
    let timer: number;
    if (calibrationStep === 'preparing' && countdown > 0) {
      timer = window.setInterval(() => {
        setCountdown(prev => prev - 1);
      }, 1000);
    } else if (calibrationStep === 'preparing' && countdown === 0) {
      captureCalibration();
    }
    return () => clearInterval(timer);
  }, [calibrationStep, countdown]);

  const getSeverityStyles = (severity?: ScoliosisSeverity) => {
    switch (severity) {
      case ScoliosisSeverity.NORMAL: return 'bg-emerald-50 text-emerald-700 border-emerald-200';
      case ScoliosisSeverity.MILD: return 'bg-blue-50 text-blue-700 border-blue-200';
      case ScoliosisSeverity.MODERATE: return 'bg-amber-50 text-amber-700 border-amber-200';
      case ScoliosisSeverity.SEVERE: return 'bg-red-50 text-red-700 border-red-200';
      default: return 'bg-slate-50 text-slate-700 border-slate-200';
    }
  };

  const addEvent = (event: Omit<SessionEvent, 'id' | 'time'>) => {
    const newEvent: SessionEvent = {
      ...event,
      id: Math.random().toString(36).substr(2, 9),
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })
    };
    setSessionEvents(prev => [...prev.slice(-49), newEvent]);
  };

  const toggleCamera = async () => {
    if (isActive) {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
      setIsActive(false);
      setIsPaused(false);
      setAnalysis(null);
      setCalibrationStep('idle');
      addEvent({ type: 'system', label: 'Monitoring Stopped', score: 0, delta: 0, feedback: 'User ended monitoring session.' });
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsActive(true);
          setIsPaused(false);
          setStartTime(Date.now());
          setSessionHistory([]);
          setSessionEvents([]);
          setError(null);
          addEvent({ type: 'system', label: 'Monitoring Started', score: 0, delta: 0, feedback: 'Computer vision engine ready.' });
        }
      } catch (err) {
        setError("Camera access required for live monitoring.");
      }
    }
  };

  const saveSessionReport = async () => {
    if (!analysis || !onSaveReport) return;
    if (!patientName.trim()) {
      setError("Please provide a Patient Name to save the session.");
      return;
    }

    setIsSaving(true);
    try {
      const snapshotCanvas = document.createElement('canvas');
      snapshotCanvas.width = 640;
      snapshotCanvas.height = 480;
      const sCtx = snapshotCanvas.getContext('2d');
      if (sCtx && videoRef.current && canvasRef.current) {
        sCtx.drawImage(videoRef.current, 0, 0, 640, 480);
        sCtx.drawImage(canvasRef.current, 0, 0, 640, 480);
      }
      const dataUrl = snapshotCanvas.toDataURL('image/jpeg', 0.8);

      const record: PatientRecord = {
        id: Math.random().toString(36).substr(2, 9),
        patientName: patientName,
        timestamp: new Date().toISOString(),
        cobbAngle: analysis.estimatedCobbAngle || 0,
        severity: analysis.severity || ScoliosisSeverity.NORMAL,
        recommendations: analysis.exercises?.map(ex => `${ex.name}: ${ex.description}`) || [],
        visualObservations: `Live stability: ${Math.round(analysis.alignmentScore)}%. ${analysis.feedback}. trend: ${analysis.isDeviating ? 'instability' : 'consistent'}.`,
        imageUrl: dataUrl,
        source: 'LIVE'
      };

      onSaveReport(record);
      setSaveSuccess(true);
      setError(null);
      setPatientName('');
      setTimeout(() => setSaveSuccess(false), 3000);
    } catch (err) {
      setError("Failed to save report.");
    } finally {
      setIsSaving(false);
    }
  };

  const captureCalibration = async () => {
    if (!videoRef.current) return;
    setCalibrationStep('capturing');

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `Locate skeletal landmarks: Head, LeftShoulder, RightShoulder, SpineCenter, LeftHip, RightHip. Return JSON.` }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  },
                  required: ['x', 'y', 'label']
                }
              },
              alignmentScore: { type: Type.NUMBER }
            },
            required: ['landmarks', 'alignmentScore']
          }
        }
      });
      const result = JSON.parse(response.text || '{}');
      if (result.landmarks) {
        setBaselineLandmarks(result.landmarks);
        setBaselineScore(result.alignmentScore);
        setCalibrationStep('complete');
        addEvent({ type: 'system', label: 'Baseline Established', score: result.alignmentScore, delta: 0, feedback: 'Fixed clinical baseline locked.' });
        setTimeout(() => setCalibrationStep('idle'), 2000);
      }
    } catch (err) {
      setCalibrationStep('idle');
      setError("Calibration failed. Please try again.");
    }
  };

  const analyzeFrame = async () => {
    if (!isActive || isPaused || !videoRef.current || isAnalyzing || calibrationStep !== 'idle') return;

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `Analyze posture skeletal landmarks. 
              1. Detect normalized landmarks (Head, LeftShoulder, RightShoulder, SpineCenter, LeftHip, RightHip).
              2. alignmentScore (0-100).
              3. estimatedCobbAngle.
              4. severity classification.
              5. feedback: one sentence clinical advice.
              6. exercises: 3 tailored exercises.
              Return JSON.` 
            }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  }
                }
              },
              alignmentScore: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              isDeviating: { type: Type.BOOLEAN },
              estimatedCobbAngle: { type: Type.NUMBER },
              severity: { type: Type.STRING },
              exercises: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    name: { type: Type.STRING },
                    focus: { type: Type.STRING },
                    reps: { type: Type.STRING },
                    description: { type: Type.STRING }
                  }
                }
              }
            },
            required: ['landmarks', 'alignmentScore', 'feedback', 'isDeviating', 'estimatedCobbAngle', 'severity', 'exercises']
          }
        }
      });

      const result = JSON.parse(response.text || '{}');

      if (sessionHistory.length > 0) {
        const lastScore = sessionHistory[sessionHistory.length - 1].score;
        const delta = result.alignmentScore - lastScore;

        if (Math.abs(delta) > 10) {
          setDeltaIndicator({ value: Math.round(Math.abs(delta)), type: delta > 0 ? 'plus' : 'minus' });
          setTriggerRipple(true);
          addEvent({
            type: delta > 0 ? 'improvement' : 'deterioration',
            label: delta > 0 ? 'Posture Correction' : 'Postural Regression',
            score: Math.round(result.alignmentScore),
            delta: Math.round(delta),
            feedback: result.feedback
          });
        }
        setTimeout(() => { setDeltaIndicator(null); setTriggerRipple(false); }, 3000);
      }

      setAnalysis(result);

      const currentTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
      setSessionHistory(prev => [...prev.slice(-29), {
        time: currentTime,
        timestamp: Date.now(),
        score: result.alignmentScore,
        angle: result.estimatedCobbAngle,
        landmarks: result.landmarks
      }]); 
    } catch (err) {
      console.error(err);
    } finally {
      setIsAnalyzing(false);
    }
  };

  useEffect(() => {
    let interval: number;
    if (isActive && !isPaused && calibrationStep === 'idle') {
      interval = window.setInterval(analyzeFrame, 4000); 
    }
    return () => clearInterval(interval);
  }, [isActive, isPaused, isAnalyzing, calibrationStep, baselineLandmarks]);

  useEffect(() => {
    if (!canvasRef.current || (!analysis && !baselineLandmarks)) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const { width, height } = canvasRef.current;
    ctx.clearRect(0, 0, width, height);

    const getPt = (points: Landmark[], label: string) => 
      points.find(p => p.label.toLowerCase().replace(/[^a-z]/g, '').includes(label.toLowerCase()));

    const drawSkeleton = (points: Landmark[], isBaseline: boolean) => {
      const head = getPt(points, 'head');
      const ls = getPt(points, 'leftshoulder');
      const rs = getPt(points, 'rightshoulder');
      const spine = getPt(points, 'spine');
      const lh = getPt(points, 'lefthip');
      const rh = getPt(points, 'righthip');

      const drawLine = (p1?: Landmark, p2?: Landmark, color: string = 'rgba(255,255,255,0.5)', lineWidth: number = 2) => {
        if (p1 && p2) {
          ctx.beginPath();
          ctx.lineWidth = lineWidth;
          ctx.strokeStyle = color;
          ctx.moveTo(p1.x * width / 100, p1.y * height / 100);
          ctx.lineTo(p2.x * width / 100, p2.y * height / 100);
          ctx.stroke();
        }
      };

      const drawSpineCurve = (h?: Landmark, s?: Landmark, lhp?: Landmark, rhp?: Landmark) => {
        if (!h || !s || !lhp || !rhp) return;
        const midHip = { x: (lhp.x + rhp.x) / 2, y: (lhp.y + rhp.y) / 2 };

        ctx.beginPath();
        ctx.lineWidth = isBaseline ? 1 : 4;
        ctx.strokeStyle = isBaseline ? 'rgba(99, 102, 241, 0.2)' : (analysis?.isDeviating ? '#ef4444' : '#10b981');

        if (!isBaseline) {
          ctx.shadowBlur = 15;
          ctx.shadowColor = analysis?.isDeviating ? '#ef4444' : '#10b981';
        }

        ctx.moveTo(h.x * width / 100, h.y * height / 100);
        ctx.quadraticCurveTo(
          s.x * width / 100, s.y * height / 100,
          midHip.x * width / 100, midHip.y * height / 100
        );
        ctx.stroke();
        ctx.shadowBlur = 0;

        if (!isBaseline && analysis?.estimatedCobbAngle) {
          ctx.fillStyle = 'white';
          ctx.font = 'black 12px Inter';
          ctx.fillText(`${analysis.estimatedCobbAngle.toFixed(1)}°`, s.x * width / 100 + 10, s.y * height / 100);
        }
      };

      if (isBaseline) {
        ctx.setLineDash([5, 5]);
        const baselineColor = 'rgba(99, 102, 241, 0.25)';
        drawSpineCurve(head, spine, lh, rh);
        drawLine(ls, rs, baselineColor, 1);
        drawLine(ls, lh, baselineColor, 1);
        drawLine(rs, rh, baselineColor, 1);
        ctx.setLineDash([]);
      } else {
        const lineColor = analysis?.isDeviating ? 'rgba(239, 68, 68, 0.4)' : 'rgba(16, 185, 129, 0.4)';
        drawSpineCurve(head, spine, lh, rh);
        drawLine(ls, rs, lineColor, 2);
        drawLine(ls, lh, lineColor, 2);
        drawLine(rs, rh, lineColor, 2);

        points.forEach(pt => {
          const x = pt.x * width / 100;
          const y = pt.y * height / 100;
          const pulse = Math.sin(Date.now() / 200) * 2;

          ctx.beginPath();
          ctx.arc(x, y, 6 + pulse, 0, Math.PI * 2);
          ctx.fillStyle = analysis?.isDeviating ? 'rgba(239, 68, 68, 0.2)' : 'rgba(16, 185, 129, 0.2)';
          ctx.fill();

          ctx.beginPath();
          ctx.arc(x, y, 4, 0, Math.PI * 2);
          ctx.fillStyle = analysis?.isDeviating ? '#ef4444' : '#10b981';
          ctx.fill();
          ctx.strokeStyle = 'white';
          ctx.lineWidth = 1.5;
          ctx.stroke();
        });
      }
    };

    const frame = requestAnimationFrame(() => {
      if (baselineLandmarks && isActive) drawSkeleton(baselineLandmarks, true);
      if (analysis?.landmarks && isActive) drawSkeleton(analysis.landmarks, false);
    });

    return () => cancelAnimationFrame(frame);
  }, [analysis, baselineLandmarks, isActive]);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <style>{`
        @keyframes ripple {
          0% { transform: translate(-50%, -50%) scale(0); opacity: 0.8; }
          100% { transform: translate(-50%, -50%) scale(2.5); opacity: 0; }
        }
        @keyframes slide-up {
          0% { transform: translateY(0); opacity: 0; }
          20% { opacity: 1; }
          80% { opacity: 1; }
          100% { transform: translateY(-30px); opacity: 0; }
        }
        .animate-ripple { animation: ripple 1.5s ease-out forwards; }
        .animate-delta { animation: slide-up 3s ease-out forwards; }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }
      `}</style>

      {/* TOP HEADER CONTROLS */}
      <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col md:flex-row items-center justify-between gap-6">
        <div className="flex-1 w-full relative">
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Active Patient Session</label>
          <div className="relative">
            <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
            <input 
              type="text" 
              placeholder="Enter Patient Full Name..." 
              value={patientName}
              onChange={(e) => setPatientName(e.target.value)}
              className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none font-bold text-slate-700"
            />
          </div>
        </div>
        <div className="flex items-center gap-3 shrink-0">
          <button 
            onClick={saveSessionReport}
            disabled={!analysis || isSaving}
            className={`flex items-center gap-2 px-6 py-3 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${
              saveSuccess 
                ? 'bg-emerald-500 text-white' 
                : !analysis || isSaving 
                ? 'bg-slate-100 text-slate-400 cursor-not-allowed' 
                : 'bg-emerald-600 text-white shadow-lg shadow-emerald-500/20 hover:bg-emerald-700'
            }`}
          >
            {saveSuccess ? <CheckCircle size={14} /> : isSaving ? <RefreshCw size={14} className="animate-spin" /> : <FileDown size={14} />}
            {saveSuccess ? 'Session Saved' : 'Archive Session'}
          </button>
        </div>
      </div>

      {error && (
        <div className="bg-red-50 border border-red-100 p-4 rounded-2xl flex items-center gap-3 text-red-600 text-sm font-bold">
          <AlertTriangle size={18} />
          {error}
        </div>
      )}

      <div className="flex flex-col xl:flex-row gap-8">
        <div className="flex-1 flex flex-col gap-6">
          <div className={`bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl relative aspect-video border-4 transition-all duration-700 ${analysis?.alignmentScore && analysis.alignmentScore > 80 ? 'border-emerald-500/30 shadow-emerald-500/5' : analysis?.isDeviating ? 'border-red-500/40 shadow-red-500/10' : 'border-slate-800'}`}>
            <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity duration-700 ${isActive ? 'opacity-100' : 'opacity-20'}`} />

            {triggerRipple && <div className="absolute top-1/2 left-1/2 w-96 h-96 rounded-full border-4 border-white/50 pointer-events-none animate-ripple" />}

            {deltaIndicator && (
               <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 pointer-events-none z-30">
                  <div className={`flex items-center gap-2 px-6 py-3 rounded-full text-2xl font-black shadow-2xl backdrop-blur-md border-2 animate-delta ${
                    deltaIndicator.type === 'plus' ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500' : 'bg-red-500/20 text-red-400 border-red-500'
                  }`}>
                    {deltaIndicator.type === 'plus' ? <MoveUp size={28} /> : <MoveDown size={28} />}
                    {deltaIndicator.type === 'plus' ? '+' : '-'}{deltaIndicator.value}%
                  </div>
               </div>
            )}

            {/* HUD-Style Real-time Graph Overlay */}
            {isActive && sessionHistory.length > 1 && (
              <div className="absolute inset-x-0 bottom-0 h-[30%] pointer-events-none z-0">
                <div className="absolute top-4 left-10 text-[9px] font-black text-indigo-400/50 uppercase tracking-[0.3em] flex items-center gap-2">
                  <TrendingUp size={10} className="text-indigo-500/50" /> Bio-Stability Index (120s window)
                </div>
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={sessionHistory} margin={{ top: 20, right: 0, left: 0, bottom: 0 }}>
                    <defs>
                      <linearGradient id="scoreHUD" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#6366f1" stopOpacity={0.3}/>
                        <stop offset="100%" stopColor="#6366f1" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <YAxis domain={[0, 100]} hide />
                    <ReferenceLine y={85} stroke="rgba(16, 185, 129, 0.1)" strokeDasharray="3 3" />
                    <ReferenceLine y={60} stroke="rgba(239, 68, 68, 0.1)" strokeDasharray="3 3" />
                    <Area 
                      type="monotone" 
                      dataKey="score" 
                      stroke="rgba(99, 102, 241, 0.6)" 
                      strokeWidth={1.5} 
                      fillOpacity={1} 
                      fill="url(#scoreHUD)" 
                      isAnimationActive={true}
                      animationDuration={1500}
                    />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
            )}

            {isActive && (
              <div className="absolute right-6 top-1/2 -translate-y-1/2 w-2 h-48 bg-white/10 rounded-full border border-white/10 p-0.5">
                <div 
                  className="w-full rounded-full transition-all duration-1000 bg-gradient-to-t from-red-500 via-amber-400 to-emerald-500" 
                  style={{ height: `${analysis?.alignmentScore || 0}%`, marginTop: `${100 - (analysis?.alignmentScore || 0)}%` }}
                />
              </div>
            )}

            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none" width={640} height={480} />

            <div className="absolute inset-8 pointer-events-none border-x border-white/5 opacity-50"></div>
            <div className="absolute inset-8 pointer-events-none border-y border-white/5 opacity-50"></div>

            <div className="absolute top-8 left-8 flex flex-col gap-2">
              <div className="flex items-center gap-3">
                <div className={`w-3 h-3 rounded-full ${isActive && !isPaused ? 'bg-red-500 animate-pulse' : 'bg-slate-600'}`}></div>
                <span className="text-white text-xs font-black tracking-widest uppercase opacity-80">
                  {isPaused ? 'Analysis Suspended' : isActive ? 'Real-Time Bio-Feedback' : 'Optical Engine Idle'}
                </span>
              </div>
              {isPaused && (
                <div className="bg-amber-500/20 border border-amber-500/50 px-3 py-1 rounded-lg flex items-center gap-2">
                   <Pause size={10} className="text-amber-400" />
                   <span className="text-[10px] font-black text-amber-400 uppercase tracking-widest">AI Core Paused</span>
                </div>
              )}
            </div>

            {isActive && (
              <div className="absolute top-8 right-12 flex flex-col items-end gap-2">
                <div className={`bg-black/40 backdrop-blur-md px-4 py-2 rounded-xl border border-white/10 flex items-center gap-3 transition-opacity ${isPaused ? 'opacity-40' : 'opacity-100'}`}>
                  <Waves size={16} className="text-indigo-400" />
                  <p className="text-sm font-black text-white">{Math.round(analysis?.alignmentScore || 0)}% Stability</p>
                </div>
                {baselineLandmarks && (
                   <div className="bg-indigo-600/90 px-3 py-1.5 rounded-lg text-white text-[10px] font-black uppercase tracking-widest shadow-lg flex items-center gap-2">
                      <ShieldCheck size={14} /> Tracking Clinical Base
                   </div>
                )}
              </div>
            )}

            {calibrationStep !== 'idle' && (
              <div className="absolute inset-0 bg-indigo-900/90 backdrop-blur-md flex flex-col items-center justify-center text-white z-20 animate-in fade-in p-12 text-center">
                {(calibrationStep === 'preparing' || calibrationStep === 'capturing') && (
                  <button 
                    onClick={() => setCalibrationStep('idle')}
                    className="absolute top-10 right-10 w-12 h-12 bg-white/10 rounded-full flex items-center justify-center hover:bg-white/20 transition-colors"
                  >
                    <X size={24} />
                  </button>
                )}

                {calibrationStep === 'instruction' && (
                  <div className="max-w-md space-y-6">
                    <div className="w-20 h-20 bg-white/10 rounded-3xl flex items-center justify-center mx-auto border border-white/20"><ScanEye size={40} className="text-indigo-400" /></div>
                    <h2 className="text-3xl font-black">Clinical Normalization</h2>
                    <p className="text-indigo-100 font-medium">Please stand centered and maintain your most comfortable upright posture to lock your skeletal baseline.</p>
                    <div className="flex gap-3">
                      <button onClick={() => setCalibrationStep('idle')} className="flex-1 py-4 bg-white/10 rounded-2xl font-bold">Cancel</button>
                      <button onClick={() => { setCalibrationStep('preparing'); setCountdown(5); }} className="flex-1 py-4 bg-indigo-500 rounded-2xl font-bold">Start Capture</button>
                    </div>
                  </div>
                )}
                {calibrationStep === 'preparing' && (
                   <><div className="w-32 h-32 rounded-full border-8 border-white/10 flex items-center justify-center mb-8"><span className="text-6xl font-black">{countdown}</span></div><h2 className="text-3xl font-black mb-2 text-indigo-100">Analyzing Body Vectors...</h2><p className="text-xs text-indigo-300 font-bold uppercase tracking-widest mt-4">Hold Still for Snapshot</p></>
                )}
                {calibrationStep === 'complete' && (
                  <div className="flex flex-col items-center gap-4"><div className="w-24 h-24 bg-emerald-500 rounded-full flex items-center justify-center"><CheckCircle2 size={48} /></div><p className="font-black text-3xl">Baseline Locked</p></div>
                )}
              </div>
            )}

            {!isActive && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-white space-y-4">
                <div className="w-20 h-20 bg-white/10 backdrop-blur-md rounded-3xl flex items-center justify-center text-slate-400"><CameraOff size={40} /></div>
                <div className="text-center px-8">
                  <p className="font-black text-xl mb-1">Optical Engine Ready</p>
                  <p className="text-slate-400 text-sm font-medium">Initiate camera feed for spinal curvature tracking.</p>
                </div>
              </div>
            )}

            <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-4 group-hover:scale-105 transition-transform z-10">
              <button onClick={toggleCamera} className={`flex items-center gap-3 px-8 py-4 rounded-2xl font-black text-sm uppercase tracking-widest transition-all ${isActive ? 'bg-white/10 backdrop-blur-md text-white border border-white/20 hover:bg-white/20' : 'bg-indigo-600 text-white shadow-xl shadow-indigo-500/20'}`}>
                {isActive ? <><Square size={18} /> Stop Session</> : <><Play size={18} /> Start Monitoring</>}
              </button>

              {isActive && (
                <>
                  <button 
                    onClick={() => setIsPaused(!isPaused)} 
                    className={`flex items-center gap-3 px-8 py-4 rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl transition-all ${isPaused ? 'bg-amber-600 text-white' : 'bg-white/20 backdrop-blur-md text-white border border-white/20'}`}
                  >
                    {isPaused ? <><Play size={18} /> Resume AI</> : <><Pause size={18} /> Pause AI</>}
