                  <div className="flex flex-col items-center justify-center py-20 text-slate-300 opacity-60 text-center">
                    <Focus size={32} className="mb-2" />
                    <p className="text-xs font-black uppercase tracking-widest">Awaiting Pose Detection</p>
                    <p className="text-[10px] mt-1 font-medium italic">Corrective plan adapts to your body vectors</p>
                  </div>
                )}
             </div>
          </div>

          <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-lg flex-1 min-h-[300px] flex flex-col overflow-hidden">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><History size={24} className="text-indigo-600" /> Bio-Metric Log</h3>
              <button onClick={() => setSessionEvents([])} className="p-2 hover:bg-slate-100 text-slate-400 rounded-lg transition-colors" title="Clear Log"><Trash2 size={16} /></button>
