            <div className="space-y-4 overflow-y-auto flex-1 pr-2 custom-scrollbar">
              {sessionEvents.length > 0 ? sessionEvents.map((event) => (
                  <div key={event.id} className={`flex gap-4 p-4 rounded-2xl border animate-in slide-in-from-left-2 ${
                    event.type === 'improvement' ? 'bg-emerald-50 border-emerald-100' :
                    event.type === 'deterioration' ? 'bg-amber-50 border-amber-100' :
                    event.type === 'deviation' ? 'bg-red-50 border-red-100' :
                    'bg-slate-50 border-slate-100'
