                </div>
              )}
              <div ref={logEndRef} />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PostureLiveView;

import React, { useEffect, useRef, useState } from 'react';
import { 
  Play, 
  Square, 
  RefreshCw, 
  ScanEye,
  Target,
  ShieldCheck,
  Dumbbell,
  TrendingUp,
  AlertTriangle,
  ArrowUpRight,
  ArrowDownRight,
  History,
  Clock,
  Waves,
  MoveUp,
  MoveDown,
  Trash2,
  Activity as ActivityIcon,
  Dna,
  Focus,
  FileDown,
  User,
  CheckCircle,
  Pause,
  X,
  CameraOff,
  Printer,
  Share2,
  LineChart as LineChartIcon,
  Calendar
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";
import { PostureAnalysis, Landmark, ScoliosisSeverity, PatientRecord } from '../types';
import { AreaChart, Area, YAxis, XAxis, ResponsiveContainer, ReferenceLine, Tooltip, CartesianGrid } from 'recharts';

type CalibrationStep = 'idle' | 'instruction' | 'preparing' | 'capturing' | 'complete';

interface Exercise {
  name: string;
  focus: string;
  reps: string;
  description: string;
}

interface SessionEvent {
  id: string;
  time: string;
  type: 'improvement' | 'deterioration' | 'deviation' | 'system';
  score: number;
  delta: number;
  label: string;
  feedback: string;
}

interface SessionDataPoint {
  time: string;
  timestamp: number;
  score: number;
  angle: number;
  landmarks?: Landmark[];
  isEvent?: boolean;
  eventLabel?: string;
}

interface PostureLiveViewProps {
  onSaveReport?: (record: PatientRecord) => void;
}

const PostureLiveView: React.FC<PostureLiveViewProps> = ({ onSaveReport }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const logEndRef = useRef<HTMLDivElement>(null);

  const [isActive, setIsActive] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<PostureAnalysis & { exercises?: Exercise[] } | null>(null);
  const [error, setError] = useState<string | null>(null);

  // sessionHistory is the sliding window for the HUD (last 30 samples)
  const [sessionHistory, setSessionHistory] = useState<SessionDataPoint[]>([]);
  // fullSessionHistory tracks everything for the analytical chart
  const [fullSessionHistory, setFullSessionHistory] = useState<SessionDataPoint[]>([]);
  const [sessionEvents, setSessionEvents] = useState<SessionEvent[]>([]);
  const [patientName, setPatientName] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  // Real-time Visual indicators
  const [deltaIndicator, setDeltaIndicator] = useState<{ value: number, type: 'plus' | 'minus' | 'alert' } | null>(null);
  const [triggerRipple, setTriggerRipple] = useState(false);

  // Calibration State
  const [calibrationStep, setCalibrationStep] = useState<CalibrationStep>('idle');
  const [baselineLandmarks, setBaselineLandmarks] = useState<Landmark[] | null>(null);
  const [countdown, setCountdown] = useState(0);

  // Auto-scroll log to bottom
  useEffect(() => {
    if (logEndRef.current) {
      logEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [sessionEvents]);

  // Calibration Countdown Logic
  useEffect(() => {
    let timer: number;
    if (calibrationStep === 'preparing' && countdown > 0) {
      timer = window.setInterval(() => {
        setCountdown(prev => prev - 1);
      }, 1000);
    } else if (calibrationStep === 'preparing' && countdown === 0) {
      captureCalibration();
    }
    return () => clearInterval(timer);
  }, [calibrationStep, countdown]);

  const getSeverityStyles = (severity?: ScoliosisSeverity) => {
    switch (severity) {
      case ScoliosisSeverity.NORMAL: return 'bg-emerald-50 text-emerald-700 border-emerald-200';
      case ScoliosisSeverity.MILD: return 'bg-blue-50 text-blue-700 border-blue-200';
      case ScoliosisSeverity.MODERATE: return 'bg-amber-50 text-amber-700 border-amber-200';
      case ScoliosisSeverity.SEVERE: return 'bg-red-50 text-red-700 border-red-200';
      default: return 'bg-slate-50 text-slate-700 border-slate-200';
    }
  };

  const addEvent = (event: Omit<SessionEvent, 'id' | 'time'>) => {
    const newEvent: SessionEvent = {
      ...event,
      id: Math.random().toString(36).substr(2, 9),
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })
    };
    setSessionEvents(prev => [...prev.slice(-49), newEvent]);
  };

  const toggleCamera = async () => {
    if (isActive) {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
      setIsActive(false);
      setIsPaused(false);
      setAnalysis(null);
      setCalibrationStep('idle');
      addEvent({ type: 'system', label: 'Session Stopped', score: 0, delta: 0, feedback: 'Analysis and monitoring terminated.' });
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsActive(true);
          setIsPaused(false);
          setSessionHistory([]);
          setFullSessionHistory([]);
          setSessionEvents([]);
          setError(null);
          addEvent({ type: 'system', label: 'Optical Engine Ready', score: 0, delta: 0, feedback: 'Calibration required to lock baseline.' });
        }
      } catch (err) {
        setError("Camera access required for live monitoring.");
      }
    }
  };

  const handlePrint = () => {
    if (!analysis) return;
    window.print();
  };

  const handleShare = async () => {
    if (!analysis) return;
    const summary = `Live Posture Analysis Summary\nPatient: ${patientName || 'Anonymous'}\nStability: ${Math.round(analysis.alignmentScore)}%\nSeverity: ${analysis.severity || 'Normal'}\nCobb Angle: ${analysis.estimatedCobbAngle || 0}°\nClinical Status: Active Monitoring`;

    try {
      if (navigator.share) {
        await navigator.share({
          title: 'ScolioVision Live Report',
          text: summary,
          url: window.location.href
        });
      } else {
        await navigator.clipboard.writeText(summary);
        alert('Report summary copied to clipboard!');
      }
    } catch (err) {
      console.error(err);
    }
  };

  const saveSessionReport = async () => {
    if (!analysis || !onSaveReport) return;
    if (!patientName.trim()) {
      setError("Please provide a Patient Name to save the session.");
      return;
    }

    setIsSaving(true);
    try {
      const snapshotCanvas = document.createElement('canvas');
      snapshotCanvas.width = 640;
      snapshotCanvas.height = 480;
      const sCtx = snapshotCanvas.getContext('2d');
      if (sCtx && videoRef.current && canvasRef.current) {
        sCtx.drawImage(videoRef.current, 0, 0, 640, 480);
        sCtx.drawImage(canvasRef.current, 0, 0, 640, 480);
      }
      const dataUrl = snapshotCanvas.toDataURL('image/jpeg', 0.8);

      const record: PatientRecord = {
        id: Math.random().toString(36).substr(2, 9),
        patientName: patientName,
        timestamp: new Date().toISOString(),
        cobbAngle: analysis.estimatedCobbAngle || 0,
        severity: analysis.severity || ScoliosisSeverity.NORMAL,
        recommendations: analysis.exercises?.map(ex => `${ex.name}: ${ex.description}`) || [],
        visualObservations: `Live stability: ${Math.round(analysis.alignmentScore)}%. ${analysis.feedback}.`,
        imageUrl: dataUrl,
        source: 'LIVE'
      };

      onSaveReport(record);
      setSaveSuccess(true);
      setError(null);
      setPatientName('');
      setTimeout(() => setSaveSuccess(false), 3000);
    } catch (err) {
      setError("Failed to save report.");
    } finally {
      setIsSaving(false);
    }
  };

  const captureCalibration = async () => {
    if (!videoRef.current) return;
    setCalibrationStep('capturing');

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `Locate skeletal landmarks: Head, LeftShoulder, RightShoulder, SpineCenter, LeftHip, RightHip. Return JSON.` }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  },
                  required: ['x', 'y', 'label']
                }
              },
              alignmentScore: { type: Type.NUMBER }
            },
            required: ['landmarks', 'alignmentScore']
          }
        }
      });
      const result = JSON.parse(response.text || '{}');
      if (result.landmarks) {
        setBaselineLandmarks(result.landmarks);
        setCalibrationStep('complete');
        addEvent({ type: 'system', label: 'Baseline Locked', score: result.alignmentScore, delta: 0, feedback: 'Fixed clinical vectors established.' });
        setTimeout(() => setCalibrationStep('idle'), 1500);
      }
    } catch (err) {
      setCalibrationStep('idle');
      setError("Calibration failed. Please retry.");
    }
  };

  const analyzeFrame = async () => {
    if (!isActive || isPaused || !videoRef.current || isAnalyzing || calibrationStep !== 'idle') return;

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `Analyze posture skeletal landmarks for clinical monitoring.
              - Detect Head, LeftShoulder, RightShoulder, SpineCenter, LeftHip, RightHip.
              - alignmentScore (0-100).
              - estimatedCobbAngle.
              - severity classification.
              - feedback (brief clinical advice).
              - 3 specific exercises.
              Return JSON.` 
            }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  }
                }
              },
              alignmentScore: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              isDeviating: { type: Type.BOOLEAN },
              estimatedCobbAngle: { type: Type.NUMBER },
              severity: { type: Type.STRING },
              exercises: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    name: { type: Type.STRING },
                    focus: { type: Type.STRING },
                    reps: { type: Type.STRING },
                    description: { type: Type.STRING }
                  }
                }
              }
            },
            required: ['landmarks', 'alignmentScore', 'feedback', 'isDeviating', 'estimatedCobbAngle', 'severity', 'exercises']
          }
        }
      });

      const result = JSON.parse(response.text || '{}');

      let isEvent = false;
      let eventLabel = '';

      if (sessionHistory.length > 0) {
        const lastScore = sessionHistory[sessionHistory.length - 1].score;
        const delta = result.alignmentScore - lastScore;

        if (Math.abs(delta) > 10) {
          isEvent = true;
          eventLabel = delta > 0 ? 'Improvement' : 'Deterioration';
          setDeltaIndicator({ value: Math.round(Math.abs(delta)), type: delta > 0 ? 'plus' : 'minus' });
          setTriggerRipple(true);
          addEvent({
            type: delta > 0 ? 'improvement' : 'deterioration',
            label: delta > 0 ? 'Posture Corrected' : 'Position Shift Detected',
            score: Math.round(result.alignmentScore),
            delta: Math.round(delta),
            feedback: result.feedback
          });
          setTimeout(() => { setDeltaIndicator(null); setTriggerRipple(false); }, 3000);
        }
      }

      setAnalysis(result);

      const currentTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
      const newDataPoint: SessionDataPoint = {
        time: currentTime,
        timestamp: Date.now(),
        score: result.alignmentScore,
        angle: result.estimatedCobbAngle,
        landmarks: result.landmarks,
        isEvent,
        eventLabel
      };

      setSessionHistory(prev => [...prev.slice(-29), newDataPoint]); 
      setFullSessionHistory(prev => [...prev, newDataPoint]);
    } catch (err) {
      console.error(err);
    } finally {
      setIsAnalyzing(false);
    }
  };

  useEffect(() => {
    let interval: number;
    if (isActive && !isPaused && calibrationStep === 'idle') {
      interval = window.setInterval(analyzeFrame, 4000); 
    }
    return () => clearInterval(interval);
  }, [isActive, isPaused, isAnalyzing, calibrationStep]);

  useEffect(() => {
    if (!canvasRef.current || (!analysis && !baselineLandmarks)) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const { width, height } = canvasRef.current;
    ctx.clearRect(0, 0, width, height);

    const getPt = (points: Landmark[], label: string) => 
      points.find(p => p.label.toLowerCase().replace(/[^a-z]/g, '').includes(label.toLowerCase()));

    const drawSkeleton = (points: Landmark[], isBaseline: boolean) => {
      const head = getPt(points, 'head');
      const ls = getPt(points, 'leftshoulder');
      const rs = getPt(points, 'rightshoulder');
      const spine = getPt(points, 'spine');
      const lh = getPt(points, 'lefthip');
      const rh = getPt(points, 'righthip');

      const drawLine = (p1?: Landmark, p2?: Landmark, color: string = 'rgba(255,255,255,0.5)', lineWidth: number = 2) => {
        if (p1 && p2) {
          ctx.beginPath();
          ctx.lineWidth = lineWidth;
          ctx.strokeStyle = color;
          ctx.moveTo(p1.x * width / 100, p1.y * height / 100);
          ctx.lineTo(p2.x * width / 100, p2.y * height / 100);
          ctx.stroke();
        }
      };

      const drawSpineCurve = (h?: Landmark, s?: Landmark, lhp?: Landmark, rhp?: Landmark) => {
        if (!h || !s || !lhp || !rhp) return;
        const midHip = { x: (lhp.x + rhp.x) / 2, y: (lhp.y + rhp.y) / 2 };

        ctx.beginPath();
        ctx.lineWidth = isBaseline ? 1 : 4;
        ctx.strokeStyle = isBaseline ? 'rgba(99, 102, 241, 0.2)' : (analysis?.isDeviating ? '#ef4444' : '#10b981');

        if (!isBaseline) {
          ctx.shadowBlur = 15;
          ctx.shadowColor = analysis?.isDeviating ? '#ef4444' : '#10b981';
        }

        ctx.moveTo(h.x * width / 100, h.y * height / 100);
        ctx.quadraticCurveTo(
          s.x * width / 100, s.y * height / 100,
          midHip.x * width / 100, midHip.y * height / 100
        );
        ctx.stroke();
        ctx.shadowBlur = 0;
      };

      if (isBaseline) {
        ctx.setLineDash([5, 5]);
        const baselineColor = 'rgba(99, 102, 241, 0.25)';
        drawSpineCurve(head, spine, lh, rh);
        drawLine(ls, rs, baselineColor, 1);
        ctx.setLineDash([]);
      } else {
        const lineColor = analysis?.isDeviating ? 'rgba(239, 68, 68, 0.4)' : 'rgba(16, 185, 129, 0.4)';
        drawSpineCurve(head, spine, lh, rh);
        drawLine(ls, rs, lineColor, 2);

        points.forEach(pt => {
          const x = pt.x * width / 100;
          const y = pt.y * height / 100;
          ctx.beginPath();
          ctx.arc(x, y, 4, 0, Math.PI * 2);
          ctx.fillStyle = analysis?.isDeviating ? '#ef4444' : '#10b981';
          ctx.fill();
          ctx.strokeStyle = 'white';
          ctx.lineWidth = 1.5;
          ctx.stroke();
        });
      }
    };

    const frame = requestAnimationFrame(() => {
      if (baselineLandmarks && isActive) drawSkeleton(baselineLandmarks, true);
      if (analysis?.landmarks && isActive) drawSkeleton(analysis.landmarks, false);
    });

    return () => cancelAnimationFrame(frame);
  }, [analysis, baselineLandmarks, isActive]);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <style>{`
        @keyframes ripple {
          0% { transform: translate(-50%, -50%) scale(0); opacity: 0.8; }
          100% { transform: translate(-50%, -50%) scale(2.5); opacity: 0; }
        }
        @keyframes slide-up {
          0% { transform: translateY(0); opacity: 0; }
          20% { opacity: 1; }
          80% { opacity: 1; }
          100% { transform: translateY(-30px); opacity: 0; }
        }
        @keyframes pulse-live {
          0%, 100% { transform: scale(1); opacity: 1; }
          50% { transform: scale(1.2); opacity: 0.6; }
        }
        @keyframes scanline {
          0% { transform: translateY(-100%); }
          100% { transform: translateY(100%); }
        }
        .animate-ripple { animation: ripple 1.5s ease-out forwards; }
        .animate-delta { animation: slide-up 3s ease-out forwards; }
        .animate-pulse-live { animation: pulse-live 1.5s ease-in-out infinite; }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }
        .hud-overlay {
          background-image: linear-gradient(0deg, transparent 24%, rgba(99, 102, 241, 0.05) 25%, rgba(99, 102, 241, 0.05) 26%, transparent 27%, transparent 74%, rgba(99, 102, 241, 0.05) 75%, rgba(99, 102, 241, 0.05) 76%, transparent 77%, transparent), 
                            linear-gradient(90deg, transparent 24%, rgba(99, 102, 241, 0.05) 25%, rgba(99, 102, 241, 0.05) 26%, transparent 27%, transparent 74%, rgba(99, 102, 241, 0.05) 75%, rgba(99, 102, 241, 0.05) 76%, transparent 77%, transparent);
          background-size: 50px 50px;
        }
      `}</style>

      {/* TOP HEADER CONTROLS */}
      <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col md:flex-row items-center justify-between gap-6">
        <div className="flex-1 w-full relative">
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Active Patient Session</label>
          <div className="relative">
            <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
            <input 
              type="text" 
              placeholder="Enter Patient Full Name..." 
              value={patientName}
              onChange={(e) => setPatientName(e.target.value)}
              className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none font-bold text-slate-700"
            />
          </div>
        </div>
        <div className="flex items-center gap-3 shrink-0">
          <button 
            onClick={handlePrint}
            disabled={!analysis}
            className="p-3 bg-slate-100 text-slate-600 rounded-2xl hover:bg-slate-200 transition-colors disabled:opacity-50"
            title="Print Session Snapshot"
          >
            <Printer size={20} />
          </button>
          <button 
            onClick={handleShare}
            disabled={!analysis}
            className="p-3 bg-slate-100 text-slate-600 rounded-2xl hover:bg-slate-200 transition-colors disabled:opacity-50"
            title="Share Clinical Summary"
          >
            <Share2 size={20} />
          </button>
          <button 
            onClick={saveSessionReport}
            disabled={!analysis || isSaving}
            className={`flex items-center gap-2 px-6 py-3 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${
              saveSuccess 
                ? 'bg-emerald-500 text-white' 
                : !analysis || isSaving 
                ? 'bg-slate-100 text-slate-400 cursor-not-allowed' 
                : 'bg-emerald-600 text-white shadow-lg shadow-emerald-500/20 hover:bg-emerald-700'
            }`}
          >
            {saveSuccess ? <CheckCircle size={14} /> : isSaving ? <RefreshCw size={14} className="animate-spin" /> : <FileDown size={14} />}
            {saveSuccess ? 'Session Saved' : 'Archive Session'}
          </button>
        </div>
      </div>

      {error && (
        <div className="bg-red-50 border border-red-100 p-4 rounded-2xl flex items-center gap-3 text-red-600 text-sm font-bold">
          <AlertTriangle size={18} />
          {error}
        </div>
      )}

      <div className="flex flex-col xl:flex-row gap-8">
        <div className="flex-1 flex flex-col gap-6">
          <div className={`bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl relative aspect-video border-4 transition-all duration-700 ${analysis?.alignmentScore && analysis.alignmentScore > 80 ? 'border-emerald-500/30 shadow-emerald-500/5' : analysis?.isDeviating ? 'border-red-500/40 shadow-red-500/10' : 'border-slate-800'}`}>
            <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity duration-700 ${isActive ? 'opacity-100' : 'opacity-20'}`} />

            {/* HUD Scanline Effect */}
            <div className="absolute inset-0 pointer-events-none opacity-10 bg-gradient-to-b from-transparent via-indigo-500 to-transparent h-2 animate-[scanline_4s_linear_infinite]" />
            <div className="absolute inset-0 hud-overlay pointer-events-none opacity-20" />

            {triggerRipple && <div className="absolute top-1/2 left-1/2 w-96 h-96 rounded-full border-4 border-white/50 pointer-events-none animate-ripple" />}

            {deltaIndicator && (
               <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 pointer-events-none z-30">
                  <div className={`flex items-center gap-2 px-6 py-3 rounded-full text-2xl font-black shadow-2xl backdrop-blur-md border-2 animate-delta ${
                    deltaIndicator.type === 'plus' ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500' : 'bg-red-500/20 text-red-400 border-red-500'
                  }`}>
                    {deltaIndicator.type === 'plus' ? <MoveUp size={28} /> : <MoveDown size={28} />}
                    {deltaIndicator.type === 'plus' ? '+' : '-'}{deltaIndicator.value}%
                  </div>
               </div>
            )}

            {/* HIGH-END HUD GRAPH OVERLAY */}
            {isActive && sessionHistory.length > 1 && (
              <div className="absolute inset-x-0 bottom-0 h-[38%] pointer-events-none z-10 p-6">
                <div className="absolute top-0 left-10 flex flex-col gap-1">
                  <div className="flex items-center gap-3">
                    <div className="flex items-center gap-2 bg-black/30 backdrop-blur-md px-3 py-1 rounded-full border border-white/10">
                      <div className="w-2 h-2 bg-indigo-500 rounded-full animate-pulse-live shadow-[0_0_10px_rgba(99,102,241,0.8)]" />
                      <span className="text-[10px] font-black text-white uppercase tracking-[0.2em]">Bio-Telemetry Active</span>
                    </div>
                  </div>
                  <div className="text-[8px] font-bold text-indigo-400/60 uppercase tracking-widest flex items-center gap-2 mt-1">
                    <TrendingUp size={10} /> 120s Real-time Stability Index
                  </div>
                </div>

                <div className="absolute top-0 right-10 text-right opacity-40">
                   <p className="text-[8px] font-black text-white uppercase tracking-widest">Signal: Synchronized</p>
                   <p className="text-[8px] font-black text-white uppercase tracking-widest">Rate: 0.25 Hz</p>
                </div>

                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={sessionHistory} margin={{ top: 40, right: 0, left: 0, bottom: 0 }}>
                    <defs>
                      <linearGradient id="hudGradient" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#6366f1" stopOpacity={0.5}/>
                        <stop offset="100%" stopColor="#6366f1" stopOpacity={0}/>
                      </linearGradient>
                      <filter id="hudGlow" x="-20%" y="-20%" width="140%" height="140%">
                        <feGaussianBlur stdDeviation="3" result="blur" />
                        <feComposite in="SourceGraphic" in2="blur" operator="over" />
                      </filter>
                    </defs>
                    <YAxis domain={[0, 100]} hide />
                    <XAxis hide />

                    {/* Visual Reference Bands */}
                    <ReferenceLine y={85} stroke="rgba(16, 185, 129, 0.15)" strokeDasharray="3 3" />
                    <ReferenceLine y={50} stroke="rgba(239, 68, 68, 0.15)" strokeDasharray="3 3" />

                    {/* Safe Zone Highlighting */}
                    <Area 
                      type="monotone" 
                      dataKey="score" 
                      stroke="#818cf8" 
                      strokeWidth={3} 
                      fill="url(#hudGradient)" 
                      filter="url(#hudGlow)"
                      isAnimationActive={true}
                      animationDuration={1500}
                    />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
            )}

            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none" width={640} height={480} />

            <div className="absolute top-8 left-8 flex flex-col gap-2">
              <div className="flex items-center gap-3">
                <div className={`w-3 h-3 rounded-full ${isActive && !isPaused ? 'bg-red-500 animate-pulse shadow-[0_0_10px_rgba(239,68,68,0.8)]' : 'bg-slate-600'}`}></div>
                <span className="text-white text-xs font-black tracking-widest uppercase opacity-80 drop-shadow-md">
                  {isPaused ? 'AI Suspended' : isActive ? 'Tracking Active' : 'System Idle'}
                </span>
              </div>
            </div>

            {isActive && (
              <div className="absolute top-8 right-12 flex flex-col items-end gap-2">
                <div className={`bg-black/60 backdrop-blur-xl px-5 py-2.5 rounded-2xl border border-white/20 flex items-center gap-3 transition-all ${isPaused ? 'opacity-40 scale-95' : 'opacity-100 scale-100'} shadow-2xl`}>
                  <Waves size={18} className="text-indigo-400" />
                  <div>
                    <p className="text-[10px] font-black text-white/40 uppercase tracking-widest leading-none mb-1">Live Index</p>
                    <p className="text-lg font-black text-white leading-none">{Math.round(analysis?.alignmentScore || 0)}% Stability</p>
                  </div>
                </div>
                {baselineLandmarks && (
                   <div className="bg-indigo-600/90 backdrop-blur-md px-3 py-1.5 rounded-xl text-white text-[10px] font-black uppercase tracking-widest shadow-lg flex items-center gap-2 border border-white/20">
                      <ShieldCheck size={14} /> Clinical Baseline Active
                   </div>
                )}
              </div>
            )}

            {calibrationStep !== 'idle' && (
              <div className="absolute inset-0 bg-indigo-900/95 backdrop-blur-xl flex flex-col items-center justify-center text-white z-20 animate-in fade-in p-12 text-center">
                {calibrationStep === 'instruction' && (
                  <div className="max-w-md space-y-6">
                    <div className="w-20 h-20 bg-white/10 rounded-3xl flex items-center justify-center mx-auto border border-white/20 shadow-2xl"><ScanEye size={40} className="text-indigo-400" /></div>
                    <h2 className="text-3xl font-black">Clinical Normalization</h2>
                    <p className="text-indigo-100 font-medium">Please stand centered and maintain an upright posture to lock your skeletal baseline for delta tracking.</p>
                    <div className="flex gap-3">
                      <button onClick={() => setCalibrationStep('idle')} className="flex-1 py-4 bg-white/10 rounded-2xl font-bold border border-white/10 hover:bg-white/20 transition-colors">Cancel</button>
                      <button onClick={() => { setCalibrationStep('preparing'); setCountdown(5); }} className="flex-1 py-4 bg-indigo-500 rounded-2xl font-bold shadow-xl shadow-indigo-500/20 hover:bg-indigo-600 transition-colors">Lock Baseline</button>
                    </div>
                  </div>
                )}
                {calibrationStep === 'preparing' && (
                   <div className="flex flex-col items-center">
                      <div className="w-32 h-32 rounded-full border-8 border-white/10 flex items-center justify-center mb-8 relative">
                        <div className="absolute inset-0 rounded-full border-8 border-indigo-400/30 animate-ping" />
                        <span className="text-6xl font-black">{countdown}</span>
                      </div>
                      <h2 className="text-3xl font-black mb-2 text-indigo-100">Analyzing Body Vectors...</h2>
                      <p className="text-xs text-indigo-300 font-bold uppercase tracking-widest mt-4 mb-8">Maintain Stillness</p>
                      <button 
                        onClick={() => setCalibrationStep('idle')}
                        className="px-6 py-3 bg-red-500/20 text-red-400 border border-red-500/50 rounded-xl font-bold hover:bg-red-500/30 transition-all flex items-center gap-2"
                      >
                        <X size={18} /> Cancel Analysis
                      </button>
                   </div>
                )}
                {calibrationStep === 'capturing' && (
                   <div className="flex flex-col items-center gap-6">
                      <div className="relative">
                        <RefreshCw size={64} className="animate-spin text-indigo-400" />
                        <ShieldCheck size={24} className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-white" />
                      </div>
                      <p className="font-black text-3xl">Synchronizing Vectors...</p>
                   </div>
                )}
                {calibrationStep === 'complete' && (
                  <div className="flex flex-col items-center gap-4 animate-in zoom-in duration-300">
                    <div className="w-24 h-24 bg-emerald-500 rounded-full flex items-center justify-center shadow-lg shadow-emerald-500/50">
                      <CheckCircle size={48} />
                    </div>
                    <p className="font-black text-3xl">Baseline Locked</p>
                    <p className="text-emerald-300 text-sm font-bold">Clinical monitoring ready.</p>
                  </div>
                )}
              </div>
            )}

            {!isActive && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-white space-y-4">
                <div className="w-20 h-20 bg-white/10 backdrop-blur-md rounded-3xl flex items-center justify-center text-slate-400 border border-white/10"><CameraOff size={40} /></div>
                <div className="text-center px-8">
                  <p className="font-black text-xl mb-1">Optical Engine Idle</p>
                  <p className="text-slate-400 text-sm font-medium">Initiate monitoring to begin real-time spinal tracking.</p>
                </div>
              </div>
            )}

            <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-4 z-20">
              <button onClick={toggleCamera} className={`flex items-center gap-3 px-8 py-4 rounded-2xl font-black text-sm uppercase tracking-widest transition-all ${isActive ? 'bg-red-600 text-white shadow-xl shadow-red-500/20' : 'bg-indigo-600 text-white shadow-xl shadow-indigo-500/20 hover:bg-indigo-700 hover:-translate-y-0.5'}`}>
                {isActive ? <><Square size={18} /> Stop Session</> : <><Play size={18} /> Start Monitoring</>}
              </button>

              {isActive && (
                <>
                  <button 
                    onClick={() => setIsPaused(!isPaused)} 
                    className={`flex items-center gap-3 px-8 py-4 rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl transition-all ${isPaused ? 'bg-amber-600 text-white shadow-amber-500/20' : 'bg-white/20 backdrop-blur-md text-white border border-white/20 hover:bg-white/30'}`}
                  >
                    {isPaused ? <><Play size={18} /> Resume Tracking</> : <><Pause size={18} /> Stop Analysis</>}
                  </button>
                  <button onClick={() => setCalibrationStep('instruction')} disabled={calibrationStep !== 'idle'} className="flex items-center gap-3 px-8 py-4 bg-indigo-600 text-white rounded-2xl font-black text-sm uppercase tracking-widest shadow-lg shadow-indigo-500/30 hover:bg-indigo-700 transition-colors border border-indigo-500/50">
                    <Target size={18} /> {baselineLandmarks ? 'Adjust Base' : 'Set Baseline'}
                  </button>
                </>
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Cobb Angle (Est)</p>
              <p className={`text-4xl font-black text-slate-800 transition-opacity ${isPaused ? 'opacity-30' : 'opacity-100'}`}>{analysis?.estimatedCobbAngle ? `${analysis.estimatedCobbAngle.toFixed(1)}°` : '--°'}</p>
            </div>
            <div className={`p-6 rounded-3xl border shadow-sm transition-all duration-500 ${isPaused ? 'bg-slate-50 opacity-50' : getSeverityStyles(analysis?.severity as ScoliosisSeverity)}`}>
              <p className="text-[10px] font-black uppercase tracking-widest mb-1 opacity-70">Severity Classification</p>
              <p className="text-3xl font-black">{isPaused ? 'Suspended' : (analysis?.severity || '--')}</p>
            </div>
            <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Alignment Score</p>
              <p className={`text-4xl font-black text-indigo-600 transition-opacity ${isPaused ? 'opacity-30' : 'opacity-100'}`}>{analysis ? `${Math.round(analysis.alignmentScore)}%` : '--%'}</p>
            </div>
          </div>

          {/* Clinical Trend Analysis Section */}
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-lg">
             <div className="flex items-center justify-between mb-8">
                <div>
                  <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><LineChartIcon size={24} className="text-indigo-600" /> Clinical Trend Analysis</h3>
                  <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-1">Full Session Stability Tracking</p>
                </div>
                <div className="flex items-center gap-3 bg-slate-50 px-4 py-2 rounded-xl border border-slate-100">
                  <Calendar size={14} className="text-slate-400" />
                  <span className="text-xs font-bold text-slate-600">{new Date().toLocaleDateString()}</span>
                </div>
             </div>

             <div className="h-[250px] w-full relative">
                {fullSessionHistory.length > 0 ? (
                  <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={fullSessionHistory} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                      <defs>
                        <linearGradient id="colorFullSession" x1="0" y1="0" x2="0" y2="1">
                          <stop offset="5%" stopColor="#6366f1" stopOpacity={0.1}/>
                          <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                        </linearGradient>
                      </defs>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                      <XAxis 
                        dataKey="time" 
                        axisLine={false} 
                        tickLine={false} 
                        tick={{fill: '#94a3b8', fontSize: 9, fontWeight: 700}} 
                        dy={10}
                        interval="preserveStartEnd"
                      />
                      <YAxis 
                        domain={[0, 100]} 
                        axisLine={false} 
                        tickLine={false} 
                        tick={{fill: '#94a3b8', fontSize: 9, fontWeight: 700}} 
                        dx={-10}
                      />
                      <Tooltip 
                        contentStyle={{borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', padding: '12px'}}
                        itemStyle={{fontWeight: '900', color: '#6366f1'}}
                        labelStyle={{fontSize: '10px', fontWeight: '800', marginBottom: '4px', textTransform: 'uppercase'}}
                      />
                      <ReferenceLine y={85} stroke="#10b981" strokeDasharray="5 5" strokeOpacity={0.3} label={{ position: 'right', value: 'OPTIMAL', fill: '#10b981', fontSize: 8, fontWeight: 'bold' }} />
                      <ReferenceLine y={60} stroke="#ef4444" strokeDasharray="5 5" strokeOpacity={0.3} label={{ position: 'right', value: 'AT-RISK', fill: '#ef4444', fontSize: 8, fontWeight: 'bold' }} />

                      <Area 
                        type="monotone" 
                        dataKey="score" 
                        stroke="#6366f1" 
                        strokeWidth={3} 
                        fillOpacity={1} 
                        fill="url(#colorFullSession)" 
                        dot={(props: any) => {
                          const { cx, cy, payload } = props;
                          if (payload.isEvent) {
                            return (
                              <circle 
                                key={payload.timestamp} 
                                cx={cx} 
                                cy={cy} 
                                r={5} 
                                fill={payload.eventLabel === 'Improvement' ? '#10b981' : '#ef4444'} 
                                stroke="white" 
                                strokeWidth={2}
                              />
                            );
                          }
                          return null;
                        }}
                      />
                    </AreaChart>
                  </ResponsiveContainer>
                ) : (
                  <div className="h-full flex flex-col items-center justify-center text-slate-300 border-2 border-dashed border-slate-100 rounded-[2rem]">
                    <ActivityIcon size={32} className="mb-2 opacity-30" />
                    <p className="text-xs font-black uppercase tracking-[0.2em]">Initiate Session to Begin Trend Analytics</p>
                  </div>
                )}
             </div>
          </div>
        </div>

        <div className="w-full xl:w-96 space-y-6 flex flex-col">
          <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-lg flex flex-col h-[400px]">
             <div className="flex items-center justify-between mb-6">
                <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><Dumbbell size={24} className="text-indigo-600" /> Prescribed Exercises</h3>
                {isAnalyzing && <RefreshCw size={16} className="text-indigo-400 animate-spin" />}
             </div>

             <div className="space-y-4 overflow-y-auto flex-1 pr-2 custom-scrollbar">
                {analysis?.exercises ? analysis.exercises.map((ex, i) => (
                  <div key={i} className="bg-slate-50 border border-slate-100 rounded-2xl p-4 group hover:border-indigo-200 transition-all animate-in slide-in-from-right-4">
                    <div className="flex items-start justify-between mb-2">
                       <h4 className="font-bold text-slate-800 text-sm leading-tight group-hover:text-indigo-600 transition-colors">{ex.name}</h4>
                       <span className="text-[10px] font-black uppercase tracking-widest bg-white border border-slate-200 px-2 py-0.5 rounded-lg text-slate-500 whitespace-nowrap">{ex.reps}</span>
                    </div>
                    <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest mb-2 flex items-center gap-1">
                       <Dna size={12} /> {ex.focus}
                    </p>
                    <p className="text-xs text-slate-500 leading-relaxed font-medium">
                       {ex.description}
                    </p>
                  </div>
                )) : (
                  <div className="flex flex-col items-center justify-center py-20 text-slate-300 opacity-60 text-center">
                    <Focus size={32} className="mb-2" />
                    <p className="text-xs font-black uppercase tracking-widest">Awaiting Pose Detection</p>
                  </div>
                )}
             </div>
          </div>

          <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-lg flex-1 min-h-[300px] flex flex-col overflow-hidden">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><History size={24} className="text-indigo-600" /> Bio-Metric Log</h3>
              <button onClick={() => { setSessionEvents([]); setFullSessionHistory([]); setSessionHistory([]); }} className="p-2 hover:bg-slate-100 text-slate-400 rounded-lg transition-colors" title="Clear All History"><Trash2 size={16} /></button>
            </div>

            <div className="space-y-4 overflow-y-auto flex-1 pr-2 custom-scrollbar">
              {sessionEvents.length > 0 ? sessionEvents.map((event) => (
                  <div key={event.id} className={`flex gap-4 p-4 rounded-2xl border animate-in slide-in-from-left-2 ${
                    event.type === 'improvement' ? 'bg-emerald-50 border-emerald-100' :
                    event.type === 'deterioration' ? 'bg-amber-50 border-amber-100' :
                    event.type === 'deviation' ? 'bg-red-50 border-red-100' :
                    'bg-slate-50 border-slate-100'
                  }`}>
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${
                      event.type === 'improvement' ? 'bg-emerald-100 text-emerald-600' : 
                      event.type === 'deterioration' ? 'bg-amber-100 text-amber-600' :
                      event.type === 'deviation' ? 'bg-red-100 text-red-600' :
                      'bg-indigo-100 text-indigo-600'
                    }`}>
                      {event.type === 'improvement' ? <ArrowUpRight size={20} /> : 
                       event.type === 'deterioration' ? <ArrowDownRight size={20} /> :
                       <ActivityIcon size={20} />}
                    </div>
                    <div className="flex-1">
                      <div className="flex justify-between items-start mb-1">
                        <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">{event.time}</p>
                        <span className={`text-[10px] font-black px-1.5 py-0.5 rounded shadow-sm ${event.delta > 0 ? 'bg-emerald-600 text-white' : 'bg-slate-200 text-slate-600'}`}>{event.delta > 0 ? '+' : ''}{event.delta}%</span>
                      </div>
                      <p className="text-sm font-bold text-slate-800 leading-tight">{event.label}</p>
                      <p className="text-[11px] font-medium text-slate-500 mt-1 leading-relaxed italic">"{event.feedback}"</p>
                    </div>
                  </div>
              )) : (
                <div className="flex flex-col items-center justify-center py-10 text-slate-300 opacity-60">
                  <Clock size={32} className="mb-2" />
                  <p className="text-xs font-bold uppercase tracking-widest">No Events Logged</p>
                </div>
              )}
              <div ref={logEndRef} />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PostureLiveView;

import React, { useEffect, useRef, useState } from 'react';
import { 
  Play, 
  Square, 
  RefreshCw, 
  ScanEye,
  Target,
  ShieldCheck,
  Dumbbell,
  TrendingUp,
  AlertTriangle,
  ArrowUpRight,
  ArrowDownRight,
  History,
  Clock,
  Waves,
  MoveUp,
  MoveDown,
  Trash2,
  Activity as ActivityIcon,
  Dna,
  Focus,
  FileDown,
  User,
  CheckCircle,
  Pause,
  X,
  CameraOff,
  Printer,
  Share2,
  LineChart as LineChartIcon,
  Calendar
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";
import { PostureAnalysis, Landmark, ScoliosisSeverity, PatientRecord } from '../types';
import { AreaChart, Area, YAxis, XAxis, ResponsiveContainer, ReferenceLine, Tooltip, CartesianGrid } from 'recharts';

type CalibrationStep = 'idle' | 'instruction' | 'preparing' | 'capturing' | 'complete';

interface Exercise {
  name: string;
  focus: string;
  reps: string;
  description: string;
}

interface SessionEvent {
  id: string;
  time: string;
  type: 'improvement' | 'deterioration' | 'deviation' | 'system';
  score: number;
  delta: number;
  label: string;
  feedback: string;
}

interface SessionDataPoint {
  time: string;
  timestamp: number;
  score: number;
  angle: number;
  landmarks?: Landmark[];
  isEvent?: boolean;
  eventLabel?: string;
}

interface PostureLiveViewProps {
  onSaveReport?: (record: PatientRecord) => void;
}

const PostureLiveView: React.FC<PostureLiveViewProps> = ({ onSaveReport }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const logEndRef = useRef<HTMLDivElement>(null);

  const [isActive, setIsActive] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<PostureAnalysis & { exercises?: Exercise[] } | null>(null);
  const [error, setError] = useState<string | null>(null);

  const [sessionHistory, setSessionHistory] = useState<SessionDataPoint[]>([]);
  const [fullSessionHistory, setFullSessionHistory] = useState<SessionDataPoint[]>([]);
  const [sessionEvents, setSessionEvents] = useState<SessionEvent[]>([]);
  const [patientName, setPatientName] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  const [deltaIndicator, setDeltaIndicator] = useState<{ value: number, type: 'plus' | 'minus' | 'alert' } | null>(null);
  const [triggerRipple, setTriggerRipple] = useState(false);

  const [calibrationStep, setCalibrationStep] = useState<CalibrationStep>('idle');
  const [baselineLandmarks, setBaselineLandmarks] = useState<Landmark[] | null>(null);
  const [countdown, setCountdown] = useState(0);

  useEffect(() => {
    if (logEndRef.current) {
      logEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [sessionEvents]);

  useEffect(() => {
    let timer: number;
    if (calibrationStep === 'preparing' && countdown > 0) {
      timer = window.setInterval(() => {
        setCountdown(prev => prev - 1);
      }, 1000);
    } else if (calibrationStep === 'preparing' && countdown === 0) {
      captureCalibration();
    }
    return () => clearInterval(timer);
  }, [calibrationStep, countdown]);

  const getSeverityStyles = (severity?: ScoliosisSeverity) => {
    switch (severity) {
      case ScoliosisSeverity.NORMAL: return 'bg-emerald-50 text-emerald-700 border-emerald-200';
      case ScoliosisSeverity.MILD: return 'bg-blue-50 text-blue-700 border-blue-200';
      case ScoliosisSeverity.MODERATE: return 'bg-amber-50 text-amber-700 border-amber-200';
      case ScoliosisSeverity.SEVERE: return 'bg-red-50 text-red-700 border-red-200';
      default: return 'bg-slate-50 text-slate-700 border-slate-200';
    }
  };

  const addEvent = (event: Omit<SessionEvent, 'id' | 'time'>) => {
    const newEvent: SessionEvent = {
      ...event,
      id: Math.random().toString(36).substr(2, 9),
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })
    };
    setSessionEvents(prev => [...prev.slice(-49), newEvent]);
  };

  const toggleCamera = async () => {
    if (isActive) {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
      setIsActive(false);
      setIsPaused(false);
      setAnalysis(null);
      setCalibrationStep('idle');
      addEvent({ type: 'system', label: 'Session Stopped', score: 0, delta: 0, feedback: 'Analysis and monitoring terminated.' });
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsActive(true);
          setIsPaused(false);
          setSessionHistory([]);
          setFullSessionHistory([]);
          setSessionEvents([]);
          setError(null);
          addEvent({ type: 'system', label: 'Optical Engine Ready', score: 0, delta: 0, feedback: 'Calibration required to lock baseline.' });
        }
      } catch (err) {
        setError("Camera access required for live monitoring.");
      }
    }
  };

  const handlePrint = () => {
    if (!analysis) return;
    window.print();
  };

  const handleShare = async () => {
    if (!analysis) return;
    const summary = `Live Posture Analysis Summary\nPatient: ${patientName || 'Anonymous'}\nStability: ${Math.round(analysis.alignmentScore)}%\nSeverity: ${analysis.severity || 'Normal'}\nCobb Angle: ${analysis.estimatedCobbAngle || 0}°\nClinical Status: Active Monitoring`;

    try {
      if (navigator.share) {
        await navigator.share({
          title: 'ScolioVision Live Report',
          text: summary,
          url: window.location.href
        });
      } else {
        await navigator.clipboard.writeText(summary);
        alert('Report summary copied to clipboard!');
      }
    } catch (err) {
      console.error(err);
    }
  };

  const saveSessionReport = async () => {
    if (!analysis || !onSaveReport) return;
    if (!patientName.trim()) {
      setError("Please provide a Patient Name to save the session.");
      return;
    }

    setIsSaving(true);
    try {
      const snapshotCanvas = document.createElement('canvas');
      snapshotCanvas.width = 640;
      snapshotCanvas.height = 480;
      const sCtx = snapshotCanvas.getContext('2d');
      if (sCtx && videoRef.current && canvasRef.current) {
        sCtx.drawImage(videoRef.current, 0, 0, 640, 480);
        sCtx.drawImage(canvasRef.current, 0, 0, 640, 480);
      }
      const dataUrl = snapshotCanvas.toDataURL('image/jpeg', 0.8);

      const record: PatientRecord = {
        id: Math.random().toString(36).substr(2, 9),
        patientName: patientName,
        timestamp: new Date().toISOString(),
        cobbAngle: analysis.estimatedCobbAngle || 0,
        severity: analysis.severity || ScoliosisSeverity.NORMAL,
        recommendations: analysis.exercises?.map(ex => `${ex.name}: ${ex.description}`) || [],
        visualObservations: `Live stability: ${Math.round(analysis.alignmentScore)}%. ${analysis.feedback}.`,
        imageUrl: dataUrl,
        source: 'LIVE'
      };

      onSaveReport(record);
      setSaveSuccess(true);
      setError(null);
      setPatientName('');
      setTimeout(() => setSaveSuccess(false), 3000);
    } catch (err) {
      setError("Failed to save report.");
    } finally {
      setIsSaving(false);
    }
  };

  const captureCalibration = async () => {
    if (!videoRef.current) return;
    setCalibrationStep('capturing');

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `Locate skeletal landmarks: Head, LeftShoulder, RightShoulder, SpineCenter, LeftHip, RightHip. Return JSON.` }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  },
                  required: ['x', 'y', 'label']
                }
              },
              alignmentScore: { type: Type.NUMBER }
            },
            required: ['landmarks', 'alignmentScore']
          }
        }
      });
      const result = JSON.parse(response.text || '{}');
      if (result.landmarks) {
        setBaselineLandmarks(result.landmarks);
        setCalibrationStep('complete');
        addEvent({ type: 'system', label: 'Baseline Locked', score: result.alignmentScore, delta: 0, feedback: 'Fixed clinical vectors established.' });
        setTimeout(() => setCalibrationStep('idle'), 1500);
      }
    } catch (err) {
      setCalibrationStep('idle');
      setError("Calibration failed. Please retry.");
    }
  };

  const analyzeFrame = async () => {
    if (!isActive || isPaused || !videoRef.current || isAnalyzing || calibrationStep !== 'idle') return;

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `Analyze posture skeletal landmarks for clinical monitoring.
              - Detect Head, LeftShoulder, RightShoulder, SpineCenter, LeftHip, RightHip.
              - alignmentScore (0-100).
              - estimatedCobbAngle.
              - severity classification.
              - feedback (brief clinical advice).
              - 3 specific exercises.
              Return JSON.` 
            }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  }
                }
              },
              alignmentScore: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              isDeviating: { type: Type.BOOLEAN },
              estimatedCobbAngle: { type: Type.NUMBER },
              severity: { type: Type.STRING },
              exercises: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    name: { type: Type.STRING },
                    focus: { type: Type.STRING },
                    reps: { type: Type.STRING },
                    description: { type: Type.STRING }
                  }
                }
              }
            },
            required: ['landmarks', 'alignmentScore', 'feedback', 'isDeviating', 'estimatedCobbAngle', 'severity', 'exercises']
          }
        }
      });

      const result = JSON.parse(response.text || '{}');

      let isEvent = false;
      let eventLabel = '';

      if (sessionHistory.length > 0) {
        const lastScore = sessionHistory[sessionHistory.length - 1].score;
        const delta = result.alignmentScore - lastScore;

        if (Math.abs(delta) > 10) {
          isEvent = true;
          eventLabel = delta > 0 ? 'Improvement' : 'Deterioration';
          setDeltaIndicator({ value: Math.round(Math.abs(delta)), type: delta > 0 ? 'plus' : 'minus' });
          setTriggerRipple(true);
          addEvent({
            type: delta > 0 ? 'improvement' : 'deterioration',
            label: delta > 0 ? 'Posture Corrected' : 'Position Shift Detected',
            score: Math.round(result.alignmentScore),
            delta: Math.round(delta),
            feedback: result.feedback
          });
          setTimeout(() => { setDeltaIndicator(null); setTriggerRipple(false); }, 3000);
        }
      }

      setAnalysis(result);

      const currentTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
      const newDataPoint: SessionDataPoint = {
        time: currentTime,
        timestamp: Date.now(),
        score: result.alignmentScore,
        angle: result.estimatedCobbAngle,
        landmarks: result.landmarks,
        isEvent,
        eventLabel
      };

      setSessionHistory(prev => [...prev.slice(-29), newDataPoint]); 
      setFullSessionHistory(prev => [...prev, newDataPoint]);
    } catch (err) {
      console.error(err);
    } finally {
      setIsAnalyzing(false);
    }
  };

  useEffect(() => {
    let interval: number;
    if (isActive && !isPaused && calibrationStep === 'idle') {
      interval = window.setInterval(analyzeFrame, 4000); 
    }
    return () => clearInterval(interval);
  }, [isActive, isPaused, isAnalyzing, calibrationStep]);

  useEffect(() => {
    if (!canvasRef.current || (!analysis && !baselineLandmarks)) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const { width, height } = canvasRef.current;
    ctx.clearRect(0, 0, width, height);

    const getPt = (points: Landmark[], label: string) => 
      points.find(p => p.label.toLowerCase().replace(/[^a-z]/g, '').includes(label.toLowerCase()));

    const drawSkeleton = (points: Landmark[], isBaseline: boolean) => {
      const head = getPt(points, 'head');
      const ls = getPt(points, 'leftshoulder');
      const rs = getPt(points, 'rightshoulder');
      const spine = getPt(points, 'spine');
      const lh = getPt(points, 'lefthip');
      const rh = getPt(points, 'righthip');

      const drawLine = (p1?: Landmark, p2?: Landmark, color: string = 'rgba(255,255,255,0.2)', lineWidth: number = 2) => {
        if (p1 && p2) {
          ctx.beginPath();
          ctx.lineWidth = lineWidth;
          ctx.strokeStyle = color;
          ctx.moveTo(p1.x * width / 100, p1.y * height / 100);
          ctx.lineTo(p2.x * width / 100, p2.y * height / 100);
          ctx.stroke();
        }
      };

      const drawSpineCurve = (h?: Landmark, s?: Landmark, lhp?: Landmark, rhp?: Landmark) => {
        if (!h || !s || !lhp || !rhp) return;
        const midHip = { x: (lhp.x + rhp.x) / 2, y: (lhp.y + rhp.y) / 2 };

        ctx.beginPath();
        ctx.lineWidth = isBaseline ? 1 : 4;

        const baseColor = isBaseline ? 'rgba(99, 102, 241, 0.2)' : (analysis?.isDeviating ? '#fb7185' : '#2dd4bf');
        ctx.strokeStyle = baseColor;

        if (!isBaseline) {
          ctx.shadowBlur = 12;
          ctx.shadowColor = analysis?.isDeviating ? '#fb7185' : '#2dd4bf';
        }

        ctx.moveTo(h.x * width / 100, h.y * height / 100);
        ctx.quadraticCurveTo(
          s.x * width / 100, s.y * height / 100,
          midHip.x * width / 100, midHip.y * height / 100
        );
        ctx.stroke();
        ctx.shadowBlur = 0;
      };

      if (isBaseline) {
        ctx.setLineDash([5, 5]);
        const baselineColor = 'rgba(99, 102, 241, 0.25)';
        drawSpineCurve(head, spine, lh, rh);
        drawLine(ls, rs, baselineColor, 1);
        ctx.setLineDash([]);
      } else {
        const themeColor = analysis?.isDeviating ? 'rgba(251, 113, 133, 0.3)' : 'rgba(45, 212, 191, 0.3)';
        const accentColor = analysis?.isDeviating ? '#fb7185' : '#2dd4bf';

        // Detailed skeletal connections
        drawSpineCurve(head, spine, lh, rh);
        drawLine(ls, rs, themeColor, 1.5);
        drawLine(ls, spine, themeColor, 1.5);
        drawLine(rs, spine, themeColor, 1.5);

        const midHip = lh && rh ? { x: (lh.x + rh.x) / 2, y: (lh.y + rh.y) / 2 } : null;
        if (midHip) {
          drawLine(lh, midHip as Landmark, themeColor, 1.5);
          drawLine(rh, midHip as Landmark, themeColor, 1.5);
        }

        points.forEach(pt => {
          const x = pt.x * width / 100;
          const y = pt.y * height / 100;

          // Outer soft glow
          ctx.beginPath();
          ctx.arc(x, y, 6, 0, Math.PI * 2);
          ctx.fillStyle = themeColor;
          ctx.fill();

          // Solid landmark core
          ctx.beginPath();
          ctx.arc(x, y, 3, 0, Math.PI * 2);
          ctx.fillStyle = accentColor;
          ctx.fill();
          ctx.strokeStyle = 'white';
          ctx.lineWidth = 1;
          ctx.stroke();
        });
      }
    };

    const frame = requestAnimationFrame(() => {
      if (baselineLandmarks && isActive) drawSkeleton(baselineLandmarks, true);
      if (analysis?.landmarks && isActive) drawSkeleton(analysis.landmarks, false);
    });

    return () => cancelAnimationFrame(frame);
  }, [analysis, baselineLandmarks, isActive]);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
