                   <p className="text-[8px] font-black text-white uppercase tracking-widest">Rate: 0.25 Hz</p>
                </div>

                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={sessionHistory} margin={{ top: 40, right: 0, left: 0, bottom: 0 }}>
                    <defs>
                      <linearGradient id="hudGradient" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#6366f1" stopOpacity={0.5}/>
                        <stop offset="100%" stopColor="#6366f1" stopOpacity={0}/>
                      </linearGradient>
                      <filter id="hudGlow" x="-20%" y="-20%" width="140%" height="140%">
                        <feGaussianBlur stdDeviation="3" result="blur" />
                        <feComposite in="SourceGraphic" in2="blur" operator="over" />
                      </filter>
                    </defs>
                    <YAxis domain={[0, 100]} hide />
                    <XAxis hide />

                    <ReferenceLine y={85} stroke="rgba(16, 185, 129, 0.15)" strokeDasharray="3 3" />
                    <ReferenceLine y={50} stroke="rgba(239, 68, 68, 0.15)" strokeDasharray="3 3" />

                    <Area 
                      type="monotone" 
                      dataKey="score" 
                      stroke="#818cf8" 
                      strokeWidth={3} 
                      fill="url(#hudGradient)" 
                      filter="url(#hudGlow)"
