            <div className="absolute inset-0 hud-overlay pointer-events-none opacity-20" />

            {/* Metrics HUD Overlay */}
            {isActive && analysis && (
              <div className="absolute inset-x-0 bottom-0 h-1/3 pointer-events-none z-10 p-6 flex items-end justify-between">
                <div className="bg-black/40 backdrop-blur-md px-4 py-2 rounded-xl border border-white/10 flex items-center gap-3">
                  <div className="w-2 h-2 bg-indigo-500 rounded-full animate-pulse shadow-[0_0_10px_rgba(99,102,241,0.8)]" />
                  <span className="text-[10px] font-black text-white uppercase tracking-widest">Live Bio-Telemetry</span>
