  const handleLogin = (userData: User) => {
    setUser(userData);
    localStorage.setItem('scolio_user', JSON.stringify(userData));
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('scolio_user');
  };

  const addRecord = (record: PatientRecord) => {
    const updated = [record, ...records];
    setRecords(updated);
    try {
      localStorage.setItem('scolio_records', JSON.stringify(updated));
    } catch (e) {
      console.error("Failed to save to local storage (quota likely exceeded):", e);
      // If we exceed local storage quota, remove the oldest records
      const trimmed = updated.slice(0, 10);
      setRecords(trimmed);
      localStorage.setItem('scolio_records', JSON.stringify(trimmed));
    }
  };

  const deleteRecord = (id: string) => {
    const updated = records.filter(r => r.id !== id);
    setRecords(updated);
    localStorage.setItem('scolio_records', JSON.stringify(updated));
  };

  const navItems = [
    { id: 'DASHBOARD' as AppView, label: 'Dashboard', icon: LayoutDashboard },
    { id: 'ANALYSIS' as AppView, label: 'AI Analysis', icon: Activity },
    { id: 'POSTURE_LIVE' as AppView, label: 'Live Monitoring', icon: Video },
    { id: 'HISTORY' as AppView, label: 'Patient History', icon: History },
  ];

  if (!user) {
    return <LoginView onLogin={handleLogin} />;
  }

  const renderView = () => {
    switch (currentView) {
      case 'DASHBOARD': return <DashboardView records={records} setView={setCurrentView} user={user} />;
      case 'ANALYSIS': return <AnalysisView onResultSave={addRecord} />;
      case 'POSTURE_LIVE': return <PostureLiveView onSaveReport={addRecord} />;
      case 'HISTORY': return <HistoryView records={records} onDelete={deleteRecord} />;
      case 'ABOUT': return <AboutView />;
      default: return <DashboardView records={records} setView={setCurrentView} user={user} />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row">
      {/* Sidebar - Desktop */}
      <aside className="hidden md:flex w-72 bg-white border-r border-slate-200 flex-col sticky top-0 h-screen shadow-sm">
        <div className="p-6 flex items-center gap-3 border-b border-slate-100">
          <div className="bg-indigo-600 p-2 rounded-xl text-white">
            <ShieldCheck size={28} />
          </div>
          <div>
            <h1 className="font-bold text-slate-800 text-lg leading-tight">ScolioVision</h1>
            <p className="text-indigo-600 text-xs font-semibold tracking-wider uppercase">AI Medical Suite</p>
          </div>
        </div>

        <nav className="flex-1 p-4 space-y-1">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setCurrentView(item.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
                currentView === item.id 
                  ? 'bg-indigo-50 text-indigo-700 shadow-sm font-semibold' 
                  : 'text-slate-500 hover:bg-slate-50 hover:text-slate-700'
              }`}
            >
              <item.icon size={20} />
              {item.label}
            </button>
          ))}
        </nav>

        <div className="p-4 mt-auto border-t border-slate-100">
          <button 
            onClick={handleLogout}
            className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-slate-500 hover:bg-red-50 hover:text-red-600 transition-colors"
          >
            <LogOut size={20} />
            Sign Out
          </button>
        </div>
      </aside>

      {/* Mobile Header */}
      <header className="md:hidden bg-white border-b border-slate-200 px-4 py-3 flex items-center justify-between sticky top-0 z-50">
        <div className="flex items-center gap-2">
          <div className="bg-indigo-600 p-1.5 rounded-lg text-white">
            <ShieldCheck size={20} />
          </div>
          <span className="font-bold text-slate-800">ScolioVision</span>
        </div>
        <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} className="p-2 text-slate-600">
          {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </header>

      {/* Mobile Nav Overlay */}
      {isMobileMenuOpen && (
        <div className="md:hidden fixed inset-0 bg-white z-40 pt-16 flex flex-col">
          <nav className="p-6 space-y-4">
            {navItems.map((item) => (
              <button
                key={item.id}
                onClick={() => {
                  setCurrentView(item.id);
                  setIsMobileMenuOpen(false);
                }}
                className={`w-full flex items-center gap-4 px-4 py-4 rounded-xl text-lg ${
                  currentView === item.id ? 'bg-indigo-50 text-indigo-700 font-bold' : 'text-slate-600 font-medium'
                }`}
              >
                <item.icon size={24} />
                {item.label}
              </button>
            ))}
            <button 
              onClick={handleLogout}
              className="w-full flex items-center gap-4 px-4 py-4 rounded-xl text-lg text-red-600 font-medium"
            >
              <LogOut size={24} />
              Sign Out
            </button>
          </nav>
        </div>
      )}

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto">
        <header className="hidden md:flex bg-white border-b border-slate-200 px-8 py-4 items-center justify-between sticky top-0 z-10">
          <h2 className="text-xl font-bold text-slate-800">
            {navItems.find(n => n.id === currentView)?.label}
          </h2>
          <div className="flex items-center gap-4">
            <button className="p-2 text-slate-400 hover:text-slate-600 relative">
              <Bell size={20} />
              <span className="absolute top-2 right-2 w-2 h-2 bg-red-500 rounded-full border-2 border-white"></span>
            </button>
            <div className="flex items-center gap-3 pl-4 border-l border-slate-200">
              <div className="text-right">
                <p className="text-sm font-bold text-slate-800">{user.name}</p>
