import React, { useEffect, useRef, useState } from 'react';
import { 
  Play, 
  Square, 
  RefreshCw, 
  ShieldCheck, 
  AlertTriangle,
  Waves,
  Pause,
  Target,
  CameraOff,
  User,
  ZapOff
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";
import { PostureAnalysis, Landmark, ScoliosisSeverity, PatientRecord } from '../types';

interface PostureLiveViewProps {
  onSaveReport?: (record: PatientRecord) => void;
}

const PostureLiveView: React.FC<PostureLiveViewProps> = ({ onSaveReport }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isActive, setIsActive] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<PostureAnalysis | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [quotaExhausted, setQuotaExhausted] = useState(false);
  const [hasBaseline, setHasBaseline] = useState(true);

  const toggleMonitoring = async () => {
    if (isActive) {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
      setIsActive(false);
      setIsPaused(false);
      setAnalysis(null);
      setQuotaExhausted(false);
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsActive(true);
          setError(null);
        }
      } catch (err) {
        setError("Camera access is required for real-time monitoring.");
      }
    }
  };

  const analyzeFrame = async () => {
    if (!isActive || isPaused || !videoRef.current || isAnalyzing || quotaExhausted) return;

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `Analyze posture skeletal landmarks for real-time clinical monitoring. Return JSON with landmarks, alignmentScore (0-100), feedback, isDeviating, estimatedCobbAngle, severity.` }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  }
                }
              },
              alignmentScore: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              isDeviating: { type: Type.BOOLEAN },
              estimatedCobbAngle: { type: Type.NUMBER },
              severity: { type: Type.STRING }
            },
            required: ['landmarks', 'alignmentScore', 'feedback', 'isDeviating', 'estimatedCobbAngle', 'severity']
          }
        }
      });

      // Added safe JSON parsing
      try {
        const result = JSON.parse(response.text || '{}');
        setAnalysis(result);
        setQuotaExhausted(false);
      } catch (jsonErr) {
        console.warn("Received malformed JSON from model:", jsonErr);
      }
    } catch (err: any) {
      console.error("Analysis Error:", err);
      // Handle quota issues specifically
      if (err.message?.includes("RESOURCE_EXHAUSTED") || err.status === 429) {
        setQuotaExhausted(true);
        setError("AI Quota Exhausted. Please wait a few moments before the next analysis.");
        // Auto-reset quota status after 30 seconds to allow retrying
        setTimeout(() => {
          setQuotaExhausted(false);
          setError(null);
        }, 30000);
      }
    } finally {
      setIsAnalyzing(false);
    }
  };

  // Replaced setInterval with a safer recursive setTimeout pattern to avoid overlapping calls
  // and handle rate limiting more effectively.
  useEffect(() => {
    let timeoutId: number;

    const poll = async () => {
      if (isActive && !isPaused && !quotaExhausted) {
        await analyzeFrame();
      }
      // Wait longer if quota was recently hit, otherwise wait 4 seconds
      const nextDelay = quotaExhausted ? 15000 : 4000;
      timeoutId = window.setTimeout(poll, nextDelay);
    };

    if (isActive) {
      timeoutId = window.setTimeout(poll, 1000);
    }

    return () => clearTimeout(timeoutId);
  }, [isActive, isPaused, quotaExhausted]);

  useEffect(() => {
    if (!canvasRef.current || !analysis?.landmarks || !isActive) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const { width, height } = canvasRef.current;
    ctx.clearRect(0, 0, width, height);

    const getPt = (label: string) => 
      analysis.landmarks.find(p => p.label.toLowerCase().includes(label.toLowerCase()));

    const scaleX = (x: number) => (x * width) / 100;
    const scaleY = (y: number) => (y * height) / 100;

    const drawBiometricSkeleton = () => {
      const head = getPt('head');
      const spine = getPt('spine');
      const color = analysis.isDeviating ? '#fb7185' : '#2dd4bf';

      const drawBone = (p1: Landmark, p2: Landmark, weight: number) => {
        const x1 = scaleX(p1.x), y1 = scaleY(p1.y);
        const x2 = scaleX(p2.x), y2 = scaleY(p2.y);
        ctx.beginPath();
        ctx.lineWidth = weight;
        ctx.lineCap = 'round';
        ctx.strokeStyle = color;
        ctx.globalAlpha = 0.5;
        ctx.moveTo(x1, y1);
        ctx.lineTo(x2, y2);
        ctx.stroke();
        ctx.globalAlpha = 1.0;
      };

      if (head && spine) {
        drawBone(head, spine, 6);
        [head, spine].forEach(j => {
          ctx.beginPath();
          ctx.arc(scaleX(j.x), scaleY(j.y), 5, 0, Math.PI * 2);
          ctx.fillStyle = color;
          ctx.fill();
        });
      }
    };

    const frame = requestAnimationFrame(drawBiometricSkeleton);
    return () => cancelAnimationFrame(frame);
  }, [analysis, isActive]);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <style>{`
        @keyframes scanline { 0% { transform: translateY(-100%); } 100% { transform: translateY(100%); } }
        .hud-overlay {
          background-image: linear-gradient(0deg, transparent 24%, rgba(99, 102, 241, 0.05) 25%, rgba(99, 102, 241, 0.05) 26%, transparent 27%, transparent 74%, rgba(99, 102, 241, 0.05) 75%, rgba(99, 102, 241, 0.05) 76%, transparent 77%, transparent), 
                            linear-gradient(90deg, transparent 24%, rgba(99, 102, 241, 0.05) 25%, rgba(99, 102, 241, 0.05) 26%, transparent 27%, transparent 74%, rgba(99, 102, 241, 0.05) 75%, rgba(99, 102, 241, 0.05) 76%, transparent 77%, transparent);
          background-size: 40px 40px;
        }
      `}</style>

      {error && (
        <div className={`p-4 rounded-2xl flex items-center gap-3 font-bold text-sm border ${
          quotaExhausted ? 'bg-amber-50 border-amber-200 text-amber-700' : 'bg-red-50 border-red-100 text-red-600'
        }`}>
          {quotaExhausted ? <ZapOff size={18} /> : <AlertTriangle size={18} />}
          {error}
        </div>
      )}

      {/* Main Monitoring Screen Area */}
      <div className="relative bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl aspect-video border-[6px] border-slate-800">
        <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity duration-700 ${isActive ? 'opacity-100' : 'opacity-20'}`} />

        <div className="absolute inset-0 pointer-events-none opacity-10 bg-gradient-to-b from-transparent via-indigo-500 to-transparent h-2 animate-[scanline_4s_linear_infinite]" />
        <div className="absolute inset-0 hud-overlay pointer-events-none opacity-20" />
        <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none" width={640} height={480} />

        {isActive && (
          <>
            {/* Top Left Status */}
            <div className="absolute top-8 left-8 flex items-center gap-3">
              <div className={`w-3 h-3 rounded-full animate-pulse shadow-md ${quotaExhausted ? 'bg-amber-500' : 'bg-red-500'}`}></div>
              <span className="text-white text-xs font-black tracking-widest uppercase opacity-90 drop-shadow-md">
                {quotaExhausted ? 'PAUSED (RATE LIMIT)' : 'TRACKING ACTIVE'}
              </span>
            </div>

            {/* Top Right Widgets */}
            <div className="absolute top-8 right-8 flex flex-col items-end gap-3">
              <div className="bg-slate-800/80 backdrop-blur-xl px-5 py-3 rounded-2xl border border-white/10 flex items-center gap-4 shadow-2xl">
                <Waves size={20} className="text-indigo-400" />
                <div>
                  <p className="text-[10px] font-black text-white/40 uppercase tracking-widest leading-none mb-1">LIVE INDEX</p>
                  <p className="text-lg font-black text-white leading-none">{analysis ? Math.round(analysis.alignmentScore) : 0}% Stability</p>
                </div>
              </div>

              {hasBaseline && (
                <div className="bg-indigo-600/90 backdrop-blur-md px-4 py-2 rounded-xl text-white text-[10px] font-black uppercase tracking-widest shadow-lg flex items-center gap-2 border border-white/10">
                  <ShieldCheck size={16} /> CLINICAL BASELINE ACTIVE
                </div>
              )}
            </div>

            {/* Bottom Controls Overlay */}
            <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex items-center gap-4 z-20">
              <button 
                onClick={toggleMonitoring}
                className="flex flex-col items-center justify-center gap-1 bg-red-600 hover:bg-red-700 text-white w-44 py-5 rounded-2xl font-black text-xs uppercase tracking-widest transition-all shadow-xl shadow-red-900/40"
              >
                <Square size={16} />
                <span>STOP SESSION</span>
              </button>

              <button 
                onClick={() => setIsPaused(!isPaused)}
                className={`flex flex-col items-center justify-center gap-1 w-44 py-5 rounded-2xl font-black text-xs uppercase tracking-widest transition-all backdrop-blur-md border border-white/20 shadow-xl ${
                  isPaused ? 'bg-amber-600/90 text-white' : 'bg-white/10 text-white hover:bg-white/20'
                }`}
              >
                {isPaused ? <Play size={16} /> : <Pause size={16} />}
                <span>{isPaused ? 'RESUME ANALYSIS' : 'STOP ANALYSIS'}</span>
              </button>

              <button 
                className="flex flex-col items-center justify-center gap-1 bg-indigo-600/90 hover:bg-indigo-700 text-white w-44 py-5 rounded-2xl font-black text-xs uppercase tracking-widest transition-all shadow-xl shadow-indigo-900/40 border border-white/10"
              >
                <Target size={16} />
                <span>ADJUST BASE</span>
              </button>
            </div>
          </>
        )}

        {!isActive && (
          <div className="absolute inset-0 flex flex-col items-center justify-center text-white space-y-4">
            <div className="w-20 h-20 bg-white/10 backdrop-blur-md rounded-3xl flex items-center justify-center text-slate-400 border border-white/10"><CameraOff size={40} /></div>
            <div className="text-center px-8">
              <p className="font-black text-xl mb-1">Optical Engine Standby</p>
              <p className="text-slate-400 text-sm font-medium">Initiate session to begin spinal tracking.</p>
            </div>
            <button 
              onClick={toggleMonitoring}
              className="mt-4 px-10 py-5 bg-indigo-600 text-white rounded-2xl font-black text-sm uppercase tracking-widest hover:bg-indigo-700 transition-all shadow-xl shadow-indigo-900/40 flex items-center gap-3"
            >
              <Play size={20} /> Start Live Session
            </button>
          </div>
        )}
      </div>

      {/* Bottom Metrics Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 px-4 md:px-0">
        <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">COBB ANGLE (EST)</p>
          <p className="text-5xl font-black text-slate-800">
            {analysis?.estimatedCobbAngle ? analysis.estimatedCobbAngle.toFixed(1) : '--'}
            <span className="text-3xl ml-1 text-slate-400">°</span>
          </p>
        </div>
        <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">SEVERITY CLASSIFICATION</p>
          <p className="text-5xl font-black text-slate-800">
            {analysis?.severity || '--'}
          </p>
        </div>
        <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">ALIGNMENT SCORE</p>
          <p className="text-5xl font-black text-indigo-600">
            {analysis ? Math.round(analysis.alignmentScore) : '--'}
            <span className="text-3xl ml-1 opacity-50">%</span>
          </p>
        </div>
      </div>
    </div>
  );
};

