import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult, ScoliosisSeverity } from "../types";

export async function analyzeXRay(base64Image: string): Promise<AnalysisResult> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'image/png',
            data: base64Image,
          },
        },
        {
          text: `You are a radiologist assistant. Analyze this spinal X-ray for Scoliosis. 
          1. Identify the most significant lateral curvature.
          2. Calculate the simulated Cobb Angle (the angle between the most tilted vertebrae).
          3. Classify severity: <10° is Normal, 10-25° is Mild, 25-45° is Moderate, >45° is Severe.
          4. Provide 3 specific physical therapy exercises suitable for this condition.
          5. Identify the top endplate and bottom endplate of the curve. Provide their coordinates (x1, y1, x2, y2) on a scale of 0-100 where 0,0 is top-left and 100,100 is bottom-right.
          Return ONLY a JSON object.`
        }
      ],
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          cobbAngle: { type: Type.NUMBER, description: 'Calculated Cobb angle in degrees' },
          severity: { type: Type.STRING, enum: ['Normal', 'Mild', 'Moderate', 'Severe'] },
          recommendations: { type: Type.ARRAY, items: { type: Type.STRING } },
          visualObservations: { type: Type.STRING, description: 'Summary of visual findings' },
          markers: {
            type: Type.OBJECT,
            properties: {
              topLine: {
                type: Type.OBJECT,
                properties: {
                  x1: { type: Type.NUMBER }, y1: { type: Type.NUMBER },
                  x2: { type: Type.NUMBER }, y2: { type: Type.NUMBER }
                },
                required: ['x1', 'y1', 'x2', 'y2']
              },
              bottomLine: {
                type: Type.OBJECT,
                properties: {
                  x1: { type: Type.NUMBER }, y1: { type: Type.NUMBER },
                  x2: { type: Type.NUMBER }, y2: { type: Type.NUMBER }
                },
                required: ['x1', 'y1', 'x2', 'y2']
              }
            },
            required: ['topLine', 'bottomLine']
          }
        },
        required: ['cobbAngle', 'severity', 'recommendations', 'visualObservations', 'markers']
      }
    }
  });

  let rawResult;
  try {
    rawResult = JSON.parse(response.text || '{}');
  } catch (err) {
    console.error("Failed to parse X-ray analysis JSON:", err);
    throw new Error("The AI provided a malformed response. Please try re-scanning the image.");
  }

  return {
    id: Math.random().toString(36).substr(2, 9),
    timestamp: new Date().toISOString(),
    cobbAngle: rawResult.cobbAngle,
    severity: rawResult.severity as ScoliosisSeverity,
    recommendations: rawResult.recommendations,
    visualObservations: rawResult.visualObservations,
    markers: rawResult.markers,
    source: 'XRAY'
  };
}

import React, { useState, useEffect } from 'react';
import { 
  Activity, 
  History, 
  LayoutDashboard, 
  ShieldCheck,
  LogOut,
  Bell,
  Menu,
  X,
  Video
} from 'lucide-react';
import { AppView, PatientRecord, User } from './types';
import DashboardView from './components/DashboardView';
import AnalysisView from './components/AnalysisView';
import HistoryView from './components/HistoryView';
import LoginView from './components/LoginView';
import PostureLiveView from './components/PostureLiveView';
import AboutView from './components/AboutView';

const MAX_RECORDS = 15; // Limit records to prevent localStorage truncation/quota issues

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<AppView>('DASHBOARD');
  const [records, setRecords] = useState<PatientRecord[]>([]);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // Load user and records from local storage with robust parsing
  useEffect(() => {
    const savedRecords = localStorage.getItem('scolio_records');
    if (savedRecords) {
      try { 
        const parsed = JSON.parse(savedRecords);
        if (Array.isArray(parsed)) {
          setRecords(parsed);
        } else {
          setRecords([]);
        }
      } catch (e) { 
        console.error("Corrupt local storage records detected:", e);
        // Clear corrupted data to prevent persistent crashes
        localStorage.removeItem('scolio_records');
        setRecords([]);
      }
    }

    const savedUser = localStorage.getItem('scolio_user');
    if (savedUser) {
      try { 
        const parsed = JSON.parse(savedUser);
        setUser(parsed); 
      } catch (e) { 
        console.error("Corrupt local storage user detected:", e);
        localStorage.removeItem('scolio_user');
      }
    }
  }, []);

  const handleLogin = (userData: User) => {
    setUser(userData);
    try {
      localStorage.setItem('scolio_user', JSON.stringify(userData));
    } catch (e) {
      console.error("Failed to save user to storage:", e);
    }
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('scolio_user');
  };

  const addRecord = (record: PatientRecord) => {
    // Trim history to prevent hitting localStorage 5MB limit with base64 images
    const updated = [record, ...records].slice(0, MAX_RECORDS);
    setRecords(updated);
    try {
      localStorage.setItem('scolio_records', JSON.stringify(updated));
    } catch (e) {
      console.error("Failed to save to local storage (quota likely exceeded):", e);
      // Fallback: save even fewer records if quota is tight
      const trimmed = updated.slice(0, 5);
      setRecords(trimmed);
      try {
        localStorage.setItem('scolio_records', JSON.stringify(trimmed));
      } catch (innerE) {
        console.error("Critical storage failure:", innerE);
      }
    }
  };

  const deleteRecord = (id: string) => {
    const updated = records.filter(r => r.id !== id);
    setRecords(updated);
    try {
      localStorage.setItem('scolio_records', JSON.stringify(updated));
    } catch (e) {
      console.error("Failed to update records storage:", e);
    }
  };

  const navItems = [
    { id: 'DASHBOARD' as AppView, label: 'Dashboard', icon: LayoutDashboard },
    { id: 'ANALYSIS' as AppView, label: 'AI Analysis', icon: Activity },
    { id: 'POSTURE_LIVE' as AppView, label: 'Live Monitoring', icon: Video },
    { id: 'HISTORY' as AppView, label: 'Patient History', icon: History },
  ];

  if (!user) {
    return <LoginView onLogin={handleLogin} />;
  }

  const renderView = () => {
    switch (currentView) {
      case 'DASHBOARD': return <DashboardView records={records} setView={setCurrentView} user={user} />;
      case 'ANALYSIS': return <AnalysisView onResultSave={addRecord} />;
      case 'POSTURE_LIVE': return <PostureLiveView onSaveReport={addRecord} />;
      case 'HISTORY': return <HistoryView records={records} onDelete={deleteRecord} />;
      case 'ABOUT': return <AboutView />;
      default: return <DashboardView records={records} setView={setCurrentView} user={user} />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row">
      {/* Sidebar - Desktop */}
      <aside className="hidden md:flex w-72 bg-white border-r border-slate-200 flex-col sticky top-0 h-screen shadow-sm">
        <div className="p-6 flex items-center gap-3 border-b border-slate-100">
          <div className="bg-indigo-600 p-2 rounded-xl text-white">
            <ShieldCheck size={28} />
          </div>
          <div>
            <h1 className="font-bold text-slate-800 text-lg leading-tight">ScolioVision</h1>
            <p className="text-indigo-600 text-xs font-semibold tracking-wider uppercase">AI Medical Suite</p>
          </div>
        </div>

        <nav className="flex-1 p-4 space-y-1">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setCurrentView(item.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
                currentView === item.id 
                  ? 'bg-indigo-50 text-indigo-700 shadow-sm font-semibold' 
                  : 'text-slate-500 hover:bg-slate-50 hover:text-slate-700'
              }`}
            >
              <item.icon size={20} />
              {item.label}
            </button>
          ))}
        </nav>

        <div className="p-4 mt-auto border-t border-slate-100">
          <button 
            onClick={handleLogout}
            className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-slate-500 hover:bg-red-50 hover:text-red-600 transition-colors"
          >
            <LogOut size={20} />
            Sign Out
          </button>
        </div>
      </aside>

      {/* Mobile Header */}
      <header className="md:hidden bg-white border-b border-slate-200 px-4 py-3 flex items-center justify-between sticky top-0 z-50">
        <div className="flex items-center gap-2">
          <div className="bg-indigo-600 p-1.5 rounded-lg text-white">
            <ShieldCheck size={20} />
          </div>
          <span className="font-bold text-slate-800">ScolioVision</span>
        </div>
        <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} className="p-2 text-slate-600">
          {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </header>

      {/* Mobile Nav Overlay */}
      {isMobileMenuOpen && (
        <div className="md:hidden fixed inset-0 bg-white z-40 pt-16 flex flex-col">
          <nav className="p-6 space-y-4">
            {navItems.map((item) => (
              <button
                key={item.id}
                onClick={() => {
                  setCurrentView(item.id);
                  setIsMobileMenuOpen(false);
                }}
                className={`w-full flex items-center gap-4 px-4 py-4 rounded-xl text-lg ${
                  currentView === item.id ? 'bg-indigo-50 text-indigo-700 font-bold' : 'text-slate-600 font-medium'
                }`}
              >
                <item.icon size={24} />
                {item.label}
              </button>
            ))}
            <button 
              onClick={handleLogout}
              className="w-full flex items-center gap-4 px-4 py-4 rounded-xl text-lg text-red-600 font-medium"
            >
              <LogOut size={24} />
              Sign Out
            </button>
          </nav>
        </div>
      )}

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto">
        <header className="hidden md:flex bg-white border-b border-slate-200 px-8 py-4 items-center justify-between sticky top-0 z-10">
          <h2 className="text-xl font-bold text-slate-800">
            {navItems.find(n => n.id === currentView)?.label}
          </h2>
          <div className="flex items-center gap-4">
            <button className="p-2 text-slate-400 hover:text-slate-600 relative">
              <Bell size={20} />
              <span className="absolute top-2 right-2 w-2 h-2 bg-red-500 rounded-full border-2 border-white"></span>
            </button>
            <div className="flex items-center gap-3 pl-4 border-l border-slate-200">
              <div className="text-right">
                <p className="text-sm font-bold text-slate-800">{user.name}</p>
                <p className="text-xs text-slate-500">{user.designation}</p>
              </div>
              <div className="w-10 h-10 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-700 font-bold ring-2 ring-white">
                {user.name.charAt(0)}
              </div>
            </div>
          </div>
        </header>

        <div className="p-4 md:p-8 max-w-7xl mx-auto">
          {renderView()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState } from 'react';
import { 
  Play, 
  Square, 
  RefreshCw, 
  ShieldCheck, 
  AlertTriangle,
  Waves,
  Pause,
  Target,
  CameraOff,
  User,
  ZapOff,
  FileDown,
  Activity as ActivityIcon,
  Focus,
  LineChart as LineChartIcon,
  CheckCircle
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";
import { PostureAnalysis, Landmark, ScoliosisSeverity, PatientRecord } from '../types';
import { AreaChart, Area, YAxis, XAxis, ResponsiveContainer, ReferenceLine } from 'recharts';

interface PostureLiveViewProps {
  onSaveReport?: (record: PatientRecord) => void;
}

interface SessionDataPoint {
  time: string;
  timestamp: number;
  score: number;
  angle: number;
}

const PostureLiveView: React.FC<PostureLiveViewProps> = ({ onSaveReport }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isActive, setIsActive] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<PostureAnalysis | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [quotaExhausted, setQuotaExhausted] = useState(false);
  const [hasBaseline, setHasBaseline] = useState(true);
  const [patientName, setPatientName] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  const [sessionHistory, setSessionHistory] = useState<SessionDataPoint[]>([]);
  const [sessionLogs, setSessionLogs] = useState<{time: string, text: string, severity: string}[]>([]);

  const toggleMonitoring = async () => {
    if (isActive) {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
      setIsActive(false);
      setIsPaused(false);
      setAnalysis(null);
      setQuotaExhausted(false);
      setSessionHistory([]);
      setSessionLogs([]);
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsActive(true);
          setError(null);
        }
      } catch (err) {
        setError("Camera access is required for real-time monitoring.");
      }
    }
  };

  const archiveSession = async () => {
    if (!analysis || !onSaveReport) return;
    if (!patientName.trim()) {
      setError("Please enter a patient name to archive this session.");
      return;
    }

    setIsSaving(true);
    try {
      // Create snapshot from video
      const snapshotCanvas = document.createElement('canvas');
      snapshotCanvas.width = 640;
      snapshotCanvas.height = 480;
      const sCtx = snapshotCanvas.getContext('2d');
      if (sCtx && videoRef.current) {
        sCtx.drawImage(videoRef.current, 0, 0, 640, 480);
        if (canvasRef.current) {
          sCtx.drawImage(canvasRef.current, 0, 0, 640, 480);
        }
      }
      const dataUrl = snapshotCanvas.toDataURL('image/jpeg', 0.7);

      const record: PatientRecord = {
        id: Math.random().toString(36).substr(2, 9),
        patientName: patientName,
        timestamp: new Date().toISOString(),
        cobbAngle: analysis.estimatedCobbAngle || 0,
        severity: analysis.severity || ScoliosisSeverity.NORMAL,
        recommendations: analysis.recommendations || [],
        visualObservations: analysis.feedback,
        imageUrl: dataUrl,
        source: 'LIVE'
      };

      onSaveReport(record);
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
    } catch (err) {
      setError("Failed to archive session.");
    } finally {
      setIsSaving(false);
    }
  };

  const analyzeFrame = async () => {
    if (!isActive || isPaused || !videoRef.current || isAnalyzing || quotaExhausted) return;

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `Analyze posture skeletal landmarks for real-time monitoring. Return JSON with landmarks (Head, Spine, Shoulders, Hips), alignmentScore (0-100), feedback, isDeviating, estimatedCobbAngle, severity.` }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  }
                }
              },
              alignmentScore: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              isDeviating: { type: Type.BOOLEAN },
              estimatedCobbAngle: { type: Type.NUMBER },
              severity: { type: Type.STRING }
            },
            required: ['landmarks', 'alignmentScore', 'feedback', 'isDeviating', 'estimatedCobbAngle', 'severity']
          }
        }
      });

      const responseText = response.text || '{}';
      try {
        const result = JSON.parse(responseText);
        setAnalysis(result);
        setQuotaExhausted(false);
        setError(null);

        const currentTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

        setSessionHistory(prev => [...prev.slice(-19), {
          time: currentTime,
          timestamp: Date.now(),
          score: result.alignmentScore,
          angle: result.estimatedCobbAngle
        }]);

        setSessionLogs(prev => [{
          time: currentTime,
          text: result.feedback,
          severity: result.severity
        }, ...prev.slice(0, 9)]);

      } catch (jsonErr) {
        console.warn("JSON Parse Error on Model Output:", jsonErr);
      }
    } catch (err: any) {
      console.error("Analysis Error:", err);
      if (err.message?.includes("RESOURCE_EXHAUSTED") || err.status === 429) {
        setQuotaExhausted(true);
        setError("AI Rate Limit Reached. Monitoring paused for cooldown.");
        setTimeout(() => {
          setQuotaExhausted(false);
          setError(null);
        }, 15000); // 15 second cooldown for rate limit
      }
    } finally {
      setIsAnalyzing(false);
    }
  };

  useEffect(() => {
    let timeoutId: number;
    const poll = async () => {
      if (isActive && !isPaused && !quotaExhausted) {
        await analyzeFrame();
      }
      timeoutId = window.setTimeout(poll, quotaExhausted ? 10000 : 4000);
    };

    if (isActive) {
      timeoutId = window.setTimeout(poll, 1000);
    }
    return () => clearTimeout(timeoutId);
  }, [isActive, isPaused, quotaExhausted]);

  useEffect(() => {
    if (!canvasRef.current || !analysis?.landmarks || !isActive) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const { width, height } = canvasRef.current;
    ctx.clearRect(0, 0, width, height);

    const getPt = (label: string) => 
      analysis.landmarks.find(p => p.label.toLowerCase().includes(label.toLowerCase()));

    const scaleX = (x: number) => (x * width) / 100;
    const scaleY = (y: number) => (y * height) / 100;

    const drawBiometricSkeleton = () => {
      const head = getPt('head');
      const spine = getPt('spine');
      const ls = getPt('shoulder');
      const lh = getPt('hip');

      const color = analysis.isDeviating ? '#fb7185' : '#2dd4bf';

      const drawBone = (p1: Landmark, p2: Landmark, weight: number) => {
        const x1 = scaleX(p1.x), y1 = scaleY(p1.y);
        const x2 = scaleX(p2.x), y2 = scaleY(p2.y);
        ctx.beginPath();
        ctx.lineWidth = weight;
        ctx.lineCap = 'round';
        ctx.strokeStyle = color;
        ctx.globalAlpha = 0.5;
        ctx.moveTo(x1, y1);
        ctx.lineTo(x2, y2);
        ctx.stroke();
        ctx.globalAlpha = 1.0;
      };

      if (head && spine) drawBone(head, spine, 6);

      analysis.landmarks.forEach(j => {
        ctx.beginPath();
        ctx.arc(scaleX(j.x), scaleY(j.y), 5, 0, Math.PI * 2);
        ctx.fillStyle = color;
        ctx.shadowBlur = 8;
        ctx.shadowColor = color;
        ctx.fill();
        ctx.shadowBlur = 0;
      });
    };

    const frame = requestAnimationFrame(drawBiometricSkeleton);
    return () => cancelAnimationFrame(frame);
  }, [analysis, isActive]);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <style>{`
        @keyframes scanline { 0% { transform: translateY(-100%); } 100% { transform: translateY(100%); } }
        .hud-overlay {
          background-image: linear-gradient(0deg, transparent 24%, rgba(99, 102, 241, 0.05) 25%, rgba(99, 102, 241, 0.05) 26%, transparent 27%, transparent 74%, rgba(99, 102, 241, 0.05) 75%, rgba(99, 102, 241, 0.05) 76%, transparent 77%, transparent), 
                            linear-gradient(90deg, transparent 24%, rgba(99, 102, 241, 0.05) 25%, rgba(99, 102, 241, 0.05) 26%, transparent 27%, transparent 74%, rgba(99, 102, 241, 0.05) 75%, rgba(99, 102, 241, 0.05) 76%, transparent 77%, transparent);
          background-size: 40px 40px;
        }
      `}</style>

      {/* Top Header Controls */}
      <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col md:flex-row items-center justify-between gap-6">
        <div className="flex-1 w-full relative">
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Active Patient Session</label>
          <div className="relative">
            <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
            <input 
              type="text" 
              placeholder="Enter Patient Full Name..." 
              value={patientName}
              onChange={(e) => setPatientName(e.target.value)}
              className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none font-bold text-slate-700"
            />
          </div>
        </div>
        <div className="shrink-0">
          <button 
            onClick={archiveSession}
            disabled={!analysis || isSaving}
            className={`flex items-center gap-2 px-8 py-3.5 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${
              saveSuccess 
                ? 'bg-emerald-500 text-white' 
                : !analysis || isSaving 
                ? 'bg-slate-100 text-slate-400 cursor-not-allowed' 
                : 'bg-emerald-600 text-white shadow-lg shadow-emerald-500/20 hover:bg-emerald-700'
            }`}
          >
            {saveSuccess ? <CheckCircle size={14} /> : isSaving ? <RefreshCw size={14} className="animate-spin" /> : <FileDown size={14} />}
            {saveSuccess ? 'Session Archived' : 'Archive Session'}
          </button>
        </div>
      </div>

      {error && (
        <div className={`p-4 rounded-2xl flex items-center gap-3 font-bold text-sm border ${
          quotaExhausted ? 'bg-amber-50 border-amber-200 text-amber-700' : 'bg-red-50 border-red-100 text-red-600'
        }`}>
          {quotaExhausted ? <ZapOff size={18} /> : <AlertTriangle size={18} />}
          {error}
        </div>
      )}

      <div className="flex flex-col xl:flex-row gap-8">
        {/* Main Viewport */}
        <div className="flex-1 flex flex-col gap-6">
          <div className="relative bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl aspect-video border-[6px] border-slate-800">
            <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity duration-700 ${isActive ? 'opacity-100' : 'opacity-20'}`} />

            <div className="absolute inset-0 pointer-events-none opacity-10 bg-gradient-to-b from-transparent via-indigo-500 to-transparent h-2 animate-[scanline_4s_linear_infinite]" />
            <div className="absolute inset-0 hud-overlay pointer-events-none opacity-20" />
            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none" width={640} height={480} />

            {isActive && (
              <>
                <div className="absolute top-8 left-8 flex items-center gap-3">
                  <div className={`w-3 h-3 rounded-full animate-pulse shadow-md ${quotaExhausted ? 'bg-amber-500' : 'bg-red-500'}`}></div>
                  <span className="text-white text-xs font-black tracking-widest uppercase opacity-90 drop-shadow-md">
                    {quotaExhausted ? 'PAUSED (RATE LIMIT)' : 'TRACKING ACTIVE'}
                  </span>
                </div>

                <div className="absolute top-8 right-8 flex flex-col items-end gap-3">
                  <div className="bg-slate-800/80 backdrop-blur-xl px-5 py-3 rounded-2xl border border-white/10 flex items-center gap-4 shadow-2xl">
                    <Waves size={20} className="text-indigo-400" />
                    <div>
                      <p className="text-[10px] font-black text-white/40 uppercase tracking-widest leading-none mb-1">LIVE INDEX</p>
                      <p className="text-lg font-black text-white leading-none">{analysis ? Math.round(analysis.alignmentScore) : 0}% Stability</p>
                    </div>
                  </div>
                  {hasBaseline && (
                    <div className="bg-indigo-600/90 backdrop-blur-md px-4 py-2 rounded-xl text-white text-[10px] font-black uppercase tracking-widest shadow-lg flex items-center gap-2 border border-white/10">
                      <ShieldCheck size={16} /> CLINICAL BASELINE ACTIVE
                    </div>
                  )}
                </div>

                <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex items-center gap-4 z-20">
                  <button 
                    onClick={toggleMonitoring}
                    className="flex flex-col items-center justify-center gap-1 bg-red-600 hover:bg-red-700 text-white w-44 py-5 rounded-2xl font-black text-xs uppercase tracking-widest transition-all shadow-xl shadow-red-900/40"
                  >
                    <Square size={16} />
                    <span>STOP SESSION</span>
                  </button>
                  <button 
                    onClick={() => setIsPaused(!isPaused)}
                    className={`flex flex-col items-center justify-center gap-1 w-44 py-5 rounded-2xl font-black text-xs uppercase tracking-widest transition-all backdrop-blur-md border border-white/20 shadow-xl ${
                      isPaused ? 'bg-amber-600/90 text-white' : 'bg-white/10 text-white hover:bg-white/20'
                    }`}
                  >
                    {isPaused ? <Play size={16} /> : <Pause size={16} />}
                    <span>{isPaused ? 'RESUME ANALYSIS' : 'STOP ANALYSIS'}</span>
                  </button>
                  <button className="flex flex-col items-center justify-center gap-1 bg-indigo-600/90 hover:bg-indigo-700 text-white w-44 py-5 rounded-2xl font-black text-xs uppercase tracking-widest transition-all shadow-xl shadow-indigo-900/40 border border-white/10">
                    <Target size={16} />
                    <span>ADJUST BASE</span>
                  </button>
                </div>
              </>
            )}

            {!isActive && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-white space-y-4">
                <div className="w-20 h-20 bg-white/10 backdrop-blur-md rounded-3xl flex items-center justify-center text-slate-400 border border-white/10"><CameraOff size={40} /></div>
                <div className="text-center px-8">
                  <p className="font-black text-xl mb-1">Optical Engine Standby</p>
                  <p className="text-slate-400 text-sm font-medium">Initiate session to begin spinal tracking.</p>
                </div>
                <button 
                  onClick={toggleMonitoring}
                  className="mt-4 px-10 py-5 bg-indigo-600 text-white rounded-2xl font-black text-sm uppercase tracking-widest hover:bg-indigo-700 transition-all shadow-xl shadow-indigo-900/40 flex items-center gap-3"
                >
                  <Play size={20} /> Start Live Session
                </button>
              </div>
            )}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">COBB ANGLE (EST)</p>
              <p className="text-5xl font-black text-slate-800">
                {analysis?.estimatedCobbAngle ? analysis.estimatedCobbAngle.toFixed(1) : '--'}
                <span className="text-3xl ml-1 text-slate-400">°</span>
              </p>
            </div>
            <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">SEVERITY CLASSIFICATION</p>
              <p className="text-5xl font-black text-slate-800">
                {analysis?.severity || '--'}
              </p>
            </div>
            <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
