import React, { useEffect, useRef, useState } from 'react';
import { 
  Play, 
  Square, 
  RefreshCw, 
  ShieldCheck, 
  AlertTriangle,
  CameraOff,
  User,
  ZapOff,
  FileDown,
  Activity as ActivityIcon,
  Focus,
  LineChart as LineChartIcon,
  CheckCircle
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";
import { PostureAnalysis, Landmark, ScoliosisSeverity, PatientRecord } from '../types';
import { AreaChart, Area, YAxis, XAxis, ResponsiveContainer, ReferenceLine } from 'recharts';

interface PostureLiveViewProps {
  onSaveReport?: (record: PatientRecord) => void;
}

interface SessionDataPoint {
  time: string;
  timestamp: number;
  score: number;
  angle: number;
}

const PostureLiveView: React.FC<PostureLiveViewProps> = ({ onSaveReport }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isActive, setIsActive] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<PostureAnalysis | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [quotaExhausted, setQuotaExhausted] = useState(false);
  const [patientName, setPatientName] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  const [sessionHistory, setSessionHistory] = useState<SessionDataPoint[]>([]);
  const [sessionLogs, setSessionLogs] = useState<{time: string, text: string, severity: string}[]>([]);

  const toggleMonitoring = async () => {
    if (isActive) {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
      setIsActive(false);
      setAnalysis(null);
      setQuotaExhausted(false);
      setSessionHistory([]);
      setSessionLogs([]);
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsActive(true);
          setError(null);
        }
      } catch (err) {
        setError("Camera access is required for real-time monitoring.");
      }
    }
  };

  const archiveSession = async () => {
    if (!analysis || !onSaveReport) return;
    if (!patientName.trim()) {
      setError("Please enter a patient name to archive this session.");
      return;
    }

    setIsSaving(true);
    try {
      const snapshotCanvas = document.createElement('canvas');
      snapshotCanvas.width = 640;
      snapshotCanvas.height = 480;
      const sCtx = snapshotCanvas.getContext('2d');
      if (sCtx && videoRef.current) {
        sCtx.drawImage(videoRef.current, 0, 0, 640, 480);
        if (canvasRef.current) {
          sCtx.drawImage(canvasRef.current, 0, 0, 640, 480);
        }
      }
      const dataUrl = snapshotCanvas.toDataURL('image/jpeg', 0.7);

      const record: PatientRecord = {
        id: Math.random().toString(36).substr(2, 9),
        patientName: patientName,
        timestamp: new Date().toISOString(),
        cobbAngle: analysis.estimatedCobbAngle || 0,
        severity: analysis.severity || ScoliosisSeverity.NORMAL,
        recommendations: analysis.recommendations || [],
        visualObservations: analysis.feedback,
        imageUrl: dataUrl,
        source: 'LIVE'
      };

      onSaveReport(record);
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
    } catch (err) {
      setError("Failed to archive session.");
    } finally {
      setIsSaving(false);
    }
  };

  const analyzeFrame = async () => {
    if (!isActive || !videoRef.current || isAnalyzing || quotaExhausted) return;

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `FAST SCOLIOSIS SCREENING. Identify landmarks: Head, LeftShoulder, RightShoulder, SpineMid, LeftHip, RightHip. Calculate: CobbAngle(est), AlignmentScore(0-100), Severity(Normal/Mild/Moderate/Severe). Provide 1-sentence diagnostic feedback. Return JSON.` }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  }
                }
              },
              alignmentScore: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              isDeviating: { type: Type.BOOLEAN },
              estimatedCobbAngle: { type: Type.NUMBER },
              severity: { type: Type.STRING }
            },
            required: ['landmarks', 'alignmentScore', 'feedback', 'isDeviating', 'estimatedCobbAngle', 'severity']
          }
        }
      });

      const responseText = response.text || '{}';
      try {
        const result = JSON.parse(responseText);
        setAnalysis(result);
        setQuotaExhausted(false);
        setError(null);

        const currentTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

        setSessionHistory(prev => [...prev.slice(-19), {
          time: currentTime,
          timestamp: Date.now(),
          score: result.alignmentScore,
          angle: result.estimatedCobbAngle
        }]);

        setSessionLogs(prev => [{
          time: currentTime,
          text: result.feedback,
          severity: result.severity
        }, ...prev.slice(0, 9)]);

      } catch (jsonErr) {
        console.warn("JSON Parse Error on Model Output:", jsonErr);
      }
    } catch (err: any) {
      if (err.message?.includes("RESOURCE_EXHAUSTED") || err.status === 429) {
        setQuotaExhausted(true);
        setError("AI rate limit reached. Analysis cooling down...");
        setTimeout(() => setQuotaExhausted(false), 10000);
      }
    } finally {
      setIsAnalyzing(false);
    }
  };

  useEffect(() => {
    let timeoutId: number;
    const poll = async () => {
      if (isActive && !quotaExhausted) {
        await analyzeFrame();
      }
      timeoutId = window.setTimeout(poll, quotaExhausted ? 8000 : 3000);
    };

    if (isActive) {
      timeoutId = window.setTimeout(poll, 1000);
    }
    return () => clearTimeout(timeoutId);
  }, [isActive, quotaExhausted]);

  useEffect(() => {
    if (!canvasRef.current || !analysis?.landmarks || !isActive) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const { width, height } = canvasRef.current;
    ctx.clearRect(0, 0, width, height);

    const getPt = (label: string) => 
      analysis.landmarks.find(p => p.label.toLowerCase().includes(label.toLowerCase()));

    const scaleX = (x: number) => (x * width) / 100;
    const scaleY = (y: number) => (y * height) / 100;

    const drawBiometricSkeleton = () => {
      const head = getPt('head');
      const spine = getPt('spine');
      const ls = getPt('leftshoulder');
      const rs = getPt('rightshoulder');
      const lh = getPt('lefthip');
      const rh = getPt('righthip');

      const drawLine = (p1: Landmark | undefined, p2: Landmark | undefined, color: string, weight: number) => {
        if (!p1 || !p2) return;
        ctx.beginPath();
        ctx.lineWidth = weight;
        ctx.lineCap = 'round';
        ctx.strokeStyle = color;
        ctx.moveTo(scaleX(p1.x), scaleY(p1.y));
        ctx.lineTo(scaleX(p2.x), scaleY(p2.y));
        ctx.stroke();
      };

      // Spinal Column (Blue Indicator)
      if (head && spine) drawLine(head, spine, '#3b82f6', 6);

      // Shoulder Alignment (Green/Red Indicator)
      const shoulderColor = analysis.isDeviating ? '#ef4444' : '#10b981';
      drawLine(ls, rs, shoulderColor, 4);

      // Hip Alignment (Green/Red Indicator)
      drawLine(lh, rh, shoulderColor, 4);

      // Anatomical Markers
      analysis.landmarks.forEach(j => {
        const jx = scaleX(j.x), jy = scaleY(j.y);
        ctx.beginPath();
        ctx.arc(jx, jy, 6, 0, Math.PI * 2);
        ctx.fillStyle = shoulderColor;
        ctx.shadowBlur = 10;
        ctx.shadowColor = shoulderColor;
        ctx.fill();
        ctx.shadowBlur = 0;
      });
    };

    const frame = requestAnimationFrame(drawBiometricSkeleton);
    return () => cancelAnimationFrame(frame);
  }, [analysis, isActive]);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      {/* Patient Header */}
      <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col md:flex-row items-center justify-between gap-6">
        <div className="flex-1 w-full">
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Patient Identity</label>
          <div className="relative">
            <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
            <input 
              type="text" 
              placeholder="Enter Patient Full Name..." 
              value={patientName}
              onChange={(e) => setPatientName(e.target.value)}
              className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none font-bold text-slate-700"
            />
          </div>
        </div>
        <div className="shrink-0">
          <button 
            onClick={archiveSession}
            disabled={!analysis || isSaving}
            className={`flex items-center gap-2 px-8 py-3.5 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${
              saveSuccess 
                ? 'bg-emerald-500 text-white' 
                : !analysis || isSaving 
                ? 'bg-slate-100 text-slate-400 cursor-not-allowed' 
                : 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20 hover:bg-indigo-700'
            }`}
          >
            {saveSuccess ? <CheckCircle size={14} /> : isSaving ? <RefreshCw size={14} className="animate-spin" /> : <FileDown size={14} />}
            {saveSuccess ? 'Report Saved' : 'Export Findings'}
          </button>
        </div>
      </div>

      <div className="flex flex-col xl:flex-row gap-8">
        {/* Main Viewport */}
        <div className="flex-1 flex flex-col gap-6">
          <div className="relative bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl aspect-video border-[6px] border-slate-800">
            <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity duration-700 ${isActive ? 'opacity-100' : 'opacity-20'}`} />

            <div className="absolute inset-0 pointer-events-none opacity-20 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]"></div>
            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none" width={640} height={480} />

            {isActive && (
              <div className="absolute top-8 left-8 flex items-center gap-3 bg-black/40 backdrop-blur-md px-4 py-2 rounded-xl border border-white/10">
                <div className="w-2.5 h-2.5 bg-red-500 rounded-full animate-pulse shadow-[0_0_10px_rgba(239,68,68,0.8)]"></div>
                <span className="text-white text-[10px] font-black tracking-widest uppercase">Live Tracking Active</span>
              </div>
            )}

            <div className="absolute bottom-10 left-1/2 -translate-x-1/2 z-20">
              {isActive ? (
                <button 
                  onClick={toggleMonitoring}
                  className="group flex items-center gap-4 bg-red-600 hover:bg-red-700 text-white px-10 py-5 rounded-3xl font-black text-sm uppercase tracking-[0.2em] transition-all shadow-2xl shadow-red-900/40 hover:-translate-y-1"
                >
                  <Square size={20} fill="currentColor" />
                  Stop Analysis
                </button>
              ) : (
                <button 
                  onClick={toggleMonitoring}
                  className="group flex items-center gap-4 bg-indigo-600 hover:bg-indigo-700 text-white px-12 py-6 rounded-3xl font-black text-sm uppercase tracking-[0.2em] transition-all shadow-2xl shadow-indigo-900/40 hover:-translate-y-1"
                >
                  <Play size={24} fill="currentColor" />
                  Start Real-Time Analysis
                </button>
              )}
            </div>

            {!isActive && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-white space-y-4 pointer-events-none">
                <div className="w-20 h-20 bg-white/5 backdrop-blur-md rounded-[2rem] flex items-center justify-center text-slate-500 border border-white/10"><CameraOff size={40} /></div>
                <div className="text-center px-8">
                  <p className="font-black text-xl mb-1 opacity-40">Postural Interface Standby</p>
                  <p className="text-slate-500 text-xs font-bold uppercase tracking-widest">Connect camera to begin spinal mapping</p>
                </div>
              </div>
            )}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm group hover:border-indigo-100 transition-colors">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Cobb Index (Est)</p>
              <p className="text-5xl font-black text-slate-800">
                {analysis?.estimatedCobbAngle ? analysis.estimatedCobbAngle.toFixed(1) : '--'}
                <span className="text-3xl ml-1 text-slate-300">°</span>
              </p>
            </div>
            <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm group hover:border-indigo-100 transition-colors">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Clinical Severity</p>
              <p className={`text-5xl font-black ${analysis?.severity === 'Severe' ? 'text-red-600' : 'text-slate-800'}`}>
                {analysis?.severity || '--'}
              </p>
            </div>
            <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm group hover:border-indigo-100 transition-colors">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Stability</p>
              <p className="text-5xl font-black text-indigo-600">
                {analysis ? Math.round(analysis.alignmentScore) : '--'}
                <span className="text-3xl ml-1 opacity-50">%</span>
              </p>
            </div>
          </div>
        </div>

        {/* Sidebar: Diagnostics Feed */}
        <div className="w-full xl:w-96 flex flex-col gap-6">
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-lg flex flex-col h-[400px]">
            <div className="flex items-center justify-between mb-6 border-b border-slate-50 pb-4">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><ShieldCheck size={24} className="text-indigo-600" /> Diagnostic Feed</h3>
              {isAnalyzing && <RefreshCw size={16} className="text-indigo-400 animate-spin" />}
            </div>

            <div className="space-y-4 overflow-y-auto flex-1 pr-2 custom-scrollbar">
              {sessionLogs.length > 0 ? sessionLogs.map((log, i) => (
                <div key={i} className={`p-5 rounded-2xl border animate-in slide-in-from-right-4 transition-all ${i === 0 ? 'bg-indigo-50 border-indigo-100' : 'bg-slate-50 border-slate-50 opacity-60'}`}>
