                      {log.severity}
                    </span>
                  </div>
                  <p className="text-xs font-bold text-slate-800 leading-relaxed italic">"{log.text}"</p>
                </div>
              )) : (
                <div className="flex flex-col items-center justify-center py-20 text-slate-300 text-center">
                  <Focus size={32} className="mb-2 opacity-20" />
                  <p className="text-xs font-black uppercase tracking-widest opacity-40">Interface Idle</p>
                </div>
              )}
            </div>
          </div>

          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-lg flex-1 min-h-[250px]">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-sm font-black text-slate-800 flex items-center gap-2"><LineChartIcon size={20} className="text-indigo-600" /> Postural Trend</h3>
            </div>
            <div className="h-40 w-full">
              {sessionHistory.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={sessionHistory}>
                    <defs>
                      <linearGradient id="colorScoreLive" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#6366f1" stopOpacity={0.2}/>
                        <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <YAxis domain={[0, 100]} hide />
                    <Area type="monotone" dataKey="score" stroke="#6366f1" strokeWidth={3} fillOpacity={1} fill="url(#colorScoreLive)" />
                    <ReferenceLine y={85} stroke="#10b981" strokeDasharray="3 3" />
