import { PostureAnalysis, Landmark, ScoliosisSeverity, PatientRecord } from '../types';
import { AreaChart, Area, YAxis, XAxis, ResponsiveContainer, ReferenceLine } from 'recharts';

interface PostureLiveViewProps {
  onSaveReport?: (record: PatientRecord) => void;
}

interface SessionDataPoint {
  time: string;
  timestamp: number;
  score: number;
  angle: number;
}

const PostureLiveView: React.FC<PostureLiveViewProps> = ({ onSaveReport }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isActive, setIsActive] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<PostureAnalysis | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [quotaExhausted, setQuotaExhausted] = useState(false);
  const [patientName, setPatientName] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  const [sessionHistory, setSessionHistory] = useState<SessionDataPoint[]>([]);
  const [sessionLogs, setSessionLogs] = useState<{time: string, text: string, severity: string}[]>([]);

  const toggleMonitoring = async () => {
    if (isActive) {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
      setIsActive(false);
      setAnalysis(null);
      setQuotaExhausted(false);
      setSessionHistory([]);
      setSessionLogs([]);
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsActive(true);
          setError(null);
        }
      } catch (err) {
        setError("Camera access is required for real-time monitoring.");
      }
    }
  };

  const archiveSession = async () => {
    if (!analysis || !onSaveReport) return;
    if (!patientName.trim()) {
      setError("Please enter a patient name to archive this session.");
      return;
    }

    setIsSaving(true);
    try {
      const snapshotCanvas = document.createElement('canvas');
      snapshotCanvas.width = 640;
      snapshotCanvas.height = 480;
      const sCtx = snapshotCanvas.getContext('2d');
      if (sCtx && videoRef.current) {
        sCtx.drawImage(videoRef.current, 0, 0, 640, 480);
        if (canvasRef.current) {
          sCtx.drawImage(canvasRef.current, 0, 0, 640, 480);
        }
      }
      const dataUrl = snapshotCanvas.toDataURL('image/jpeg', 0.7);

      const record: PatientRecord = {
        id: Math.random().toString(36).substr(2, 9),
        patientName: patientName,
        timestamp: new Date().toISOString(),
        cobbAngle: analysis.estimatedCobbAngle || 0,
        severity: analysis.severity || ScoliosisSeverity.NORMAL,
        recommendations: analysis.recommendations || [],
        visualObservations: analysis.feedback,
        imageUrl: dataUrl,
        source: 'LIVE'
      };

      onSaveReport(record);
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
    } catch (err) {
      setError("Failed to archive session.");
    } finally {
      setIsSaving(false);
    }
  };

  const analyzeFrame = async () => {
    if (!isActive || !videoRef.current || isAnalyzing || quotaExhausted) return;

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `FAST SCOLIOSIS SCREENING. Identify landmarks: Head, LeftShoulder, RightShoulder, SpineMid, LeftHip, RightHip. Calculate: CobbAngle(est), AlignmentScore(0-100), Severity(Normal/Mild/Moderate/Severe). Provide 1-sentence diagnostic feedback. Return JSON.` }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  }
                }
              },
              alignmentScore: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              isDeviating: { type: Type.BOOLEAN },
              estimatedCobbAngle: { type: Type.NUMBER },
              severity: { type: Type.STRING }
            },
            required: ['landmarks', 'alignmentScore', 'feedback', 'isDeviating', 'estimatedCobbAngle', 'severity']
          }
        }
      });

      const responseText = response.text || '{}';
      try {
        const result = JSON.parse(responseText);
        setAnalysis(result);
        setQuotaExhausted(false);
        setError(null);

        const currentTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

        setSessionHistory(prev => [...prev.slice(-19), {
          time: currentTime,
          timestamp: Date.now(),
          score: result.alignmentScore,
          angle: result.estimatedCobbAngle
        }]);

        setSessionLogs(prev => [{
          time: currentTime,
          text: result.feedback,
          severity: result.severity
        }, ...prev.slice(0, 9)]);

      } catch (jsonErr) {
        console.warn("JSON Parse Error on Model Output:", jsonErr);
      }
    } catch (err: any) {
      if (err.message?.includes("RESOURCE_EXHAUSTED") || err.status === 429) {
        setQuotaExhausted(true);
        setError("AI rate limit reached. Analysis cooling down...");
        setTimeout(() => setQuotaExhausted(false), 10000);
      }
    } finally {
      setIsAnalyzing(false);
    }
  };

  useEffect(() => {
    let timeoutId: number;
    const poll = async () => {
      if (isActive && !quotaExhausted) {
        await analyzeFrame();
      }
      timeoutId = window.setTimeout(poll, quotaExhausted ? 8000 : 3000);
    };

    if (isActive) {
      timeoutId = window.setTimeout(poll, 1000);
    }
    return () => clearTimeout(timeoutId);
  }, [isActive, quotaExhausted]);

  useEffect(() => {
    if (!canvasRef.current || !analysis?.landmarks || !isActive) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const { width, height } = canvasRef.current;
    ctx.clearRect(0, 0, width, height);

    const getPt = (label: string) => 
      analysis.landmarks.find(p => p.label.toLowerCase().replace(/\s/g, '').includes(label.toLowerCase().replace(/\s/g, '')));

    const scaleX = (x: number) => (x * width) / 100;
    const scaleY = (y: number) => (y * height) / 100;

    const getLandmarkColor = (label: string) => {
      const l = label.toLowerCase();
      if (l.includes('head')) return '#fbbf24'; // Amber/Yellow
      if (l.includes('shoulder')) return '#22d3ee'; // Cyan
      if (l.includes('spine')) return '#f8fafc'; // White/Slate
      if (l.includes('hip')) return '#a855f7'; // Purple
      return '#ffffff';
    };

    const drawBiometricSkeleton = () => {
      const head = getPt('head');
      const spine = getPt('spinemid');
      const ls = getPt('leftshoulder');
      const rs = getPt('rightshoulder');
      const lh = getPt('lefthip');
      const rh = getPt('righthip');

      const drawLine = (p1: Landmark | undefined, p2: Landmark | undefined, color: string, weight: number) => {
        if (!p1 || !p2) return;
        ctx.beginPath();
        ctx.lineWidth = weight;
        ctx.lineCap = 'round';
        ctx.strokeStyle = color;
        ctx.globalAlpha = 0.8;
        ctx.moveTo(scaleX(p1.x), scaleY(p1.y));
        ctx.lineTo(scaleX(p2.x), scaleY(p2.y));
        ctx.stroke();
        ctx.globalAlpha = 1.0;
      };

      // 1. Spinal Column (Blue Indicator)
      if (head && spine) drawLine(head, spine, '#3b82f6', 6);

      // 2. Shoulder Alignment (Green/Red Indicator)
      const shoulderColor = analysis.isDeviating ? '#ef4444' : '#10b981';
      if (ls && rs) drawLine(ls, rs, shoulderColor, 4);

      // 3. Hip Alignment (Green/Red Indicator)
      if (lh && rh) drawLine(lh, rh, shoulderColor, 4);

      // 4. Distinct Anatomical Markers (Colored Dots)
      analysis.landmarks.forEach(j => {
        const jx = scaleX(j.x), jy = scaleY(j.y);
        const dotColor = getLandmarkColor(j.label);

        // Marker Outer Glow
        ctx.beginPath();
        ctx.arc(jx, jy, 12, 0, Math.PI * 2);
        ctx.fillStyle = dotColor;
        ctx.globalAlpha = 0.2;
        ctx.fill();
        ctx.globalAlpha = 1.0;

        // Marker Core
        ctx.beginPath();
        ctx.arc(jx, jy, 6, 0, Math.PI * 2);
        ctx.fillStyle = dotColor;
        ctx.strokeStyle = '#0f172a';
        ctx.lineWidth = 2;
        ctx.shadowBlur = 10;
        ctx.shadowColor = dotColor;
        ctx.fill();
        ctx.stroke();
        ctx.shadowBlur = 0;
      });
    };

    const frame = requestAnimationFrame(drawBiometricSkeleton);
    return () => cancelAnimationFrame(frame);
  }, [analysis, isActive]);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      {/* Patient Header */}
      <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col md:flex-row items-center justify-between gap-6">
        <div className="flex-1 w-full">
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Patient Identity</label>
          <div className="relative">
            <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
            <input 
              type="text" 
              placeholder="Enter Patient Full Name..." 
              value={patientName}
              onChange={(e) => setPatientName(e.target.value)}
              className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none font-bold text-slate-700"
            />
          </div>
        </div>
        <div className="shrink-0">
          <button 
            onClick={archiveSession}
            disabled={!analysis || isSaving}
            className={`flex items-center gap-2 px-8 py-3.5 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${
              saveSuccess 
                ? 'bg-emerald-500 text-white' 
                : !analysis || isSaving 
                ? 'bg-slate-100 text-slate-400 cursor-not-allowed' 
                : 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20 hover:bg-indigo-700'
            }`}
          >
            {saveSuccess ? <CheckCircle size={14} /> : isSaving ? <RefreshCw size={14} className="animate-spin" /> : <FileDown size={14} />}
            {saveSuccess ? 'Report Saved' : 'Export Findings'}
          </button>
        </div>
      </div>

      <div className="flex flex-col xl:flex-row gap-8">
        {/* Main Viewport */}
        <div className="flex-1 flex flex-col gap-6">
          <div className="relative bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl aspect-video border-[6px] border-slate-800">
            <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity duration-700 ${isActive ? 'opacity-100' : 'opacity-20'}`} />

            <div className="absolute inset-0 pointer-events-none opacity-20 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]"></div>
            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none" width={640} height={480} />

            {isActive && (
              <div className="absolute top-8 left-8 flex items-center gap-3 bg-black/40 backdrop-blur-md px-4 py-2 rounded-xl border border-white/10">
                <div className="w-2.5 h-2.5 bg-red-500 rounded-full animate-pulse shadow-[0_0_10px_rgba(239,68,68,0.8)]"></div>
                <span className="text-white text-[10px] font-black tracking-widest uppercase">Live Tracking Active</span>
              </div>
            )}

            <div className="absolute bottom-10 left-1/2 -translate-x-1/2 z-20">
              {isActive ? (
                <button 
                  onClick={toggleMonitoring}
                  className="group flex items-center gap-4 bg-red-600 hover:bg-red-700 text-white px-10 py-5 rounded-3xl font-black text-sm uppercase tracking-[0.2em] transition-all shadow-2xl shadow-red-900/40 hover:-translate-y-1"
                >
                  <Square size={20} fill="currentColor" />
                  Stop Analysis
                </button>
              ) : (
                <button 
                  onClick={toggleMonitoring}
                  className="group flex items-center gap-4 bg-indigo-600 hover:bg-indigo-700 text-white px-12 py-6 rounded-3xl font-black text-sm uppercase tracking-[0.2em] transition-all shadow-2xl shadow-indigo-900/40 hover:-translate-y-1"
                >
                  <Play size={24} fill="currentColor" />
                  Start Real-Time Analysis
                </button>
              )}
            </div>

            {!isActive && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-white space-y-4 pointer-events-none">
                <div className="w-20 h-20 bg-white/5 backdrop-blur-md rounded-[2rem] flex items-center justify-center text-slate-500 border border-white/10"><CameraOff size={40} /></div>
                <div className="text-center px-8">
                  <p className="font-black text-xl mb-1 opacity-40">Postural Interface Standby</p>
                  <p className="text-slate-500 text-xs font-bold uppercase tracking-widest">Connect camera to begin spinal mapping</p>
                </div>
              </div>
            )}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm group hover:border-indigo-100 transition-colors">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Cobb Index (Est)</p>
              <p className="text-5xl font-black text-slate-800">
                {analysis?.estimatedCobbAngle ? analysis.estimatedCobbAngle.toFixed(1) : '--'}
                <span className="text-3xl ml-1 text-slate-300">°</span>
              </p>
            </div>
            <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm group hover:border-indigo-100 transition-colors">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Clinical Severity</p>
              <p className={`text-5xl font-black ${analysis?.severity === 'Severe' ? 'text-red-600' : 'text-slate-800'}`}>
                {analysis?.severity || '--'}
              </p>
            </div>
            <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm group hover:border-indigo-100 transition-colors">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Stability</p>
              <p className="text-5xl font-black text-indigo-600">
                {analysis ? Math.round(analysis.alignmentScore) : '--'}
                <span className="text-3xl ml-1 opacity-50">%</span>
              </p>
            </div>
          </div>
        </div>

        {/* Sidebar: Diagnostics Feed */}
        <div className="w-full xl:w-96 flex flex-col gap-6">
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-lg flex flex-col h-[400px]">
            <div className="flex items-center justify-between mb-6 border-b border-slate-50 pb-4">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><ShieldCheck size={24} className="text-indigo-600" /> Diagnostic Feed</h3>
              {isAnalyzing && <RefreshCw size={16} className="text-indigo-400 animate-spin" />}
            </div>

            <div className="space-y-4 overflow-y-auto flex-1 pr-2 custom-scrollbar">
              {sessionLogs.length > 0 ? sessionLogs.map((log, i) => (
                <div key={i} className={`p-5 rounded-2xl border animate-in slide-in-from-right-4 transition-all ${i === 0 ? 'bg-indigo-50 border-indigo-100' : 'bg-slate-50 border-slate-50 opacity-60'}`}>
                  <div className="flex justify-between items-start mb-2">
                    <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">{log.time}</span>
                    <span className={`text-[9px] font-black px-2 py-0.5 rounded shadow-sm ${log.severity === 'Severe' ? 'bg-red-500 text-white' : 'bg-slate-200 text-slate-600'}`}>
                      {log.severity}
                    </span>
                  </div>
                  <p className="text-xs font-bold text-slate-800 leading-relaxed italic">"{log.text}"</p>
                </div>
              )) : (
                <div className="flex flex-col items-center justify-center py-20 text-slate-300 text-center">
                  <Focus size={32} className="mb-2 opacity-20" />
                  <p className="text-xs font-black uppercase tracking-widest opacity-40">Interface Idle</p>
                </div>
              )}
            </div>
          </div>

          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-lg flex-1 min-h-[250px]">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-sm font-black text-slate-800 flex items-center gap-2"><LineChartIcon size={20} className="text-indigo-600" /> Postural Trend</h3>
            </div>
            <div className="h-40 w-full">
              {sessionHistory.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={sessionHistory}>
                    <defs>
                      <linearGradient id="colorScoreLive" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#6366f1" stopOpacity={0.2}/>
                        <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <YAxis domain={[0, 100]} hide />
                    <Area type="monotone" dataKey="score" stroke="#6366f1" strokeWidth={3} fillOpacity={1} fill="url(#colorScoreLive)" />
                    <ReferenceLine y={85} stroke="#10b981" strokeDasharray="3 3" />
                  </AreaChart>
                </ResponsiveContainer>
              ) : (
                <div className="h-full flex flex-col items-center justify-center text-slate-200">
                  <ActivityIcon size={40} className="opacity-10" />
                </div>
              )}
            </div>
            <div className="mt-4 flex items-center gap-3 bg-emerald-50 px-4 py-3 rounded-2xl border border-emerald-100">
               <ShieldCheck size={16} className="text-emerald-500" />
               <p className="text-[10px] font-bold text-emerald-700 leading-tight tracking-tight">AI accuracy boosted. Visual markers mapping anatomical vertex points.</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PostureLiveView;

import React, { useEffect, useRef, useState } from 'react';
import { 
  Play, 
  Square, 
  RefreshCw, 
  ShieldCheck, 
  AlertTriangle,
  CameraOff,
  User,
  ZapOff,
  FileDown,
  Activity as ActivityIcon,
  Focus,
  LineChart as LineChartIcon,
  CheckCircle
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";
import { PostureAnalysis, Landmark, ScoliosisSeverity, PatientRecord } from '../types';
import { AreaChart, Area, YAxis, XAxis, ResponsiveContainer, ReferenceLine } from 'recharts';

interface PostureLiveViewProps {
  onSaveReport?: (record: PatientRecord) => void;
}

interface SessionDataPoint {
  time: string;
  timestamp: number;
  score: number;
  angle: number;
}

const PostureLiveView: React.FC<PostureLiveViewProps> = ({ onSaveReport }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isActive, setIsActive] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<PostureAnalysis | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [quotaExhausted, setQuotaExhausted] = useState(false);
  const [cooldownRemaining, setCooldownRemaining] = useState(0);
  const [patientName, setPatientName] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  const [sessionHistory, setSessionHistory] = useState<SessionDataPoint[]>([]);
  const [sessionLogs, setSessionLogs] = useState<{time: string, text: string, severity: string}[]>([]);

  // Timer for cooldown if 429 occurs
  useEffect(() => {
    let timer: number;
    if (cooldownRemaining > 0) {
      timer = window.setInterval(() => {
        setCooldownRemaining(prev => Math.max(0, prev - 1));
      }, 1000);
    } else if (quotaExhausted) {
      setQuotaExhausted(false);
      setError(null);
    }
    return () => clearInterval(timer);
  }, [cooldownRemaining, quotaExhausted]);

  const toggleMonitoring = async () => {
    if (isActive) {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
      setIsActive(false);
      setAnalysis(null);
      setQuotaExhausted(false);
      setCooldownRemaining(0);
      setSessionHistory([]);
      setSessionLogs([]);
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsActive(true);
          setError(null);
        }
      } catch (err) {
        setError("Camera access is required for real-time monitoring.");
      }
    }
  };

  const archiveSession = async () => {
    if (!analysis || !onSaveReport) return;
    if (!patientName.trim()) {
      setError("Please enter a patient name to archive this session.");
      return;
    }

    setIsSaving(true);
    try {
      const snapshotCanvas = document.createElement('canvas');
      snapshotCanvas.width = 640;
      snapshotCanvas.height = 480;
      const sCtx = snapshotCanvas.getContext('2d');
      if (sCtx && videoRef.current) {
        sCtx.drawImage(videoRef.current, 0, 0, 640, 480);
        if (canvasRef.current) {
          sCtx.drawImage(canvasRef.current, 0, 0, 640, 480);
        }
      }
      const dataUrl = snapshotCanvas.toDataURL('image/jpeg', 0.7);

      const record: PatientRecord = {
        id: Math.random().toString(36).substr(2, 9),
        patientName: patientName,
        timestamp: new Date().toISOString(),
        cobbAngle: analysis.estimatedCobbAngle || 0,
        severity: analysis.severity || ScoliosisSeverity.NORMAL,
        recommendations: analysis.recommendations || [],
        visualObservations: analysis.feedback,
        imageUrl: dataUrl,
        source: 'LIVE'
      };

      onSaveReport(record);
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
    } catch (err) {
      setError("Failed to archive session.");
    } finally {
      setIsSaving(false);
    }
  };

  const analyzeFrame = async () => {
    if (!isActive || !videoRef.current || isAnalyzing || quotaExhausted) return;

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `SCOLIOSIS CLINICAL MONITORING. Map anatomical landmarks: Head, LeftShoulder, RightShoulder, SpineMid, LeftHip, RightHip. Return JSON with: landmarks, alignmentScore (0-100), clinicalFeedback (precise 1-sentence diagnostic), isDeviating (bool), estimatedCobbAngle, severity.` }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  }
                }
              },
              alignmentScore: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              isDeviating: { type: Type.BOOLEAN },
              estimatedCobbAngle: { type: Type.NUMBER },
              severity: { type: Type.STRING }
            },
            required: ['landmarks', 'alignmentScore', 'feedback', 'isDeviating', 'estimatedCobbAngle', 'severity']
          }
        }
      });

      const responseText = response.text || '{}';
      const result = JSON.parse(responseText);
      setAnalysis(result);
      setQuotaExhausted(false);
      setError(null);

      const currentTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

      setSessionHistory(prev => [...prev.slice(-19), {
        time: currentTime,
        timestamp: Date.now(),
        score: result.alignmentScore,
        angle: result.estimatedCobbAngle
      }]);

      setSessionLogs(prev => [{
        time: currentTime,
        text: result.feedback,
        severity: result.severity
      }, ...prev.slice(0, 9)]);

    } catch (err: any) {
      if (err.message?.includes("RESOURCE_EXHAUSTED") || err.status === 429) {
        setQuotaExhausted(true);
        setCooldownRemaining(30); // 30 second cooldown
        setError("AI Rate Limit Exceeded. Cooling down to prevent lockout...");
      } else {
        console.error("Analysis Error:", err);
      }
    } finally {
      setIsAnalyzing(false);
    }
  };

  // Poll for analysis every 3 seconds, but back off if quota is hit
  useEffect(() => {
    let timeoutId: number;
    const poll = async () => {
      if (isActive && !quotaExhausted) {
        await analyzeFrame();
      }
      // If we just hit a quota error, wait 30 seconds. Otherwise wait 3 seconds.
      const delay = quotaExhausted ? 30000 : 3000;
      timeoutId = window.setTimeout(poll, delay);
    };

    if (isActive) {
      timeoutId = window.setTimeout(poll, 1000);
    }
    return () => clearTimeout(timeoutId);
  }, [isActive, quotaExhausted]);

  useEffect(() => {
    if (!canvasRef.current || !analysis?.landmarks || !isActive) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const { width, height } = canvasRef.current;
    ctx.clearRect(0, 0, width, height);

    const getPt = (label: string) => 
      analysis.landmarks.find(p => p.label.toLowerCase().replace(/\s/g, '').includes(label.toLowerCase()));

    const scaleX = (x: number) => (x * width) / 100;
    const scaleY = (y: number) => (y * height) / 100;

    const getMarkerColor = (label: string) => {
      const l = label.toLowerCase();
      if (l.includes('head')) return '#fbbf24'; // Amber
      if (l.includes('shoulder')) return '#22d3ee'; // Cyan
      if (l.includes('spine')) return '#f8fafc'; // White
      if (l.includes('hip')) return '#a855f7'; // Purple
      return '#ffffff';
    };

    const drawBiometricSkeleton = () => {
      const head = getPt('head');
      const spine = getPt('spinemid');
      const ls = getPt('leftshoulder');
      const rs = getPt('rightshoulder');
      const lh = getPt('lefthip');
      const rh = getPt('righthip');

      // 1. Spinal Axis (Blue Indicator)
      if (head && spine) {
        ctx.beginPath();
        ctx.lineWidth = 6;
        ctx.strokeStyle = '#3b82f6';
        ctx.lineCap = 'round';
        ctx.globalAlpha = 0.6;
        ctx.moveTo(scaleX(head.x), scaleY(head.y));
        ctx.lineTo(scaleX(spine.x), scaleY(spine.y));
        ctx.stroke();
      }

      // 2. Transverse Alignment (Green/Red Indicators)
      const transverseColor = analysis.isDeviating ? '#ef4444' : '#10b981';
      ctx.lineWidth = 4;
      ctx.strokeStyle = transverseColor;
      ctx.globalAlpha = 0.8;

      if (ls && rs) {
        ctx.beginPath();
        ctx.moveTo(scaleX(ls.x), scaleY(ls.y));
        ctx.lineTo(scaleX(rs.x), scaleY(rs.y));
        ctx.stroke();
      }

      if (lh && rh) {
        ctx.beginPath();
        ctx.moveTo(scaleX(lh.x), scaleY(lh.y));
        ctx.lineTo(scaleX(rh.x), scaleY(rh.y));
        ctx.stroke();
      }

      // 3. Precise Landmark Markers (Colored Dots)
      analysis.landmarks.forEach(j => {
        const jx = scaleX(j.x), jy = scaleY(j.y);
        const color = getMarkerColor(j.label);

        ctx.globalAlpha = 1.0;
        ctx.beginPath();
        ctx.arc(jx, jy, 6, 0, Math.PI * 2);
        ctx.fillStyle = color;
        ctx.shadowBlur = 10;
        ctx.shadowColor = color;
        ctx.fill();
        ctx.stroke();
        ctx.shadowBlur = 0;
      });
    };

    const frame = requestAnimationFrame(drawBiometricSkeleton);
    return () => cancelAnimationFrame(frame);
  }, [analysis, isActive]);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      {/* Session Controls */}
      <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col md:flex-row items-center justify-between gap-6">
        <div className="flex-1 w-full relative">
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Clinical Subject Identity</label>
          <div className="relative">
            <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
            <input 
              type="text" 
              placeholder="Enter Patient Full Name..." 
              value={patientName}
              onChange={(e) => setPatientName(e.target.value)}
              className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none font-bold text-slate-700"
            />
          </div>
        </div>
        <div className="shrink-0">
          <button 
            onClick={archiveSession}
            disabled={!analysis || isSaving}
            className={`flex items-center gap-2 px-8 py-3.5 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${
              saveSuccess 
                ? 'bg-emerald-500 text-white' 
                : !analysis || isSaving 
                ? 'bg-slate-100 text-slate-400 cursor-not-allowed' 
                : 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20 hover:bg-indigo-700'
            }`}
          >
            {saveSuccess ? <CheckCircle size={14} /> : isSaving ? <RefreshCw size={14} className="animate-spin" /> : <FileDown size={14} />}
            {saveSuccess ? 'Report Finalized' : 'Export Findings'}
          </button>
        </div>
      </div>

      {error && (
        <div className={`p-4 rounded-2xl flex items-center gap-4 font-bold text-sm border shadow-sm ${
          quotaExhausted ? 'bg-amber-50 border-amber-200 text-amber-700' : 'bg-red-50 border-red-100 text-red-600'
        }`}>
          {quotaExhausted ? <ZapOff size={20} /> : <AlertTriangle size={20} />}
          <div className="flex-1">
            <p>{error}</p>
            {quotaExhausted && <p className="text-[10px] mt-1 opacity-70">Analysis will resume automatically in {cooldownRemaining}s</p>}
          </div>
        </div>
      )}

      <div className="flex flex-col xl:flex-row gap-8">
        {/* Main Viewport */}
        <div className="flex-1 flex flex-col gap-6">
          <div className="relative bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl aspect-video border-[6px] border-slate-800 group">
            <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity duration-700 ${isActive ? 'opacity-100' : 'opacity-20'}`} />

            <div className="absolute inset-0 pointer-events-none opacity-20 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]"></div>
            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none" width={640} height={480} />

            {isActive && (
              <div className="absolute top-8 left-8 flex items-center gap-3 bg-black/40 backdrop-blur-md px-4 py-2 rounded-xl border border-white/10">
                <div className={`w-2.5 h-2.5 rounded-full animate-pulse shadow-md ${quotaExhausted ? 'bg-amber-500 shadow-amber-500' : 'bg-red-500 shadow-red-500'}`}></div>
                <span className="text-white text-[10px] font-black tracking-widest uppercase">
                  {quotaExhausted ? `Rate Limit Cooling... (${cooldownRemaining}s)` : 'AI Biometric Tracking'}
                </span>
              </div>
            )}

            <div className="absolute bottom-10 left-1/2 -translate-x-1/2 z-20">
              {isActive ? (
                <button 
                  onClick={toggleMonitoring}
                  className="flex items-center gap-4 bg-red-600 hover:bg-red-700 text-white px-10 py-5 rounded-3xl font-black text-sm uppercase tracking-[0.2em] transition-all shadow-2xl shadow-red-900/40"
                >
                  <Square size={20} fill="currentColor" />
                  Terminate Session
                </button>
              ) : (
                <button 
                  onClick={toggleMonitoring}
                  className="flex items-center gap-4 bg-indigo-600 hover:bg-indigo-700 text-white px-12 py-6 rounded-3xl font-black text-sm uppercase tracking-[0.2em] transition-all shadow-2xl shadow-indigo-900/40"
                >
                  <Play size={24} fill="currentColor" />
                  Initiate Live Mapping
                </button>
              )}
            </div>

            {!isActive && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-white space-y-4 pointer-events-none">
                <div className="w-20 h-20 bg-white/5 backdrop-blur-md rounded-[2rem] flex items-center justify-center text-slate-500 border border-white/10"><CameraOff size={40} /></div>
                <div className="text-center px-8">
                  <p className="font-black text-xl mb-1 opacity-40">Optical Engine Offline</p>
                  <p className="text-slate-500 text-[10px] font-bold uppercase tracking-widest">Awaiting clinical session initialization</p>
                </div>
              </div>
            )}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm group">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Geometric Variance</p>
              <p className="text-5xl font-black text-slate-800">
                {analysis?.estimatedCobbAngle ? analysis.estimatedCobbAngle.toFixed(1) : '--'}
                <span className="text-3xl ml-1 text-slate-300">°</span>
              </p>
            </div>
            <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm group">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Scoliosis Class</p>
              <p className={`text-5xl font-black ${analysis?.severity === 'Severe' ? 'text-red-600' : 'text-slate-800'}`}>
                {analysis?.severity || '--'}
              </p>
            </div>
            <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm group">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Optical Stability</p>
              <p className="text-5xl font-black text-indigo-600">
                {analysis ? Math.round(analysis.alignmentScore) : '--'}
                <span className="text-3xl ml-1 opacity-50">%</span>
              </p>
            </div>
          </div>
        </div>

        {/* Sidebar: AI Diagnostics */}
        <div className="w-full xl:w-96 flex flex-col gap-6">
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-lg flex flex-col h-[400px]">
            <div className="flex items-center justify-between mb-6 border-b border-slate-50 pb-4">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><ShieldCheck size={24} className="text-indigo-600" /> AI Findings</h3>
              {isAnalyzing && <RefreshCw size={16} className="text-indigo-400 animate-spin" />}
            </div>

            <div className="space-y-4 overflow-y-auto flex-1 pr-2 custom-scrollbar">
              {sessionLogs.length > 0 ? sessionLogs.map((log, i) => (
                <div key={i} className={`p-5 rounded-2xl border animate-in slide-in-from-right-4 transition-all ${i === 0 ? 'bg-indigo-50 border-indigo-100' : 'bg-slate-50 border-slate-50 opacity-60'}`}>
                  <div className="flex justify-between items-start mb-2">
                    <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">{log.time}</span>
                    <span className={`text-[9px] font-black px-2 py-0.5 rounded shadow-sm ${log.severity === 'Severe' ? 'bg-red-500 text-white' : 'bg-slate-200 text-slate-600'}`}>
                      {log.severity}
                    </span>
                  </div>
                  <p className="text-xs font-bold text-slate-800 leading-relaxed italic">"{log.text}"</p>
                </div>
              )) : (
                <div className="flex flex-col items-center justify-center py-20 text-slate-300 text-center">
                  <Focus size={32} className="mb-2 opacity-20" />
                  <p className="text-xs font-black uppercase tracking-widest opacity-40">Ready for Mapping</p>
                </div>
              )}
            </div>
          </div>

          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-lg flex-1 min-h-[250px]">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-sm font-black text-slate-800 flex items-center gap-2"><LineChartIcon size={20} className="text-indigo-600" /> Postural Trend</h3>
            </div>
            <div className="h-40 w-full">
              {sessionHistory.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={sessionHistory}>
                    <defs>
                      <linearGradient id="colorScoreLive" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#6366f1" stopOpacity={0.2}/>
                        <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <YAxis domain={[0, 100]} hide />
                    <Area type="monotone" dataKey="score" stroke="#6366f1" strokeWidth={3} fillOpacity={1} fill="url(#colorScoreLive)" />
                    <ReferenceLine y={85} stroke="#10b981" strokeDasharray="3 3" />
                  </AreaChart>
                </ResponsiveContainer>
              ) : (
                <div className="h-full flex flex-col items-center justify-center text-slate-200">
                  <ActivityIcon size={40} className="opacity-10" />
                </div>
              )}
            </div>
            <div className="mt-4 flex items-center gap-3 bg-indigo-50 px-4 py-3 rounded-2xl border border-indigo-100">
               <ShieldCheck size={16} className="text-indigo-500" />
               <p className="text-[10px] font-bold text-indigo-700 leading-tight tracking-tight">AI vertex mapping active. Anatomical markers identified for clinical verification.</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PostureLiveView;

import React, { useEffect, useRef, useState } from 'react';
import { 
  Play, 
  Square, 
  RefreshCw, 
  ShieldCheck, 
  AlertTriangle,
  CameraOff,
  User,
  ZapOff,
  FileDown,
  Activity as ActivityIcon,
  Focus,
  LineChart as LineChartIcon,
  CheckCircle
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";
import { PostureAnalysis, Landmark, ScoliosisSeverity, PatientRecord } from '../types';
import { AreaChart, Area, YAxis, XAxis, ResponsiveContainer, ReferenceLine } from 'recharts';

interface PostureLiveViewProps {
  onSaveReport?: (record: PatientRecord) => void;
}

interface SessionDataPoint {
  time: string;
  timestamp: number;
  score: number;
  angle: number;
}

const PostureLiveView: React.FC<PostureLiveViewProps> = ({ onSaveReport }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isActive, setIsActive] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<PostureAnalysis | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [quotaExhausted, setQuotaExhausted] = useState(false);
  const [cooldownRemaining, setCooldownRemaining] = useState(0);
  const [patientName, setPatientName] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  const [sessionHistory, setSessionHistory] = useState<SessionDataPoint[]>([]);
  const [sessionLogs, setSessionLogs] = useState<{time: string, text: string, severity: string}[]>([]);

  // Timer for cooldown if 429 occurs
  useEffect(() => {
    let timer: number;
    if (cooldownRemaining > 0) {
      timer = window.setInterval(() => {
        setCooldownRemaining(prev => Math.max(0, prev - 1));
      }, 1000);
    } else if (quotaExhausted) {
      setQuotaExhausted(false);
      setError(null);
    }
    return () => clearInterval(timer);
  }, [cooldownRemaining, quotaExhausted]);

  const toggleMonitoring = async () => {
    if (isActive) {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
      setIsActive(false);
      setAnalysis(null);
      setQuotaExhausted(false);
      setCooldownRemaining(0);
      setSessionHistory([]);
      setSessionLogs([]);
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsActive(true);
          setError(null);
        }
      } catch (err) {
        setError("Camera access is required for real-time monitoring.");
      }
    }
  };

  const archiveSession = async () => {
    if (!analysis || !onSaveReport) return;
    if (!patientName.trim()) {
      setError("Please enter a patient name to archive this session.");
      return;
    }

    setIsSaving(true);
    try {
      const snapshotCanvas = document.createElement('canvas');
      snapshotCanvas.width = 640;
      snapshotCanvas.height = 480;
      const sCtx = snapshotCanvas.getContext('2d');
      if (sCtx && videoRef.current) {
        sCtx.drawImage(videoRef.current, 0, 0, 640, 480);
        if (canvasRef.current) {
          sCtx.drawImage(canvasRef.current, 0, 0, 640, 480);
        }
      }
      const dataUrl = snapshotCanvas.toDataURL('image/jpeg', 0.7);

      const record: PatientRecord = {
        id: Math.random().toString(36).substr(2, 9),
        patientName: patientName,
        timestamp: new Date().toISOString(),
        cobbAngle: analysis.estimatedCobbAngle || 0,
        severity: analysis.severity || ScoliosisSeverity.NORMAL,
        recommendations: analysis.recommendations || [],
        visualObservations: analysis.feedback,
        imageUrl: dataUrl,
        source: 'LIVE'
      };

      onSaveReport(record);
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
    } catch (err) {
      setError("Failed to archive session.");
    } finally {
      setIsSaving(false);
    }
  };

  const analyzeFrame = async () => {
    if (!isActive || !videoRef.current || isAnalyzing || quotaExhausted) return;

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `SCOLIOSIS CLINICAL MONITORING. Map anatomical landmarks: Head, LeftShoulder, RightShoulder, SpineMid, LeftHip, RightHip. Return JSON with: landmarks, alignmentScore (0-100), clinicalFeedback (precise 1-sentence diagnostic), isDeviating (bool), estimatedCobbAngle, severity.` }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  }
                }
              },
              alignmentScore: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              isDeviating: { type: Type.BOOLEAN },
              estimatedCobbAngle: { type: Type.NUMBER },
              severity: { type: Type.STRING }
            },
            required: ['landmarks', 'alignmentScore', 'feedback', 'isDeviating', 'estimatedCobbAngle', 'severity']
          }
        }
      });

      const responseText = response.text || '{}';
      const result = JSON.parse(responseText);
      setAnalysis(result);
      setQuotaExhausted(false);
      setError(null);

      const currentTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

      setSessionHistory(prev => [...prev.slice(-19), {
        time: currentTime,
        timestamp: Date.now(),
        score: result.alignmentScore,
        angle: result.estimatedCobbAngle
      }]);

      setSessionLogs(prev => [{
        time: currentTime,
        text: result.feedback,
        severity: result.severity
      }, ...prev.slice(0, 9)]);

    } catch (err: any) {
      if (err.message?.includes("RESOURCE_EXHAUSTED") || err.status === 429) {
        setQuotaExhausted(true);
        setCooldownRemaining(30);
        setError("AI Rate Limit Exceeded. Cooling down to prevent lockout...");
      } else {
        console.error("Analysis Error:", err);
      }
    } finally {
      setIsAnalyzing(false);
    }
  };

  useEffect(() => {
    let timeoutId: number;
    const poll = async () => {
      if (isActive && !quotaExhausted) {
        await analyzeFrame();
      }
      const delay = quotaExhausted ? 30000 : 3000;
      timeoutId = window.setTimeout(poll, delay);
    };

    if (isActive) {
      timeoutId = window.setTimeout(poll, 1000);
    }
    return () => clearTimeout(timeoutId);
  }, [isActive, quotaExhausted]);

  useEffect(() => {
    if (!canvasRef.current || !analysis?.landmarks || !isActive) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const { width, height } = canvasRef.current;
    ctx.clearRect(0, 0, width, height);

    const getPt = (label: string) => 
      analysis.landmarks.find(p => p.label.toLowerCase().replace(/\s/g, '').includes(label.toLowerCase()));

    const scaleX = (x: number) => (x * width) / 100;
    const scaleY = (y: number) => (y * height) / 100;

    const getMarkerColor = (label: string) => {
      const l = label.toLowerCase();
      if (l.includes('head')) return '#fbbf24'; 
      if (l.includes('shoulder')) return '#22d3ee'; 
      if (l.includes('spine')) return '#f8fafc'; 
      if (l.includes('hip')) return '#a855f7'; 
      return '#ffffff';
    };

    const drawBiometricSkeleton = () => {
      const head = getPt('head');
      const spineMid = getPt('spinemid');
      const ls = getPt('leftshoulder');
      const rs = getPt('rightshoulder');
      const lh = getPt('lefthip');
      const rh = getPt('righthip');

      // Calculate Center Midpoints
      const midShoulder = (ls && rs) ? { x: (ls.x + rs.x) / 2, y: (ls.y + rs.y) / 2 } : null;
      const midHip = (lh && rh) ? { x: (lh.x + rh.x) / 2, y: (lh.y + rh.y) / 2 } : null;

      // 1. Spinal Axis Curve (Subtle Blue Visual)
      if (head && spineMid && midShoulder && midHip) {
        ctx.beginPath();
        ctx.lineWidth = 4;
        ctx.strokeStyle = '#3b82f6';
        ctx.lineCap = 'round';
        ctx.globalAlpha = 0.5;

        const hX = scaleX(head.x), hY = scaleY(head.y);
        const msX = scaleX(midShoulder.x), msY = scaleY(midShoulder.y);
        const smX = scaleX(spineMid.x), smY = scaleY(spineMid.y);
        const mhX = scaleX(midHip.x), mhY = scaleY(midHip.y);

        ctx.moveTo(hX, hY);
        // Drawing a smooth curve through spine landmarks
        ctx.bezierCurveTo(msX, msY, smX, smY, mhX, mhY);
        ctx.stroke();

        // 2. Cobb Angle Indicator Arc
        if (analysis.estimatedCobbAngle && analysis.estimatedCobbAngle > 5) {
          const arcRadius = 40;
          ctx.beginPath();
          ctx.strokeStyle = analysis.isDeviating ? '#ef4444' : '#10b981';
          ctx.lineWidth = 2;
          ctx.globalAlpha = 0.8;
          // Offset arc slightly from spinemid
          ctx.arc(smX, smY, arcRadius, 1.5 * Math.PI, (1.5 + (analysis.estimatedCobbAngle / 180) * Math.PI) * Math.PI);
          ctx.stroke();

          // Angle Text
          ctx.font = 'bold 12px Inter';
          ctx.fillStyle = analysis.isDeviating ? '#ef4444' : '#10b981';
          ctx.fillText(`${analysis.estimatedCobbAngle.toFixed(1)}° Cobb`, smX + arcRadius + 5, smY);
        }
      }

      // 3. Transverse Alignment (Shoulders & Hips)
      const transverseColor = analysis.isDeviating ? '#ef4444' : '#10b981';
      ctx.lineWidth = 3;
      ctx.strokeStyle = transverseColor;
      ctx.globalAlpha = 0.6;

      if (ls && rs) {
        ctx.beginPath();
        ctx.moveTo(scaleX(ls.x), scaleY(ls.y));
        ctx.lineTo(scaleX(rs.x), scaleY(rs.y));
        ctx.stroke();
      }

      if (lh && rh) {
        ctx.beginPath();
        ctx.moveTo(scaleX(lh.x), scaleY(lh.y));
        ctx.lineTo(scaleX(rh.x), scaleY(rh.y));
        ctx.stroke();
      }

      // 4. Precise Landmark Markers
      analysis.landmarks.forEach(j => {
        const jx = scaleX(j.x), jy = scaleY(j.y);
        const color = getMarkerColor(j.label);

        ctx.globalAlpha = 1.0;
        ctx.beginPath();
        ctx.arc(jx, jy, 5, 0, Math.PI * 2);
        ctx.fillStyle = color;
        ctx.shadowBlur = 8;
        ctx.shadowColor = color;
        ctx.fill();
        ctx.stroke();
        ctx.shadowBlur = 0;
      });
    };

    const frame = requestAnimationFrame(drawBiometricSkeleton);
    return () => cancelAnimationFrame(frame);
  }, [analysis, isActive]);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col md:flex-row items-center justify-between gap-6">
        <div className="flex-1 w-full relative">
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Clinical Subject Identity</label>
          <div className="relative">
            <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
            <input 
              type="text" 
              placeholder="Enter Patient Full Name..." 
              value={patientName}
              onChange={(e) => setPatientName(e.target.value)}
              className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none font-bold text-slate-700"
            />
          </div>
        </div>
        <div className="shrink-0">
          <button 
            onClick={archiveSession}
            disabled={!analysis || isSaving}
            className={`flex items-center gap-2 px-8 py-3.5 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${
              saveSuccess 
                ? 'bg-emerald-500 text-white' 
                : !analysis || isSaving 
                ? 'bg-slate-100 text-slate-400 cursor-not-allowed' 
                : 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20 hover:bg-indigo-700'
            }`}
          >
            {saveSuccess ? <CheckCircle size={14} /> : isSaving ? <RefreshCw size={14} className="animate-spin" /> : <FileDown size={14} />}
            {saveSuccess ? 'Report Finalized' : 'Export Findings'}
          </button>
        </div>
      </div>

      {error && (
        <div className={`p-4 rounded-2xl flex items-center gap-4 font-bold text-sm border shadow-sm ${
          quotaExhausted ? 'bg-amber-50 border-amber-200 text-amber-700' : 'bg-red-50 border-red-100 text-red-600'
        }`}>
          {quotaExhausted ? <ZapOff size={20} /> : <AlertTriangle size={20} />}
          <div className="flex-1">
            <p>{error}</p>
            {quotaExhausted && <p className="text-[10px] mt-1 opacity-70">Analysis will resume automatically in {cooldownRemaining}s</p>}
          </div>
        </div>
      )}

      <div className="flex flex-col xl:flex-row gap-8">
        <div className="flex-1 flex flex-col gap-6">
          <div className="relative bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl aspect-video border-[6px] border-slate-800 group">
            <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity duration-700 ${isActive ? 'opacity-100' : 'opacity-20'}`} />
            <div className="absolute inset-0 pointer-events-none opacity-20 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]"></div>
            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none" width={640} height={480} />

            {isActive && (
              <div className="absolute top-8 left-8 flex items-center gap-3 bg-black/40 backdrop-blur-md px-4 py-2 rounded-xl border border-white/10">
                <div className={`w-2.5 h-2.5 rounded-full animate-pulse shadow-md ${quotaExhausted ? 'bg-amber-500 shadow-amber-500' : 'bg-red-500 shadow-red-500'}`}></div>
                <span className="text-white text-[10px] font-black tracking-widest uppercase">
                  {quotaExhausted ? `Rate Limit Cooling... (${cooldownRemaining}s)` : 'AI Biometric Tracking'}
                </span>
              </div>
            )}

            <div className="absolute bottom-10 left-1/2 -translate-x-1/2 z-20">
              {isActive ? (
                <button 
                  onClick={toggleMonitoring}
                  className="flex items-center gap-4 bg-red-600 hover:bg-red-700 text-white px-10 py-5 rounded-3xl font-black text-sm uppercase tracking-[0.2em] transition-all shadow-2xl shadow-red-900/40"
                >
                  <Square size={20} fill="currentColor" />
                  Terminate Session
                </button>
              ) : (
                <button 
                  onClick={toggleMonitoring}
                  className="flex items-center gap-4 bg-indigo-600 hover:bg-indigo-700 text-white px-12 py-6 rounded-3xl font-black text-sm uppercase tracking-[0.2em] transition-all shadow-2xl shadow-indigo-900/40"
                >
                  <Play size={24} fill="currentColor" />
                  Initiate Live Mapping
                </button>
              )}
            </div>

            {!isActive && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-white space-y-4 pointer-events-none">
                <div className="w-20 h-20 bg-white/5 backdrop-blur-md rounded-[2rem] flex items-center justify-center text-slate-500 border border-white/10"><CameraOff size={40} /></div>
                <div className="text-center px-8">
                  <p className="font-black text-xl mb-1 opacity-40">Optical Engine Offline</p>
                  <p className="text-slate-500 text-[10px] font-bold uppercase tracking-widest">Awaiting clinical session initialization</p>
                </div>
              </div>
            )}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm group">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Geometric Variance</p>
              <p className="text-5xl font-black text-slate-800">
                {analysis?.estimatedCobbAngle ? analysis.estimatedCobbAngle.toFixed(1) : '--'}
                <span className="text-3xl ml-1 text-slate-300">°</span>
              </p>
            </div>
            <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm group">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Scoliosis Class</p>
              <p className={`text-5xl font-black ${analysis?.severity === 'Severe' ? 'text-red-600' : 'text-slate-800'}`}>
                {analysis?.severity || '--'}
              </p>
            </div>
            <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm group">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Optical Stability</p>
              <p className="text-5xl font-black text-indigo-600">
                {analysis ? Math.round(analysis.alignmentScore) : '--'}
                <span className="text-3xl ml-1 opacity-50">%</span>
              </p>
            </div>
          </div>
        </div>

        <div className="w-full xl:w-96 flex flex-col gap-6">
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-lg flex flex-col h-[400px]">
            <div className="flex items-center justify-between mb-6 border-b border-slate-50 pb-4">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><ShieldCheck size={24} className="text-indigo-600" /> AI Findings</h3>
              {isAnalyzing && <RefreshCw size={16} className="text-indigo-400 animate-spin" />}
            </div>

            <div className="space-y-4 overflow-y-auto flex-1 pr-2 custom-scrollbar">
              {sessionLogs.length > 0 ? sessionLogs.map((log, i) => (
                <div key={i} className={`p-5 rounded-2xl border animate-in slide-in-from-right-4 transition-all ${i === 0 ? 'bg-indigo-50 border-indigo-100' : 'bg-slate-50 border-slate-50 opacity-60'}`}>
                  <div className="flex justify-between items-start mb-2">
                    <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">{log.time}</span>
                    <span className={`text-[9px] font-black px-2 py-0.5 rounded shadow-sm ${log.severity === 'Severe' ? 'bg-red-500 text-white' : 'bg-slate-200 text-slate-600'}`}>
                      {log.severity}
                    </span>
                  </div>
                  <p className="text-xs font-bold text-slate-800 leading-relaxed italic">"{log.text}"</p>
                </div>
              )) : (
                <div className="flex flex-col items-center justify-center py-20 text-slate-300 text-center">
                  <Focus size={32} className="mb-2 opacity-20" />
                  <p className="text-xs font-black uppercase tracking-widest opacity-40">Ready for Mapping</p>
                </div>
              )}
            </div>
          </div>

          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-lg flex-1 min-h-[250px]">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-sm font-black text-slate-800 flex items-center gap-2"><LineChartIcon size={20} className="text-indigo-600" /> Postural Trend</h3>
            </div>
            <div className="h-40 w-full">
              {sessionHistory.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={sessionHistory}>
                    <defs>
                      <linearGradient id="colorScoreLive" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#6366f1" stopOpacity={0.2}/>
                        <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <YAxis domain={[0, 100]} hide />
                    <Area type="monotone" dataKey="score" stroke="#6366f1" strokeWidth={3} fillOpacity={1} fill="url(#colorScoreLive)" />
                    <ReferenceLine y={85} stroke="#10b981" strokeDasharray="3 3" />
                  </AreaChart>
                </ResponsiveContainer>
              ) : (
                <div className="h-full flex flex-col items-center justify-center text-slate-200">
                  <ActivityIcon size={40} className="opacity-10" />
                </div>
              )}
            </div>
            <div className="mt-4 flex items-center gap-3 bg-indigo-50 px-4 py-3 rounded-2xl border border-indigo-100">
               <ShieldCheck size={16} className="text-indigo-500" />
               <p className="text-[10px] font-bold text-indigo-700 leading-tight tracking-tight">AI vertex mapping active. Anatomical markers identified for clinical verification.</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PostureLiveView;

import React, { useEffect, useRef, useState } from 'react';
import { 
  Play, 
  Square, 
  RefreshCw, 
  ShieldCheck, 
  AlertTriangle,
  CameraOff,
  User,
  ZapOff,
  FileDown,
  Activity as ActivityIcon,
  Focus,
  LineChart as LineChartIcon,
  CheckCircle,
  Stethoscope
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";
import { PostureAnalysis, Landmark, ScoliosisSeverity, PatientRecord } from '../types';
import { AreaChart, Area, YAxis, XAxis, ResponsiveContainer, ReferenceLine } from 'recharts';

interface PostureLiveViewProps {
  onSaveReport?: (record: PatientRecord) => void;
}

interface SessionDataPoint {
  time: string;
  timestamp: number;
  score: number;
  angle: number;
}

const PostureLiveView: React.FC<PostureLiveViewProps> = ({ onSaveReport }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isActive, setIsActive] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<PostureAnalysis | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [quotaExhausted, setQuotaExhausted] = useState(false);
  const [cooldownRemaining, setCooldownRemaining] = useState(0);
  const [patientName, setPatientName] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  const [sessionHistory, setSessionHistory] = useState<SessionDataPoint[]>([]);
  const [sessionLogs, setSessionLogs] = useState<{time: string, text: string, severity: string}[]>([]);

  // Timer for cooldown if 429 occurs
  useEffect(() => {
    let timer: number;
    if (cooldownRemaining > 0) {
      timer = window.setInterval(() => {
        setCooldownRemaining(prev => Math.max(0, prev - 1));
      }, 1000);
    } else if (quotaExhausted) {
      setQuotaExhausted(false);
      setError(null);
    }
    return () => clearInterval(timer);
  }, [cooldownRemaining, quotaExhausted]);

  const toggleMonitoring = async () => {
    if (isActive) {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
      setIsActive(false);
      setAnalysis(null);
      setQuotaExhausted(false);
      setCooldownRemaining(0);
      setSessionHistory([]);
      setSessionLogs([]);
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsActive(true);
          setError(null);
        }
      } catch (err) {
        setError("Camera access is required for real-time monitoring.");
      }
    }
  };

  const archiveSession = async () => {
    if (!analysis || !onSaveReport) return;
    if (!patientName.trim()) {
      setError("Please enter a patient name to archive this session.");
      return;
    }

    setIsSaving(true);
    try {
      const snapshotCanvas = document.createElement('canvas');
      snapshotCanvas.width = 640;
      snapshotCanvas.height = 480;
      const sCtx = snapshotCanvas.getContext('2d');
      if (sCtx && videoRef.current) {
        sCtx.drawImage(videoRef.current, 0, 0, 640, 480);
        if (canvasRef.current) {
          sCtx.drawImage(canvasRef.current, 0, 0, 640, 480);
        }
      }
      const dataUrl = snapshotCanvas.toDataURL('image/jpeg', 0.7);

      const record: PatientRecord = {
        id: Math.random().toString(36).substr(2, 9),
        patientName: patientName,
        timestamp: new Date().toISOString(),
        cobbAngle: analysis.estimatedCobbAngle || 0,
        severity: analysis.severity || ScoliosisSeverity.NORMAL,
        recommendations: analysis.recommendations || [],
        visualObservations: analysis.feedback,
        imageUrl: dataUrl,
        source: 'LIVE'
      };

      onSaveReport(record);
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
    } catch (err) {
      setError("Failed to archive session.");
    } finally {
      setIsSaving(false);
    }
  };

  const analyzeFrame = async () => {
    if (!isActive || !videoRef.current || isAnalyzing || quotaExhausted) return;

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `SCOLIOSIS CLINICAL MONITORING. Map anatomical landmarks: Head, LeftShoulder, RightShoulder, SpineMid, LeftHip, RightHip. Return JSON with: landmarks, alignmentScore (0-100), clinicalFeedback (precise 1-sentence diagnostic), isDeviating (bool), estimatedCobbAngle, severity, recommendations (array of 3 specific therapeutic exercises).` }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  }
                }
              },
              alignmentScore: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              isDeviating: { type: Type.BOOLEAN },
              estimatedCobbAngle: { type: Type.NUMBER },
              severity: { type: Type.STRING },
              recommendations: { type: Type.ARRAY, items: { type: Type.STRING } }
            },
            required: ['landmarks', 'alignmentScore', 'feedback', 'isDeviating', 'estimatedCobbAngle', 'severity', 'recommendations']
          }
        }
      });

      const responseText = response.text || '{}';
      const result = JSON.parse(responseText);
      setAnalysis(result);
      setQuotaExhausted(false);
      setError(null);

      const currentTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

      setSessionHistory(prev => [...prev.slice(-19), {
        time: currentTime,
        timestamp: Date.now(),
        score: result.alignmentScore,
        angle: result.estimatedCobbAngle
      }]);

      setSessionLogs(prev => [{
        time: currentTime,
        text: result.feedback,
        severity: result.severity
      }, ...prev.slice(0, 9)]);

    } catch (err: any) {
      if (err.message?.includes("RESOURCE_EXHAUSTED") || err.status === 429) {
        setQuotaExhausted(true);
        setCooldownRemaining(30);
        setError("AI Rate Limit Exceeded. Cooling down to prevent lockout...");
      } else {
        console.error("Analysis Error:", err);
      }
    } finally {
      setIsAnalyzing(false);
    }
  };

  useEffect(() => {
    let timeoutId: number;
    const poll = async () => {
      if (isActive && !quotaExhausted) {
        await analyzeFrame();
      }
      const delay = quotaExhausted ? 30000 : 3000;
      timeoutId = window.setTimeout(poll, delay);
    };

    if (isActive) {
      timeoutId = window.setTimeout(poll, 1000);
    }
    return () => clearTimeout(timeoutId);
  }, [isActive, quotaExhausted]);

  useEffect(() => {
    if (!canvasRef.current || !analysis?.landmarks || !isActive) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const { width, height } = canvasRef.current;
    ctx.clearRect(0, 0, width, height);

    const getPt = (label: string) => 
      analysis.landmarks.find(p => p.label.toLowerCase().replace(/\s/g, '').includes(label.toLowerCase()));

    const scaleX = (x: number) => (x * width) / 100;
    const scaleY = (y: number) => (y * height) / 100;

    const getMarkerColor = (label: string) => {
      const l = label.toLowerCase();
      if (l.includes('head')) return '#fbbf24'; 
      if (l.includes('shoulder')) return '#22d3ee'; 
      if (l.includes('spine')) return '#f8fafc'; 
      if (l.includes('hip')) return '#a855f7'; 
      return '#ffffff';
    };

    const drawBiometricSkeleton = () => {
      const head = getPt('head');
      const spineMid = getPt('spinemid');
      const ls = getPt('leftshoulder');
      const rs = getPt('rightshoulder');
      const lh = getPt('lefthip');
      const rh = getPt('righthip');

      const midShoulder = (ls && rs) ? { x: (ls.x + rs.x) / 2, y: (ls.y + rs.y) / 2 } : null;
      const midHip = (lh && rh) ? { x: (lh.x + rh.x) / 2, y: (lh.y + rh.y) / 2 } : null;

      if (head && spineMid && midShoulder && midHip) {
        ctx.beginPath();
        ctx.lineWidth = 4;
        ctx.strokeStyle = '#3b82f6';
        ctx.lineCap = 'round';
        ctx.globalAlpha = 0.5;

        const hX = scaleX(head.x), hY = scaleY(head.y);
        const msX = scaleX(midShoulder.x), msY = scaleY(midShoulder.y);
        const smX = scaleX(spineMid.x), smY = scaleY(spineMid.y);
        const mhX = scaleX(midHip.x), mhY = scaleY(midHip.y);

        ctx.moveTo(hX, hY);
        ctx.bezierCurveTo(msX, msY, smX, smY, mhX, mhY);
        ctx.stroke();

        if (analysis.estimatedCobbAngle && analysis.estimatedCobbAngle > 5) {
          const arcRadius = 40;
          ctx.beginPath();
          ctx.strokeStyle = analysis.isDeviating ? '#ef4444' : '#10b981';
          ctx.lineWidth = 2;
          ctx.globalAlpha = 0.8;
          ctx.arc(smX, smY, arcRadius, 1.5 * Math.PI, (1.5 + (analysis.estimatedCobbAngle / 180) * Math.PI) * Math.PI);
          ctx.stroke();

          ctx.font = 'bold 12px Inter';
          ctx.fillStyle = analysis.isDeviating ? '#ef4444' : '#10b981';
          ctx.fillText(`${analysis.estimatedCobbAngle.toFixed(1)}° Cobb`, smX + arcRadius + 5, smY);
        }
      }

      const transverseColor = analysis.isDeviating ? '#ef4444' : '#10b981';
      ctx.lineWidth = 3;
      ctx.strokeStyle = transverseColor;
      ctx.globalAlpha = 0.6;

      if (ls && rs) {
        ctx.beginPath();
        ctx.moveTo(scaleX(ls.x), scaleY(ls.y));
        ctx.lineTo(scaleX(rs.x), scaleY(rs.y));
        ctx.stroke();
      }

      if (lh && rh) {
        ctx.beginPath();
        ctx.moveTo(scaleX(lh.x), scaleY(lh.y));
        ctx.lineTo(scaleX(rh.x), scaleY(rh.y));
        ctx.stroke();
      }

      analysis.landmarks.forEach(j => {
        const jx = scaleX(j.x), jy = scaleY(j.y);
        const color = getMarkerColor(j.label);

        ctx.globalAlpha = 1.0;
        ctx.beginPath();
        ctx.arc(jx, jy, 5, 0, Math.PI * 2);
        ctx.fillStyle = color;
        ctx.shadowBlur = 8;
        ctx.shadowColor = color;
        ctx.fill();
        ctx.stroke();
        ctx.shadowBlur = 0;
      });
    };

    const frame = requestAnimationFrame(drawBiometricSkeleton);
    return () => cancelAnimationFrame(frame);
  }, [analysis, isActive]);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col md:flex-row items-center justify-between gap-6">
        <div className="flex-1 w-full relative">
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Clinical Subject Identity</label>
          <div className="relative">
            <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
            <input 
              type="text" 
              placeholder="Enter Patient Full Name..." 
              value={patientName}
              onChange={(e) => setPatientName(e.target.value)}
              className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none font-bold text-slate-700"
            />
          </div>
        </div>
        <div className="shrink-0">
          <button 
            onClick={archiveSession}
            disabled={!analysis || isSaving}
            className={`flex items-center gap-2 px-8 py-3.5 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${
              saveSuccess 
                ? 'bg-emerald-500 text-white' 
                : !analysis || isSaving 
                ? 'bg-slate-100 text-slate-400 cursor-not-allowed' 
                : 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20 hover:bg-indigo-700'
            }`}
          >
            {saveSuccess ? <CheckCircle size={14} /> : isSaving ? <RefreshCw size={14} className="animate-spin" /> : <FileDown size={14} />}
            {saveSuccess ? 'Report Finalized' : 'Export Findings'}
          </button>
        </div>
      </div>

      {error && (
        <div className={`p-4 rounded-2xl flex items-center gap-4 font-bold text-sm border shadow-sm ${
          quotaExhausted ? 'bg-amber-50 border-amber-200 text-amber-700' : 'bg-red-50 border-red-100 text-red-600'
        }`}>
          {quotaExhausted ? <ZapOff size={20} /> : <AlertTriangle size={20} />}
          <div className="flex-1">
            <p>{error}</p>
            {quotaExhausted && <p className="text-[10px] mt-1 opacity-70">Analysis will resume automatically in {cooldownRemaining}s</p>}
          </div>
        </div>
      )}

      <div className="flex flex-col xl:flex-row gap-8">
        <div className="flex-1 flex flex-col gap-6">
          <div className="relative bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl aspect-video border-[6px] border-slate-800 group">
            <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity duration-700 ${isActive ? 'opacity-100' : 'opacity-20'}`} />
            <div className="absolute inset-0 pointer-events-none opacity-20 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]"></div>
            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none" width={640} height={480} />

            {isActive && (
              <div className="absolute top-8 left-8 flex items-center gap-3 bg-black/40 backdrop-blur-md px-4 py-2 rounded-xl border border-white/10">
                <div className={`w-2.5 h-2.5 rounded-full animate-pulse shadow-md ${quotaExhausted ? 'bg-amber-500 shadow-amber-500' : 'bg-red-500 shadow-red-500'}`}></div>
                <span className="text-white text-[10px] font-black tracking-widest uppercase">
                  {quotaExhausted ? `Rate Limit Cooling... (${cooldownRemaining}s)` : 'AI Biometric Tracking'}
                </span>
              </div>
            )}

            <div className="absolute bottom-10 left-1/2 -translate-x-1/2 z-20">
              {isActive ? (
                <button 
                  onClick={toggleMonitoring}
                  className="flex items-center gap-4 bg-red-600 hover:bg-red-700 text-white px-10 py-5 rounded-3xl font-black text-sm uppercase tracking-[0.2em] transition-all shadow-2xl shadow-red-900/40"
                >
                  <Square size={20} fill="currentColor" />
                  Terminate Session
                </button>
              ) : (
                <button 
                  onClick={toggleMonitoring}
                  className="flex items-center gap-4 bg-indigo-600 hover:bg-indigo-700 text-white px-12 py-6 rounded-3xl font-black text-sm uppercase tracking-[0.2em] transition-all shadow-2xl shadow-indigo-900/40"
                >
                  <Play size={24} fill="currentColor" />
                  Initiate Live Mapping
                </button>
              )}
            </div>

            {!isActive && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-white space-y-4 pointer-events-none">
                <div className="w-20 h-20 bg-white/5 backdrop-blur-md rounded-[2rem] flex items-center justify-center text-slate-500 border border-white/10"><CameraOff size={40} /></div>
                <div className="text-center px-8">
                  <p className="font-black text-xl mb-1 opacity-40">Optical Engine Offline</p>
                  <p className="text-slate-500 text-[10px] font-bold uppercase tracking-widest">Awaiting clinical session initialization</p>
                </div>
              </div>
            )}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm group">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Geometric Variance</p>
              <div className="flex items-baseline">
                <p className="text-5xl font-black text-slate-800 truncate">
                  {analysis?.estimatedCobbAngle ? analysis.estimatedCobbAngle.toFixed(1) : '--'}
                </p>
                <span className="text-3xl ml-1 text-slate-300 font-black">°</span>
              </div>
            </div>
            <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm group overflow-hidden">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Scoliosis Class</p>
              <p className={`text-4xl lg:text-5xl font-black truncate leading-tight ${analysis?.severity === 'Severe' ? 'text-red-600' : 'text-slate-800'}`}>
                {analysis?.severity || '--'}
              </p>
            </div>
            <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm group">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Optical Stability</p>
              <div className="flex items-baseline">
                <p className="text-5xl font-black text-indigo-600 truncate">
                  {analysis ? Math.round(analysis.alignmentScore) : '--'}
                </p>
                <span className="text-3xl ml-1 opacity-50 font-black text-indigo-600">%</span>
              </div>
            </div>
          </div>
        </div>

        <div className="w-full xl:w-96 flex flex-col gap-6">
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-lg flex flex-col h-[350px]">
            <div className="flex items-center justify-between mb-6 border-b border-slate-50 pb-4 shrink-0">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><ShieldCheck size={24} className="text-indigo-600" /> AI Findings</h3>
              {isAnalyzing && <RefreshCw size={16} className="text-indigo-400 animate-spin" />}
            </div>

            <div className="space-y-4 overflow-y-auto flex-1 pr-2 custom-scrollbar">
              {sessionLogs.length > 0 ? sessionLogs.map((log, i) => (
                <div key={i} className={`p-5 rounded-2xl border animate-in slide-in-from-right-4 transition-all ${i === 0 ? 'bg-indigo-50 border-indigo-100' : 'bg-slate-50 border-slate-50 opacity-60'}`}>
                  <div className="flex justify-between items-start mb-2">
                    <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">{log.time}</span>
                    <span className={`text-[9px] font-black px-2 py-0.5 rounded shadow-sm ${log.severity === 'Severe' ? 'bg-red-500 text-white' : 'bg-slate-200 text-slate-600'}`}>
                      {log.severity}
                    </span>
                  </div>
                  <p className="text-xs font-bold text-slate-800 leading-relaxed italic">"{log.text}"</p>
                </div>
              )) : (
                <div className="flex flex-col items-center justify-center h-full text-slate-300 text-center">
                  <Focus size={32} className="mb-2 opacity-20" />
                  <p className="text-xs font-black uppercase tracking-widest opacity-40">Ready for Mapping</p>
                </div>
              )}
            </div>
          </div>

          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-lg flex flex-col h-[350px]">
            <div className="flex items-center justify-between mb-6 border-b border-slate-50 pb-4 shrink-0">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><Stethoscope size={24} className="text-emerald-500" /> Recommended Protocol</h3>
            </div>
            <div className="space-y-3 overflow-y-auto flex-1 pr-2 custom-scrollbar">
              {analysis?.recommendations && analysis.recommendations.length > 0 ? analysis.recommendations.map((rec, i) => (
                <div key={i} className="bg-emerald-50/50 border border-emerald-100 p-4 rounded-2xl flex items-start gap-3 animate-in fade-in duration-300">
                  <div className="w-6 h-6 rounded-full bg-emerald-100 text-emerald-600 flex items-center justify-center font-black text-[10px] shrink-0 mt-0.5">
                    {i + 1}
                  </div>
                  <p className="text-xs font-bold text-slate-700 leading-tight">{rec}</p>
                </div>
              )) : (
                <div className="flex flex-col items-center justify-center h-full text-slate-300 text-center">
                  <ActivityIcon size={32} className="mb-2 opacity-20" />
                  <p className="text-xs font-black uppercase tracking-widest opacity-40">Awaiting Diagnostics</p>
                </div>
              )}
            </div>
          </div>

          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-lg h-[250px] flex flex-col">
            <div className="flex items-center justify-between mb-6 shrink-0">
              <h3 className="text-sm font-black text-slate-800 flex items-center gap-2"><LineChartIcon size={20} className="text-indigo-600" /> Postural Trend</h3>
            </div>
            <div className="flex-1 w-full overflow-hidden">
              {sessionHistory.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={sessionHistory}>
                    <defs>
                      <linearGradient id="colorScoreLive" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#6366f1" stopOpacity={0.2}/>
                        <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <YAxis domain={[0, 100]} hide />
                    <Area type="monotone" dataKey="score" stroke="#6366f1" strokeWidth={3} fillOpacity={1} fill="url(#colorScoreLive)" />
                    <ReferenceLine y={85} stroke="#10b981" strokeDasharray="3 3" />
                  </AreaChart>
                </ResponsiveContainer>
              ) : (
                <div className="h-full flex flex-col items-center justify-center text-slate-200">
                  <ActivityIcon size={40} className="opacity-10" />
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PostureLiveView;

import React, { useEffect, useRef, useState } from 'react';
import { 
  Play, 
  Square, 
  RefreshCw, 
  ShieldCheck, 
  AlertTriangle,
  CameraOff,
  User,
  ZapOff,
  FileDown,
  Activity as ActivityIcon,
  Focus,
  LineChart as LineChartIcon,
  CheckCircle,
  Stethoscope,
  Info
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";
import { PostureAnalysis, Landmark, ScoliosisSeverity, PatientRecord } from '../types';
import { AreaChart, Area, YAxis, XAxis, ResponsiveContainer, ReferenceLine } from 'recharts';

interface PostureLiveViewProps {
  onSaveReport?: (record: PatientRecord) => void;
}

interface SessionDataPoint {
  time: string;
  timestamp: number;
  score: number;
  angle: number;
}

const PostureLiveView: React.FC<PostureLiveViewProps> = ({ onSaveReport }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isActive, setIsActive] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<PostureAnalysis | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [quotaExhausted, setQuotaExhausted] = useState(false);
  const [cooldownRemaining, setCooldownRemaining] = useState(0);
  const [patientName, setPatientName] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  const [sessionHistory, setSessionHistory] = useState<SessionDataPoint[]>([]);
  const [sessionLogs, setSessionLogs] = useState<{time: string, text: string, severity: string}[]>([]);

  // Timer for cooldown if 429 occurs
  useEffect(() => {
    let timer: number;
    if (cooldownRemaining > 0) {
      timer = window.setInterval(() => {
        setCooldownRemaining(prev => Math.max(0, prev - 1));
      }, 1000);
    } else if (quotaExhausted) {
      setQuotaExhausted(false);
      setError(null);
    }
    return () => clearInterval(timer);
  }, [cooldownRemaining, quotaExhausted]);

  const toggleMonitoring = async () => {
    if (isActive) {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
      setIsActive(false);
      setAnalysis(null);
      setQuotaExhausted(false);
      setCooldownRemaining(0);
      setSessionHistory([]);
      setSessionLogs([]);
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsActive(true);
          setError(null);
        }
      } catch (err) {
        setError("Camera access is required for real-time monitoring.");
      }
    }
  };

  const archiveSession = async () => {
    if (!analysis || !onSaveReport) return;
    if (!patientName.trim()) {
      setError("Please enter a patient name to archive this session.");
      return;
    }

    setIsSaving(true);
    try {
      const snapshotCanvas = document.createElement('canvas');
      snapshotCanvas.width = 640;
      snapshotCanvas.height = 480;
      const sCtx = snapshotCanvas.getContext('2d');
      if (sCtx && videoRef.current) {
        sCtx.drawImage(videoRef.current, 0, 0, 640, 480);
        if (canvasRef.current) {
          sCtx.drawImage(canvasRef.current, 0, 0, 640, 480);
        }
      }
      const dataUrl = snapshotCanvas.toDataURL('image/jpeg', 0.7);

      const record: PatientRecord = {
        id: Math.random().toString(36).substr(2, 9),
        patientName: patientName,
        timestamp: new Date().toISOString(),
        cobbAngle: analysis.estimatedCobbAngle || 0,
        severity: analysis.severity || ScoliosisSeverity.NORMAL,
        recommendations: analysis.recommendations || [],
        visualObservations: analysis.feedback,
        imageUrl: dataUrl,
        source: 'LIVE'
      };

      onSaveReport(record);
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
    } catch (err) {
      setError("Failed to archive session.");
    } finally {
      setIsSaving(false);
    }
  };

  const analyzeFrame = async () => {
    if (!isActive || !videoRef.current || isAnalyzing || quotaExhausted) return;

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `SCOLIOSIS CLINICAL MONITORING. Map anatomical landmarks: Head, LeftShoulder, RightShoulder, SpineMid, LeftHip, RightHip. Return JSON with: landmarks, alignmentScore (0-100), clinicalFeedback (precise 1-sentence diagnostic), isDeviating (bool), estimatedCobbAngle, severity, recommendations (array of 3 specific therapeutic exercises based on the detected curvature).` }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  }
                }
              },
              alignmentScore: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              isDeviating: { type: Type.BOOLEAN },
              estimatedCobbAngle: { type: Type.NUMBER },
              severity: { type: Type.STRING },
              recommendations: { type: Type.ARRAY, items: { type: Type.STRING } }
            },
            required: ['landmarks', 'alignmentScore', 'feedback', 'isDeviating', 'estimatedCobbAngle', 'severity', 'recommendations']
          }
        }
      });

      const responseText = response.text || '{}';
      const result = JSON.parse(responseText);
      setAnalysis(result);
      setQuotaExhausted(false);
      setError(null);

      const currentTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

      setSessionHistory(prev => [...prev.slice(-19), {
        time: currentTime,
        timestamp: Date.now(),
        score: result.alignmentScore,
        angle: result.estimatedCobbAngle
      }]);

      setSessionLogs(prev => [{
        time: currentTime,
        text: result.feedback,
        severity: result.severity
      }, ...prev.slice(0, 9)]);

    } catch (err: any) {
      if (err.message?.includes("RESOURCE_EXHAUSTED") || err.status === 429) {
        setQuotaExhausted(true);
        setCooldownRemaining(30);
        setError("AI Rate Limit Exceeded. Cooling down to prevent lockout...");
      } else {
        console.error("Analysis Error:", err);
      }
    } finally {
      setIsAnalyzing(false);
    }
  };

  useEffect(() => {
    let timeoutId: number;
    const poll = async () => {
      if (isActive && !quotaExhausted) {
        await analyzeFrame();
      }
      const delay = quotaExhausted ? 30000 : 3000;
      timeoutId = window.setTimeout(poll, delay);
    };

    if (isActive) {
      timeoutId = window.setTimeout(poll, 1000);
    }
    return () => clearTimeout(timeoutId);
  }, [isActive, quotaExhausted]);

  useEffect(() => {
    if (!canvasRef.current || !analysis?.landmarks || !isActive) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const { width, height } = canvasRef.current;
    ctx.clearRect(0, 0, width, height);

    const getPt = (label: string) => 
      analysis.landmarks.find(p => p.label.toLowerCase().replace(/\s/g, '').includes(label.toLowerCase()));

    const scaleX = (x: number) => (x * width) / 100;
    const scaleY = (y: number) => (y * height) / 100;

    const getMarkerColor = (label: string) => {
      const l = label.toLowerCase();
      if (l.includes('head')) return '#fbbf24'; 
      if (l.includes('shoulder')) return '#22d3ee'; 
      if (l.includes('spine')) return '#f8fafc'; 
      if (l.includes('hip')) return '#a855f7'; 
      return '#ffffff';
    };

    const drawBiometricSkeleton = () => {
      const head = getPt('head');
      const spineMid = getPt('spinemid');
      const ls = getPt('leftshoulder');
      const rs = getPt('rightshoulder');
      const lh = getPt('lefthip');
      const rh = getPt('righthip');

      const midShoulder = (ls && rs) ? { x: (ls.x + rs.x) / 2, y: (ls.y + rs.y) / 2 } : null;
      const midHip = (lh && rh) ? { x: (lh.x + rh.x) / 2, y: (lh.y + rh.y) / 2 } : null;

      if (head && spineMid && midShoulder && midHip) {
        ctx.beginPath();
        ctx.lineWidth = 4;
        ctx.strokeStyle = '#3b82f6';
        ctx.lineCap = 'round';
        ctx.globalAlpha = 0.5;

        const hX = scaleX(head.x), hY = scaleY(head.y);
        const msX = scaleX(midShoulder.x), msY = scaleY(midShoulder.y);
        const smX = scaleX(spineMid.x), smY = scaleY(spineMid.y);
        const mhX = scaleX(midHip.x), mhY = scaleY(midHip.y);

        ctx.moveTo(hX, hY);
        ctx.bezierCurveTo(msX, msY, smX, smY, mhX, mhY);
        ctx.stroke();

        if (analysis.estimatedCobbAngle && analysis.estimatedCobbAngle > 5) {
          const arcRadius = 40;
          ctx.beginPath();
          ctx.strokeStyle = analysis.isDeviating ? '#ef4444' : '#10b981';
          ctx.lineWidth = 2;
          ctx.globalAlpha = 0.8;
          ctx.arc(smX, smY, arcRadius, 1.5 * Math.PI, (1.5 + (analysis.estimatedCobbAngle / 180) * Math.PI) * Math.PI);
          ctx.stroke();

          ctx.font = 'bold 12px Inter';
          ctx.fillStyle = analysis.isDeviating ? '#ef4444' : '#10b981';
          ctx.fillText(`${analysis.estimatedCobbAngle.toFixed(1)}° Cobb`, smX + arcRadius + 5, smY);
        }
      }

      const transverseColor = analysis.isDeviating ? '#ef4444' : '#10b981';
      ctx.lineWidth = 3;
      ctx.strokeStyle = transverseColor;
      ctx.globalAlpha = 0.6;

      if (ls && rs) {
        ctx.beginPath();
        ctx.moveTo(scaleX(ls.x), scaleY(ls.y));
        ctx.lineTo(scaleX(rs.x), scaleY(rs.y));
        ctx.stroke();
      }

      if (lh && rh) {
        ctx.beginPath();
        ctx.moveTo(scaleX(lh.x), scaleY(lh.y));
        ctx.lineTo(scaleX(rh.x), scaleY(rh.y));
        ctx.stroke();
      }

      analysis.landmarks.forEach(j => {
        const jx = scaleX(j.x), jy = scaleY(j.y);
        const color = getMarkerColor(j.label);

        ctx.globalAlpha = 1.0;
        ctx.beginPath();
        ctx.arc(jx, jy, 5, 0, Math.PI * 2);
        ctx.fillStyle = color;
        ctx.shadowBlur = 8;
        ctx.shadowColor = color;
        ctx.fill();
        ctx.stroke();
        ctx.shadowBlur = 0;
      });
    };

    const frame = requestAnimationFrame(drawBiometricSkeleton);
    return () => cancelAnimationFrame(frame);
  }, [analysis, isActive]);

  const severityLevels = ['Normal', 'Mild', 'Moderate', 'Severe'];

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col md:flex-row items-center justify-between gap-6">
        <div className="flex-1 w-full relative">
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Clinical Subject Identity</label>
          <div className="relative">
            <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
            <input 
              type="text" 
              placeholder="Enter Patient Full Name..." 
              value={patientName}
              onChange={(e) => setPatientName(e.target.value)}
              className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none font-bold text-slate-700"
            />
          </div>
        </div>
        <div className="shrink-0">
          <button 
            onClick={archiveSession}
            disabled={!analysis || isSaving}
            className={`flex items-center gap-2 px-8 py-3.5 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${
              saveSuccess 
                ? 'bg-emerald-500 text-white' 
                : !analysis || isSaving 
                ? 'bg-slate-100 text-slate-400 cursor-not-allowed' 
                : 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20 hover:bg-indigo-700'
            }`}
          >
            {saveSuccess ? <CheckCircle size={14} /> : isSaving ? <RefreshCw size={14} className="animate-spin" /> : <FileDown size={14} />}
            {saveSuccess ? 'Report Finalized' : 'Export Findings'}
          </button>
        </div>
      </div>

      {error && (
        <div className={`p-4 rounded-2xl flex items-center gap-4 font-bold text-sm border shadow-sm ${
          quotaExhausted ? 'bg-amber-50 border-amber-200 text-amber-700' : 'bg-red-50 border-red-100 text-red-600'
        }`}>
          {quotaExhausted ? <ZapOff size={20} /> : <AlertTriangle size={20} />}
          <div className="flex-1">
            <p>{error}</p>
            {quotaExhausted && <p className="text-[10px] mt-1 opacity-70">Analysis will resume automatically in {cooldownRemaining}s</p>}
          </div>
        </div>
      )}

      <div className="flex flex-col xl:flex-row gap-8">
        <div className="flex-1 flex flex-col gap-6">
          <div className="relative bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl aspect-video border-[6px] border-slate-800 group">
            <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity duration-700 ${isActive ? 'opacity-100' : 'opacity-20'}`} />
            <div className="absolute inset-0 pointer-events-none opacity-20 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]"></div>
            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none" width={640} height={480} />

            {isActive && (
              <div className="absolute top-8 left-8 flex items-center gap-3 bg-black/40 backdrop-blur-md px-4 py-2 rounded-xl border border-white/10">
                <div className={`w-2.5 h-2.5 rounded-full animate-pulse shadow-md ${quotaExhausted ? 'bg-amber-500 shadow-amber-500' : 'bg-red-500 shadow-red-500'}`}></div>
                <span className="text-white text-[10px] font-black tracking-widest uppercase">
                  {quotaExhausted ? `Rate Limit Cooling... (${cooldownRemaining}s)` : 'AI Biometric Tracking'}
                </span>
              </div>
            )}

            <div className="absolute bottom-10 left-1/2 -translate-x-1/2 z-20">
              {isActive ? (
                <button 
                  onClick={toggleMonitoring}
                  className="flex items-center gap-4 bg-red-600 hover:bg-red-700 text-white px-10 py-5 rounded-3xl font-black text-sm uppercase tracking-[0.2em] transition-all shadow-2xl shadow-red-900/40"
                >
                  <Square size={20} fill="currentColor" />
