          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-lg h-[200px] flex flex-col">
            <div className="flex items-center justify-between mb-4 shrink-0">
              <h3 className="text-sm font-black text-slate-800 flex items-center gap-2"><LineChartIcon size={20} className="text-indigo-600" /> Alignment Trend</h3>
            </div>
            <div className="flex-1 w-full overflow-hidden">
              {sessionHistory.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={sessionHistory}>
                    <defs>
                      <linearGradient id="colorScoreLive" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#6366f1" stopOpacity={0.2}/>
                        <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <YAxis domain={[0, 100]} hide />
                    <Area type="monotone" dataKey="score" stroke="#6366f1" strokeWidth={3} fillOpacity={1} fill="url(#colorScoreLive)" isAnimationActive={false} />
                    <ReferenceLine y={85} stroke="#10b981" strokeDasharray="3 3" />
