import React, { useEffect, useRef, useState } from 'react';
import { 
  Play, 
  Square, 
  RefreshCw, 
  ShieldCheck, 
  AlertTriangle,
  CameraOff,
  User,
  ZapOff,
  FileDown,
  Activity as ActivityIcon,
  Focus,
  LineChart as LineChartIcon,
  CheckCircle,
  Stethoscope,
  Info
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";
import { PostureAnalysis, Landmark, ScoliosisSeverity, PatientRecord } from '../types';
import { AreaChart, Area, YAxis, XAxis, ResponsiveContainer, ReferenceLine } from 'recharts';

interface PostureLiveViewProps {
  onSaveReport?: (record: PatientRecord) => void;
}

interface SessionDataPoint {
  time: string;
  timestamp: number;
  score: number;
  angle: number;
}

const PostureLiveView: React.FC<PostureLiveViewProps> = ({ onSaveReport }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isActive, setIsActive] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<PostureAnalysis | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [quotaExhausted, setQuotaExhausted] = useState(false);
  const [cooldownRemaining, setCooldownRemaining] = useState(0);
  const [patientName, setPatientName] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  const [sessionHistory, setSessionHistory] = useState<SessionDataPoint[]>([]);
  const [sessionLogs, setSessionLogs] = useState<{time: string, text: string, severity: string}[]>([]);

  // Timer for cooldown if 429 occurs
  useEffect(() => {
    let timer: number;
    if (cooldownRemaining > 0) {
      timer = window.setInterval(() => {
        setCooldownRemaining(prev => Math.max(0, prev - 1));
      }, 1000);
    } else if (quotaExhausted) {
      setQuotaExhausted(false);
      setError(null);
    }
    return () => clearInterval(timer);
  }, [cooldownRemaining, quotaExhausted]);

  const toggleMonitoring = async () => {
    if (isActive) {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
      setIsActive(false);
      setAnalysis(null);
      setQuotaExhausted(false);
      setCooldownRemaining(0);
      setSessionHistory([]);
      setSessionLogs([]);
    } else {
      try {
        // Requested higher resolution (HD 720p) for better landmark precision
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { 
            facingMode: 'user', 
            width: { ideal: 1280 }, 
            height: { ideal: 720 } 
          } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsActive(true);
          setError(null);
        }
      } catch (err) {
        setError("Camera access is required for real-time monitoring.");
      }
    }
  };

  const archiveSession = async () => {
    if (!analysis || !onSaveReport) return;
    if (!patientName.trim()) {
      setError("Please enter a patient name to archive this session.");
      return;
    }

    setIsSaving(true);
    try {
      const snapshotCanvas = document.createElement('canvas');
      // Matched snapshot size to the HD camera feed
      snapshotCanvas.width = 1280;
      snapshotCanvas.height = 720;
      const sCtx = snapshotCanvas.getContext('2d');
      if (sCtx && videoRef.current) {
        sCtx.drawImage(videoRef.current, 0, 0, 1280, 720);
        if (canvasRef.current) {
          sCtx.drawImage(canvasRef.current, 0, 0, 1280, 720);
        }
      }
      const dataUrl = snapshotCanvas.toDataURL('image/jpeg', 0.7);

      const record: PatientRecord = {
        id: Math.random().toString(36).substr(2, 9),
        patientName: patientName,
        timestamp: new Date().toISOString(),
        cobbAngle: analysis.estimatedCobbAngle || 0,
        severity: analysis.severity || ScoliosisSeverity.NORMAL,
        recommendations: analysis.recommendations || [],
        visualObservations: analysis.feedback,
        imageUrl: dataUrl,
        source: 'LIVE'
      };

      onSaveReport(record);
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
    } catch (err) {
      setError("Failed to archive session.");
    } finally {
      setIsSaving(false);
    }
  };

  const analyzeFrame = async () => {
    if (!isActive || !videoRef.current || isAnalyzing || quotaExhausted) return;

    const canvas = document.createElement('canvas');
    // Using 16:9 aspect ratio for analysis frame to match HD feed
    canvas.width = 320;
    canvas.height = 180;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `SCOLIOSIS CLINICAL MONITORING. Map anatomical landmarks: Head, LeftShoulder, RightShoulder, SpineMid, LeftHip, RightHip. Return JSON with: landmarks, alignmentScore (0-100), clinicalFeedback (precise 1-sentence diagnostic), isDeviating (bool), estimatedCobbAngle, severity, recommendations (array of 3 specific therapeutic exercises based on the detected curvature).` }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  }
                }
              },
              alignmentScore: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              isDeviating: { type: Type.BOOLEAN },
              estimatedCobbAngle: { type: Type.NUMBER },
              severity: { type: Type.STRING },
              recommendations: { type: Type.ARRAY, items: { type: Type.STRING } }
            },
            required: ['landmarks', 'alignmentScore', 'feedback', 'isDeviating', 'estimatedCobbAngle', 'severity', 'recommendations']
          }
        }
      });

      const responseText = response.text || '{}';
      const result = JSON.parse(responseText);
      setAnalysis(result);
      setQuotaExhausted(false);
      setError(null);

      const currentTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

      setSessionHistory(prev => [...prev.slice(-19), {
        time: currentTime,
        timestamp: Date.now(),
        score: result.alignmentScore,
        angle: result.estimatedCobbAngle
      }]);

      setSessionLogs(prev => [{
        time: currentTime,
        text: result.feedback,
        severity: result.severity
      }, ...prev.slice(0, 9)]);

    } catch (err: any) {
      if (err.message?.includes("RESOURCE_EXHAUSTED") || err.status === 429) {
        setQuotaExhausted(true);
        setCooldownRemaining(30);
        setError("AI Rate Limit Exceeded. Cooling down to prevent lockout...");
      } else {
        console.error("Analysis Error:", err);
      }
    } finally {
      setIsAnalyzing(false);
    }
  };

  useEffect(() => {
    let timeoutId: number;
    const poll = async () => {
      if (isActive && !quotaExhausted) {
        await analyzeFrame();
      }
      const delay = quotaExhausted ? 30000 : 3000;
      timeoutId = window.setTimeout(poll, delay);
    };

    if (isActive) {
      timeoutId = window.setTimeout(poll, 1000);
    }
    return () => clearTimeout(timeoutId);
  }, [isActive, quotaExhausted]);

  useEffect(() => {
    if (!canvasRef.current || !analysis?.landmarks || !isActive) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const { width, height } = canvasRef.current;
    ctx.clearRect(0, 0, width, height);

    const getPt = (label: string) => 
      analysis.landmarks.find(p => p.label.toLowerCase().replace(/\s/g, '').includes(label.toLowerCase()));

    const scaleX = (x: number) => (x * width) / 100;
    const scaleY = (y: number) => (y * height) / 100;

    const getMarkerColor = (label: string) => {
      const l = label.toLowerCase();
      if (l.includes('head')) return '#fbbf24'; 
      if (l.includes('shoulder')) return '#22d3ee'; 
      if (l.includes('spine')) return '#f8fafc'; 
      if (l.includes('hip')) return '#a855f7'; 
      return '#ffffff';
    };

    const drawBiometricSkeleton = () => {
      const head = getPt('head');
      const spineMid = getPt('spinemid');
      const ls = getPt('leftshoulder');
      const rs = getPt('rightshoulder');
      const lh = getPt('lefthip');
      const rh = getPt('righthip');

      const midShoulder = (ls && rs) ? { x: (ls.x + rs.x) / 2, y: (ls.y + rs.y) / 2 } : null;
      const midHip = (lh && rh) ? { x: (lh.x + rh.x) / 2, y: (lh.y + rh.y) / 2 } : null;

      if (head && spineMid && midShoulder && midHip) {
        ctx.beginPath();
        ctx.lineWidth = 4;
        ctx.strokeStyle = '#3b82f6';
        ctx.lineCap = 'round';
        ctx.globalAlpha = 0.5;

        const hX = scaleX(head.x), hY = scaleY(head.y);
        const msX = scaleX(midShoulder.x), msY = scaleY(midShoulder.y);
        const smX = scaleX(spineMid.x), smY = scaleY(spineMid.y);
        const mhX = scaleX(midHip.x), mhY = scaleY(midHip.y);

        ctx.moveTo(hX, hY);
        ctx.bezierCurveTo(msX, msY, smX, smY, mhX, mhY);
        ctx.stroke();

        if (analysis.estimatedCobbAngle && analysis.estimatedCobbAngle > 5) {
          const arcRadius = 40;
          ctx.beginPath();
          ctx.strokeStyle = analysis.isDeviating ? '#ef4444' : '#10b981';
          ctx.lineWidth = 2;
          ctx.globalAlpha = 0.8;
          ctx.arc(smX, smY, arcRadius, 1.5 * Math.PI, (1.5 + (analysis.estimatedCobbAngle / 180) * Math.PI) * Math.PI);
          ctx.stroke();

          ctx.font = 'bold 12px Inter';
          ctx.fillStyle = analysis.isDeviating ? '#ef4444' : '#10b981';
          ctx.fillText(`${analysis.estimatedCobbAngle.toFixed(1)}° Cobb`, smX + arcRadius + 5, smY);
        }
      }

      const transverseColor = analysis.isDeviating ? '#ef4444' : '#10b981';
      ctx.lineWidth = 3;
      ctx.strokeStyle = transverseColor;
      ctx.globalAlpha = 0.6;

      if (ls && rs) {
        ctx.beginPath();
        ctx.moveTo(scaleX(ls.x), scaleY(ls.y));
        ctx.lineTo(scaleX(rs.x), scaleY(rs.y));
        ctx.stroke();
      }

      if (lh && rh) {
        ctx.beginPath();
        ctx.moveTo(scaleX(lh.x), scaleY(lh.y));
        ctx.lineTo(scaleX(rh.x), scaleY(rh.y));
        ctx.stroke();
      }

      analysis.landmarks.forEach(j => {
        const jx = scaleX(j.x), jy = scaleY(j.y);
        const color = getMarkerColor(j.label);

        ctx.globalAlpha = 1.0;
        ctx.beginPath();
        ctx.arc(jx, jy, 5, 0, Math.PI * 2);
        ctx.fillStyle = color;
        ctx.shadowBlur = 8;
        ctx.shadowColor = color;
        ctx.fill();
        ctx.stroke();
        ctx.shadowBlur = 0;
      });
    };

    const frame = requestAnimationFrame(drawBiometricSkeleton);
    return () => cancelAnimationFrame(frame);
  }, [analysis, isActive]);

  const severityLevels = ['Normal', 'Mild', 'Moderate', 'Severe'];

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col md:flex-row items-center justify-between gap-6">
        <div className="flex-1 w-full relative">
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Clinical Subject Identity</label>
          <div className="relative">
            <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
            <input 
              type="text" 
              placeholder="Enter Patient Full Name..." 
              value={patientName}
              onChange={(e) => setPatientName(e.target.value)}
              className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none font-bold text-slate-700"
            />
          </div>
        </div>
        <div className="shrink-0">
          <button 
            onClick={archiveSession}
            disabled={!analysis || isSaving}
            className={`flex items-center gap-2 px-8 py-3.5 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${
              saveSuccess 
                ? 'bg-emerald-500 text-white' 
                : !analysis || isSaving 
                ? 'bg-slate-100 text-slate-400 cursor-not-allowed' 
                : 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20 hover:bg-indigo-700'
            }`}
          >
            {saveSuccess ? <CheckCircle size={14} /> : isSaving ? <RefreshCw size={14} className="animate-spin" /> : <FileDown size={14} />}
            {saveSuccess ? 'Report Finalized' : 'Export Findings'}
          </button>
        </div>
      </div>

      {error && (
        <div className={`p-4 rounded-2xl flex items-center gap-4 font-bold text-sm border shadow-sm ${
          quotaExhausted ? 'bg-amber-50 border-amber-200 text-amber-700' : 'bg-red-50 border-red-100 text-red-600'
        }`}>
          {quotaExhausted ? <ZapOff size={20} /> : <AlertTriangle size={20} />}
          <div className="flex-1">
            <p>{error}</p>
            {quotaExhausted && <p className="text-[10px] mt-1 opacity-70">Analysis will resume automatically in {cooldownRemaining}s</p>}
          </div>
        </div>
      )}

      <div className="flex flex-col xl:flex-row gap-8">
        <div className="flex-1 flex flex-col gap-6">
          <div className="relative bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl aspect-video border-[6px] border-slate-800 group">
            <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity duration-700 ${isActive ? 'opacity-100' : 'opacity-20'}`} />
            <div className="absolute inset-0 pointer-events-none opacity-20 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]"></div>
            {/* Canvas resolution updated to 1280x720 (HD 16:9) */}
            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none" width={1280} height={720} />

            {isActive && (
              <div className="absolute top-8 left-8 flex items-center gap-3 bg-black/40 backdrop-blur-md px-4 py-2 rounded-xl border border-white/10">
                <div className={`w-2.5 h-2.5 rounded-full animate-pulse shadow-md ${quotaExhausted ? 'bg-amber-500 shadow-amber-500' : 'bg-red-500 shadow-red-500'}`}></div>
                <span className="text-white text-[10px] font-black tracking-widest uppercase">
                  {quotaExhausted ? `Rate Limit Cooling... (${cooldownRemaining}s)` : 'AI Biometric Tracking'}
                </span>
              </div>
            )}

            <div className="absolute bottom-10 left-1/2 -translate-x-1/2 z-20">
              {isActive ? (
                <button 
                  onClick={toggleMonitoring}
                  className="flex items-center gap-4 bg-red-600 hover:bg-red-700 text-white px-10 py-5 rounded-3xl font-black text-sm uppercase tracking-[0.2em] transition-all shadow-2xl shadow-red-900/40"
                >
                  <Square size={20} fill="currentColor" />
                  Terminate Session
                </button>
              ) : (
                <button 
                  onClick={toggleMonitoring}
                  className="flex items-center gap-4 bg-indigo-600 hover:bg-indigo-700 text-white px-12 py-6 rounded-3xl font-black text-sm uppercase tracking-[0.2em] transition-all shadow-2xl shadow-indigo-900/40"
                >
                  <Play size={24} fill="currentColor" />
                  Initiate Live Mapping
                </button>
              )}
            </div>

            {!isActive && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-white space-y-4 pointer-events-none">
                <div className="w-20 h-20 bg-white/5 backdrop-blur-md rounded-[2rem] flex items-center justify-center text-slate-500 border border-white/10"><CameraOff size={40} /></div>
                <div className="text-center px-8">
                  <p className="font-black text-xl mb-1 opacity-40">Optical Engine Offline</p>
                  <p className="text-slate-500 text-[10px] font-bold uppercase tracking-widest">Awaiting clinical session initialization</p>
                </div>
              </div>
            )}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm group">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Geometric Variance</p>
              <div className="flex items-baseline gap-1">
                <p className="text-4xl lg:text-5xl font-black text-slate-800 tabular-nums">
                  {analysis?.estimatedCobbAngle ? analysis.estimatedCobbAngle.toFixed(1) : '--'}
                </p>
                <span className="text-2xl text-slate-300 font-black">°</span>
              </div>
            </div>

            <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm group flex flex-col">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Scoliosis Class</p>
              <div className="flex-1 flex flex-col justify-center">
                <p className={`text-2xl lg:text-3xl font-black mb-4 ${
                  analysis?.severity === 'Severe' ? 'text-red-600' : 
                  analysis?.severity === 'Moderate' ? 'text-amber-600' :
                  analysis?.severity === 'Mild' ? 'text-blue-600' :
                  'text-emerald-600'
                }`}>
                  {analysis?.severity || '--'}
                </p>
                <div className="flex gap-1 h-2 w-full bg-slate-100 rounded-full overflow-hidden">
                  {severityLevels.map((lvl) => (
                    <div 
                      key={lvl} 
                      className={`flex-1 transition-all duration-500 ${
                        analysis?.severity === lvl ? (
                          lvl === 'Severe' ? 'bg-red-500' : 
                          lvl === 'Moderate' ? 'bg-amber-500' :
                          lvl === 'Mild' ? 'bg-blue-500' :
                          'bg-emerald-500'
                        ) : 'bg-transparent'
                      }`}
                    />
                  ))}
                </div>
              </div>
            </div>

            <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm group">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Optical Stability</p>
              <div className="flex items-baseline gap-1">
                <p className="text-4xl lg:text-5xl font-black text-indigo-600 tabular-nums">
                  {analysis ? Math.round(analysis.alignmentScore) : '--'}
                </p>
                <span className="text-2xl opacity-50 font-black text-indigo-600">%</span>
              </div>
            </div>
          </div>
        </div>

        <div className="w-full xl:w-96 flex flex-col gap-6">
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-lg flex flex-col h-[350px]">
            <div className="flex items-center justify-between mb-6 border-b border-slate-50 pb-4 shrink-0">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><ShieldCheck size={24} className="text-indigo-600" /> AI Findings</h3>
              {isAnalyzing && <RefreshCw size={16} className="text-indigo-400 animate-spin" />}
            </div>

            <div className="space-y-4 overflow-y-auto flex-1 pr-2 custom-scrollbar">
              {sessionLogs.length > 0 ? sessionLogs.map((log, i) => (
                <div key={i} className={`p-5 rounded-2xl border animate-in slide-in-from-right-4 transition-all ${i === 0 ? 'bg-indigo-50 border-indigo-100' : 'bg-slate-50 border-slate-50 opacity-60'}`}>
                  <div className="flex justify-between items-start mb-2">
                    <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">{log.time}</span>
                    <span className={`text-[9px] font-black px-2 py-0.5 rounded shadow-sm ${log.severity === 'Severe' ? 'bg-red-500 text-white' : 'bg-slate-200 text-slate-600'}`}>
                      {log.severity}
                    </span>
                  </div>
                  <p className="text-xs font-bold text-slate-800 leading-relaxed italic">"{log.text}"</p>
                </div>
              )) : (
                <div className="flex flex-col items-center justify-center h-full text-slate-300 text-center">
                  <Focus size={32} className="mb-2 opacity-20" />
                  <p className="text-xs font-black uppercase tracking-widest opacity-40">Awaiting Signal...</p>
                </div>
              )}
            </div>
          </div>

          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-lg flex flex-col h-[350px]">
            <div className="flex items-center justify-between mb-6 border-b border-slate-50 pb-4 shrink-0">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><Stethoscope size={24} className="text-emerald-500" /> Recommended Protocol</h3>
            </div>
            <div className="space-y-3 overflow-y-auto flex-1 pr-2 custom-scrollbar">
              {analysis?.recommendations && analysis.recommendations.length > 0 ? analysis.recommendations.map((rec, i) => (
                <div key={i} className="bg-emerald-50/50 border border-emerald-100 p-4 rounded-2xl flex items-start gap-3 animate-in fade-in duration-300">
                  <div className="w-6 h-6 rounded-full bg-emerald-100 text-emerald-600 flex items-center justify-center font-black text-[10px] shrink-0 mt-0.5 shadow-sm">
                    {i + 1}
                  </div>
                  <p className="text-xs font-bold text-slate-700 leading-tight">{rec}</p>
                </div>
              )) : (
                <div className="flex flex-col items-center justify-center h-full text-slate-300 text-center px-4">
                  <ActivityIcon size={32} className="mb-4 opacity-20" />
                  <p className="text-xs font-black uppercase tracking-widest opacity-40 mb-2">Prescription Pending</p>
                  <p className="text-[10px] text-slate-400 font-medium leading-relaxed">AI will suggest exercises once a stable anatomical curve is identified.</p>
                </div>
              )}
            </div>
            {analysis?.recommendations && (
              <div className="mt-4 p-3 bg-indigo-50 rounded-xl flex items-start gap-2 border border-indigo-100">
                <div className="text-indigo-600 shrink-0 mt-0.5"><Info size={14} /></div>
                <p className="text-[9px] font-bold text-indigo-700 leading-tight">These exercises are dynamic suggestions. Consult a medical professional for a personalized Schroth or PT plan.</p>
              </div>
            )}
          </div>

          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-lg h-[200px] flex flex-col">
            <div className="flex items-center justify-between mb-4 shrink-0">
              <h3 className="text-sm font-black text-slate-800 flex items-center gap-2"><LineChartIcon size={20} className="text-indigo-600" /> Alignment Trend</h3>
            </div>
            <div className="flex-1 w-full overflow-hidden">
              {sessionHistory.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={sessionHistory}>
                    <defs>
                      <linearGradient id="colorScoreLive" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#6366f1" stopOpacity={0.2}/>
                        <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <YAxis domain={[0, 100]} hide />
                    <Area type="monotone" dataKey="score" stroke="#6366f1" strokeWidth={3} fillOpacity={1} fill="url(#colorScoreLive)" isAnimationActive={false} />
                    <ReferenceLine y={85} stroke="#10b981" strokeDasharray="3 3" />
                  </AreaChart>
                </ResponsiveContainer>
              ) : (
                <div className="h-full flex flex-col items-center justify-center text-slate-200">
                  <ActivityIcon size={32} className="opacity-10" />
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PostureLiveView;

import React, { useEffect, useRef, useState } from 'react';
import { 
  Play, 
  Square, 
  RefreshCw, 
  ShieldCheck, 
  AlertTriangle,
  CameraOff,
  User,
  ZapOff,
  FileDown,
  Activity as ActivityIcon,
  Focus,
  LineChart as LineChartIcon,
  CheckCircle,
  Stethoscope,
  Info,
  RotateCcw
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";
import { PostureAnalysis, Landmark, ScoliosisSeverity, PatientRecord } from '../types';
import { AreaChart, Area, YAxis, XAxis, ResponsiveContainer, ReferenceLine } from 'recharts';

interface PostureLiveViewProps {
  onSaveReport?: (record: PatientRecord) => void;
}

interface SessionDataPoint {
  time: string;
  timestamp: number;
  score: number;
  angle: number;
}

const PostureLiveView: React.FC<PostureLiveViewProps> = ({ onSaveReport }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isActive, setIsActive] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<PostureAnalysis | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [quotaExhausted, setQuotaExhausted] = useState(false);
  const [cooldownRemaining, setCooldownRemaining] = useState(0);
  const [patientName, setPatientName] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  const [sessionHistory, setSessionHistory] = useState<SessionDataPoint[]>([]);
  const [sessionLogs, setSessionLogs] = useState<{time: string, text: string, severity: string}[]>([]);

  // Timer for cooldown if 429 occurs
  useEffect(() => {
    let timer: number;
    if (cooldownRemaining > 0) {
      timer = window.setInterval(() => {
        setCooldownRemaining(prev => Math.max(0, prev - 1));
      }, 1000);
    } else if (quotaExhausted && cooldownRemaining === 0) {
      setQuotaExhausted(false);
      setError(null);
    }
    return () => clearInterval(timer);
  }, [cooldownRemaining, quotaExhausted]);

  const toggleMonitoring = async () => {
    if (isActive) {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
      setIsActive(false);
      setAnalysis(null);
      setQuotaExhausted(false);
      setCooldownRemaining(0);
      setSessionHistory([]);
      setSessionLogs([]);
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { 
            facingMode: 'user', 
            width: { ideal: 1280 }, 
            height: { ideal: 720 } 
          } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsActive(true);
          setError(null);
        }
      } catch (err) {
        setError("Camera access is required for real-time monitoring.");
      }
    }
  };

  const retryAnalysis = () => {
    setQuotaExhausted(false);
    setCooldownRemaining(0);
    setError(null);
    analyzeFrame();
  };

  const archiveSession = async () => {
    if (!analysis || !onSaveReport) return;
    if (!patientName.trim()) {
      setError("Please enter a patient name to archive this session.");
      return;
    }

    setIsSaving(true);
    try {
      const snapshotCanvas = document.createElement('canvas');
      snapshotCanvas.width = 1280;
      snapshotCanvas.height = 720;
      const sCtx = snapshotCanvas.getContext('2d');
      if (sCtx && videoRef.current) {
        sCtx.drawImage(videoRef.current, 0, 0, 1280, 720);
        if (canvasRef.current) {
          sCtx.drawImage(canvasRef.current, 0, 0, 1280, 720);
        }
      }
      const dataUrl = snapshotCanvas.toDataURL('image/jpeg', 0.7);

      const record: PatientRecord = {
        id: Math.random().toString(36).substr(2, 9),
        patientName: patientName,
        timestamp: new Date().toISOString(),
        cobbAngle: analysis.estimatedCobbAngle || 0,
        severity: analysis.severity || ScoliosisSeverity.NORMAL,
        recommendations: analysis.recommendations || [],
        visualObservations: analysis.feedback,
        imageUrl: dataUrl,
        source: 'LIVE'
      };

      onSaveReport(record);
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
    } catch (err) {
      setError("Failed to archive session.");
    } finally {
      setIsSaving(false);
    }
  };

  const analyzeFrame = async () => {
    if (!isActive || !videoRef.current || isAnalyzing || quotaExhausted) return;

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 180;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `SCOLIOSIS CLINICAL MONITORING. Map anatomical landmarks: Head, LeftShoulder, RightShoulder, SpineMid, LeftHip, RightHip. Return JSON with: landmarks, alignmentScore (0-100), clinicalFeedback (precise 1-sentence diagnostic), isDeviating (bool), estimatedCobbAngle, severity, recommendations (array of 3 specific therapeutic exercises based on the detected curvature).` }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  }
                }
              },
              alignmentScore: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              isDeviating: { type: Type.BOOLEAN },
              estimatedCobbAngle: { type: Type.NUMBER },
              severity: { type: Type.STRING },
              recommendations: { type: Type.ARRAY, items: { type: Type.STRING } }
            },
            required: ['landmarks', 'alignmentScore', 'feedback', 'isDeviating', 'estimatedCobbAngle', 'severity', 'recommendations']
          }
        }
      });

      const responseText = response.text || '{}';
      const result = JSON.parse(responseText);
      setAnalysis(result);
      setQuotaExhausted(false);
      setError(null);

      const currentTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

      setSessionHistory(prev => [...prev.slice(-19), {
        time: currentTime,
        timestamp: Date.now(),
        score: result.alignmentScore,
        angle: result.estimatedCobbAngle
      }]);

      setSessionLogs(prev => [{
        time: currentTime,
        text: result.feedback,
        severity: result.severity
      }, ...prev.slice(0, 9)]);

    } catch (err: any) {
      if (err.message?.includes("RESOURCE_EXHAUSTED") || err.status === 429) {
        setQuotaExhausted(true);
        setCooldownRemaining(15); // Reduced from 30 for faster manual recovery
        setError("AI Rate Limit Exceeded. System throttled to protect API quota.");
      } else {
        console.error("Analysis Error:", err);
        setError("Communication error with AI service.");
      }
    } finally {
      setIsAnalyzing(false);
    }
  };

  useEffect(() => {
    let timeoutId: number;
    const poll = async () => {
      if (isActive && !quotaExhausted) {
        await analyzeFrame();
      }
      // Adjusted polling interval to 5 seconds for better quota sustainability
      const delay = quotaExhausted ? 15000 : 5000;
      timeoutId = window.setTimeout(poll, delay);
    };

    if (isActive) {
      timeoutId = window.setTimeout(poll, 1000);
    }
    return () => clearTimeout(timeoutId);
  }, [isActive, quotaExhausted]);

  useEffect(() => {
    if (!canvasRef.current || !analysis?.landmarks || !isActive) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const { width, height } = canvasRef.current;
    ctx.clearRect(0, 0, width, height);

    const getPt = (label: string) => 
      analysis.landmarks.find(p => p.label.toLowerCase().replace(/\s/g, '').includes(label.toLowerCase()));

    const scaleX = (x: number) => (x * width) / 100;
    const scaleY = (y: number) => (y * height) / 100;

    const getMarkerColor = (label: string) => {
      const l = label.toLowerCase();
      if (l.includes('head')) return '#fbbf24'; 
      if (l.includes('shoulder')) return '#22d3ee'; 
      if (l.includes('spine')) return '#f8fafc'; 
      if (l.includes('hip')) return '#a855f7'; 
      return '#ffffff';
    };

    const drawBiometricSkeleton = () => {
      const head = getPt('head');
      const spineMid = getPt('spinemid');
      const ls = getPt('leftshoulder');
      const rs = getPt('rightshoulder');
      const lh = getPt('lefthip');
      const rh = getPt('righthip');

      const midShoulder = (ls && rs) ? { x: (ls.x + rs.x) / 2, y: (ls.y + rs.y) / 2 } : null;
      const midHip = (lh && rh) ? { x: (lh.x + rh.x) / 2, y: (lh.y + rh.y) / 2 } : null;

      if (head && spineMid && midShoulder && midHip) {
        ctx.beginPath();
        ctx.lineWidth = 4;
        ctx.strokeStyle = '#3b82f6';
        ctx.lineCap = 'round';
        ctx.globalAlpha = 0.5;

        const hX = scaleX(head.x), hY = scaleY(head.y);
        const msX = scaleX(midShoulder.x), msY = scaleY(midShoulder.y);
        const smX = scaleX(spineMid.x), smY = scaleY(spineMid.y);
        const mhX = scaleX(midHip.x), mhY = scaleY(midHip.y);

        ctx.moveTo(hX, hY);
        ctx.bezierCurveTo(msX, msY, smX, smY, mhX, mhY);
        ctx.stroke();

        if (analysis.estimatedCobbAngle && analysis.estimatedCobbAngle > 5) {
          const arcRadius = 40;
          ctx.beginPath();
          ctx.strokeStyle = analysis.isDeviating ? '#ef4444' : '#10b981';
          ctx.lineWidth = 2;
          ctx.globalAlpha = 0.8;
          ctx.arc(smX, smY, arcRadius, 1.5 * Math.PI, (1.5 + (analysis.estimatedCobbAngle / 180) * Math.PI) * Math.PI);
          ctx.stroke();

          ctx.font = 'bold 12px Inter';
          ctx.fillStyle = analysis.isDeviating ? '#ef4444' : '#10b981';
          ctx.fillText(`${analysis.estimatedCobbAngle.toFixed(1)}° Cobb`, smX + arcRadius + 5, smY);
        }
      }

      const transverseColor = analysis.isDeviating ? '#ef4444' : '#10b981';
      ctx.lineWidth = 3;
      ctx.strokeStyle = transverseColor;
      ctx.globalAlpha = 0.6;

      if (ls && rs) {
        ctx.beginPath();
        ctx.moveTo(scaleX(ls.x), scaleY(ls.y));
        ctx.lineTo(scaleX(rs.x), scaleY(rs.y));
        ctx.stroke();
      }

      if (lh && rh) {
        ctx.beginPath();
        ctx.moveTo(scaleX(lh.x), scaleY(lh.y));
        ctx.lineTo(scaleX(rh.x), scaleY(rh.y));
        ctx.stroke();
      }

      analysis.landmarks.forEach(j => {
        const jx = scaleX(j.x), jy = scaleY(j.y);
        const color = getMarkerColor(j.label);

        ctx.globalAlpha = 1.0;
        ctx.beginPath();
        ctx.arc(jx, jy, 5, 0, Math.PI * 2);
        ctx.fillStyle = color;
        ctx.shadowBlur = 8;
        ctx.shadowColor = color;
        ctx.fill();
        ctx.stroke();
        ctx.shadowBlur = 0;
      });
    };

    const frame = requestAnimationFrame(drawBiometricSkeleton);
    return () => cancelAnimationFrame(frame);
  }, [analysis, isActive]);

  const severityLevels = ['Normal', 'Mild', 'Moderate', 'Severe'];

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col md:flex-row items-center justify-between gap-6">
        <div className="flex-1 w-full relative">
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Clinical Subject Identity</label>
          <div className="relative">
            <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
            <input 
              type="text" 
              placeholder="Enter Patient Full Name..." 
              value={patientName}
              onChange={(e) => setPatientName(e.target.value)}
              className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none font-bold text-slate-700"
            />
          </div>
        </div>
        <div className="shrink-0">
          <button 
            onClick={archiveSession}
            disabled={!analysis || isSaving}
            className={`flex items-center gap-2 px-8 py-3.5 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${
              saveSuccess 
                ? 'bg-emerald-500 text-white' 
                : !analysis || isSaving 
                ? 'bg-slate-100 text-slate-400 cursor-not-allowed' 
                : 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20 hover:bg-indigo-700'
            }`}
          >
            {saveSuccess ? <CheckCircle size={14} /> : isSaving ? <RefreshCw size={14} className="animate-spin" /> : <FileDown size={14} />}
            {saveSuccess ? 'Report Finalized' : 'Export Findings'}
          </button>
        </div>
      </div>

      {error && (
        <div className={`p-4 rounded-2xl flex flex-col md:flex-row items-center gap-4 font-bold text-sm border shadow-sm ${
          quotaExhausted ? 'bg-amber-50 border-amber-200 text-amber-700' : 'bg-red-50 border-red-100 text-red-600'
        }`}>
          <div className="flex items-center gap-4 flex-1">
            {quotaExhausted ? <ZapOff size={20} className="shrink-0" /> : <AlertTriangle size={20} className="shrink-0" />}
            <div>
              <p>{error}</p>
              {quotaExhausted && <p className="text-[10px] mt-1 opacity-70">Resume analysis in {cooldownRemaining}s</p>}
            </div>
          </div>
          {quotaExhausted && (
            <button 
              onClick={retryAnalysis}
              className="px-4 py-2 bg-amber-600 text-white rounded-xl text-xs uppercase tracking-widest font-black flex items-center gap-2 hover:bg-amber-700 transition-colors shadow-sm"
            >
              <RotateCcw size={14} />
              Force Retry
            </button>
          )}
        </div>
      )}

      <div className="flex flex-col xl:flex-row gap-8">
        <div className="flex-1 flex flex-col gap-6">
          <div className="relative bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl aspect-video border-[6px] border-slate-800 group">
            <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity duration-700 ${isActive ? 'opacity-100' : 'opacity-20'}`} />
            <div className="absolute inset-0 pointer-events-none opacity-20 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]"></div>
            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none" width={1280} height={720} />

            {isActive && (
              <div className="absolute top-8 left-8 flex items-center gap-3 bg-black/40 backdrop-blur-md px-4 py-2 rounded-xl border border-white/10">
                <div className={`w-2.5 h-2.5 rounded-full animate-pulse shadow-md ${quotaExhausted ? 'bg-amber-500 shadow-amber-500' : 'bg-red-500 shadow-red-500'}`}></div>
                <span className="text-white text-[10px] font-black tracking-widest uppercase">
                  {quotaExhausted ? `Rate Limited (${cooldownRemaining}s)` : 'AI Biometric Tracking'}
                </span>
              </div>
            )}

            <div className="absolute bottom-10 left-1/2 -translate-x-1/2 z-20">
              {isActive ? (
                <button 
                  onClick={toggleMonitoring}
                  className="flex items-center gap-4 bg-red-600 hover:bg-red-700 text-white px-10 py-5 rounded-3xl font-black text-sm uppercase tracking-[0.2em] transition-all shadow-2xl shadow-red-900/40"
                >
                  <Square size={20} fill="currentColor" />
                  Terminate Session
                </button>
              ) : (
                <button 
                  onClick={toggleMonitoring}
                  className="flex items-center gap-4 bg-indigo-600 hover:bg-indigo-700 text-white px-12 py-6 rounded-3xl font-black text-sm uppercase tracking-[0.2em] transition-all shadow-2xl shadow-indigo-900/40"
                >
                  <Play size={24} fill="currentColor" />
                  Initiate Live Mapping
                </button>
              )}
            </div>

            {!isActive && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-white space-y-4 pointer-events-none">
                <div className="w-20 h-20 bg-white/5 backdrop-blur-md rounded-[2rem] flex items-center justify-center text-slate-500 border border-white/10"><CameraOff size={40} /></div>
                <div className="text-center px-8">
                  <p className="font-black text-xl mb-1 opacity-40">Optical Engine Offline</p>
                  <p className="text-slate-500 text-[10px] font-bold uppercase tracking-widest">Awaiting clinical session initialization</p>
                </div>
              </div>
            )}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm group">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Geometric Variance</p>
              <div className="flex items-baseline gap-1">
                <p className="text-4xl lg:text-5xl font-black text-slate-800 tabular-nums">
                  {analysis?.estimatedCobbAngle ? analysis.estimatedCobbAngle.toFixed(1) : '--'}
                </p>
                <span className="text-2xl text-slate-300 font-black">°</span>
              </div>
            </div>

            <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm group flex flex-col">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Scoliosis Class</p>
              <div className="flex-1 flex flex-col justify-center">
                <p className={`text-2xl lg:text-3xl font-black mb-4 ${
                  analysis?.severity === 'Severe' ? 'text-red-600' : 
                  analysis?.severity === 'Moderate' ? 'text-amber-600' :
                  analysis?.severity === 'Mild' ? 'text-blue-600' :
                  'text-emerald-600'
                }`}>
                  {analysis?.severity || '--'}
                </p>
                <div className="flex gap-1 h-2 w-full bg-slate-100 rounded-full overflow-hidden">
                  {severityLevels.map((lvl) => (
                    <div 
                      key={lvl} 
                      className={`flex-1 transition-all duration-500 ${
                        analysis?.severity === lvl ? (
                          lvl === 'Severe' ? 'bg-red-500' : 
                          lvl === 'Moderate' ? 'bg-amber-500' :
                          lvl === 'Mild' ? 'bg-blue-500' :
                          'bg-emerald-500'
                        ) : 'bg-transparent'
                      }`}
                    />
                  ))}
                </div>
              </div>
            </div>

            <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm group">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Optical Stability</p>
              <div className="flex items-baseline gap-1">
                <p className="text-4xl lg:text-5xl font-black text-indigo-600 tabular-nums">
                  {analysis ? Math.round(analysis.alignmentScore) : '--'}
                </p>
                <span className="text-2xl opacity-50 font-black text-indigo-600">%</span>
              </div>
            </div>
          </div>
        </div>

        <div className="w-full xl:w-96 flex flex-col gap-6">
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-lg flex flex-col h-[350px]">
            <div className="flex items-center justify-between mb-6 border-b border-slate-50 pb-4 shrink-0">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><ShieldCheck size={24} className="text-indigo-600" /> AI Findings</h3>
              {isAnalyzing && <RefreshCw size={16} className="text-indigo-400 animate-spin" />}
            </div>

            <div className="space-y-4 overflow-y-auto flex-1 pr-2 custom-scrollbar">
              {sessionLogs.length > 0 ? sessionLogs.map((log, i) => (
                <div key={i} className={`p-5 rounded-2xl border animate-in slide-in-from-right-4 transition-all ${i === 0 ? 'bg-indigo-50 border-indigo-100' : 'bg-slate-50 border-slate-50 opacity-60'}`}>
                  <div className="flex justify-between items-start mb-2">
                    <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">{log.time}</span>
                    <span className={`text-[9px] font-black px-2 py-0.5 rounded shadow-sm ${log.severity === 'Severe' ? 'bg-red-500 text-white' : 'bg-slate-200 text-slate-600'}`}>
                      {log.severity}
                    </span>
                  </div>
                  <p className="text-xs font-bold text-slate-800 leading-relaxed italic">"{log.text}"</p>
                </div>
              )) : (
                <div className="flex flex-col items-center justify-center h-full text-slate-300 text-center">
                  <Focus size={32} className="mb-2 opacity-20" />
                  <p className="text-xs font-black uppercase tracking-widest opacity-40">Awaiting Signal...</p>
                </div>
              )}
            </div>
          </div>

          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-lg flex flex-col h-[350px]">
            <div className="flex items-center justify-between mb-6 border-b border-slate-50 pb-4 shrink-0">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><Stethoscope size={24} className="text-emerald-500" /> Recommended Protocol</h3>
            </div>
            <div className="space-y-3 overflow-y-auto flex-1 pr-2 custom-scrollbar">
              {analysis?.recommendations && analysis.recommendations.length > 0 ? analysis.recommendations.map((rec, i) => (
                <div key={i} className="bg-emerald-50/50 border border-emerald-100 p-4 rounded-2xl flex items-start gap-3 animate-in fade-in duration-300">
                  <div className="w-6 h-6 rounded-full bg-emerald-100 text-emerald-600 flex items-center justify-center font-black text-[10px] shrink-0 mt-0.5 shadow-sm">
                    {i + 1}
                  </div>
                  <p className="text-xs font-bold text-slate-700 leading-tight">{rec}</p>
                </div>
              )) : (
                <div className="flex flex-col items-center justify-center h-full text-slate-300 text-center px-4">
                  <ActivityIcon size={32} className="mb-4 opacity-20" />
                  <p className="text-xs font-black uppercase tracking-widest opacity-40 mb-2">Prescription Pending</p>
                  <p className="text-[10px] text-slate-400 font-medium leading-relaxed">AI will suggest exercises once a stable anatomical curve is identified.</p>
                </div>
              )}
            </div>
            {analysis?.recommendations && (
              <div className="mt-4 p-3 bg-indigo-50 rounded-xl flex items-start gap-2 border border-indigo-100">
                <div className="text-indigo-600 shrink-0 mt-0.5"><Info size={14} /></div>
                <p className="text-[9px] font-bold text-indigo-700 leading-tight">These exercises are dynamic suggestions. Consult a medical professional for a personalized Schroth or PT plan.</p>
              </div>
            )}
          </div>

          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-lg h-[200px] flex flex-col">
            <div className="flex items-center justify-between mb-4 shrink-0">
              <h3 className="text-sm font-black text-slate-800 flex items-center gap-2"><LineChartIcon size={20} className="text-indigo-600" /> Alignment Trend</h3>
            </div>
            <div className="flex-1 w-full overflow-hidden">
              {sessionHistory.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={sessionHistory}>
                    <defs>
                      <linearGradient id="colorScoreLive" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#6366f1" stopOpacity={0.2}/>
                        <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <YAxis domain={[0, 100]} hide />
                    <Area type="monotone" dataKey="score" stroke="#6366f1" strokeWidth={3} fillOpacity={1} fill="url(#colorScoreLive)" isAnimationActive={false} />
                    <ReferenceLine y={85} stroke="#10b981" strokeDasharray="3 3" />
                  </AreaChart>
                </ResponsiveContainer>
              ) : (
                <div className="h-full flex flex-col items-center justify-center text-slate-200">
                  <ActivityIcon size={32} className="opacity-10" />
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PostureLiveView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { 
  Play, 
  Square, 
  RefreshCw, 
  ShieldCheck, 
  AlertTriangle,
  CameraOff,
  User,
  ZapOff,
  FileDown,
  Activity as ActivityIcon,
  Focus,
  LineChart as LineChartIcon,
  CheckCircle,
  Stethoscope,
  Info,
  RotateCcw,
  Zap,
  Clock,
  Hand
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";
import { PostureAnalysis, Landmark, ScoliosisSeverity, PatientRecord } from '../types';
import { AreaChart, Area, YAxis, XAxis, ResponsiveContainer, ReferenceLine } from 'recharts';

interface PostureLiveViewProps {
  onSaveReport?: (record: PatientRecord) => void;
}

interface SessionDataPoint {
  time: string;
  timestamp: number;
  score: number;
  angle: number;
}

type ScanMode = 'LIVE' | 'BALANCED' | 'ECO' | 'MANUAL';

const PostureLiveView: React.FC<PostureLiveViewProps> = ({ onSaveReport }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isActive, setIsActive] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<PostureAnalysis | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [quotaExhausted, setQuotaExhausted] = useState(false);
  const [cooldownRemaining, setCooldownRemaining] = useState(0);
  const [patientName, setPatientName] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);
  const [scanMode, setScanMode] = useState<ScanMode>('BALANCED');

  const [sessionHistory, setSessionHistory] = useState<SessionDataPoint[]>([]);
  const [sessionLogs, setSessionLogs] = useState<{time: string, text: string, severity: string}[]>([]);

  // Timer for cooldown if 429 occurs
  useEffect(() => {
    let timer: number;
    if (cooldownRemaining > 0) {
      timer = window.setInterval(() => {
        setCooldownRemaining(prev => Math.max(0, prev - 1));
      }, 1000);
    } else if (quotaExhausted && cooldownRemaining === 0) {
      setQuotaExhausted(false);
      setError(null);
    }
    return () => clearInterval(timer);
  }, [cooldownRemaining, quotaExhausted]);

  const toggleMonitoring = async () => {
    if (isActive) {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
      setIsActive(false);
      setAnalysis(null);
      setQuotaExhausted(false);
      setCooldownRemaining(0);
      setSessionHistory([]);
      setSessionLogs([]);
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { 
            facingMode: 'user', 
            width: { ideal: 1280 }, 
            height: { ideal: 720 } 
          } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsActive(true);
          setError(null);
        }
      } catch (err) {
        setError("Camera access is required for real-time monitoring.");
      }
    }
  };

  const analyzeFrame = useCallback(async (isManual = false) => {
    if (!isActive || !videoRef.current || isAnalyzing || (quotaExhausted && !isManual)) return;

    // Stop wasted calls if patient name is missing
    if (!patientName.trim() && !isManual) {
      setError("Please enter patient identity to enable automated tracking.");
      return;
    }

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 180;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `SCOLIOSIS CLINICAL MONITORING. Map anatomical landmarks: Head, LeftShoulder, RightShoulder, SpineMid, LeftHip, RightHip. Return JSON with: landmarks, alignmentScore (0-100), clinicalFeedback (precise 1-sentence diagnostic), isDeviating (bool), estimatedCobbAngle, severity, recommendations (array of 3 specific therapeutic exercises).` }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  }
                }
              },
              alignmentScore: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              isDeviating: { type: Type.BOOLEAN },
              estimatedCobbAngle: { type: Type.NUMBER },
              severity: { type: Type.STRING },
              recommendations: { type: Type.ARRAY, items: { type: Type.STRING } }
            },
            required: ['landmarks', 'alignmentScore', 'feedback', 'isDeviating', 'estimatedCobbAngle', 'severity', 'recommendations']
          }
        }
      });

      const responseText = response.text || '{}';
      const result = JSON.parse(responseText);
      setAnalysis(result);
      setQuotaExhausted(false);
      setError(null);

      const currentTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

      setSessionHistory(prev => [...prev.slice(-19), {
        time: currentTime,
        timestamp: Date.now(),
        score: result.alignmentScore,
        angle: result.estimatedCobbAngle
      }]);

      setSessionLogs(prev => [{
        time: currentTime,
        text: result.feedback,
        severity: result.severity
      }, ...prev.slice(0, 9)]);

    } catch (err: any) {
      if (err.message?.includes("RESOURCE_EXHAUSTED") || err.status === 429) {
        setQuotaExhausted(true);
        setCooldownRemaining(30);
        setScanMode('ECO'); // Automatically back off to ECO mode
        setError("API Quota Reached. System is cooling down to preserve your free tier allowance.");
      } else {
        console.error("Analysis Error:", err);
        setError("Clinical data connection lost. Check internet or API status.");
      }
    } finally {
      setIsAnalyzing(false);
    }
  }, [isActive, isAnalyzing, quotaExhausted, patientName]);

  useEffect(() => {
    let timeoutId: number;
    const poll = async () => {
      if (isActive && !quotaExhausted && scanMode !== 'MANUAL') {
        await analyzeFrame();
      }

      let delay = 5000; // Balanced
      if (scanMode === 'LIVE') delay = 3000;
      if (scanMode === 'ECO') delay = 15000;
      if (quotaExhausted) delay = 30000;

      timeoutId = window.setTimeout(poll, delay);
    };

    if (isActive) {
      timeoutId = window.setTimeout(poll, 1000);
    }
    return () => clearTimeout(timeoutId);
  }, [isActive, quotaExhausted, scanMode, analyzeFrame]);

  // Skeleton Overlay Drawing Logic
  useEffect(() => {
    if (!canvasRef.current || !analysis?.landmarks || !isActive) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const { width, height } = canvasRef.current;
    ctx.clearRect(0, 0, width, height);

    const getPt = (label: string) => 
      analysis.landmarks.find(p => p.label.toLowerCase().replace(/\s/g, '').includes(label.toLowerCase()));

    const scaleX = (x: number) => (x * width) / 100;
    const scaleY = (y: number) => (y * height) / 100;

    const drawBiometricSkeleton = () => {
      const head = getPt('head');
      const spineMid = getPt('spinemid');
      const ls = getPt('leftshoulder');
      const rs = getPt('rightshoulder');
      const lh = getPt('lefthip');
      const rh = getPt('righthip');

      const midShoulder = (ls && rs) ? { x: (ls.x + rs.x) / 2, y: (ls.y + rs.y) / 2 } : null;
      const midHip = (lh && rh) ? { x: (lh.x + rh.x) / 2, y: (lh.y + rh.y) / 2 } : null;

      if (head && spineMid && midShoulder && midHip) {
        ctx.beginPath();
        ctx.lineWidth = 4;
        ctx.strokeStyle = '#3b82f6';
        ctx.lineCap = 'round';
        ctx.globalAlpha = 0.5;

        ctx.moveTo(scaleX(head.x), scaleY(head.y));
        ctx.bezierCurveTo(scaleX(midShoulder.x), scaleY(midShoulder.y), scaleX(spineMid.x), scaleY(spineMid.y), scaleX(midHip.x), scaleY(midHip.y));
        ctx.stroke();

        if (analysis.estimatedCobbAngle && analysis.estimatedCobbAngle > 5) {
          const smX = scaleX(spineMid.x), smY = scaleY(spineMid.y);
          ctx.beginPath();
          ctx.strokeStyle = analysis.isDeviating ? '#ef4444' : '#10b981';
          ctx.lineWidth = 2;
          ctx.globalAlpha = 0.8;
          ctx.arc(smX, smY, 40, 1.5 * Math.PI, (1.5 + (analysis.estimatedCobbAngle / 180) * Math.PI) * Math.PI);
          ctx.stroke();
          ctx.font = 'bold 12px Inter';
          ctx.fillStyle = analysis.isDeviating ? '#ef4444' : '#10b981';
          ctx.fillText(`${analysis.estimatedCobbAngle.toFixed(1)}° Cobb`, smX + 45, smY);
        }
      }

      analysis.landmarks.forEach(j => {
        ctx.globalAlpha = 1.0;
        ctx.beginPath();
        ctx.arc(scaleX(j.x), scaleY(j.y), 5, 0, Math.PI * 2);
        ctx.fillStyle = '#ffffff';
        ctx.shadowBlur = 8;
        ctx.shadowColor = '#3b82f6';
        ctx.fill();
        ctx.stroke();
      });
    };

    const frame = requestAnimationFrame(drawBiometricSkeleton);
    return () => cancelAnimationFrame(frame);
  }, [analysis, isActive]);

  const archiveSession = async () => {
    if (!analysis || !onSaveReport || !patientName.trim()) return;
    setIsSaving(true);
    try {
      const snap = document.createElement('canvas');
      snap.width = 1280; snap.height = 720;
      const sCtx = snap.getContext('2d');
      if (sCtx && videoRef.current) {
        sCtx.drawImage(videoRef.current, 0, 0, 1280, 720);
        if (canvasRef.current) sCtx.drawImage(canvasRef.current, 0, 0, 1280, 720);
      }
      onSaveReport({
        id: Math.random().toString(36).substr(2, 9),
        patientName,
        timestamp: new Date().toISOString(),
        cobbAngle: analysis.estimatedCobbAngle || 0,
        severity: analysis.severity || ScoliosisSeverity.NORMAL,
        recommendations: analysis.recommendations || [],
        visualObservations: analysis.feedback,
        imageUrl: snap.toDataURL('image/jpeg', 0.7),
        source: 'LIVE'
      });
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
    } finally {
      setIsSaving(false);
    }
  };

  const severityLevels = ['Normal', 'Mild', 'Moderate', 'Severe'];

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      {/* Patient & Control Bar */}
      <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col md:flex-row items-center justify-between gap-6">
        <div className="flex-1 w-full relative">
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Clinical Subject Identity</label>
          <div className="relative">
            <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
            <input 
              type="text" 
              placeholder="Enter Patient Full Name..." 
              value={patientName}
              onChange={(e) => setPatientName(e.target.value)}
              className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none font-bold text-slate-700"
            />
          </div>
        </div>
        <div className="flex gap-2">
          <button 
            onClick={archiveSession}
            disabled={!analysis || isSaving}
            className={`flex items-center gap-2 px-6 py-3.5 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${
              saveSuccess ? 'bg-emerald-500 text-white' : !analysis || isSaving ? 'bg-slate-100 text-slate-400 cursor-not-allowed' : 'bg-indigo-600 text-white hover:bg-indigo-700'
            }`}
          >
            {saveSuccess ? <CheckCircle size={14} /> : isSaving ? <RefreshCw size={14} className="animate-spin" /> : <FileDown size={14} />}
            {saveSuccess ? 'Archived' : 'Export'}
          </button>
        </div>
      </div>

      {error && (
        <div className={`p-4 rounded-2xl flex flex-col md:flex-row items-center gap-4 font-bold text-sm border shadow-sm ${
          quotaExhausted ? 'bg-amber-50 border-amber-200 text-amber-700' : 'bg-red-50 border-red-100 text-red-600'
        }`}>
          <div className="flex items-center gap-4 flex-1">
            {quotaExhausted ? <ZapOff size={20} /> : <AlertTriangle size={20} />}
            <div>
              <p>{error}</p>
              {quotaExhausted && <p className="text-[10px] mt-1 opacity-70">Analysis throttle active. Resume in {cooldownRemaining}s</p>}
            </div>
          </div>
          {quotaExhausted && (
            <button 
              onClick={() => analyzeFrame(true)}
              className="px-4 py-2 bg-amber-600 text-white rounded-xl text-xs uppercase tracking-widest font-black flex items-center gap-2 hover:bg-amber-700 shadow-sm"
            >
              <RotateCcw size={14} /> Force Manual Scan
            </button>
          )}
        </div>
      )}

      <div className="flex flex-col xl:flex-row gap-8">
        <div className="flex-1 flex flex-col gap-6">
          {/* Main Video Engine */}
          <div className="relative bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl aspect-video border-[6px] border-slate-800 group">
            <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity duration-700 ${isActive ? 'opacity-100' : 'opacity-20'}`} />
            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none" width={1280} height={720} />

            {/* Scan Control Overlay */}
            {isActive && (
              <div className="absolute top-8 left-8 right-8 flex justify-between items-start">
                <div className="flex flex-col gap-2">
                  <div className="bg-black/40 backdrop-blur-md px-4 py-2 rounded-xl border border-white/10 flex items-center gap-3">
                    <div className={`w-2.5 h-2.5 rounded-full animate-pulse ${quotaExhausted ? 'bg-amber-500' : 'bg-red-500'}`}></div>
                    <span className="text-white text-[10px] font-black tracking-widest uppercase">
                      {quotaExhausted ? 'Throttle Active' : 'Live Mapping'}
                    </span>
                  </div>
                  <div className="bg-indigo-600/80 backdrop-blur-md px-3 py-1.5 rounded-lg flex items-center gap-2 border border-white/10">
                    <Clock size={12} className="text-white" />
                    <span className="text-white text-[9px] font-black uppercase tracking-tighter">
                      Mode: {scanMode}
                    </span>
                  </div>
                </div>

                <div className="bg-black/60 backdrop-blur-lg p-1.5 rounded-2xl border border-white/10 flex gap-1">
                  {[
                    { id: 'ECO', icon: Clock, label: 'Eco' },
                    { id: 'BALANCED', icon: ActivityIcon, label: 'Auto' },
                    { id: 'LIVE', icon: Zap, label: 'Fast' },
                    { id: 'MANUAL', icon: Hand, label: 'Man' },
                  ].map((m) => (
                    <button 
                      key={m.id}
                      onClick={() => setScanMode(m.id as ScanMode)}
                      className={`px-3 py-2 rounded-xl flex flex-col items-center gap-1 transition-all ${
                        scanMode === m.id ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:text-white'
                      }`}
                    >
                      <m.icon size={16} />
                      <span className="text-[8px] font-black uppercase">{m.label}</span>
                    </button>
                  ))}
                </div>
              </div>
            )}

            <div className="absolute bottom-10 left-1/2 -translate-x-1/2 z-20 flex flex-col items-center gap-4">
              {isActive ? (
                <div className="flex gap-4">
                  <button 
                    onClick={toggleMonitoring}
                    className="bg-red-600 hover:bg-red-700 text-white px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest transition-all shadow-xl shadow-red-900/40 flex items-center gap-3"
                  >
                    <Square size={16} fill="currentColor" /> Terminate
                  </button>
                  {scanMode === 'MANUAL' && (
                    <button 
                      onClick={() => analyzeFrame(true)}
                      disabled={isAnalyzing}
                      className="bg-emerald-600 hover:bg-emerald-700 text-white px-10 py-4 rounded-2xl font-black text-xs uppercase tracking-widest transition-all shadow-xl shadow-emerald-900/40 flex items-center gap-3"
                    >
                      {isAnalyzing ? <RefreshCw size={16} className="animate-spin" /> : <Focus size={16} />}
                      Run Instant Scan
                    </button>
                  )}
                </div>
              ) : (
                <button 
                  onClick={toggleMonitoring}
                  className="bg-indigo-600 hover:bg-indigo-700 text-white px-12 py-6 rounded-3xl font-black text-sm uppercase tracking-[0.2em] transition-all shadow-2xl shadow-indigo-900/40 flex items-center gap-4"
                >
                  <Play size={24} fill="currentColor" /> Initiate Session
                </button>
              )}
            </div>

            {!isActive && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-white space-y-4 pointer-events-none">
                <div className="w-20 h-20 bg-white/5 backdrop-blur-md rounded-[2rem] flex items-center justify-center text-slate-500 border border-white/10"><CameraOff size={40} /></div>
                <div className="text-center">
                  <p className="font-black text-xl mb-1 opacity-40">Optical Engine Offline</p>
                  <p className="text-slate-500 text-[10px] font-bold uppercase tracking-widest">Select patient to start mapping</p>
                </div>
              </div>
            )}
          </div>

          {/* Diagnostic Metrics */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Geometric Variance</p>
              <div className="flex items-baseline gap-1">
                <p className="text-4xl lg:text-5xl font-black text-slate-800 tabular-nums">
                  {analysis?.estimatedCobbAngle ? analysis.estimatedCobbAngle.toFixed(1) : '--'}
                </p>
                <span className="text-2xl text-slate-300 font-black">°</span>
              </div>
            </div>

            <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex flex-col">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Scoliosis Class</p>
              <div className="flex-1 flex flex-col justify-center">
                <p className={`text-2xl lg:text-3xl font-black mb-4 ${
                  analysis?.severity === 'Severe' ? 'text-red-600' : 
                  analysis?.severity === 'Moderate' ? 'text-amber-600' :
                  analysis?.severity === 'Mild' ? 'text-blue-600' :
                  'text-emerald-600'
                }`}>
                  {analysis?.severity || '--'}
                </p>
                <div className="flex gap-1 h-2 w-full bg-slate-100 rounded-full overflow-hidden">
                  {severityLevels.map((lvl) => (
                    <div key={lvl} className={`flex-1 transition-all duration-500 ${analysis?.severity === lvl ? (lvl === 'Severe' ? 'bg-red-500' : lvl === 'Moderate' ? 'bg-amber-500' : lvl === 'Mild' ? 'bg-blue-500' : 'bg-emerald-500') : 'bg-transparent'}`} />
                  ))}
                </div>
              </div>
            </div>

            <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Optical Stability</p>
              <div className="flex items-baseline gap-1">
                <p className="text-4xl lg:text-5xl font-black text-indigo-600 tabular-nums">
                  {analysis ? Math.round(analysis.alignmentScore) : '--'}
                </p>
                <span className="text-2xl opacity-50 font-black text-indigo-600">%</span>
              </div>
            </div>
          </div>
        </div>

        {/* Sidebar Diagnostics */}
        <div className="w-full xl:w-96 flex flex-col gap-6">
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-lg flex flex-col h-[350px]">
            <div className="flex items-center justify-between mb-6 border-b border-slate-50 pb-4 shrink-0">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><ShieldCheck size={24} className="text-indigo-600" /> AI Findings</h3>
              {isAnalyzing && <RefreshCw size={16} className="text-indigo-400 animate-spin" />}
            </div>
            <div className="space-y-4 overflow-y-auto flex-1 pr-2 custom-scrollbar">
              {sessionLogs.length > 0 ? sessionLogs.map((log, i) => (
                <div key={i} className={`p-5 rounded-2xl border transition-all ${i === 0 ? 'bg-indigo-50 border-indigo-100' : 'bg-slate-50 border-slate-50 opacity-60'}`}>
                  <div className="flex justify-between items-start mb-2">
                    <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">{log.time}</span>
                    <span className={`text-[9px] font-black px-2 py-0.5 rounded shadow-sm ${log.severity === 'Severe' ? 'bg-red-500 text-white' : 'bg-slate-200 text-slate-600'}`}>{log.severity}</span>
                  </div>
                  <p className="text-xs font-bold text-slate-800 leading-relaxed italic">"{log.text}"</p>
                </div>
              )) : (
                <div className="flex flex-col items-center justify-center h-full text-slate-300 text-center">
                  <Focus size={32} className="mb-2 opacity-20" />
                  <p className="text-xs font-black uppercase tracking-widest opacity-40">Ready to Map</p>
                </div>
              )}
            </div>
          </div>

          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-lg flex flex-col h-[350px]">
            <div className="flex items-center justify-between mb-6 border-b border-slate-50 pb-4 shrink-0">
              <h3 className="text-xl font-black text-slate-800 flex items-center gap-2"><Stethoscope size={24} className="text-emerald-500" /> Recommended Protocol</h3>
            </div>
            <div className="space-y-3 overflow-y-auto flex-1 pr-2 custom-scrollbar">
              {analysis?.recommendations?.map((rec, i) => (
                <div key={i} className="bg-emerald-50/50 border border-emerald-100 p-4 rounded-2xl flex items-start gap-3 animate-in fade-in">
                  <div className="w-6 h-6 rounded-full bg-emerald-100 text-emerald-600 flex items-center justify-center font-black text-[10px] shrink-0 mt-0.5">{i + 1}</div>
                  <p className="text-xs font-bold text-slate-700 leading-tight">{rec}</p>
                </div>
              )) || (
                <div className="flex flex-col items-center justify-center h-full text-slate-300 text-center px-4">
                  <ActivityIcon size={32} className="mb-4 opacity-20" />
                  <p className="text-xs font-black uppercase tracking-widest opacity-40 mb-2">Protocol Pending</p>
                  <p className="text-[10px] text-slate-400 font-medium">Automatic suggestions will appear after anatomical validation.</p>
                </div>
              )}
            </div>
            {analysis?.recommendations && (
              <div className="mt-4 p-3 bg-indigo-50 rounded-xl flex items-start gap-2 border border-indigo-100">
                <Info size={14} className="text-indigo-600 shrink-0 mt-0.5" />
                <p className="text-[9px] font-bold text-indigo-700 leading-tight">Dynamic AI suggestions. Medical validation required before starting exercises.</p>
              </div>
            )}
          </div>

          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-lg h-[200px] flex flex-col">
            <div className="flex items-center justify-between mb-4 shrink-0">
              <h3 className="text-sm font-black text-slate-800 flex items-center gap-2"><LineChartIcon size={20} className="text-indigo-600" /> Stability Trend</h3>
            </div>
            <div className="flex-1 w-full overflow-hidden">
              {sessionHistory.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={sessionHistory}>
                    <defs>
                      <linearGradient id="colorScoreLive" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#6366f1" stopOpacity={0.2}/>
                        <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <YAxis domain={[0, 100]} hide />
                    <Area type="monotone" dataKey="score" stroke="#6366f1" strokeWidth={3} fillOpacity={1} fill="url(#colorScoreLive)" isAnimationActive={false} />
                    <ReferenceLine y={85} stroke="#10b981" strokeDasharray="3 3" />
                  </AreaChart>
                </ResponsiveContainer>
              ) : (
                <div className="h-full flex flex-col items-center justify-center text-slate-200">
                  <ActivityIcon size={32} className="opacity-10" />
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PostureLiveView;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { 
  Play, 
  Square, 
  RefreshCw, 
  ShieldCheck, 
  AlertTriangle,
  CameraOff,
  User,
  ZapOff,
  FileDown,
  Activity as ActivityIcon,
  Focus,
  LineChart as LineChartIcon,
  CheckCircle,
  Stethoscope,
  Info,
  RotateCcw,
  Zap,
  Clock,
  Hand
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";
import { PostureAnalysis, Landmark, ScoliosisSeverity, PatientRecord } from '../types';
import { AreaChart, Area, YAxis, XAxis, ResponsiveContainer, ReferenceLine } from 'recharts';

interface PostureLiveViewProps {
  onSaveReport?: (record: PatientRecord) => void;
}

interface SessionDataPoint {
  time: string;
  timestamp: number;
  score: number;
  angle: number;
}

type ScanMode = 'LIVE' | 'BALANCED' | 'ECO' | 'MANUAL';

const PostureLiveView: React.FC<PostureLiveViewProps> = ({ onSaveReport }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isActive, setIsActive] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState<PostureAnalysis | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [quotaExhausted, setQuotaExhausted] = useState(false);
  const [cooldownRemaining, setCooldownRemaining] = useState(0);
  const [patientName, setPatientName] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);
  const [scanMode, setScanMode] = useState<ScanMode>('BALANCED');

  const [sessionHistory, setSessionHistory] = useState<SessionDataPoint[]>([]);
  const [sessionLogs, setSessionLogs] = useState<{time: string, text: string, severity: string}[]>([]);

  // Timer for cooldown if 429 occurs
  useEffect(() => {
    let timer: number;
    if (cooldownRemaining > 0) {
      timer = window.setInterval(() => {
        setCooldownRemaining(prev => Math.max(0, prev - 1));
      }, 1000);
    } else if (quotaExhausted && cooldownRemaining === 0) {
      setQuotaExhausted(false);
      setError(null);
    }
    return () => clearInterval(timer);
  }, [cooldownRemaining, quotaExhausted]);

  const toggleMonitoring = async () => {
    if (isActive) {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
      setIsActive(false);
      setAnalysis(null);
      setQuotaExhausted(false);
      setCooldownRemaining(0);
      setSessionHistory([]);
      setSessionLogs([]);
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { 
            facingMode: 'user', 
            width: { ideal: 1280 }, 
            height: { ideal: 720 } 
          } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsActive(true);
          setError(null);
        }
      } catch (err) {
        setError("Camera access is required for real-time monitoring.");
      }
    }
  };

  const analyzeFrame = useCallback(async (isManual = false) => {
    // Basic pre-checks to save quota
    if (!isActive || !videoRef.current || isAnalyzing || (quotaExhausted && !isManual)) return;

    if (!patientName.trim() && !isManual) {
      setError("Analysis paused: Patient Identity required for automated tracking.");
      return;
    }

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 180;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `SCOLIOSIS CLINICAL MONITORING. Map anatomical landmarks: Head, LeftShoulder, RightShoulder, SpineMid, LeftHip, RightHip. Return JSON with: landmarks, alignmentScore (0-100), clinicalFeedback (precise 1-sentence diagnostic), isDeviating (bool), estimatedCobbAngle, severity, recommendations (array of 3 specific therapeutic exercises).` }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              landmarks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    x: { type: Type.NUMBER }, y: { type: Type.NUMBER }, label: { type: Type.STRING }
                  }
                }
              },
              alignmentScore: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              isDeviating: { type: Type.BOOLEAN },
              estimatedCobbAngle: { type: Type.NUMBER },
              severity: { type: Type.STRING },
              recommendations: { type: Type.ARRAY, items: { type: Type.STRING } }
            },
            required: ['landmarks', 'alignmentScore', 'feedback', 'isDeviating', 'estimatedCobbAngle', 'severity', 'recommendations']
          }
        }
      });

      const responseText = response.text || '{}';
      const result = JSON.parse(responseText);
      setAnalysis(result);
      setQuotaExhausted(false);
      setError(null);

      const currentTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

      setSessionHistory(prev => [...prev.slice(-19), {
        time: currentTime,
        timestamp: Date.now(),
        score: result.alignmentScore,
        angle: result.estimatedCobbAngle
      }]);

      setSessionLogs(prev => [{
        time: currentTime,
        text: result.feedback,
        severity: result.severity
      }, ...prev.slice(0, 9)]);

    } catch (err: any) {
      if (err.message?.includes("RESOURCE_EXHAUSTED") || err.status === 429) {
        setQuotaExhausted(true);
        setCooldownRemaining(60); // Increased cooldown for safer recovery
        setScanMode('ECO'); 
        setError("API Quota Exceeded. System is temporarily throttled to protect your service allowance.");
      } else {
        console.error("Analysis Error:", err);
        setError("Clinical data connection interrupted. Retrying in next cycle.");
      }
    } finally {
      setIsAnalyzing(false);
    }
  }, [isActive, isAnalyzing, quotaExhausted, patientName]);

  useEffect(() => {
    let timeoutId: number;
    const poll = async () => {
      if (isActive && !quotaExhausted && scanMode !== 'MANUAL') {
        await analyzeFrame();
      }

      // More conservative intervals to stay within 15 RPM limits
      let delay = 12000; // Balanced (5 requests/min)
      if (scanMode === 'LIVE') delay = 6000; // Fast (10 requests/min)
      if (scanMode === 'ECO') delay = 25000; // Eco (2.4 requests/min)
      if (quotaExhausted) delay = 60000; // Cooldown

      timeoutId = window.setTimeout(poll, delay);
    };

    if (isActive) {
      timeoutId = window.setTimeout(poll, 1000);
    }
    return () => clearTimeout(timeoutId);
  }, [isActive, quotaExhausted, scanMode, analyzeFrame]);

  // Skeleton Overlay Drawing Logic
  useEffect(() => {
    if (!canvasRef.current || !analysis?.landmarks || !isActive) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const { width, height } = canvasRef.current;
    ctx.clearRect(0, 0, width, height);

    const getPt = (label: string) => 
      analysis.landmarks.find(p => p.label.toLowerCase().replace(/\s/g, '').includes(label.toLowerCase()));

    const scaleX = (x: number) => (x * width) / 100;
    const scaleY = (y: number) => (y * height) / 100;

    const drawBiometricSkeleton = () => {
      const head = getPt('head');
      const spineMid = getPt('spinemid');
      const ls = getPt('leftshoulder');
      const rs = getPt('rightshoulder');
      const lh = getPt('lefthip');
      const rh = getPt('righthip');

      const midShoulder = (ls && rs) ? { x: (ls.x + rs.x) / 2, y: (ls.y + rs.y) / 2 } : null;
      const midHip = (lh && rh) ? { x: (lh.x + rh.x) / 2, y: (lh.y + rh.y) / 2 } : null;

      if (head && spineMid && midShoulder && midHip) {
        ctx.beginPath();
        ctx.lineWidth = 4;
        ctx.strokeStyle = '#3b82f6';
        ctx.lineCap = 'round';
        ctx.globalAlpha = 0.5;

        ctx.moveTo(scaleX(head.x), scaleY(head.y));
        ctx.bezierCurveTo(scaleX(midShoulder.x), scaleY(midShoulder.y), scaleX(spineMid.x), scaleY(spineMid.y), scaleX(midHip.x), scaleY(midHip.y));
        ctx.stroke();

        if (analysis.estimatedCobbAngle && analysis.estimatedCobbAngle > 5) {
          const smX = scaleX(spineMid.x), smY = scaleY(spineMid.y);
          ctx.beginPath();
          ctx.strokeStyle = analysis.isDeviating ? '#ef4444' : '#10b981';
          ctx.lineWidth = 2;
          ctx.globalAlpha = 0.8;
          ctx.arc(smX, smY, 40, 1.5 * Math.PI, (1.5 + (analysis.estimatedCobbAngle / 180) * Math.PI) * Math.PI);
          ctx.stroke();
          ctx.font = 'bold 12px Inter';
          ctx.fillStyle = analysis.isDeviating ? '#ef4444' : '#10b981';
          ctx.fillText(`${analysis.estimatedCobbAngle.toFixed(1)}° Cobb`, smX + 45, smY);
        }
      }

      analysis.landmarks.forEach(j => {
        ctx.globalAlpha = 1.0;
        ctx.beginPath();
        ctx.arc(scaleX(j.x), scaleY(j.y), 5, 0, Math.PI * 2);
        ctx.fillStyle = '#ffffff';
        ctx.shadowBlur = 8;
        ctx.shadowColor = '#3b82f6';
        ctx.fill();
        ctx.stroke();
      });
    };

    const frame = requestAnimationFrame(drawBiometricSkeleton);
    return () => cancelAnimationFrame(frame);
  }, [analysis, isActive]);

  const archiveSession = async () => {
    if (!analysis || !onSaveReport || !patientName.trim()) return;
    setIsSaving(true);
    try {
      const snap = document.createElement('canvas');
      snap.width = 1280; snap.height = 720;
      const sCtx = snap.getContext('2d');
      if (sCtx && videoRef.current) {
        sCtx.drawImage(videoRef.current, 0, 0, 1280, 720);
        if (canvasRef.current) sCtx.drawImage(canvasRef.current, 0, 0, 1280, 720);
      }
      onSaveReport({
        id: Math.random().toString(36).substr(2, 9),
        patientName,
        timestamp: new Date().toISOString(),
        cobbAngle: analysis.estimatedCobbAngle || 0,
        severity: analysis.severity || ScoliosisSeverity.NORMAL,
        recommendations: analysis.recommendations || [],
        visualObservations: analysis.feedback,
        imageUrl: snap.toDataURL('image/jpeg', 0.7),
        source: 'LIVE'
      });
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
    } finally {
      setIsSaving(false);
    }
  };

  const severityLevels = ['Normal', 'Mild', 'Moderate', 'Severe'];

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      {/* Patient & Control Bar */}
      <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col md:flex-row items-center justify-between gap-6">
        <div className="flex-1 w-full relative">
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Clinical Subject Identity</label>
          <div className="relative">
            <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
            <input 
              type="text" 
              placeholder="Enter Patient Full Name..." 
              value={patientName}
              onChange={(e) => setPatientName(e.target.value)}
              className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none font-bold text-slate-700"
            />
          </div>
        </div>
        <div className="flex gap-2">
          <button 
            onClick={archiveSession}
            disabled={!analysis || isSaving}
            className={`flex items-center gap-2 px-6 py-3.5 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${
              saveSuccess ? 'bg-emerald-500 text-white' : !analysis || isSaving ? 'bg-slate-100 text-slate-400 cursor-not-allowed' : 'bg-indigo-600 text-white hover:bg-indigo-700'
            }`}
          >
            {saveSuccess ? <CheckCircle size={14} /> : isSaving ? <RefreshCw size={14} className="animate-spin" /> : <FileDown size={14} />}
            {saveSuccess ? 'Archived' : 'Export'}
          </button>
        </div>
      </div>

      {error && (
        <div className={`p-5 rounded-2xl flex flex-col md:flex-row items-center gap-6 font-bold text-sm border shadow-sm ${
          quotaExhausted ? 'bg-amber-50 border-amber-200 text-amber-700' : 'bg-red-50 border-red-100 text-red-600'
        }`}>
          <div className="flex items-center gap-4 flex-1">
            {quotaExhausted ? <ZapOff size={24} className="animate-pulse" /> : <AlertTriangle size={24} />}
            <div className="space-y-1">
              <p className="text-base">{error}</p>
              {quotaExhausted && (
                <div className="flex flex-col gap-2">
                  <p className="text-xs opacity-70">Automated analysis will resume after the cooldown period.</p>
                  <div className="w-full bg-amber-200/50 h-1.5 rounded-full overflow-hidden">
                    <div 
                      className="bg-amber-500 h-full transition-all duration-1000" 
                      style={{ width: `${(cooldownRemaining / 60) * 100}%` }}
                    />
                  </div>
                  <span className="text-[10px] font-black uppercase tracking-widest">{cooldownRemaining}s remaining</span>
                </div>
              )}
            </div>
          </div>
          {quotaExhausted && (
            <button 
