import React, { useEffect, useRef, useState, useCallback } from 'react';
import { 
  Play, 
  Square, 
  RefreshCw, 
  ShieldCheck, 
  AlertTriangle,
  CameraOff,
  User,
  ZapOff,
  FileDown,
  Activity as ActivityIcon,
  Focus,
  LineChart as LineChartIcon,
  CheckCircle,
  Stethoscope,
  Info,
  RotateCcw,
  Zap,
  Clock,
  Hand,
  Cpu,
  Monitor,
  TrendingUp
} from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";
import { PostureAnalysis, Landmark, ScoliosisSeverity, PatientRecord } from '../types';
import { AreaChart, Area, YAxis, XAxis, ResponsiveContainer, ReferenceLine } from 'recharts';

declare const poseDetection: any;

interface PostureLiveViewProps {
  onSaveReport?: (record: PatientRecord) => void;
}

interface SessionDataPoint {
  time: string;
  timestamp: number;
  score: number;
  angle: number;
}

const PostureLiveView: React.FC<PostureLiveViewProps> = ({ onSaveReport }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const detectorRef = useRef<any>(null);

  const [isActive, setIsActive] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [localAnalysis, setLocalAnalysis] = useState<{angle: number, score: number, peakAngle: number} | null>(null);
  const [cloudAnalysis, setCloudAnalysis] = useState<Partial<PostureAnalysis> | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [patientName, setPatientName] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  const [sessionHistory, setSessionHistory] = useState<SessionDataPoint[]>([]);
  const [sessionLogs, setSessionLogs] = useState<{time: string, text: string, severity: string}[]>([]);

  // Initialize TensorFlow MoveNet Detector
  const initDetector = async () => {
    try {
      const detectorConfig = {
        modelType: poseDetection.movenet.modelType.SINGLEPOSE_LIGHTNING
      };
      detectorRef.current = await poseDetection.createDetector(
        poseDetection.SupportedModels.MoveNet, 
        detectorConfig
      );
    } catch (err) {
      console.error("TFJS Init Error:", err);
      setError("Local AI Engine failed to load. Check GPU support.");
    }
  };

  const toggleMonitoring = async () => {
    if (isActive) {
      const stream = videoRef.current?.srcObject as MediaStream;
      stream?.getTracks().forEach(track => track.stop());
      setIsActive(false);
      setLocalAnalysis(null);
      setCloudAnalysis(null);
      setSessionHistory([]);
      setSessionLogs([]);
    } else {
      try {
        if (!detectorRef.current) await initDetector();
        const stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: 640, height: 480 } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsActive(true);
          setError(null);
        }
      } catch (err) {
        setError("Optical link failure: Camera access denied.");
      }
    }
  };

  const runCloudInsights = useCallback(async () => {
    if (!isActive || !videoRef.current || isAnalyzing) return;

    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 180;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
    const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];

    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
            { text: `SCOLIOSIS CLINICAL CONSULTATION. Analyze the spinal alignment in this frame. Return JSON: feedback (1 medical sentence), severity (Normal/Mild/Moderate/Severe), recommendations (3 exercises).` }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              feedback: { type: Type.STRING },
              severity: { type: Type.STRING },
              recommendations: { type: Type.ARRAY, items: { type: Type.STRING } }
            },
            required: ['feedback', 'severity', 'recommendations']
          }
        }
      });

      const result = JSON.parse(response.text || '{}');
      setCloudAnalysis(result);

      const currentTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      setSessionLogs(prev => [{
        time: currentTime,
        text: result.feedback,
        severity: result.severity
      }, ...prev.slice(0, 5)]);

    } catch (err) {
      console.warn("Cloud quota reached - utilizing Local Heuristics only.");
    } finally {
      setIsAnalyzing(false);
    }
  }, [isActive, isAnalyzing]);

  // Main Local Frame Loop
  useEffect(() => {
    let animationFrame: number;
    let peak = 0;

    const processFrame = async () => {
      if (!isActive || !videoRef.current || !detectorRef.current || !canvasRef.current) return;

      const poses = await detectorRef.current.estimatePoses(videoRef.current);
      const ctx = canvasRef.current.getContext('2d');

      if (poses.length > 0 && ctx) {
        const pose = poses[0];
        const { width, height } = canvasRef.current;
        ctx.clearRect(0, 0, width, height);

        // Biometric Mapping
        const getKpt = (name: string) => pose.keypoints.find((k: any) => k.name === name);
        const lS = getKpt('left_shoulder');
        const rS = getKpt('right_shoulder');
        const lH = getKpt('left_hip');
        const rH = getKpt('right_hip');

        if (lS && rS && lH && rH) {
          const midS = { x: (lS.x + rS.x) / 2, y: (lS.y + rS.y) / 2 };
          const midH = { x: (lH.x + rH.x) / 2, y: (lH.y + rH.y) / 2 };

          // Local Cobb Approximation (Simple linear deviation)
          const dx = midS.x - midH.x;
          const dy = midS.y - midH.y;
          const angle = Math.abs(Math.atan2(dx, dy) * (180 / Math.PI));
          const score = Math.round(pose.score * 100);

          if (angle > peak) peak = angle;

          setLocalAnalysis({ angle, score, peakAngle: peak });

          // Draw HUD
          ctx.beginPath();
          ctx.lineWidth = 4;
          ctx.strokeStyle = angle > 10 ? '#f43f5e' : '#10b981';
          ctx.setLineDash([10, 5]);
          ctx.moveTo(midS.x, midS.y);
          ctx.lineTo(midH.x, midH.y);
          ctx.stroke();
          ctx.setLineDash([]);

          // Markers
          [lS, rS, lH, rH].forEach(kp => {
            ctx.beginPath();
            ctx.arc(kp.x, kp.y, 6, 0, Math.PI * 2);
            ctx.fillStyle = '#ffffff';
            ctx.fill();
            ctx.strokeStyle = '#6366f1';
            ctx.lineWidth = 2;
            ctx.stroke();
          });
        }
      }
      animationFrame = requestAnimationFrame(processFrame);
    };

    if (isActive) {
      processFrame();
      // Cloud insights every 15s to save API quota
      const cloudInterval = setInterval(runCloudInsights, 15000);
      return () => {
        cancelAnimationFrame(animationFrame);
        clearInterval(cloudInterval);
      };
    }
  }, [isActive, runCloudInsights]);

  const archiveSession = async () => {
    if (!localAnalysis || !onSaveReport) return;
    setIsSaving(true);
    try {
      const snap = document.createElement('canvas');
      snap.width = 640; snap.height = 480;
      const sCtx = snap.getContext('2d');
      if (sCtx && videoRef.current) {
        sCtx.drawImage(videoRef.current, 0, 0, 640, 480);
        if (canvasRef.current) sCtx.drawImage(canvasRef.current, 0, 0, 640, 480);
      }
      onSaveReport({
        id: Math.random().toString(36).substr(2, 9),
        patientName: patientName || 'Unidentified Subject',
        timestamp: new Date().toISOString(),
        cobbAngle: localAnalysis.angle,
        severity: (cloudAnalysis?.severity as ScoliosisSeverity) || ScoliosisSeverity.NORMAL,
        recommendations: cloudAnalysis?.recommendations || [],
        visualObservations: cloudAnalysis?.feedback || 'Local biometric baseline recorded.',
        imageUrl: snap.toDataURL('image/jpeg', 0.7),
        source: 'LIVE'
      });
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      {/* HUD Header */}
      <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col md:flex-row items-center justify-between gap-6">
        <div className="flex-1 w-full">
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Subject Profile Mapping</label>
          <div className="relative">
            <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
            <input 
              type="text" 
              placeholder="Assign Patient ID..." 
              value={patientName}
              onChange={(e) => setPatientName(e.target.value)}
              className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none font-bold text-slate-700"
            />
          </div>
        </div>
        <button 
          onClick={archiveSession}
          disabled={!localAnalysis || isSaving}
          className={`px-8 py-3.5 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${
            saveSuccess ? 'bg-emerald-500 text-white' : !localAnalysis || isSaving ? 'bg-slate-100 text-slate-400' : 'bg-indigo-600 text-white shadow-lg shadow-indigo-200'
          }`}
        >
          {saveSuccess ? 'Session Logged' : 'Capture Baseline'}
        </button>
      </div>

      <div className="flex flex-col xl:flex-row gap-8">
        <div className="flex-1 flex flex-col gap-6">
          {/* Medical Viewport */}
          <div className="relative bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl aspect-[4/3] border-[6px] border-slate-800">
            <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover ${isActive ? 'opacity-100' : 'opacity-10'}`} />
            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none" width={640} height={480} />

            {isActive && (
              <div className="absolute top-8 left-8 flex flex-col gap-3">
                <div className="bg-black/60 backdrop-blur-md px-4 py-2 rounded-xl border border-white/10 flex items-center gap-3">
                  <Cpu size={14} className="text-emerald-400 animate-spin" />
                  <span className="text-white text-[10px] font-black tracking-widest uppercase">Biometric HUD (Active)</span>
                </div>
                {isAnalyzing && (
                  <div className="bg-indigo-600/80 backdrop-blur-md px-4 py-2 rounded-xl border border-white/10 flex items-center gap-3 animate-pulse">
                    <Monitor size={14} className="text-white" />
                    <span className="text-white text-[10px] font-black tracking-widest uppercase">Gemini Cloud Sync...</span>
                  </div>
                )}
              </div>
            )}

            <div className="absolute bottom-10 left-1/2 -translate-x-1/2 z-20 flex gap-4">
              {!isActive ? (
                <button onClick={toggleMonitoring} className="bg-indigo-600 hover:bg-indigo-700 text-white px-12 py-6 rounded-3xl font-black text-sm uppercase tracking-[0.2em] shadow-2xl flex items-center gap-4">
                  <Play size={24} fill="currentColor" /> Activate Sensors
                </button>
              ) : (
                <>
                  <button onClick={toggleMonitoring} className="bg-red-600 text-white px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl flex items-center gap-3">
                    <Square size={16} fill="currentColor" /> Terminate Session
                  </button>
                  <button onClick={runCloudInsights} disabled={isAnalyzing} className="bg-white text-slate-900 px-10 py-4 rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl flex items-center gap-3">
                    <Zap size={16} className="text-indigo-600" /> Manual Sync
                  </button>
                </>
              )}
            </div>

            {!isActive && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-slate-500 pointer-events-none">
                <CameraOff size={64} className="mb-4 opacity-20" />
                <p className="font-black text-xs uppercase tracking-widest">Sensors Offline</p>
              </div>
            )}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm border-l-4 border-l-indigo-600">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 flex items-center gap-2">
                <Focus size={12} className="text-indigo-600" />
                Live Cobb Angle
              </p>
              <div className="flex items-baseline gap-1">
                <p className="text-5xl font-black text-slate-800">{localAnalysis?.angle.toFixed(1) || '--'}</p>
                <span className="text-2xl font-bold text-slate-300">°</span>
              </div>
            </div>
            <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm border-l-4 border-l-emerald-600">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 flex items-center gap-2">
                <TrendingUp size={12} className="text-emerald-600" />
                Peak Cobb Angle
              </p>
              <div className="flex items-baseline gap-1">
                <p className="text-5xl font-black text-slate-800">{localAnalysis?.peakAngle.toFixed(1) || '--'}</p>
                <span className="text-2xl font-bold text-slate-300">°</span>
              </div>
            </div>
            <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm border-l-4 border-l-amber-600">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 flex items-center gap-2">
                <ShieldCheck size={12} className="text-amber-600" />
                Tracking Confidence
              </p>
              <div className="flex items-baseline gap-1">
                <p className="text-5xl font-black text-slate-800">{localAnalysis?.score || '--'}</p>
                <span className="text-2xl font-bold text-slate-300">%</span>
              </div>
            </div>
          </div>
        </div>

        {/* Diagnostic Stream */}
        <div className="w-full xl:w-96 flex flex-col gap-6">
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-lg flex flex-col h-[400px]">
            <h3 className="text-xl font-black text-slate-800 flex items-center gap-2 mb-6 border-b pb-4 shrink-0">
              <ShieldCheck size={24} className="text-indigo-600" /> AI Diagnostic Log
            </h3>
            <div className="space-y-4 overflow-y-auto flex-1 pr-2 custom-scrollbar">
