            <div className="hidden md:flex gap-2">
              <span className="px-3 py-1 bg-indigo-50 text-indigo-700 text-xs font-bold rounded-full border border-indigo-100 uppercase tracking-tighter">AI Vision v4.2</span>
            </div>
          </div>

          <div className="p-8 space-y-6">
            <div>
