              </div>

              <div className="flex-1 space-y-6 print:w-1/2">
                <div className="bg-white p-8 rounded-3xl border border-slate-100 shadow-lg print:shadow-none print:border-none">
                  <div className="flex items-center justify-between mb-8">
                    <div>
                      <h2 className="text-2xl font-bold text-slate-800">{patientName}</h2>
