                <tr><td colSpan={6} className="px-8 py-20 text-center text-slate-400 italic">No records found.</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Report Modal & Printable Area */}
      {selectedRecord && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 md:p-8 animate-in fade-in duration-300">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm no-print" onClick={() => setSelectedRecord(null)}></div>
          <div className="bg-white w-full max-w-5xl max-h-[90vh] rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden flex flex-col animate-in zoom-in-95 duration-300 printable-area">

            {/* Modal Header (No Print) */}
