              <div className="flex items-center gap-4">
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center font-bold text-white shadow-lg ${selectedRecord.source === 'LIVE' ? 'bg-indigo-600' : 'bg-blue-600'}`}>
                  {selectedRecord.patientName.charAt(0)}
                </div>
                <div>
                  <h3 className="text-xl font-bold text-slate-800">{selectedRecord.patientName}</h3>
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Diagnostic ID: {selectedRecord.id}</span>
                </div>
              </div>
              <div className="flex items-center gap-2">
                <button onClick={handleShare} className="p-2 text-slate-400 hover:text-indigo-600 rounded-full transition-all"><Share2 size={20} /></button>
                <button onClick={() => setSelectedRecord(null)} className="w-10 h-10 rounded-full hover:bg-slate-100 flex items-center justify-center text-slate-400 transition-colors"><X size={24} /></button>
