                  </td>
                  <td className="px-8 py-5 text-right">
                    <div className="flex items-center justify-end gap-2">
                      <button onClick={() => setSelectedRecord(record)} className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all"><ExternalLink size={18} /></button>
                      <button onClick={() => onDelete(record.id)} className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all"><Trash2 size={18} /></button>
                    </div>
                  </td>
                </tr>
              )) : (
                <tr><td colSpan={6} className="px-8 py-20 text-center text-slate-400 italic">No records found.</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Report Modal & Printable Area */}
      {selectedRecord && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 md:p-8 animate-in fade-in duration-300">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm no-print" onClick={() => setSelectedRecord(null)}></div>
          <div className="bg-white w-full max-w-5xl max-h-[90vh] rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden flex flex-col animate-in zoom-in-95 duration-300 printable-area">

            {/* Modal Header (No Print) */}
            <div className="px-8 py-6 border-b border-slate-100 flex items-center justify-between shrink-0 no-print">
              <div className="flex items-center gap-4">
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center font-bold text-white shadow-lg ${selectedRecord.source === 'LIVE' ? 'bg-indigo-600' : 'bg-blue-600'}`}>
                  {selectedRecord.patientName.charAt(0)}
                </div>
                <div>
                  <h3 className="text-xl font-bold text-slate-800">{selectedRecord.patientName}</h3>
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Diagnostic ID: {selectedRecord.id}</span>
                </div>
              </div>
              <div className="flex items-center gap-2">
                <button onClick={handleShare} className="p-2 text-slate-400 hover:text-indigo-600 rounded-full transition-all"><Share2 size={20} /></button>
                <button onClick={() => setSelectedRecord(null)} className="w-10 h-10 rounded-full hover:bg-slate-100 flex items-center justify-center text-slate-400 transition-colors"><X size={24} /></button>
