            {/* Print Only Header */}
            <div className="hidden print:block p-8 mb-4 border-b-2 border-slate-900">
              <div className="flex justify-between items-start">
                <div className="flex items-center gap-3">
                  <div className="bg-slate-900 p-2 rounded-lg text-white"><ShieldCheck size={32} /></div>
                  <div>
                    <h1 className="text-3xl font-black text-slate-900 tracking-tighter">ScolioVision AI</h1>
                    <p className="text-xs font-bold uppercase tracking-widest text-slate-500">Historical Clinical Report</p>
                  </div>
                </div>
                <div className="text-right">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Session ID</p>
                  <p className="text-sm font-bold text-slate-900">{selectedRecord.id}</p>
                </div>
              </div>
            </div>

            {/* Modal Content */}
            <div className="flex-1 overflow-y-auto p-8 custom-scrollbar">
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                <div className="space-y-6">
                  <div className="relative rounded-[2rem] overflow-hidden shadow-xl border border-slate-100 bg-slate-900 print:shadow-none print:border-slate-300">
                    <img src={selectedRecord.imageUrl} className="w-full h-auto object-contain" alt="Clinical Scan" />
                    {selectedRecord.markers && (
                      <svg className="absolute inset-0 w-full h-full pointer-events-none" viewBox="0 0 100 100" preserveAspectRatio="none">
                        {renderMarker(selectedRecord.markers.topLine, 'Top', '#4f46e5')}
                        {renderMarker(selectedRecord.markers.bottomLine, 'Bottom', '#4f46e5')}
                      </svg>
                    )}
                  </div>
                  <div className="bg-slate-50 p-6 rounded-3xl border border-slate-100 print:bg-white print:border-slate-200">
                    <div className="flex items-center justify-between mb-2">
                      <span className="text-sm font-bold text-slate-600">Calculated Cobb Angle</span>
                      <span className="text-2xl font-black text-slate-800">{selectedRecord.cobbAngle.toFixed(1)}°</span>
                    </div>
                    <div className="flex items-center justify-between">
                      <span className="text-sm font-bold text-slate-600">Severity</span>
                      <span className={`px-4 py-1.5 rounded-xl border text-[10px] font-black uppercase tracking-widest ${getSeverityColor(selectedRecord.severity)}`}>
                        {selectedRecord.severity}
                      </span>
                    </div>
                  </div>
                </div>

                <div className="space-y-8">
                  <div className="space-y-4">
                    <h4 className="text-sm font-black text-slate-800 flex items-center gap-2">
                      <Activity size={18} className="text-indigo-600" />Historical Interpretation
                    </h4>
                    <div className="bg-white p-6 rounded-3xl border border-slate-100 text-sm text-slate-600 italic print:border-slate-200">
                      "{selectedRecord.visualObservations}"
                    </div>
                  </div>

                  <div className="space-y-4">
                    <h4 className="text-sm font-black text-slate-800 flex items-center gap-2">
                      <Stethoscope size={18} className="text-emerald-500" />Corrective Protocol
                    </h4>
                    <div className="grid grid-cols-1 gap-3">
                      {selectedRecord.recommendations.map((rec, i) => (
                        <div key={i} className="bg-emerald-50/50 border border-emerald-100 p-4 rounded-2xl flex items-center gap-4 print:bg-white print:border-slate-200">
                          <div className="w-8 h-8 rounded-full bg-emerald-100 text-emerald-600 flex items-center justify-center font-black text-xs shrink-0">{i + 1}</div>
                          <p className="text-sm font-bold text-slate-700">{rec}</p>
                        </div>
                      ))}
                    </div>
                  </div>

                  <div className="flex gap-4 pt-4 no-print">
                    <button onClick={handlePrint} className="flex-1 py-4 bg-indigo-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest flex items-center justify-center gap-3 shadow-lg shadow-indigo-100"><Printer size={18} />Export PDF</button>
                    <button onClick={handleShare} className="flex-1 py-4 bg-slate-100 text-slate-600 rounded-2xl font-black text-xs uppercase tracking-widest flex items-center justify-center gap-3"><Share2 size={18} />Share</button>
                  </div>
                </div>
              </div>

              {/* Print Verification Footer */}
              <div className="hidden print:flex justify-between items-end mt-20 pt-10 border-t border-slate-200">
                <div className="space-y-1">
                  <p className="text-[10px] font-black uppercase text-slate-400">Digital Validation Signature</p>
                  <div className="w-48 h-1 bg-slate-200 mt-8 mb-2"></div>
                  <p className="text-sm font-bold text-slate-900">ScolioVision AI Medical Core</p>
                </div>
                <div className="text-right">
                  <p className="text-[8px] font-bold text-slate-400 max-w-xs leading-tight uppercase tracking-tighter">Archived Case Report • Subject Identity: {selectedRecord.patientName} • Diagnostic verified by AI Core</p>
                </div>
              </div>
            </div>

            <div className="px-8 py-6 bg-slate-50 border-t border-slate-100 flex items-center justify-between text-[10px] font-black text-slate-400 uppercase tracking-widest no-print">
              <span>Diagnostic History • HIPAA Secure</span>
              <span className="flex items-center gap-2"><FileDown size={14} />Case Records Locked</span>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default HistoryView;

export enum ScoliosisSeverity {
  NORMAL = 'Normal',
  MILD = 'Mild',
  MODERATE = 'Moderate',
  SEVERE = 'Severe'
}

export type AnalysisSource = 'XRAY' | 'LIVE';

export interface LineCoords {
  x1: number;
  y1: number;
  x2: number;
  y2: number;
}

export interface Landmark {
  x: number;
  y: number;
  label: string;
}

export interface PostureAnalysis {
  landmarks: Landmark[];
  alignmentScore: number;
  feedback: string;
  isDeviating: boolean;
  estimatedCobbAngle?: number;
  severity?: ScoliosisSeverity;
  recommendations?: string[];
}

export interface AnalysisResult {
  cobbAngle: number;
  severity: ScoliosisSeverity;
  recommendations: string[];
  visualObservations: string;
  timestamp: string;
  id: string;
  imageUrl?: string;
  source?: AnalysisSource;
  markers?: {
    topLine: LineCoords;
    bottomLine: LineCoords;
  };
}

export interface PatientRecord extends AnalysisResult {
  patientName: string;
}

export interface User {
  name: string;
  designation: string;
  department: string;
}

export type AppView = 'DASHBOARD' | 'ANALYSIS' | 'HISTORY' | 'POSTURE_LIVE' | 'DOCUMENTATION';

import React, { useState, useEffect } from 'react';
import { 
  Activity, 
  History, 
  LayoutDashboard, 
  ShieldCheck,
  LogOut,
  Bell,
  Menu,
  X,
  Video,
  BookOpen
} from 'lucide-react';
import { AppView, PatientRecord, User } from './types';
import DashboardView from './components/DashboardView';
import AnalysisView from './components/AnalysisView';
import HistoryView from './components/HistoryView';
import LoginView from './components/LoginView';
import PostureLiveView from './components/PostureLiveView';
import DocumentationView from './components/DocumentationView';

const MAX_RECORDS = 15;

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<AppView>('DASHBOARD');
  const [records, setRecords] = useState<PatientRecord[]>([]);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    const savedRecords = localStorage.getItem('scolio_records');
    if (savedRecords) {
      try { 
        const parsed = JSON.parse(savedRecords);
        if (Array.isArray(parsed)) setRecords(parsed);
      } catch (e) { 
        localStorage.removeItem('scolio_records');
      }
    }

    const savedUser = localStorage.getItem('scolio_user');
    if (savedUser) {
      try { 
        const parsed = JSON.parse(savedUser);
        setUser(parsed); 
      } catch (e) { 
        localStorage.removeItem('scolio_user');
      }
    }
  }, []);

  const handleLogin = (userData: User) => {
    setUser(userData);
    localStorage.setItem('scolio_user', JSON.stringify(userData));
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('scolio_user');
  };

  const addRecord = (record: PatientRecord) => {
    const updated = [record, ...records].slice(0, MAX_RECORDS);
    setRecords(updated);
    try {
      localStorage.setItem('scolio_records', JSON.stringify(updated));
    } catch (e) {
      const trimmed = updated.slice(0, 5);
      setRecords(trimmed);
      localStorage.setItem('scolio_records', JSON.stringify(trimmed));
    }
  };

  const deleteRecord = (id: string) => {
    const updated = records.filter(r => r.id !== id);
    setRecords(updated);
    localStorage.setItem('scolio_records', JSON.stringify(updated));
  };

  const navItems = [
    { id: 'DASHBOARD' as AppView, label: 'Dashboard', icon: LayoutDashboard },
    { id: 'ANALYSIS' as AppView, label: 'AI Analysis', icon: Activity },
    { id: 'POSTURE_LIVE' as AppView, label: 'Live Monitoring', icon: Video },
    { id: 'HISTORY' as AppView, label: 'Patient History', icon: History },
    { id: 'DOCUMENTATION' as AppView, label: 'Project Report', icon: BookOpen },
  ];

  if (!user) {
    return <LoginView onLogin={handleLogin} />;
  }

  const renderView = () => {
    switch (currentView) {
      case 'DASHBOARD': return <DashboardView records={records} setView={setCurrentView} user={user} />;
      case 'ANALYSIS': return <AnalysisView onResultSave={addRecord} />;
      case 'POSTURE_LIVE': return <PostureLiveView onSaveReport={addRecord} />;
      case 'HISTORY': return <HistoryView records={records} onDelete={deleteRecord} />;
      case 'DOCUMENTATION': return <DocumentationView />;
      default: return <DashboardView records={records} setView={setCurrentView} user={user} />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row">
      {/* Sidebar - Desktop */}
      <aside className="hidden md:flex w-72 bg-white border-r border-slate-200 flex-col sticky top-0 h-screen shadow-sm no-print">
        <div className="p-6 flex items-center gap-3 border-b border-slate-100">
          <div className="bg-indigo-600 p-2 rounded-xl text-white">
            <ShieldCheck size={28} />
          </div>
          <div>
            <h1 className="font-bold text-slate-800 text-lg leading-tight">ScolioVision</h1>
            <p className="text-indigo-600 text-xs font-semibold tracking-wider uppercase">AI Medical Suite</p>
          </div>
        </div>

        <nav className="flex-1 p-4 space-y-1">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setCurrentView(item.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
                currentView === item.id 
                  ? 'bg-indigo-50 text-indigo-700 shadow-sm font-semibold' 
                  : 'text-slate-500 hover:bg-slate-50 hover:text-slate-700'
              }`}
            >
              <item.icon size={20} />
              {item.label}
            </button>
          ))}
        </nav>

        <div className="p-4 mt-auto border-t border-slate-100">
          <button 
            onClick={handleLogout}
            className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-slate-500 hover:bg-red-50 hover:text-red-600 transition-colors"
          >
            <LogOut size={20} />
            Sign Out
          </button>
        </div>
      </aside>

      {/* Mobile Header */}
      <header className="md:hidden bg-white border-b border-slate-200 px-4 py-3 flex items-center justify-between sticky top-0 z-50 no-print">
        <div className="flex items-center gap-2">
          <div className="bg-indigo-600 p-1.5 rounded-lg text-white">
            <ShieldCheck size={20} />
          </div>
          <span className="font-bold text-slate-800">ScolioVision</span>
        </div>
        <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} className="p-2 text-slate-600">
          {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </header>

      {/* Mobile Nav Overlay */}
      {isMobileMenuOpen && (
        <div className="md:hidden fixed inset-0 bg-white z-40 pt-16 flex flex-col no-print">
          <nav className="p-6 space-y-4">
            {navItems.map((item) => (
              <button
                key={item.id}
                onClick={() => {
                  setCurrentView(item.id);
                  setIsMobileMenuOpen(false);
                }}
                className={`w-full flex items-center gap-4 px-4 py-4 rounded-xl text-lg ${
                  currentView === item.id ? 'bg-indigo-50 text-indigo-700 font-bold' : 'text-slate-600 font-medium'
                }`}
              >
                <item.icon size={24} />
                {item.label}
              </button>
            ))}
            <button 
              onClick={handleLogout}
              className="w-full flex items-center gap-4 px-4 py-4 rounded-xl text-lg text-red-600 font-medium"
            >
              <LogOut size={24} />
              Sign Out
            </button>
          </nav>
        </div>
      )}

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto">
        <header className="hidden md:flex bg-white border-b border-slate-200 px-8 py-4 items-center justify-between sticky top-0 z-10 no-print">
          <h2 className="text-xl font-bold text-slate-800">
            {navItems.find(n => n.id === currentView)?.label}
          </h2>
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-3 pl-4 border-l border-slate-200">
              <div className="text-right">
                <p className="text-sm font-bold text-slate-800">{user.name}</p>
                <p className="text-xs text-slate-500">{user.designation}</p>
              </div>
              <div className="w-10 h-10 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-700 font-bold ring-2 ring-white">
                {user.name.charAt(0)}
              </div>
            </div>
          </div>
        </header>

        <div className="p-0 md:p-8 max-w-7xl mx-auto">
          {renderView()}
        </div>
      </main>
    </div>
  );
};

export default App;
